; ---- firmware: firmware variables ----
KL_UPPER_ROM            EQU #B1A8       ; 1 byte: upper ROM status (e.g. its select number)
KL_ROM_IY_TABLE         EQU #B1AA       ; 16 bytes: data area (IY) of each background ROM, ROM n at +2n (464: ROMs 1-7)
SCR_OFFSET              EQU #B1C9       ; 2 bytes: screen offset
SCR_BASE                EQU #B1CB       ; 1 byte: screen base, high byte
TXT_PAPER               EQU #B290       ; 1 byte: text paper (encoded)
TXT_UDG_FIRST           EQU #B294       ; 1 byte: first character of the user defined matrix table
TXT_UDG_PRESENT         EQU #B295       ; 1 byte: user defined matrix table present (&00 no, &FF yes)
TXT_UDG_TABLE           EQU #B296       ; 2 bytes: address of the user defined matrix table

; ---- vdos: VDOS variables and RAM code (workspace &BE00-&BFFF) ----
rel_files_flag          EQU #0026       ; 1 byte: &FF: |FILES channels defined (rsx_files), 0: none. In low RAM at &0026 (observed)
fast_write_stub         EQU #B1BA       ; 4 bytes: |FAST: RST 3 / DEFW fast_write_far / RET - IND TXT WRITE CHAR (&BDD3) jumps here; free firmware RAM after KL_ROM_IY_TABLE on the 464 (not checked)
fast_write_far          EQU #B1BE       ; 3 bytes: |FAST: far address of fast_write_char (&FD7D, ROM = VDOS's number at the time of |FAST)
autodetect_format       EQU #BE03       ; 1 byte: Format detection of the 3" drive on SELDSK (detect_format, from the sector number of READ ID): &FF = on - set by rom_init (BASIC) and the |CPM,1 boot (observed: a data format disc was recognised under BASIC); 0 = off while the relative files read or write a record (rel_read_random / rel_write_random); disc_init clears it
xpb_cache_drive         EQU #BE04       ; 1 byte: Drive whose DPH and XPB addresses are in xpb_cache_dph / xpb_cache_xpb (xpb_select_drive); &FF = none - disc_init and every CAS call (cas_entry_setup) set &FF so the next access looks them up again
xpb_cache_dph           EQU #BE05       ; 2 bytes: DPH address of xpb_cache_drive
xpb_cache_xpb           EQU #BE07       ; 2 bytes: XPB (DPB) address of xpb_cache_drive (word at DPH+10)
km_disarm_break_saved   EQU #BE24       ; 2 bytes: Address bytes of the original KM DISARM BREAK entry (RST 1 / LOW JUMP &9C82 on the 464), saved by hook_km_disarm_break
km_disarm_break_far     EQU #BE26       ; 3 bytes: Far address object for the KM DISARM BREAK hook: &C26E in our ROM
disarm_break_count      EQU #BE2D       ; 1 byte: Calls of KM DISARM BREAK left until post_boot_setup: rom_init sets 2, km_disarm_break_hook counts down (BASIC 1.0 calls it twice during its start-up)
dph_drive_a             EQU #BE40       ; 2 bytes: Address of drive A's disc parameter header (workspace+&43E, &AB3E here); drive B's DPH follows 16 bytes later. Set by setup_drive_tables
disc_time_constants     EQU #BE44       ; 7 bytes: Disc time constants: +0 motor on delay (word, 1/50 s), +2 motor off delay (word), +4 unused, +5 head settle (ms), +6 step rates (high nibble 3", low nibble Vortex, ms). Set by bios_setup_disc
fdc_result              EQU #BE4B       ; 7 bytes: uPD765 result bytes of the last command (fdc_read_result): ST0, ST1, ST2, C, H, R, N (READ ID: R at &BE50 is the sector number used by detect_format)
sek_drive               EQU #BE53       ; 1 byte: Deblocking (Digital Research's CP/M algorithm): drive of the requested record (SELDSK)
sek_track               EQU #BE54       ; 1 byte: Deblocking: track of the requested record (SETTRK)
sek_record              EQU #BE55       ; 1 byte: Deblocking: 128-byte record number within the track (SETSEC)
hst_drive               EQU #BE56       ; 1 byte: Deblocking: drive of the sector in the host buffer
hst_sector              EQU #BE58       ; 1 byte: Deblocking: sector (0-based, records / records per sector) in the host buffer
deblock_flags           EQU #BE59       ; 1 byte: Deblocking flags: bit 7 host buffer written to (hstwrt), bit 6 host buffer valid (hstact), bit 5 sector must be read first (rsflag), bit 4 read operation (readop), bits 3-0 write type of the last WRITE (0 normal, 1 directory, 2 unallocated block)
una_count               EQU #BE5A       ; 1 byte: Deblocking: records left in the unallocated block being written (unacnt)
una_drive               EQU #BE5B       ; 1 byte: Deblocking: drive of the next record of the unallocated block (unadsk)
seek_command            EQU #BE5E       ; 1 byte: FDC command of the current seek_track call: &0F SEEK or &07 RECALIBRATE (sent again on a retry)
step_rate               EQU #BE5F       ; 1 byte: Step rate of the selected drive in ms (bios_setup_disc / specify_for_drive), used by seek_wait per track
dma_address             EQU #BE60       ; 2 bytes: Record buffer address set by SETDMA (bios_setdma); read_record / write_record copy 128 bytes between it and the host buffer
sector_buffer           EQU #BE62       ; 2 bytes: Buffer address of the current sector transfer (fdc_sector_rw)
retry_count             EQU #BE64       ; 1 byte: Number of retries after a disc error (default 16); set by bios_set_retry_count
disc_frame_sp           EQU #BE65       ; 2 bytes: SP of the frame built by disc_begin; disc_end (normal end or fatal error) returns through it
motor_ticker            EQU #BE67       ; 6 bytes: Ticker block of the motor timing (KL ADD TICKER); its event block follows at motor_event_block (&BE6D)
motor_event_block       EQU #BE6D       ; 7 bytes: Firmware event block of the motor on/off ticker: routine motor_event (&CE18) in our ROM, class &80. Set up by disc_init
fdc_command             EQU #BE74       ; 1 byte: FDC command of the current sector transfer: &66 READ DATA, &45 WRITE DATA, &4D FORMAT; its low nibble is also the error message number (&06 Lese-, &05 Schreib-, &0D Formatierfehler)
vdos_workspace          EQU #BE75       ; 2 bytes: Base of VDOS's workspace (AMSDOS's data area, &A700 with AMSDOS as ROM 7); set by rom_init, loaded into IY by cas_dispatcher and load_workspace_iy
cas_oneshot_ptr         EQU #BE77       ; 2 bytes: One-shot CAS pointer (manual 2.0: "Adresse einer DOS-Routine im ROM", default 0): if not 0, cas_dispatcher RETs there instead of the CAS routine - once, it clears it first; the target gets the caller's registers and the unchanged FAR CALL frame. A hook for outside or inside code; purpose unknown - nothing in the OS, BASIC, AMSDOS, VDOS or the disc programs sets it (observed with a test hook at &9100). AMSDOS uses &BE76/&BE77 as its sector buffer pointer and writes it at its init; VDOS disc_init clears it again.
code_key                EQU #BE79       ; 2 bytes: |CODE key (any 16-bit value; 0 = none): when not 0, crypt_record XORs protected files (SAVE ,P) with these 2 bytes instead of the 11-byte crypt_table. Cleared at boot (disc_init clears &BE01-&BF00)
messages_off            EQU #BE7B       ; 1 byte: Disc error messages: 0 = shown, &FF = suppressed (manual; hidden RSX &81 BIOS SET MESSAGE sets it, the HELLO loader switches it off while probing drive A)
eof_test_1a             EQU #BE7C       ; 1 byte: End of file mode of CAS IN CHAR / TEST EOF (manual appendix 'Das EOF Problem'): 0 = only the physical end of the file (|DERROR,3; default after reset: MERGE of BASIC programs works, ASCII files read up to 127 bytes of &1A padding), &FF = &1A also ends the file (|DERROR,2, AMSDOS behaviour). Set by rsx_derror; observed: 0 -> padding read, &FF -> stops at &1A
drives_swapped          EQU #BE7F       ; 1 byte: Drives swapped flag: 0 = normal, 3" drive is A and Vortex drive is B (default, set by rom_init); 1 = swapped, Vortex drive is A. Toggled by |X (rsx_x), used by setup_drive_tables to place the XPBs; kept across disc_init's RAM clear
fdc_sector              EQU #BEBF       ; 1 byte: Sector number R of the current transfer
fdc_last_sector         EQU #BEC0       ; 1 byte: Last sector EOT of the current transfer (= fdc_sector, or B in multi-sector mode)

; ---- xmon: XMON monitor variables (&BEC8-&BEFF, breakpoints &BF00, work areas in BASIC's input buffer &ACA4) ----
xmon_text_length        EQU #ACA4       ; 1 byte: XMON: the length of the text read by xmon_input_text (A); the text itself follows at &ACA5 (255 bytes, the same place as xmon_decoded). Observed 3 for "XYQ". Lies in BASIC's input buffer
xmon_decoded            EQU #ACA5       ; 5 bytes: XMON disassembler work area in BASIC's input buffer: +0 length - 1, +1 mnemonic number, +2 operand 1, +3 operand 2 (&FF = none), +4 index prefix (0, &64 = DD / IX, &65 = FD / IY). Set by xmon_list_line (observed)
xmon_rom                EQU #BEC8       ; 1 byte: XMON: number of the upper ROM that XMON shows at &C000 (Y command, manual); &FC-&FF = no ROM, the RAM (screen memory) is read with the upper ROM off. rsx_xmon sets it to this ROM at the start (observed 5); Y set it to &FF (observed)
xmon_firmware_rom       EQU #BEC9       ; 1 byte: XMON X switch (manual): 0 = firmware ROM off (RAM at &0000-&3FFF), &FF = on. rsx_xmon sets 0 (observed); X toggles it (observed 2026-10-25: 0 -> &FF -> 0)
xmon_break_far          EQU #BED0       ; 3 bytes: XMON: far address used by the RST 6 at &0030 (PUSH IY / RST 3 / DEFW &BED0): xmon_breakpoint (&F8D9) in this ROM. Written by rsx_xmon via xmon_set_far_jump (observed D9 F8 05)
xmon_subst_address      EQU #BED3       ; 2 bytes: XMON: the current address of S (observed 2026-10-26: &4003 after S4000 and three RETURNs). The manual says "aktuelle Adresse für M Kommando" - but M does not use it (its default is a fixed 0000); S does: corrected
xmon_list_address       EQU #BED5       ; 2 bytes: XMON current address for L (manual): the next instruction to disassemble; default start of the next L. Observed: &4148 after L4000,4148
xmon_fill_address       EQU #BED7       ; 2 bytes: XMON: the start address of F (manual: "aktuelle Adresse für F Kommando") and of A - one shared default: F and A both offer it and store their start address there (observed: A9000 -> F offered 9000; F4030 + ESC -> &4030). Not advanced after the fill / text
xmon_dump_address       EQU #BED9       ; 2 bytes: XMON current address for D (manual): the start of the next dump line; default start of the next D. Observed: &0100 after D0000,0100
xmon_cpm_flag           EQU #BEDD       ; 1 byte: XMON CP/M flag (manual): 0 = VDOS (BASIC) active, &FF = CP/M active; tested by xmon_cpm_mode (observed 0 from BASIC). Set to &FF by the CP/M program XMON.COM before it jumps to rsx_xmon (observed 2026-10-26 after |CPM,2)
xmon_saved_sp           EQU #BEDE       ; 2 bytes: XMON: the caller's stack pointer, saved by rsx_xmon (observed &BFF4 from BASIC); xmon_command_loop goes back to it before every prompt
xmon_bank               EQU #BEE0       ; 1 byte: XMON bank of the Vortex RAM expansion for memory accesses (manual: "interne Variable"): 0 = off, &20 + n = bank n (0-7), set by xmon_cmd_z (observed: Z 03 -> &22). Written to port &FBBD by the memory access routine (&FB7C); port &FBBD (owner): bits 7, 6 ignored, bit 5 = expansion on, bits 2-0 = bank
xmon_branch_byte        EQU #BEE2       ; 1 byte: XMON T: the byte under the breakpoint at the branch target (xmon_branch_target), put back by xmon_breakpoint when trace flag bit 7 of &BEFF is set (manual: "Opcode Zwischenspeicher"; observed &C9 for the JP (IY) target &403E)
xmon_branch_target      EQU #BEE3       ; 2 bytes: XMON: the last word / jump target shown by the disassembler (manual: "Zwischenspeicher für Programmverzweigungen"); written for nn operands and relative jumps. T puts its target breakpoint there (also user HL / IX / IY for JP (HL) / (IX) / (IY), or the stack word for RST 1 / 5) and xmon_breakpoint puts xmon_branch_byte back (observed &403E)
xmon_run_sp             EQU #BEE5       ; 2 bytes: XMON: its own SP while a user program runs (G / T; manual: "Zwischenspeicher für Stackpointer"); set by xmon_run, taken back by xmon_breakpoint (observed &BFF4)
xmon_run_address        EQU #BEE7       ; 2 bytes: XMON: the start address of the last G / T step (manual: "Zwischenspeicher für HL" - it is the HL given to xmon_run); xmon_breakpoint puts xmon_run_byte back there (observed &4000)
xmon_trace_count        EQU #BEE9       ; 2 bytes: XMON: the number of trace steps left (manual: "Anzahl Traceschritte"), counted down by xmon_breakpoint; negative = stop (G passes &EDA1, observed)
xmon_run_byte           EQU #BEEB       ; 1 byte: XMON: the byte at the start address of G (manual: "Zwischenspeicher für AF", 2 bytes - but &BEEC is user AF; observed as one byte: &3E for G4000); put back by xmon_breakpoint
xmon_user_af            EQU #BEEC       ; 2 bytes: XMON user AF (manual) for G / T; shown and changed by R (observed 2026-10-26: 1234 stored as 34 12). Start of the 7 user pairs AF BC DE HL IX IY SP
xmon_user_bc            EQU #BEEE       ; 2 bytes: XMON user BC (manual) for G / T; changed by R (observed)
xmon_user_de            EQU #BEF0       ; 2 bytes: XMON user DE (manual) for G / T; changed by R (observed)
xmon_user_hl            EQU #BEF2       ; 2 bytes: XMON user HL (manual) for G / T; shown by R (the R loop runs over it)
xmon_user_ix            EQU #BEF4       ; 2 bytes: XMON user IX (manual) for G / T; shown by R (the R loop runs over it)
xmon_user_iy            EQU #BEF6       ; 2 bytes: XMON user IY (manual) for G / T; shown by R (the R loop runs over it)
xmon_user_sp            EQU #BEF8       ; 2 bytes: XMON user SP (manual): loaded by xmon_run for G / T and taken back by xmon_breakpoint (observed &BF80 before and after the G tests); rsx_xmon sets it to the monitor stack &BF80
xmon_user_jump          EQU #BEFA       ; 1 byte: XMON: &C3 (JP) put here by xmon_run, so &BEFA-&BEFC = JP xmon_user_pc - the user program is entered by a RET to &BEFA (observed C3 05 40). Manual: "interne Variable"
xmon_user_pc            EQU #BEFB       ; 2 bytes: XMON user PC (manual) for G / T; shown by R as "XP", edited after SP (R skips the internal byte &BEFA)
xmon_index_disp         EQU #BEFD       ; 1 byte: XMON L: the displacement d of an (IX+d) / (IY+d) instruction (manual: "Distanz bei relativen Z80 Befehlen"; research: REL_DISTANCE_Z80_CMD). Written by xll_index (&F202) from the byte after the opcode, shown by xlo_hl_ind (&F2B4) unsigned (observed 2026-10-26: d = &05 and &FD). Relative jumps do not use it (xlo_fb reads the byte itself)
xmon_printer_saved      EQU #BEFE       ; 1 byte: XMON: the printer switch kept by xmon_hex_byte_quiet (manual: "internes Flag"); xmon_input_byte / _word put it back into xmon_printer_switch after each quiet output, xmon_edit_word does not (bug, observed)
xmon_printer_switch     EQU #BEFF       ; 1 byte: XMON flags (manual: "internes Flag"): bit 0 = printer echo, set / cleared by P (observed 00 -> 01 -> 00), tested by xmon_out_char; bits 7-5 = trace flags of T (tested by xmon_breakpoint &F904, not observed yet). xmon_hex_byte_quiet clears bit 0 for a moment and keeps the old value in xmon_printer_saved

; ---- basic: BASIC 1.0 (CPC 464) variables used by VDOS ----
basic_stmt_ptr          EQU #AE34       ; 2 bytes: BASIC 1.0 (464): address of the byte before the current statement (&003F in direct mode); memory map, read by basic_error_patch
basic_vacc              EQU #B0C2       ; 5 bytes: BASIC 1.0 (464): virtual accumulator of the maths routines (2 bytes integer, 3 bytes string descriptor, 5 bytes real); for a string result the first word holds the address of its descriptor (e.g. &B09C, the string concatenation area); memory map

; ---- cpm: CP/M 2.2 variables (BIOS/BDOS) used by VDOS ----
bios_entry              EQU #B046
bios_entry_target       EQU #B047       ; 2 bytes: Jump address of bios_entry: bios_entry_handler (reg_save_mode 0) or bios_entry_fast (&FF); set by install_entry_handler
firmware_int_vector     EQU #B049       ; 2 bytes: The firmware's interrupt jump address (the word at &0039, &B939 on the 464), saved by the |CPM,1 boot; bios_entry_enter puts it back while firmware code runs
firmware_bc_alt         EQU #B04B       ; 2 bytes: The firmware's BC' (B = &7F gate array port, C = its ROM/mode state, &7F86 observed); loaded into BC' for each firmware call and saved again after it
con_cursor_count        EQU #B04D       ; 1 byte: Console cursor-off counter (IX+0 of the character I/O): con_crt_out sets &FF and hides the cursor, con_crt_status counts it down and switches the cursor on at 0, con_crt_in clears it (cursor on). Cleared by cpm_cold_boot
autostart_flag          EQU #B04E       ; 1 byte: Autostart string flag (IX+1), A of SET CMND BUFFER: 0 = a key pressed during the string cancels the rest, else the key is returned first and the string goes on (both observed). The Vortex boot sector passes &FF
autostart_ptr           EQU #B04F       ; 2 bytes: Autostart string: pointer to the next character (IX+2/3), set to &B052 by bios_set_cmnd_buffer
autostart_count         EQU #B051       ; 1 byte: Autostart string: characters left (IX+4) - the length byte copied by bios_set_cmnd_buffer; con_crt_in takes characters while it is not 0
autostart_string        EQU #B052       ; 128 bytes: Autostart string (INSTALL, parameter sector): up to 128 characters, copied by bios_set_cmnd_buffer; observed: DIR + &0D
bios_caller_sp          EQU #B0D2       ; 2 bytes: Stack pointer of the CP/M caller while bios_entry runs on its own stack below &C000
reg_save_mode           EQU #B0D4       ; 1 byte: bios_set_reg_save: 0 = bios_entry saves the alternate registers, IX and IY (default, set by the |CPM,1 boot); &FF = bios_entry_fast, no saving (BC' must keep the firmware's value)
sio_wr5                 EQU #BE01       ; 2 bytes: Copies of the DART write register 5 (DTR, Tx bits, Tx enable, RTS) for the status handshake: +0 meant for channel A, +1 for channel B - but the code tells the channels apart by bit 0 of the control port, which is 1 for both (&FADD, &FADF), so both use +1 (&BE02) and +0 stays 0 (observed: &00 &6A after SET SIO). Set by dart_init_channel, used by sio_in_status
fast_flag               EQU #BE7C       ; 1 byte: Under CP/M: FAST flag (manual), toggled by bios_select_format A = &FE: 0 = normal text output (TXT RESET), else the |FAST patch (fast_install). Code read, not observed
cpm_rom_iy              EQU #BE7D       ; 2 bytes: IY for the ROM code under CP/M, saved by the |CPM,1 boot (&AB68 observed; what it points to: open)

; ---- bdos: VDOS's internal BDOS (Vortex's implementation after Digital Research's CP/M 2.2 BDOS) - &BE09-&BE2D; the boot hook borrows &BE24-&BE2D before ----
bdos_dph                EQU #BE09       ; 2 bytes: DPH of the drive selected by bdos_select_fcb_drive
bdos_xlt                EQU #BE0B       ; 2 bytes: Sector translation table of that drive (DPH+0; 0 = none)
bdos_dirbuf             EQU #BE0D       ; 2 bytes: Directory record buffer (DPH+8, DIRBUF)
bdos_dpb                EQU #BE0F       ; 2 bytes: Disc parameter block = XPB of the drive (DPH+10)
bdos_csv                EQU #BE11       ; 2 bytes: Directory checksum vector (DPH+12, CSV) - detects a changed disc
bdos_alv                EQU #BE13       ; 2 bytes: Allocation vector (DPH+14, ALV): one bit per block, 1 = used
dpb_spt                 EQU #BE15       ; 2 bytes: DPB copy: 128-byte records per track
dpb_bsh                 EQU #BE17       ; 1 byte: DPB copy: block shift (3 = 1K blocks)
dpb_blm                 EQU #BE18       ; 1 byte: DPB copy: block mask (records per block - 1)
dpb_exm                 EQU #BE19       ; 1 byte: DPB copy: extent mask
dpb_dsm                 EQU #BE1A       ; 2 bytes: DPB copy: highest block number (< 256: one byte per block in the FCB)
dpb_drm                 EQU #BE1C       ; 2 bytes: DPB copy: highest directory entry number
dpb_al                  EQU #BE1E       ; 2 bytes: DPB copy: AL0/AL1, the directory's blocks as bits (put into the ALV at login)
dpb_cks                 EQU #BE20       ; 2 bytes: DPB copy: size of the checksum vector (directory records checked)
dpb_off                 EQU #BE22       ; 2 bytes: DPB copy: reserved tracks (the directory starts there)
bdos_fcb                EQU #BE24       ; 2 bytes: BDOS 'info': address of the current FCB (bdos_call_*); the boot hook keeps the KM DISARM BREAK address here first (km_disarm_break_saved)
dir_count               EQU #BE26       ; 2 bytes: BDOS 'dcnt': number of the current directory entry (&FFFF = before the first / end)
actual_record           EQU #BE28       ; 2 bytes: BDOS 'arecord': block number from the FCB, then (block_to_record) the record number on the disc
bdos_dma                EQU #BE2A       ; 2 bytes: DMA address of the BDOS caller, set again after directory access (set_dma_again)
virtual_record          EQU #BE2C       ; 1 byte: BDOS 'vrecord': current record within the extent (FCB byte 32, cr)
record_count            EQU #BE2D       ; 1 byte: BDOS 'rcount': records in the extent (FCB byte 15, rc)

        OUTPUT "VDOS-2.11-X.rom"
        ORG #C000

rom_type:
        defb #01                        ; background ROM
rom_mark:
        defb #01
rom_version:
        defb #21
rom_modification:
        defb #03
rom_name_pointer:
        defw rom_name_table             ; name table
rom_jumpblock:
        jp rom_init                     ; ROM init "V ROM"
        jp rsx_get                      ; RSX "GET"
rom_jumpblock_put:
        jp rsx_put                      ; RSX "PUT"
        jp rsx_files                    ; RSX "FILES"
        jp rsx_open                     ; RSX "OPEN"
        jp rsx_close                    ; RSX "CLOSE"
        jp rsx_field                    ; RSX "FIELD"
        jp rsx_cpm                      ; RSX "CPM"
        jp rsx_disc                     ; RSX "DISC"
        jp rsx_disc_in                  ; RSX "DISC.IN"
        jp rsx_disc_out                 ; RSX "DISC.OUT"
        jp rsx_cas                      ; RSX "CAS"
        jp rsx_cas_in                   ; RSX "CAS.IN"
        jp rsx_cas_out                  ; RSX "CAS.OUT"
        jp rsx_a                        ; RSX "A"
        jp rsx_b                        ; RSX "B"
        jp rsx_select                   ; RSX "SELECT"
        jp rsx_dir                      ; RSX "DIR"
        jp rsx_era                      ; RSX "ERA"
        jp rsx_ren                      ; RSX "REN"
        jp rsx_reset                    ; RSX "RESET"
        jp rsx_format                   ; RSX "FORMAT"
