; ----------------------------------------------------------------------
; Subroutine: basic_error_patch [#BEA1] (RAM, from &C117)
; Tasks:        BASIC 1.0 error indirection (basic_error_indirection &AC04 = JP here). Lets RSX
;               commands and CALL take string literals on BASIC 1.0, e.g. |DIR,"*.COM" -
;               BASIC 1.0 itself only allows @a$. Their parameters must be numbers: BASIC
;               evaluates the string anyway and then raises error 13 (Type mismatch). For error
;               13 in a statement that starts with '|' or the CALL token &83 the patch takes the
;               string's descriptor address from BASIC's virtual accumulator as the parameter
;               value - what @a$ would pass - drops two return addresses of the error path and
;               lets BASIC go on. Any other error: RET, BASIC reports it.
;               Observed with |DIR,"*.COM": E = &0D, statement at &0040, descriptor at &B09C;
;               the directory was listed correctly. Where BASIC goes on is inferred from the
;               code (two return addresses dropped).
;               Limit (observed with |PUT): every string literal passed this way stays on BASIC's
;               stack of temporary strings - the patch never releases it. The 5th |PUT with two
;               literals gives "String expression too complex" (and BASIC can get into a bad
;               state afterwards); in loops use @a$.
; Input:        E = error number
; Changed:      AF, DE, HL
; Called by:    BASIC 1.0 through basic_error_indirection (&AC04)
; Calls:        RAM_LAM (RST 4)
basic_error_patch:
        ld a,e                          ; E = BASIC error number
        cp #0D                          ; error 13 (Type mismatch)?
        ret nz                          ; no: BASIC reports the error
        ld hl,(basic_stmt_ptr)          ; address of the byte before the current statement (&003F in direct mode) ...
        inc hl                          ; ... its first character
        rst #20                         ; RAM LAM; read it from RAM (the ROMs are paged in)
        cp #7C                          ; '|': an RSX command?
        jr z,bep_drop_error
        cp #83                          ; the CALL token?; [static]
        ret nz                          ; neither: BASIC reports the error; [static]
; '|' or CALL: drop the error
bep_drop_error:
        ld hl,(basic_vacc)              ; HL = virtual accumulator: address of the string's descriptor (&B09C here) = the parameter value
        pop de                          ; drop two return addresses of BASIC's error path ...
        pop de
        ret                             ; ... and go back into BASIC as if no error had happened
        ENT                             ; end of DISP #BE8F
; ---- end of RAM copy #BE8F-#BEB6 (from #C105) ----

