        jp vdos_cas_in_close            ; CAS IN CLOSE (&BC7A)
        jp vdos_cas_in_abandon          ; CAS IN ABANDON (&BC7D)
        jp vdos_cas_in_char             ; CAS IN CHAR (&BC80)
