        jp vdos_cas_return              ; CAS RETURN (&BC86) (BASIC does not call it here - its EOF reaches vdos_cas_return through CAS TEST EOF; observed with a machine-code CALL)
        jp vdos_cas_test_eof            ; CAS TEST EOF (&BC89)
        jp vdos_cas_out_open            ; CAS OUT OPEN (&BC8C)
        jp vdos_cas_out_close           ; CAS OUT CLOSE (&BC8F)
        jp vdos_cas_out_abandon         ; CAS OUT ABANDON (&BC92)
