; Data: xpb_3inch [#C154]
; Contents:     25-byte extended disc parameter block (XPB) of the 3" drive, system format:
;               the CP/M DPB (15 bytes) followed by the Vortex extension (10 bytes).
;               Last 3 bytes, as drive A: +&16 ATRK (current track, start value &27), +&17 the
;               flag byte (no MTRK byte!), +&18 unused. As drive B (|X, drives_swapped = 1)
;               setup_drive_tables writes +&17 = &27 (MTRK 39) and +&18 = &20 (flag), the layout
;               of xpb_vortex. Observed both (|X).
; Used by:      setup_drive_tables (copied to drive A's or B's DPB slot)
xpb_3inch:
        defw #0024                      ; SPT: 36 records per track (9 x 512 bytes)
        defb #03                        ; BSH 3: 1K blocks
        defb #07                        ; BLM 7
        defb #00                        ; EXM 0
        defw #00AA                      ; DSM 170: 171 blocks of 1K
        defw #003F                      ; DRM 63: 64 directory entries
        defb #C0                        ; AL0 &C0: blocks 0-1 hold the directory
        defb #00                        ; AL1 &00
        defw #0010                      ; CKS 16: check vector for 64 entries
        defw #0002                      ; OFF 2: two system tracks
        defb #41                        ; first sector &41 (system format, sectors &41-&49)
        defb #09                        ; 9 sectors per track
        defb #2A                        ; GAP read/write &2A
        defb #52                        ; GAP format &52
        defb #E5                        ; filler &E5
        defb #02                        ; N 2: 512 bytes per sector
        defb #04                        ; 4 records per sector
        defb #27                        ; &27: ATRK, the current physical track (seek_track); &27 is only the start value, the first seek overwrites it (observed: 2 after CAT, &17 after reading ROINTIME.DEM)
        defb #20                        ; &20: as drive A the FLAG byte (drive_flag_offset: +&17; bit 5 = 3" drive; observed &28 = + bit 3 motors running) - so as drive A this XPB has no MTRK byte; as drive B setup_drive_tables writes MTRK &27 (39) here
        defb #00                        ; &00: unused as drive A; as drive B the flag byte &20 (read at +&18)
