        defb #00                        ; AL1 &00
        defw #0020                      ; CKS 32: check vector for 128 entries
        defw #0002                      ; OFF 2: two system tracks
        defb #01                        ; first sector 1
        defb #09                        ; 9 sectors per track
        defb #2A                        ; GAP read/write &2A
        defb #52                        ; GAP format &52
        defb #E5                        ; filler &E5
        defb #02                        ; N 2: 512 bytes per sector
        defb #04                        ; 4 records per sector
        defb #4F                        ; &4F: current physical track (ATRK per the manual)
        defb #4F                        ; &4F: last track 79 (MTRK)
        defb #01                        ; &01: flag byte (bit 0 = heads - 1: two heads; bit 5 = 0: not a 3" drive)
