; ----------------------------------------------------------------------
; Subroutine: cas_dispatcher [#C1C2]
; Tasks:        Common entry of all 13 CAS jumpblock entries. AMSDOS makes each entry
;               &BC77-&BC9B "RST 3 / defw &A88B" (FAR CALL through one far address in its data
;               area); rom_init points that far address to here (ROM 5). The firmware's FAR CALL
;               leaves 3 words on the stack, below them the address after the called entry
;               (e.g. &BC80 for CAS IN ABANDON at &BC7D). The dispatcher takes that word out
;               (the frame moves up one word, so the routine returns straight to the CAS
;               caller and not into the next jumpblock entry), adds &04B3 and RETs to the
;               result: &BC7A..&BC9E -> cas_jump_table &C12D..&C151 (13 JPs).
;               Observed: CAT, LOAD, SAVE, OPENIN/OPENOUT, INPUT#, PRINT#, EOF, LINE INPUT#.
;               One-shot pointer cas_oneshot_ptr (&BE77, manual: "address of a DOS routine in ROM"): if
;               not 0 it RETs there once instead, with the caller's registers and the FAR CALL
;               frame unchanged, and clears it. Nothing in the ROMs (OS, BASIC, AMSDOS, VDOS)
;               or on the discs sets it; observed with a test hook at &9100 that re-entered
;               cas_dispatcher - CAT then ran normally.
; Input:        AF, BC, DE, HL: the CAS function's parameters (passed on unchanged)
; Output:       whatever the CAS function returns; IY = VDOS workspace
; Changed:      IY, alternate registers
; Called by:    CAS jumpblock &BC77-&BC9B via FAR CALL (far address at AMSDOS data area+&18B)
cas_dispatcher:
        di                              ; no interrupts: the firmware keeps BC' (gate array / ROM state) in the alternate set, which is used now
        ld iy,(vdos_workspace)          ; IY = VDOS workspace (&A700) for the CAS routines
        ex af,af'                       ; caller's AF into AF' ...
        exx                             ; ... and BC, DE, HL into the alternate set: work with the other set
        ld hl,(cas_oneshot_ptr)         ; a one-shot target address set?
        ld a,h
        or l
        jr z,cd_by_entry                ; 0 (normal; nothing in the ROMs or on the discs sets it): dispatch by the jumpblock entry
        push hl                         ; set (observed with a test hook at &9100, entered at CAS IN ABANDON of CAT): RET goes there ...
        ld hl,#0000                     ; ... and it is cleared: one shot only (observed: &BE77 = 0 when the hook ran) ...
        ld (cas_oneshot_ptr),hl
        jr cd_restore_registers         ; ... caller's registers back; the FAR CALL frame stays as it is (not moved), so the hook must deal with it - e.g. re-enter cas_dispatcher (done by the test hook: CAT then ran normally)
cd_by_entry:
        pop af                          ; take the three words of the firmware's FAR CALL frame off the stack ...
        pop de                          ; (2nd word)
        pop hl                          ; (3rd word)
        ex (sp),hl                      ; HL = 4th word = address after the called CAS entry (&BC7A..&BC9E); 3rd word into its place
        push de                         ; put the frame back, one word higher: after the routine the firmware returns to the CAS caller
        push af
        ld de,#04B3                     ; entry address + &04B3 ...
        add hl,de                       ; ... = its JP in cas_jump_table (&BC7A -> &C12D)
        push hl                         ; RET target
cd_restore_registers:
        exx                             ; caller's BC, DE, HL back
        or a                            ; clear the carry of the scratch AF (it goes to AF'; purpose not clear)
        ex af,af'                       ; caller's AF back
        ei
        ret                             ; jump to the CAS routine (or to &BE77's address)
; ----------------------------------------------------------------------
; Subroutine: rom_init [#C1E9]
; Tasks:        ROM init of VDOS, called by the firmware's ROM walk (KL INIT BACK, ROM 7 -> 0).
;               With AMSDOS (ROM 7): use AMSDOS's data area as VDOS workspace (no RAM reserved),
;               clear its first 256 bytes, set up the disc system (disc_init), point the far
;               address of all 13 CAS jumpblock entries to cas_dispatcher, hook KM DISARM BREAK
;               for the deferred start-up, print the banner (message &0E).
;               Without AMSDOS (observed with output/machine_noamsdos.toml, no ROM 7): reserve
;               &500 bytes below the highest free address (&ABFF -> workspace &A700, ROM number
;               &85 = bit 7 "own workspace"), keep the original tape CAS entries at
;               workspace+&164, set the far address at workspace+&18B to cas_dispatcher and
;               switch the CAS entries to disc (|DISC: DF 8B A8 = RST 3 via &A88B). The RAM
;               layout is the same as with AMSDOS (HIMEM &A67B); banner, CAT work.
;               VDOS as ROM 0 (observed 2026-10-26 with output/machine_vdos_rom0.toml: VDOS alone
;               in upper slot 0, no BASIC, no AMSDOS; own analysis target rom0): the firmware starts
;               ROM 0 as the foreground program and enters here (DE = &0040, HL = &ABFF);
;               KL CURR SELECTION = 0 -> rom_init_foreground -> MC START PROGRAM cpm_cold_boot:
;               clear_memory, disc_init, bios_setup_disc, install_entry_handler, the boot sector
;               from A: (bios_read_sector, ~1 s motor spin-up) -> "CP/M 2.2 - Amstrad Consumer
;               Electronics plc", " 44K CP/M vers. 2.2-07/86    vortex GmbH", "A>". That boot read
;               no ROM byte that the main analysis had not read before.
; Input:        DE = lowest free address, HL = highest free address
; Output:       CY = 1 (ROM initialised); DE, HL = new RAM limits (unchanged with AMSDOS); IY kept
; Changed:      AF, BC
; Called by:    firmware ROM walk via rom_jumpblock (first jumpblock entry); as ROM 0 the firmware's
;               start of the foreground program
; Calls:        KL_CURR_SELECTION, disc_init, clear_memory, workspace_offset, rsx_disc,
;               hook_km_disarm_break, print_message; rom_init_foreground (MC START PROGRAM)
; RAM:          vdos_workspace, drives_swapped, &BE03, &BE2D; workspace+&45, +&69; the far address at
;               workspace+&18B (&A88B; with AMSDOS that is AMSDOS's data area+&18B)
rom_init:
        call KL_CURR_SELECTION          ; A = our ROM number (5 here)
        or a                            ; ROM 0 = VDOS is the foreground ROM?
        jp z,rom_init_foreground        ; yes: boot CP/M (does not return; observed with VDOS as ROM 0, output/machine_vdos_rom0.toml)
        push iy                         ; save IY and the RAM limits for the firmware
        push de
        push hl
        ld hl,(KL_ROM_IY_TABLE+14)      ; HL = data area of ROM 7 (AMSDOS), &A700 here
        ld e,a                          ; keep our ROM number
        ld a,h                          ; data area 0 = no AMSDOS in ROM 7?
        or l
        ld a,e                          ; A = our ROM number again
        jr nz,rom_init_workspace        ; AMSDOS there: VDOS shares its data area, reserves no RAM
        pop hl                          ; no AMSDOS (observed with a machine without ROM 7): HL = highest free address (&ABFF) ...
        ld de,#0500                     ; ... reserve &500 bytes of own workspace below it (as much as AMSDOS takes: HIMEM is &A67B as with AMSDOS, observed)
        sbc hl,de                       ; (HL = &A6FF)
        push hl                         ; new highest free address, returned in HL at the end
        inc hl                          ; workspace starts one byte above it (&A700, observed)
        set 7,a                         ; bit 7 of the ROM number = VDOS has its own workspace (observed: A = &85)
rom_init_workspace:
        push hl                         ; HL = workspace base (AMSDOS's data area, &A700 here)
        pop iy                          ; IY = workspace (offsets below are from here)
        push af                         ; save ROM number + own-workspace flag
        push hl                         ; save workspace base
        xor a
        ld (drives_swapped),a           ; drives_swapped = 0: normal, the 3" drive is drive A (setup_drive_tables puts the 3" XPB in drive A's DPB); |X toggles it
        call disc_init                  ; disc_init: motors off, clear &BE01-&BF00, motor event, FDC SPECIFY, DPHs/DPBs, retry count 16
        pop de
        ld (vdos_workspace),de          ; remember the workspace base
        ld b,#00                        ; 256 bytes
        call clear_memory               ; clear workspace+0..&FF (&A700-&A7FF here)
        ld a,#FF
        ld (iy+#45),a                   ; workspace+&45 = &FF: input FCB closed
        ld (iy+#69),a                   ; workspace+&69 = &FF: output FCB closed
        ld (autodetect_format),a        ; autodetect_format = &FF: SELDSK detects the 3" disc's format (disc_init had cleared it; observed: data format disc under BASIC)
        pop af
        bit 7,a                         ; own workspace (no AMSDOS)?
        push af
        jr z,rom_init_amsdos_far        ; no: use AMSDOS's CAS entries
        ld hl,CAS_IN_OPEN               ; no AMSDOS (observed): save the 13 tape CAS entries &BC77-&BC9D ...
        ld de,#0164                     ; ... at workspace+&164 (&A864: CF xx xx = RST 1 into the OS tape code, observed) ...
        call workspace_offset           ; DE = workspace+&164
        ld bc,#0027                     ; 13 entries of 3 bytes
        ldir                            ; keep the original CAS entries in the workspace (|CAS / |TAPE use them)
        ex de,hl                        ; HL = workspace+&18B: VDOS's own far address (observed: C2 C1 05 = cas_dispatcher, ROM 5; the CAS entries then read DF 8B A8 = RST 3 via &A88B)
        jr rom_init_set_far
rom_init_amsdos_far:
        ld hl,(KL_ROM_IY_TABLE+14)      ; AMSDOS present: HL = AMSDOS's data area
        ld de,#018B
        add hl,de                       ; HL = AMSDOS data area+&18B (&A88B): far address of its CAS entries (RST 3), held &CD30 in ROM 7
rom_init_set_far:
        ld de,cas_dispatcher            ; HL = far address called by all 13 CAS jumpblock entries: point it to VDOS's CAS dispatcher
        ld (hl),e                       ; far address = cas_dispatcher ...
        inc hl
        ld (hl),d
        inc hl
        pop af                          ; ROM number + flag
        bit 7,a
        res 7,a
        ld (hl),a                       ; ... in our ROM: every CAS call now enters VDOS
        call nz,rsx_disc                ; own workspace: also switch the CAS entries to disc (|DISC; not observed)
        ld a,#02
        ld (disarm_break_count),a       ; &BE2D = 2: KM DISARM BREAK calls until the post-boot setup at &C2B4 (counted down by the hook)
        call hook_km_disarm_break       ; hook KM DISARM BREAK (&BB48)
        ld a,#0E
        call print_message              ; print "(C)1986 VDOS 2.11-X by vortex GmbH"
        pop hl                          ; RAM limits back for the firmware (unchanged with AMSDOS)
        pop de
        pop iy
        scf                             ; CY=1: init done
        ret
; ----------------------------------------------------------------------
; Subroutine: load_workspace_iy [#C269]
; Tasks:        IY = VDOS workspace (vdos_workspace); entry point for the DOS routines.
; Output:       IY = workspace
; Changed:      IY
; Called by:    the DOS routines (set_disc_entries, rsx_reset, ...)
load_workspace_iy:
        ld iy,(vdos_workspace)          ; IY = VDOS workspace
        ret
; ----------------------------------------------------------------------
; Subroutine: km_disarm_break_hook [#C26E]
; Tasks:        Entered when BASIC calls KM DISARM BREAK (&BB48) while the hook is armed
;               (RST 3 FAR CALL via km_disarm_break_far). First makes the RST 3 entry behave
;               like a jump: the return address &BB4B behind the 3-byte entry is removed, so the
;               far return goes straight back to BASIC. Then counts disarm_break_count down:
;               first call (2 -> 1): unhook, call the real KM DISARM BREAK, arm the hook again;
;               second call (1 -> 0): post_boot_setup - the real KM DISARM BREAK is not called.
;               Observed: BASIC 1.0 calls KM DISARM BREAK twice during its start-up.
; Input:        registers of the caller (kept, through EXX)
; Changed:      AF, BC, DE, HL
; Called by:    BASIC via the KM DISARM BREAK jumpblock entry (FAR CALL)
; Calls:        unhook_km_disarm_break, KM_DISARM_BREAK, hook_km_disarm_break (falls in), post_boot_setup; falls through into hook_km_disarm_break
km_disarm_break_hook:
        di                              ; no interrupts while the stack is rearranged
        exx                             ; keep the caller's BC, DE, HL
        pop af                          ; the three words of the firmware's FAR CALL frame ...
        pop de
        pop hl
        ex (sp),hl                      ; ... move up one slot over the return address &BB4B (behind the RST 3 entry) ...
        push de
        push af                         ; ... so the far routine returns straight to BASIC: the RST 3 entry acts like a jump
        exx                             ; caller's registers back
        ei
        ld a,(disarm_break_count)       ; count the KM DISARM BREAK calls (rom_init set 2)
        dec a                           ; one call less
        ld (disarm_break_count),a       ; keep the count
        jr z,post_boot_setup            ; second call: post-boot set-up
        call unhook_km_disarm_break     ; first call: original KM DISARM BREAK back ...
        call KM_DISARM_BREAK            ; ... do what BASIC asked for, then arm the hook again (falls into hook_km_disarm_break)
; ----------------------------------------------------------------------
; Subroutine: hook_km_disarm_break [#C287]
; Tasks:        Hook the firmware entry KM DISARM BREAK (&BB48), which BASIC calls during its
;               start-up, so that VDOS gets control again after the ROM walk: build the far
;               address km_disarm_break_far = &C26E in our ROM, turn &BB48 into RST 3 / defw
;               &BE26 and keep the original entry's address (RST 1 / LOW JUMP &9C82 on the 464)
;               in km_disarm_break_saved for unhook_km_disarm_break.
; Input:        -
; Output:       -
; Changed:      AF, DE, HL
; Called by:    rom_init; km_disarm_break_hook (falls in after the first call)
; Calls:        KL_CURR_SELECTION
hook_km_disarm_break:
        ld hl,km_disarm_break_far       ; far address object at &BE26
        ld (hl),#6E                     ; far address: routine &C26E ...
        inc hl
        ld (hl),#C2                     ; far address = &C2xx ... (hook routine in this ROM)
        inc hl
        call KL_CURR_SELECTION          ; ... and our ROM number
        ld (hl),a                       ; ... in our ROM
        ld hl,#BB4A                     ; KM DISARM BREAK entry &BB48 (address bytes at &BB49/&BB4A)
        ld d,(hl)                       ; D = old high address byte ...
        ld (hl),#BE                     ; ... new: &BE
        dec hl
        ld e,(hl)                       ; E = old low address byte ...
        ld (hl),#26                     ; ... new: &26 (address &BE26)
        dec hl
        ld (hl),#DF                     ; RST 3 (FAR CALL) instead of RST 1 (LOW JUMP, &CF)
        ld (km_disarm_break_saved),de   ; keep the original address (&9C82 on the 464)
        ret
; ----------------------------------------------------------------------
; Subroutine: unhook_km_disarm_break [#C2A6]
; Tasks:        Restore KM DISARM BREAK: &BB48 = RST 1 / defw (km_disarm_break_saved).
; Changed:      DE, HL
; Called by:    km_disarm_break_hook (first call), post_boot_setup
unhook_km_disarm_break:
        ld hl,#BB4A                     ; Restore KM DISARM BREAK: &BB48 = RST 1 / defw (km_disarm_break_saved)
        ld de,(km_disarm_break_saved)   ; the saved address of the original entry ...
        ld (hl),d                       ; ... back into &BB49/&BB4A
        dec hl
        ld (hl),e
        dec hl
        ld (hl),#CF                     ; &BB48 = &CF: RST 1 (LOW JUMP) again
        ret
; ----------------------------------------------------------------------
; Routine: post_boot_setup [#C2B4]
; Tasks:        Post-boot set-up at BASIC's second KM DISARM BREAK call (BASIC has initialised
;               its own indirections by then): unhook KM DISARM BREAK, copy the DOS indirections
;               and the BASIC error patch (&C105-&C12C, 40 bytes) to &BE8F-&BEB6, set BASIC 1.0's
;               error indirection &AC04 (was RET) to JP basic_error_patch. Unless a key is
;               waiting, copy the HELLO loader (&C2DE, 63 bytes) to &BF00 and jump there; it
;               returns to BASIC (to the caller of KM DISARM BREAK).
; Entered from: km_disarm_break_hook (disarm_break_count reached 0)
; Calls:        unhook_km_disarm_break, KM_READ_CHAR, hello_loader (by RET)
post_boot_setup:
        call unhook_km_disarm_break     ; KM DISARM BREAK back to the original
        ld hl,#C105                     ; DOS indirections + BASIC error patch ...
        ld de,#BE8F                     ; DOS indirections + error patch to &BE8F ...
        ld bc,#0028                     ; ... 40 bytes
        ldir                            ; ... 40 bytes to &BE8F-&BEB6
        ld hl,cpm_const                 ; BASIC 1.0's error indirection (&AC04, second of the nine at &AC01-&AC1B) ...
        ld (hl),#BE                     ; high byte &BE ...
        dec hl
        ld (hl),#A1                     ; ... low byte &A1 ...
        dec hl
        ld (hl),#C3                     ; ... = JP basic_error_patch (&BEA1)
        call KM_READ_CHAR               ; a key waiting (e.g. ESC held after power-on)?
        ret c                           ; yes: no HELLO, back to BASIC
        ld de,#BF00                     ; RET address = the HELLO loader at &BF00
        push de                         ; return address = the HELLO loader
        ld hl,#C2DE                     ; its ROM copy ...
        ld bc,#003F                     ; ... 63 bytes
        ldir                            ; copy the HELLO loader (63 bytes) to &BF00
        ret                             ; run it

; ---- copied to RAM #BF00-#BF3E (from #C2DE), executed there ----
        DISP #BF00
; ----------------------------------------------------------------------
; Subroutine: hello_loader [#BF00] (RAM, from &C2DE)
; Tasks:        Turnkey function (464 / BASIC 1.0): if drive A has a disc with a file HELLO,
;               run it as if RUN "HELLO" had been typed. Finds BIOS GET STATUS (hidden RSX &88),
;               switches the disc error messages off, checks drive A, tries CAS IN OPEN "HELLO"
;               (and closes it again), messages back on; if found, FAR CALL BASIC 1.0's RUN-a-
;               file routine &E9CF in ROM 0 with HL = '"HELLO"<0>' (it opens the file: binary
;               -> MC BOOT PROGRAM, BASIC -> load and RUN). CAS IN OPEN tries the extensions, so
;               HELLO.BAS or HELLO.BIN etc. is found.
;               Observed: no HELLO -> back to BASIC; HELLO.BAS on disc A -> it ran after the reset
;               ("HELLO STARTED"); also from a write-protected disc, where GET STATUS returns CY = 0
;               and the loader takes bit 5 (ready) of the FDC result instead (&BF12).
; Changed:      AF, DE, HL
; Entered from: post_boot_setup (by RET); returns to BASIC
; Calls:        KL_FIND_COMMAND, bios_get_status (KL_FAR_PCHL), CAS_IN_OPEN, CAS_IN_ABANDON, BASIC &E9CF
hello_loader:
        ld hl,bios_get_status_name      ; RSX name of BIOS GET STATUS (&88) ...
        call KL_FIND_COMMAND            ; ... HL = its address, C = its ROM
        ret nc                          ; not found: back to BASIC
        ld a,#FF
        ld (messages_off),a             ; no disc error messages while probing
        xor a                           ; drive A
        call KL_FAR_PCHL                ; BIOS GET STATUS of drive A (&CB79)
        jr c,hello_try_open             ; CY: status read (a normal disc)
        ld hl,fdc_result                ; CY = 0: GET STATUS reports a write-protected disc as an error (ST3 bit 6 read as 'abnormal') - the FDC result byte (ST3) ...
        bit 5,(hl)                      ; ... bit 5: drive ready? (observed: &60 for a write-protected disc with HELLO.BAS)
        jr z,hello_done                 ; not ready: no disc, back to BASIC; ready: try HELLO (observed: "HELLO STARTED" from the write-protected disc)
hello_try_open:
        ld hl,hello_name                ; file name "HELLO" ...
        push hl
        ld b,#05                        ; ... 5 characters
        call CAS_IN_OPEN                ; try to open it: CY = found
        push af
        call CAS_IN_ABANDON             ; close it again - it was only a test
        pop af
        pop hl
hello_done:
        ld a,#00
        ld (messages_off),a             ; disc error messages on again
        ret nc                          ; no HELLO: back to BASIC (observed)
        dec hl                          ; found: HL = '"HELLO"<0>', like the parameter of a typed RUN (observed: &BF37)
hello_run:
        rst #18                         ; FAR CALL; BASIC 1.0 &E9CF in ROM 0: RUN of a file (observed: HELLO.BAS loaded and started)
        defw hello_run_far              ;   (out of range)  (observed: reached rom0)
        ret                             ; (never reached: RUN does not return); [static]
bios_get_status_name:
        defb #88                        ; &88: RSX name of BIOS GET STATUS (one character, bit 7 = last)
hello_run_far:
        defw #E9CF                      ; far address: to #E9CF; BASIC 1.0: RUN "file" (opens it; binary -> MC BOOT PROGRAM, else load + RUN)
        defb #00                        ;   ROM 0
        defb #22                        ; opening quote: after DEC HL, HL points here
hello_name:
        defb "HELLO"                    ; "HELLO", 5 characters, then '"' and 0
        defb #22,#00
        ENT                             ; end of DISP #BF00
; ---- end of RAM copy #BF00-#BF3E (from #C2DE) ----

; ----------------------------------------------------------------------
; Subroutine: bios_boot [#C31D]
; Tasks:        CP/M 2.2 BIOS function 0 BOOT: cold boot of VDOS's CP/M - the boot drive from
;               drives_swapped, then cpm_vdos_boot (rom_init_foreground -> cpm_cold_boot). Observed:
;               INSTALL "CP/M neu starten" calls BOOT (&AC00) after writing the parameter sector.
; Called by:    cpm_boot (CP/M BIOS jumpblock)
bios_boot:
        ld a,(drives_swapped)
        jr cpm_vdos_boot
cpm_amsdos_boot:
        rst #18                         ; FAR CALL; FAR CALL AMSDOS's |CPM boot (ROM 7, &C1DC): loads CP/M from the 3" disc (observed: "CP/M 2.2 - Amstrad ...")
        defw far_amsdos_cpm             ;   to #C1DC [ROM 7]  (observed: reached rom7)

; ---- never accessed: #C325-#C327 (3 bytes, fill: static) ----
        jp cpm_back_to_basic            ; only if AMSDOS's boot returned - it cannot: AMSDOS &C1DC starts with ld sp,#C000 (the FAR CALL's return address is gone), then boots (jp &C177) or retries for ever (&C224-&C229: message, jr &C20A); no jump / call / word points here (static search). Unreachable - on the ignore list (project/never_read_ignore.md); [static]
; ---- end of never accessed ----

far_amsdos_cpm:
        defw #C1DC                      ; far address: to #C1DC; far address: AMSDOS (ROM 7) &C1DC, its CP/M boot (|CPM)
        defb #07                        ;   ROM 7
; ----------------------------------------------------------------------
; Subroutine: rsx_cpm [#C32B]
; Tasks:        |CPM[,n]: start CP/M. No parameter or n = 0 (low byte): AMSDOS's own CP/M boot
;               (cpm_amsdos_boot, ROM 7) - the Amstrad CP/M from the 3" disc, VDOS is gone.
;               n = 1: VDOS's 44K CP/M from the 3" drive (drives_swapped = 0); n = 2: from the
;               Vortex drive, which becomes drive A (drives_swapped = 1) - both through
;               rom_init_foreground -> MC START PROGRAM cpm_cold_boot. Other n: Eingabefehler.
;               Observed: |CPM and |CPM,0 -> "CP/M 2.2 - Amstrad Consumer Electronics plc";
;               |CPM,1 -> that line (boot sector from the 3" disc), then " 44K CP/M vers.
;               2.2-07/86    vortex GmbH", A>, &BE7F = 0; |CPM,2 -> only the vortex line,
;               &BE7F = 1; |CPM,3 / -1 / 259 (low byte 3) -> Eingabefehler.
;               Manual (2.0): "44K CP/M vers. 2.2-03/86"; the ROM's CP/M says 07/86.
; Input:        A = number of parameters (0 or 1), IX = parameters
; Output:       does not return (CP/M starts), except for an error
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "CPM" (rom_jumpblock)
; Calls:        cas_entry, rsx_param, cpm_amsdos_boot, KL_CURR_SELECTION, MC_START_PROGRAM (rom_init_foreground)
rsx_cpm:
        call cas_entry                  ; IY, error SP
        or a                            ; no parameter?
        jr z,cpm_amsdos_boot            ; yes: AMSDOS's CP/M (observed)
        call rsx_param                  ; HL = n
        ld a,l                          ; only the low byte counts (observed: 259 = &0103 -> 3)
        or a
        jr z,cpm_amsdos_boot            ; 0: AMSDOS's CP/M (observed)
        cp #03                          ; 1 or 2?
        jp nc,error_bad_name            ; no: Eingabefehler (observed)
        dec a                           ; 0 / 1 = drives_swapped
cpm_vdos_boot:
        ld (drives_swapped),a           ; drives_swapped (observed: 0 for |CPM,1, 1 for |CPM,2; bios_boot joins here)
        call KL_CURR_SELECTION          ; A = our ROM number
; Common end of the VDOS CP/M start: rom_init (VDOS as ROM 0, not observed), rsx_cpm with
; |CPM,1 / |CPM,2 and bios_boot (both through cpm_vdos_boot: drives_swapped = A, A = our ROM
; number). |CPM without a parameter does not come here: cpm_amsdos_boot far-calls AMSDOS's CP/M
; boot (ROM 7, &C1DC).
rom_init_foreground:
        ld c,a                          ; C = our ROM number (KL CURR SELECTION, or rom_init's A): the foreground ROM for MC START PROGRAM (observed with |CPM,1)
        ld hl,cpm_cold_boot             ; HL = cpm_cold_boot: the program's entry
        jp MC_START_PROGRAM             ; reset the firmware and run it as the foreground program (does not return)
; ----------------------------------------------------------------------
; Subroutine: bios_wboot [#C34B]
; Tasks:        CP/M 2.2 BIOS function 1 WBOOT: through the BIOS entry handler (&B046).
;               Not analysed in detail yet.
; Called by:    cpm_wboot (CP/M BIOS jumpblock)
bios_wboot:
        call bios_entry                 ; WBOOT: through bios_entry to &C4AA
        defb #AA,#C4
; ----------------------------------------------------------------------
; Subroutine: bios_seldsk [#C350]
; Tasks:        CP/M 2.2 BIOS function 9 SELDSK: through the BIOS entry handler (&B046).
;               Not analysed in detail yet.
; Called by:    cpm_seldsk (CP/M BIOS jumpblock)
bios_seldsk:
        call bios_entry                 ; SELDSK: through bios_entry to &C7D5 (as dos_seldsk)
        defb #D5,#C7
; ----------------------------------------------------------------------
; Subroutine: bios_home [#C355]
; Tasks:        CP/M 2.2 BIOS function 8 HOME: track 0 (C = 0) and falls into bios_settrk.
;               Not analysed in detail yet.
; Called by:    cpm_home (CP/M BIOS jumpblock)
bios_home:
        ld hl,deblock_flags
        bit 7,(hl)
        jr nz,home_track0
