home_track0:
        ld c,#00                        ; track 0 - falls into bios_settrk (HOME = SETTRK 0, as in DR's sample BIOS)
; ----------------------------------------------------------------------
; Subroutine: bios_settrk [#C360]
; Tasks:        CP/M 2.2 BIOS function 10 SETTRK: track C to &BE54.
;               Not analysed in detail yet.
; Called by:    cpm_settrk (CP/M BIOS jumpblock)
; Entered from: bios_home (falls through)
bios_settrk:
        ld a,c
        ld (sek_track),a
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_setsec [#C365]
; Tasks:        CP/M 2.2 BIOS function 11 SETSEC: sector C to &BE55.
;               Not analysed in detail yet.
; Called by:    cpm_setsec (CP/M BIOS jumpblock)
bios_setsec:
        ld a,c
        ld (sek_record),a
