; ----------------------------------------------------------------------
; Subroutine: bios_setdma [#C36A]
; Tasks:        CP/M 2.2 BIOS function 12 SETDMA: DMA address BC to &BE60.
;               Not analysed in detail yet.
; Called by:    cpm_setdma (CP/M BIOS jumpblock)
bios_setdma:
        ld (dma_address),bc
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_sectran [#C36F]
; Tasks:        CP/M 2.2 BIOS function 16 SECTRAN: no translation: HL = BC.
;               Not analysed in detail yet.
; Called by:    cpm_sectran (CP/M BIOS jumpblock)
bios_sectran:
        ld h,b
        ld l,c
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_write [#C372]
; Tasks:        CP/M 2.2 BIOS function 14 WRITE: through the BIOS entry handler (&B046).
;               Not analysed in detail yet.
; Called by:    cpm_write (CP/M BIOS jumpblock)
bios_write:
        call bios_entry                 ; WRITE: through bios_entry to &C8AA (as dos_write)
        defb #AA,#C8
; ----------------------------------------------------------------------
; Subroutine: bios_read [#C377]
; Tasks:        CP/M 2.2 BIOS function 13 READ: through the BIOS entry handler (&B046).
;               Not analysed in detail yet.
; Called by:    cpm_read (CP/M BIOS jumpblock)
bios_read:
        call bios_entry                 ; READ: through bios_entry to &C89A (as dos_read)
        defb #9A,#C8
; ----------------------------------------------------------------------
; Subroutine: bios_entry_handler [#C37C]
; Tasks:        BIOS entry handler with register save (reg_save_mode 0, the default): lets CP/M
;               code call ROM code that needs the firmware. Used as CALL bios_entry (&B046) /
;               DEFW target: switches to the alternate set, saves the caller's SP and moves to
;               an own stack below &C000, saves the caller's AF', BC', DE', HL', IX and IY,
;               loads the firmware's BC' (firmware_bc_alt), then bios_entry_enter restores the
;               firmware's interrupt vector and IY and jumps to the target with the caller's
;               main registers. When the target returns: firmware_bc_alt = BC' (the firmware
;               may have changed it), the CP/M interrupt vector (&0039 = bios_interrupt) is set
;               again, the saved registers come back and RET goes to the caller's caller - the
;               word after the CALL is not skipped, so the CALL is always the last instruction
;               of a BIOS function (e.g. bios_conout ... &C630: CALL bios_entry / DEFW &C635).
;               Observed (DIR under the 44K CP/M): called from &C630 with target &C635.
; Input:        (SP) = address of the target word; AF, BC, DE, HL for the target
; Output:       AF, BC, DE, HL from the target; alternate registers, IX, IY kept
; Called by:    bios_entry (&B046) from bios_wboot, bios_seldsk, bios_read, bios_write, the
;               character I/O (&C630), bios_interrupt, bios_enter_firmware
; Calls:        bios_entry_enter -> the target
bios_entry_handler:
        di                              ; alternate set: AF', BC', DE', HL' of the CP/M caller
        ex af,af'
        exx
        ex (sp),hl                      ; HL' = address of the target word; the caller's HL' on the stack in its place
        ld (bios_caller_sp),sp          ; keep the caller's SP
        ld sp,#C000                     ; own stack below &C000
        push af                         ; save the caller's AF' ...
        push bc                         ; ... BC' ...
        push de                         ; ... DE' ...
        push iy                         ; ... IY ...
        push ix                         ; ... and IX
        ld bc,(firmware_bc_alt)         ; BC' = the firmware's value (gate array port and ROM state)
        or a                            ; clear the carry (purpose not clear)
        call bios_entry_enter           ; run the target in the firmware's environment
; the target returns here
beh_return:
        di
        ex af,af'                       ; back to the alternate set (the target's AF, BC, DE, HL stay)
        exx
        ld (firmware_bc_alt),bc         ; keep the firmware's BC' for the next call
        ld hl,bios_interrupt            ; CP/M's interrupt vector again: &0038 JP bios_interrupt
        ld (#0039),hl
        pop ix                          ; restore the caller's IX ...
        pop iy
        pop de
        pop bc
        pop af                          ; ... and AF'
        ld sp,(bios_caller_sp)          ; the caller's stack
        pop hl                          ; the caller's HL' (the slot of the target word's address)
        exx
        ex af,af'                       ; the target's AF, BC, DE, HL as result
        ei
        ret                             ; to the caller of the BIOS function
; ----------------------------------------------------------------------
; Subroutine: bios_entry_fast [#C3B3]
; Tasks:        BIOS entry handler without register save (reg_save_mode &FF, set by
;               bios_set_reg_save): as bios_entry_handler, but the alternate registers, IX and IY
;               are not saved and BC' is not reloaded - CP/M code must leave BC' to the firmware.
;               The target runs with the caller's main registers (bios_entry_enter swaps back) and
;               its AF, BC, DE, HL go straight back to the caller.
;               Observed (FM.COM, marker registers IX &1234, IY &5678, DE' &2222, HL' &3333,
;               A' &AA): interrupts come here too (bios_interrupt, return &C3E8 on the stack) and
;               already destroy IY (&AB68 = cpm_rom_iy), DE' (&0038, the target), HL' (&C3E5,
;               set by bef_return) and AF' (the firmware's interrupt routine); a CONOUT also
;               leaves IX = &B04D (bios_char_io). So in this mode a CP/M program cannot use IY
;               or the alternate registers at all, and IX not across BIOS calls. In mode 0
;               (bios_entry_handler) all markers were kept, across interrupts and CONOUT.
; Input:        (SP) = address of the target word; AF, BC, DE, HL for the target
; Output:       AF, BC, DE, HL from the target
; Changed:      IY, AF', DE', HL' (and what the target changes, e.g. IX in the character I/O)
; Called by:    bios_entry (&B046) when reg_save_mode = &FF - BIOS functions and bios_interrupt
; Calls:        bios_entry_enter -> the target
bios_entry_fast:
        di                              ; alternate set
        ex af,af'
        exx
        pop hl                          ; HL' = address of the target word (taken off the stack)
        ld (bios_caller_sp),sp          ; keep the caller's SP
        ld sp,#C000                     ; own stack below &C000
        or a
        call bios_entry_enter           ; run the target in the firmware's environment
; the target returns here
bef_return:
        di
        exx
        ld hl,bios_interrupt            ; CP/M's interrupt vector again: &0038 JP bios_interrupt
        ld (#0039),hl
        exx
        ld sp,(bios_caller_sp)          ; the caller's stack
        ei
        ret                             ; to the caller of the BIOS function
; ----------------------------------------------------------------------
; Subroutine: bios_entry_enter [#C3D1]
; Tasks:        Common part of bios_entry_handler / bios_entry_fast: give the firmware its
;               environment back - interrupt vector &0039 = firmware_int_vector (&B939), IY =
;               cpm_rom_iy - and jump to the target (the word at HL') with the caller's main
;               registers and interrupts on. The target's RET returns to the handler.
; Input:        alternate set active, HL' = address of the target word
; Called by:    bios_entry_handler, bios_entry_fast
bios_entry_enter:
        ld de,(firmware_int_vector)     ; the firmware's interrupt jump address ...
        ld (#0039),de                   ; ... back to &0039: interrupts go to the firmware again
        ld iy,(cpm_rom_iy)              ; IY for the ROM code
        ld e,(hl)                       ; DE' = the target word ...
        inc hl
        ld d,(hl)
        push de                         ; ... as RET address
        exx                             ; the caller's main registers ...
        ex af,af'
        ei
        ret                             ; ... into the target
; ----------------------------------------------------------------------
; Subroutine: bios_interrupt [#C3E5]
; Tasks:        Interrupt entry under CP/M: while CP/M code runs, &0038 = JP &C3E5 (set by
;               start_with_cpm_vector and by every bios_entry return). Runs the firmware's interrupt
;               routine through bios_entry with the target &0038: bios_entry_enter has put the
;               firmware's vector back into &0039 by then, so &0038 is JP &B939 (the firmware's RAM
;               interrupt entry). While firmware code runs (inside any bios_entry call) &0039 points to
;               the firmware, so an interrupt there goes straight to &B939 and the stack below &C000
;               is never used twice. Observed single-stepped (2026-10-25): interrupt in the CCP (SP
;               &A135) -> &0038 -> here -> bios_entry_handler -> &0038 JP &B939 -> beh_return (&0039 =
;               bios_interrupt again) -> EI / RET into the CCP.
; Called by:    the Z80 interrupt (IM 1, &0038) under CP/M
; Calls:        bios_entry (target &0038)
bios_interrupt:
        call bios_entry                 ; firmware interrupt entry, in the firmware's environment
        defb #38,#00
; ----------------------------------------------------------------------
; Subroutine: bios_enter_firmware [#C3EA]
; Tasks:        Extended BIOS &BE9B ENTER FIRMWARE: call a firmware routine (or any routine
;               that needs the firmware's environment) from CP/M as CALL &BE9B / DEFW address.
;               Unlike a direct CALL bios_entry this returns to the caller after the address word:
;               the return address is moved two bytes on and the word's address is pushed for
;               bios_entry, which then returns there. Observed: INSTALL (Vortex disc) calls it once
;               at its start with DEFW &BE89 (READ SECTOR, the parameter sector), return address
;               &011A on the stack (SP &9E04); breakpoint at &011C: INSTALL goes on there with
;               SP &9E06 (stack balanced) and CY = 1 from READ SECTOR.
; Input:        (SP) = address of the firmware address word; AF, BC, DE, HL for it
; Output:       AF, BC, DE, HL from the firmware routine; HL' changed
; Called by:    cpm_ext_enter_firmware (&BE9B)
; Calls:        bios_entry
bios_enter_firmware:
        di                              ; alternate set
        exx
        pop hl                          ; HL' = address of the address word
        push hl
        inc hl                          ; past the word ...
        inc hl
        ex (sp),hl                      ; ... is the new return address; HL' = the word's address again
        push hl                         ; for bios_entry: (SP) = address of the target word
        exx
        jp bios_entry                   ; bios_entry (&B046)
; ----------------------------------------------------------------------
; Subroutine: cpm_cold_boot [#C3F6]
; Tasks:        Cold boot of VDOS's own CP/M, started as the foreground program by MC START
;               PROGRAM from rom_init_foreground (|CPM,1 / |CPM,2, bios_boot, VDOS as ROM 0).
;               Sets up what CP/M needs to call the ROM: the extended BIOS jumpblock at &BE80,
;               page zero (&0000 / &0005 JP opcodes, IOBYTE, drive), bios_entry (&B046) with the
;               register-saving handler, and the interrupt vector. Then reads the boot sector
;               (track 0, first sector) to &0100 and enters it with BC = &C0D2, the address of
;               the CP/M BIOS jumpblock in the ROM - the same interface as AMSDOS's CP/M boot, so
;               the Amstrad boot sector works unchanged. Observed with |CPM,1 and the 3" system
;               disc: the boot sector copies the 17 JPs from BC to &0500, reads the
;               configuration sector &42 to &0300 through &BE89 READ SECTOR, sets up the disc
;               (&BE83), messages (&BE80), register save (&BE9E), SIO (&BEA1), the IOBYTE and
;               the keyboard tables, then jumps to &0503 = WBOOT (wboot_body), which loads CCP
;               and BDOS and copies the jumpblock to the BIOS base (&AC00).
; Input:        drives_swapped (0 |CPM,1, 1 |CPM,2)
; Called by:    MC START PROGRAM (rom_init_foreground)
; Calls:        clear_memory, disc_init, install_entry_handler, specify_for_drive, then
;               boot_read_boot_sector (falls through) -> the boot sector
cpm_cold_boot:
        ld sp,#C000                     ; own stack below &C000
        ld iy,#AB68                     ; IY = VDOS workspace under CP/M (&AB68, below the BIOS at &AC00)
        ld de,#B046                     ; clear the CP/M side's RAM &B046-&B0EA ...
        ld b,#A5                        ; (&A5 bytes: bios_entry, vectors, console state, caller SP, ...)
        call clear_memory
        ld (con_cursor_count),a         ; console state bytes &B04D / &B04E = 0 (already 0 from the clear)
        ld (autostart_flag),a
        call disc_init                  ; disc system: motors, VDOS RAM, DPHs / DPBs, SPECIFY
        ld hl,#C093                     ; the extended BIOS jumpblock in the ROM ...
        ld de,cpm_ext_set_message
        ld bc,#003F                     ; 21 JPs
        ldir                            ; ... to &BE80 (as AMSDOS's: SET MESSAGE .. READ SECTOR .., ENTER FIRMWARE, SIO)
        ld a,#81                        ; IOBYTE: CONSOLE = CRT (1), LIST = LPT (2)
        ld (#0003),a
        xor a                           ; drive A, user 0
        ld (#0004),a
        ld (reg_save_mode),a            ; reg_save_mode 0: bios_entry saves the registers
        dec a                           ; &FF: ...
        ld (autodetect_format),a        ; ... format detection on
        ld a,#C3                        ; JP opcodes for ...
        ld (bios_entry),a               ; ... bios_entry (&B046), ...
        ld (#0005),a                    ; ... &0005 (BDOS, address set by WBOOT) and ...
        ld (RESET_ENTRY),a              ; ... &0000 (WBOOT, address set by WBOOT)
        ld hl,(#0039)                   ; the firmware's interrupt jump address (&B939) ...
        ld (firmware_int_vector),hl     ; ... kept for bios_entry_enter
        call install_entry_handler      ; bios_entry = JP bios_entry_handler, firmware_bc_alt = BC'
        ld (cpm_rom_iy),iy              ; IY for the ROM code under CP/M
        ld a,(drives_swapped)           ; the boot drive
        call specify_for_drive          ; SPECIFY for it
boot_read_boot_sector:
        ld de,#0000                     ; track 0
        ld c,#41                        ; first sector &41 (3" system format); boot_sector_number makes it &01 when drives_swapped
        call boot_sector_number
        ld hl,#0100
        call bios_read_sector           ; read the boot sector to &0100
        jr nc,boot_no_cpm_disc          ; read error -> "keine CP/M Diskette"
        ld a,(hl)
        cp #E5                          ; &E5: empty (formatted, no system)
        jr z,boot_no_cpm_disc
        ld bc,#C0D2                     ; BC = the CP/M BIOS jumpblock in the ROM (for the boot sector, as AMSDOS)
        ld sp,#BF80                     ; stack below the extended jumpblock area
; Enter CP/M code: interrupt vector &0039 = bios_interrupt (so &0038 = JP bios_interrupt),
; then JP (HL). Used by the cold boot (HL = &0100, the boot sector) and WBOOT (HL = CCP base).
start_with_cpm_vector:
        ld de,bios_interrupt            ; &0038 JP bios_interrupt from now on
        ld (#0039),de
        jp (hl)                         ; into the boot sector / the CCP
; ----------------------------------------------------------------------
; Subroutine: install_entry_handler [#C46A]
; Tasks:        Make bios_entry (&B046) JP bios_entry_handler and keep the current BC' as
;               firmware_bc_alt. Second entry ieh_set (HL = handler) is used by
;               bios_set_reg_save for bios_entry_fast.
; Called by:    the |CPM,1 boot (research), bios_set_reg_save (A = 0)
install_entry_handler:
        di                              ; no interrupts while the vector changes
        ld hl,bios_entry_handler        ; the handler with register save
        exx
        ld (firmware_bc_alt),bc         ; the firmware's BC' (gate array / ROM state)
        exx
ieh_set:
        ld (bios_entry_target),hl       ; bios_entry_target = HL
        ei
        ret
; ----------------------------------------------------------------------
; Subroutine: boot_sector_number [#C479]
; Tasks:        With drives_swapped (|CPM,2: the Vortex drive is A) the sector number C loses its
;               format bits (&41 -> &01, &48 -> &08): the Vortex format numbers its sectors
;               from 1, the 3" system format from &41.
; Input:        C = sector number of the 3" system format
; Output:       C = the sector number for drive A; Z = not swapped (C unchanged)
; Changed:      AF, C
; Called by:    boot_read_boot_sector, wboot_body
boot_sector_number:
        ld a,(drives_swapped)           ; Vortex drive as A?
        or a
        ret z                           ; not swapped: keep C
        ld a,c
        and #0F                         ; swapped: drop the &40 format bits
        ld c,a
        ret
; Cold boot: the boot sector cannot be read or is empty. "keine CP/M Diskette - Wiederholen
; J/N ?": J reads again, N goes back to BASIC. Observed 2026-10-26: |CPM,1 with a blank system
; format disc in A: (cpcxray draft) -> A = &E5 at &C483, the message (MODE 1); J -> read again,
; the same message; N -> cpm_back_to_basic: BASIC starts afresh (VDOS sign-on, "Ready").
; Not observed: the read error branch (jr nc above) - same code.
boot_no_cpm_disc:
        ld a,#09                        ; msg &09 "keine CP/M Diskette " (observed)
        call print_error_and_ask
        jr nz,boot_read_boot_sector     ; J: read the boot sector again
; Leave CP/M: copy the name "BASIC" into the host buffer (the name must be in RAM) and let
; KL FIND COMMAND start the foreground program BASIC. Observed after N at the warm boot
; error: BASIC starts afresh (the ROMs are initialised, VDOS sign-on).
cpm_back_to_basic:
        call host_buffer                ; HL = host buffer (RAM)
        push hl
        ld de,basic_command_name        ; the name "BASIC"
        ex de,hl
        ld bc,#0005
        ldir                            ; into RAM
        pop hl                          ; HL = the name
        call KL_FIND_COMMAND            ; a foreground program is entered at once: does not return

; ---- never accessed: #C49B-#C49D (3 bytes, fill: static) ----
        jp rsx_cpm                      ; only if KL FIND COMMAND does not find "BASIC" - never seen. On the 464 its ROM scan (&02DA-&02ED) stops only at a ROM of type &80 (the built-in BASIC answers for empty ROM numbers), so with BASIC present it is always found; tested 2026-10-26 with VDOS alone as ROM 0 (output/machine_vdos_rom0.toml, VDOS answers for every number, type &01): N at "keine CP/M Diskette" -> the scan runs forever, &C49B is not reached. Unreachable - on the ignore list (project/never_read_ignore.md); [static]
; ---- end of never accessed ----

basic_command_name:
        defb "BASI","C"+#80             ; "BASIC", last character with bit 7
; WBOOT failed (flush error, sector error or no CCP/BDOS on the system tracks): "keine CP/M
; Diskette - Wiederholen J/N ?". J tries the warm boot again, N leaves CP/M for BASIC.
; Observed with a write-protected disc: the message is misleading there, the disc is fine.
wboot_no_cpm_disc:
        ld a,#09                        ; msg &09 "keine CP/M Diskette "
        call print_error_and_ask        ; + "Wiederholen J/N ?": NZ = J, Z = N
        jr z,cpm_back_to_basic          ; N: back to BASIC (observed); J falls into wboot_body again
; WBOOT (through bios_wboot / bios_entry): first write back what the deblocking buffer still
; holds, then reload CCP and BDOS from the system tracks.
wboot_body:
        call flush_host_buffer          ; pending host buffer written back
        jr nc,wboot_no_cpm_disc         ; write error -> "keine CP/M Diskette" (observed: write-protected disc)
        xor a                           ; drive 0
        call specify_for_drive          ; SPECIFY with drive A's step rate
        ld de,#0000                     ; track 0
        ld c,#48                        ; sector &48: the first sector of the CCP image (3" system format)
        call boot_sector_number         ; &08 for the Vortex format
        jr nz,wboot_read_ccp            ; Vortex drive as A: go and read (its boot sector passes the step rate in VDOS's combined format)
        call drive_a_flags_address
        bit 1,(hl)                      ; bit 1 of drive A's flags: system loaded once (banner shown)
        jr nz,wboot_read_ccp            ; yes: the step rate is already converted
        ld hl,disc_time_constants+6     ; first load from the 3" drive: the Amstrad boot sector has just called SETUP DISC (&BE83) with an AMSDOS block, whose byte 6 is ONE step rate in ms (&0C) - VDOS reads it as 3" = high nibble, Vortex = low nibble
        ld a,(hl)
        rlca                            ; swap the nibbles: the 12 ms go to the 3" nibble (&0C -> &C0)
        rlca
        rlca
        rlca
        or #04                          ; Vortex step rate 4 ms (the default) -> &C4 (observed: &0C -> &C4)
        ld (hl),a                       ; back into disc_time_constants+6
        push de
        push bc
        xor a
        call specify_for_drive          ; SPECIFY for drive A with the converted step rate
        pop bc
        pop de
wboot_read_ccp:
        call host_buffer                ; HL = host buffer
        call bios_read_sector           ; read the first sector of the CCP image
        jr nc,wboot_no_cpm_disc         ; read error
        ld a,#C3                        ; the CCP starts with JP (&C3)
        cp (hl)
        jr nz,wboot_no_cpm_disc         ; no JP: not a CP/M system
        push hl                         ; keep the host buffer address
        inc hl
        ld e,(hl)                       ; DE = the CCP's JP target = CCP base + &35C
        inc hl
        ld d,(hl)
        ld hl,#FCA4                     ; -&35C
        add hl,de
        ex de,hl                        ; DE = CCP base (the address the system was built for)
        push de
        ld hl,#0806                     ; BDOS entry = CCP base + &806
        add hl,de
        ld (#0006),hl                   ; &0005 JP BDOS: its address
        ld hl,#1603                     ; BIOS WBOOT = CCP base + &1603
        add hl,de
        ld (#0001),hl                   ; &0000 JP WBOOT: its address
        dec hl                          ; HL = BIOS base = CCP base + &1600
        dec hl
        dec hl
        ld de,#C0D2                     ; the CP/M BIOS jumpblock in the ROM
        ex de,hl
        ld bc,#0033                     ; 17 JPs
        ldir                            ; copy the jumpblock to the BIOS base (every warm boot)
        pop de                          ; DE = CCP base
        pop hl                          ; HL = host buffer
        ld bc,#0200                     ; the first 512 bytes of the CCP
        ldir                            ; to the CCP base
        ex de,hl                        ; HL = where the next sector goes
        ld bc,#0A49                     ; 10 more sectors, starting with sector &49
        ld de,#0000                     ; track 0
        call boot_sector_number         ; &09 for the Vortex format
wboot_read_loop:
        call bios_read_sector           ; read the sector to (HL)
        jr nc,wboot_no_cpm_disc         ; read error
        ld a,c
        inc c                           ; next sector (A = the one just read)
        and #0F
        cp #09                          ; was it the last sector (9) of the track?
        jr c,wboot_next_sector
        ld c,#41                        ; yes: first sector &41 ...
        call boot_sector_number         ; (&01 Vortex)
        inc d                           ; ... of the next track
wboot_next_sector:
        inc h                           ; HL + 512
        inc h
        djnz wboot_read_loop            ; until CCP and BDOS are in (&1600 bytes)
        push hl                         ; keep HL = end = BIOS base
        ex de,hl
        call drive_a_flags_address
        bit 1,(hl)                      ; system loaded once already?
        jr nz,wboot_start_ccp           ; yes: no banner
        push hl
        ex de,hl
        ld a,#05                        ; size in K = (5 + 256-byte pages up to the BIOS base + 1) / 4: &AC00 -> &B2 / 4 = 44
        or a
        ld de,#0100
wboot_size_loop:
        sbc hl,de                       ; (HL = BIOS base - n * 256)
        inc a
        jr nc,wboot_size_loop
        rrca                            ; / 4: pages -> K
        rrca
        and #3F
        ld e,a                          ; DE = the size in K
        ld d,#00
        ld a,#10                        ; msg &10 "<DE>K CP/M vers. 2.2-07/86    vortex GmbH" (banner)
        call print_message
        pop hl
        set 1,(hl)                      ; mark: system loaded once
wboot_start_ccp:
        ld a,(#0004)                    ; current drive / user (&0004)
        ld c,a                          ; C = drive / user for the CCP
        pop de                          ; DE = BIOS base
        ld hl,#EA00                     ; -&1600: CCP + BDOS size
        add hl,de                       ; HL = CCP base
        jp start_with_cpm_vector        ; set CP/M's interrupt vector, then JP (HL) = CCP
; ----------------------------------------------------------------------
; Subroutine: flush_host_buffer [#C562]
; Tasks:        Write the deblocking host buffer back if it holds unwritten data (bit 7 of
;               deblock_flags = hstwrt), then clear deblock_flags and the byte after it. On a
;               write error the flags stay as they are. Observed: SAVE under CP/M on a
;               write-protected disc, then a warm boot - the write fails, CY = 0.
; Output:       CY = 1 ok (also when nothing was to write), CY = 0 write error
; Changed:      AF, HL (+ host_read_write)
; Called by:    wboot_body
; Calls:        host_read_write
flush_host_buffer:
        ld hl,deblock_flags             ; deblocking flags
        push hl
        xor a
        ccf                             ; CY = 1: ok if nothing is to write
        bit 7,(hl)                      ; host buffer written to (hstwrt)?
        call nz,host_read_write         ; yes: write it back
        pop hl
        ret nc                          ; write error: keep the flags
        ld (hl),#00                     ; clear the flags (and the byte after them)
        inc hl
        ld (hl),#00
        ret
; ----------------------------------------------------------------------
; Subroutine: disc_init [#C575]
; Tasks:        Initialise the disc system: all motors off; clear VDOS's fixed RAM &BE01-&BF00
;               (keeps drives_swapped); &BE04 = &FF; set up motor_event_block;
;               copy the default time constants and send FDC SPECIFY (bios_setup_disc); build
;               the DPHs and DPBs of both drives (setup_drive_tables); retry count = 16.
; Input:        IY = VDOS workspace, drives_swapped
; Output:       A = old retry count
; Changed:      AF, BC, DE, HL
; Called by:    rom_init (research: also cpm_main)
; Calls:        motor_off, clear_memory, KL_CURR_SELECTION, KL_INIT_EVENT, bios_setup_disc,
;               setup_drive_tables; falls into set_retry_default
disc_init:
        call motor_off                  ; all drive motors off
        ld hl,drives_swapped            ; keep drives_swapped ...
        ld c,(hl)                       ; ... in C across the clear
        ld de,sio_wr5                   ; from &BE01 ...
        ld b,#00                        ; ... 256 bytes
        call clear_memory               ; clear &BE01-&BF00: VDOS's fixed RAM, including the AMSDOS variables at &BE40-&BE7F
        ld (hl),c                       ; drives_swapped back
        ld hl,xpb_cache_drive
        ld (hl),#FF                     ; &BE04 = &FF (purpose unknown)
        call KL_CURR_SELECTION
        ld c,a                          ; C = our ROM number: the event routine is a far address
        ld b,#80                        ; event class &80 (express per the firmware class bits; not verified)
        ld de,motor_event               ; event routine
        ld hl,motor_event_block
        call KL_INIT_EVENT              ; set up the event block kicked by the motor ticker (&BE67)
        ld hl,time_constants_default    ; default time constants (+7/+8: HUT, HLT for SPECIFY)
        call bios_setup_disc            ; copy them to &BE44-&BE4A and send FDC SPECIFY
        call setup_drive_tables         ; DPHs and DPBs of drives A and B
; ----------------------------------------------------------------------
; Subroutine: set_retry_default [#C5A2]
; Tasks:        Set the retry count to its default of 16; falls into bios_set_retry_count.
; Output:       A = old retry count
; Changed:      A
; Called by:    disc_init (falls in), detect_format
set_retry_default:
        ld a,#10                        ; 16 retries
; ----------------------------------------------------------------------
; Subroutine: bios_set_retry_count [#C5A4]
; Tasks:        Hidden RSX &89 SET RETRY COUNT: set the number of tries of a disc operation
;               (same entry and registers as AMSDOS's, so programs written for AMSDOS work).
; Input:        A = new number of retries
; Output:       A = old number of retries; HL kept
; Changed:      AF
;               Observed through RSX &89: A = 5 -> A = &10 back, retry_count = 5, HL kept; A = &10 back.
; Called by:    RSX &89 (rom_jumpblock), set_retry_default, detect_format
bios_set_retry_count:
        push hl                         ; keep HL
        ld hl,(retry_count)             ; L = old count
        ld (retry_count),a              ; new count
        ld a,l                          ; return the old count in A
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: setup_drive_tables [#C5AE]
; Tasks:        Copy the two DPH templates (dph_templates) to workspace+&43E and turn their
;               workspace offsets into absolute addresses; store drive A's DPH in dph_drive_a.
;               Then copy the 25-byte XPBs into the DPB slots (workspace+&4AC drive A, +&4C5
;               drive B): with drives_swapped = 0 the 3" XPB to drive A and the Vortex XPB to drive B,
;               otherwise swapped (not observed). &BE42 = address of the 3" drive's XPB.
; Input:        IY = VDOS workspace, drives_swapped
; Output:       -
; Changed:      AF, BC, DE, HL; interrupts are disabled while SP walks the DPHs
; Called by:    disc_init; rsx_x (|X) jumps to sdt_copy_xpbs after toggling drives_swapped
; Calls:        workspace_offset, copy_xpb
setup_drive_tables:
        ld hl,dph_templates             ; the two DPH templates
        ld de,#043E
        call workspace_offset           ; DE = workspace+&43E (&AB3E): drive A's DPH, drive B's 16 bytes later
        ld (dph_drive_a),de             ; remember drive A's DPH
        push de
        ld bc,#0020
        ldir                            ; copy both templates (2 x 16 bytes)
        ld b,#10                        ; 16 words in the two DPHs
        di                              ; SP is used as a pointer below: no interrupts
        pop hl                          ; HL = first DPH
        ld (#BE42),sp                   ; save SP (&BE42 as temporary)
        push iy
        pop de                          ; DE = workspace base
        ld sp,hl                        ; walk the DPH words with POP
; make the 16 DPH words absolute: offset + workspace base, 0 stays 0
sdt_relocate:
        pop hl                          ; next word: a workspace offset or 0
        ld a,l
        or h                            ; 0 (XLT, scratch words)?
        jr z,sdt_next_word              ; yes: keep it
        add hl,de                       ; offset + workspace base = absolute address
        push hl                         ; write it back over the offset ...
        pop hl                          ; ... and step SP past it again
sdt_next_word:
        djnz sdt_relocate               ; all 16 words
        ld sp,(#BE42)                   ; SP back
        ei
; copy the XPBs for drives_swapped - also entered from rsx_x after |X has toggled drives_swapped (0 <-> 1)
sdt_copy_xpbs:
        ld hl,xpb_3inch                 ; first copy the 3" XPB (the Vortex XPB follows it)
        ld a,(drives_swapped)           ; drives_swapped = 0: 3" drive is A?
        or a
        jr nz,sdt_swapped               ; drives_swapped = 1 (|X): Vortex drive is A (observed)
        ld de,#04AC                     ; 3" XPB to drive A's DPB (workspace+&4AC); &BE42 = its address
        call copy_xpb
        ld de,#04C5                     ; Vortex XPB (HL = &C16D now) ...
        call workspace_offset           ; ... to drive B's DPB (workspace+&4C5)
        push af
        jr copy_xpb_bytes               ; copy it
; drives_swapped <> 0: Vortex drive is A, 3" drive is B (not observed)
sdt_swapped:
        ld de,#04C5                     ; swapped (observed with |X): 3" XPB to drive B's DPB ...
        call copy_xpb                   ; ... &BE42 = its address
        ex de,hl                        ; HL = end of that DPB
        dec hl
        ld a,#20
        ld (hl),a                       ; last byte (+&18) = &20: the flag byte of the 3" drive as B (observed)
        dec hl
        ld a,#27
        ld (hl),a                       ; +&17 = &27: MTRK, last track 39 (observed: the 3" XPB as B has the Vortex layout)
        ex de,hl                        ; HL = Vortex XPB again ...
        ld de,#04AC                     ; ... to drive A's DPB: fall into copy_xpb
; ----------------------------------------------------------------------
; Subroutine: copy_xpb [#C607]
; Tasks:        Copy the 25-byte XPB at HL to workspace+DE and set &BE42 to its address.
; Input:        HL = XPB in the ROM, DE = workspace offset of the DPB slot, IY = workspace
; Output:       HL = byte after the XPB (the next XPB), DE = end of the copy
; Changed:      BC, DE, HL
; Called by:    setup_drive_tables
; Calls:        workspace_offset
copy_xpb:
        push af                         ; keep AF
        call workspace_offset           ; DE = workspace + DE
        ld (#BE42),de                   ; &BE42 = this DPB
copy_xpb_bytes:
        ld bc,#0019                     ; 25 bytes: CP/M DPB (15) + Vortex extension (10)
        ldir                            ; copy the XPB
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_const [#C616]
; Tasks:        CP/M 2.2 BIOS function 2 CONST: console status, A = &FF character ready, 0 none.
;               L = &00: entry +&00 of char_io_table, device by the CON: field of the IOBYTE.
;               Observed (CON: = CRT: -> con_crt_status).
; Called by:    cpm_const (CP/M BIOS jumpblock)
bios_const:
        ld l,#00
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_conin [#C61A]
; Tasks:        CP/M 2.2 BIOS function 3 CONIN: wait for a console character, A = character.
;               L = &09: entry +&09 of char_io_table, device by the CON: field. Observed (CRT ->
;               con_crt_in).
; Called by:    cpm_conin (CP/M BIOS jumpblock)
bios_conin:
        ld l,#09
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_conout [#C61E]
; Tasks:        CP/M 2.2 BIOS function 4 CONOUT: character C to the console. L = &12: entry +&12
;               of char_io_table, device by the CON: field. Observed (CRT -> con_crt_out).
; Called by:    cpm_conout (CP/M BIOS jumpblock)
bios_conout:
        ld l,#12
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_punch [#C622]
; Tasks:        CP/M 2.2 BIOS function 6 PUNCH: character C to the punch device. L = &24: entry
;               +&24 of char_io_table, device by the PUN: field (TTY SIO A, PTP ignored, UP1 SIO B,
;               UP2 screen).
; Called by:    cpm_punch (CP/M BIOS jumpblock)
bios_punch:
        ld l,#24
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_reader [#C626]
; Tasks:        CP/M 2.2 BIOS function 7 READER: A = character from the reader device. L = &1B:
;               entry +&1B of char_io_table, device by the RDR: field (TTY SIO A, PTR end of file
;               &1A, UR1 SIO B, UR2 keyboard).
; Called by:    cpm_reader (CP/M BIOS jumpblock)
bios_reader:
        ld l,#1B
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_list [#C62A]
; Tasks:        CP/M 2.2 BIOS function 5 LIST: character C to the list device. L = &2D: entry
;               +&2D of char_io_table, device by the LST: field (TTY SIO A, CRT ignored, LPT printer,
;               UL1 SIO B). Observed: PIP LST:= with LST: = LPT: -> char_list_out.
; Called by:    cpm_list (CP/M BIOS jumpblock)
bios_list:
        ld l,#2D
        jr bios_char_io
; ----------------------------------------------------------------------
; Subroutine: bios_listst [#C62E]
; Tasks:        CP/M 2.2 BIOS function 15 LISTST: A = &FF list device ready, 0 not. L = &36:
;               entry +&36 of char_io_table, device by the LST: field (TTY SIO A out status, CRT
;               ready, LPT printer status, UL1 SIO B out status).
; Called by:    cpm_listst (CP/M BIOS jumpblock)
bios_listst:
        ld l,#36
; ----------------------------------------------------------------------
; Subroutine: bios_char_io [#C630]
; Tasks:        Common part of the seven character I/O functions (CONST, CONIN, CONOUT, READER,
;               PUNCH, LIST, LISTST): through bios_entry into the firmware's environment, then
;               pick the device routine from char_io_table by the function's 9-byte entry (L)
;               and its IOBYTE field (&0003), and JP to it with IX = &B04D (console state) and
;               A = 0. Observed: CONST, CONIN, CONOUT (CON: = CRT:), LIST (LST: = LPT:).
; Input:        L = offset of the function's entry in char_io_table; C = character (output)
; Output:       as the device routine (A = character / status)
; Changed:      AF, BC, DE, HL (the alternate registers, IX, IY are restored by bios_entry)
; Entered from: bios_const, bios_conin, bios_conout, bios_reader, bios_punch, bios_list,
;               bios_listst
; Calls:        bios_entry -> the device routine
bios_char_io:
        call bios_entry                 ; on to &C635 in the firmware's environment (observed)
        defb #35,#C6
        ld h,#00                        ; HL = the function's entry ...
        ld de,char_io_table             ; ... in char_io_table
        add hl,de
        ld b,(hl)                       ; B = rotate count: brings the function's IOBYTE field to bits 1-2
        inc hl
        ld a,(#0003)                    ; IOBYTE
cio_rotate:
        rlca                            ; rotate the IOBYTE until the function's field is in bits 1-2
        djnz cio_rotate
        and #06                         ; field x 2
        ld e,a
        ld d,#00
        add hl,de                       ; HL = the field's word in the entry
        call load_hl_indirect           ; HL = the device routine
        ld ix,con_cursor_count          ; IX = console state (&B04D: cursor counter, autostart flag, pointer, count)
        xor a                           ; A = 0 (the stubs return it)
        jp (hl)                         ; to the device routine
; ----------------------------------------------------------------------
; Data: char_io_table [#C652]
; Contents:     One 9-byte entry per character function (offset = L of the function): a
;               rotate count (RLCA x n brings the IOBYTE field to bits 1-2), then the routine
;               for field value 0, 1, 2, 3. SIO = the extended jumpblock at &BE80 (vortex RS232C
;               interface; observed with I/O injection, the emulator has no DART).
;               +&00 CONST   (CON:, bits 0-1): TTY SIO A in status &BEA7, CRT con_crt_status,
;                             BAT char_status_ready, UC1 SIO B in status &BEAA
;               +&09 CONIN   (CON:): TTY SIO A in &BEB3, CRT con_crt_in, BAT char_out_none
;                             (returns A = 0), UC1 SIO B in &BEB6
;               +&12 CONOUT  (CON:): TTY SIO A out, CRT con_crt_out, BAT char_out_none, UC1 SIO B out
;               +&1B READER  (RDR:, bits 2-3): TTY SIO A in &BEB3, PTR char_in_eof (&1A),
;                             UR1 SIO B in &BEB6, UR2 con_crt_in (keyboard)
;               +&24 PUNCH   (PUN:, bits 4-5): TTY SIO A out, PTP char_out_none, UP1 SIO B out,
;                             UP2 con_crt_out (screen)
;               +&2D LIST    (LST:, bits 6-7): TTY SIO A out, CRT char_out_none (!), LPT
;                             char_list_out (printer), UL1 SIO B out
;               +&36 LISTST  (LST:): TTY SIO A out status &BEAD, CRT char_status_ready, LPT
;                             char_list_status, UL1 SIO B out status &BEB0
;               Note: BAT (CON: = 2) is not DR's batch mode (READER in, LIST out) - it is a
;               dead console (status ready, input 0, output ignored; observed). LST: = CRT: drops
;               the characters. Every entry observed (STAT DEV:/VAL:, PIP, LS.COM, sio_sim.py).
; Used by:      bios_char_io
char_io_table:
        defb #01                        ; CONST: rotate 1 (CON: field)
        defw #BEA7                      ; TTY: SIO A in status (&BEA7) (observed, CON: = TTY:)
        defw con_crt_status             ; CRT: keyboard status
        defw char_status_ready          ; BAT: always ready (observed: CON: = BAT: is a dead console)
        defw #BEAA                      ; UC1: SIO B in status (&BEAA) (observed, CON: = UC1:)
        defb #01                        ; CONIN: rotate 1 (CON: field)
        defw #BEB3                      ; TTY: SIO A in (&BEB3) (observed)
        defw con_crt_in                 ; CRT: keyboard (with the autostart string)
        defw char_out_none              ; BAT: no input (A = 0) (observed)
        defw #BEB6                      ; UC1: SIO B in (&BEB6) (observed)
        defb #01                        ; CONOUT: rotate 1 (CON: field)
        defw cpm_ext_sio_a_out          ; TTY: SIO A out (observed)
        defw con_crt_out                ; CRT: screen
        defw char_out_none              ; BAT: ignored (observed)
        defw cpm_ext_sio_b_out          ; UC1: SIO B out (observed)
        defb #07                        ; READER: rotate 7 (RDR: field, bits 2-3)
        defw #BEB3                      ; TTY: SIO A in (&BEB3) (observed, PIP R.TXT=RDR:)
        defw char_in_eof                ; PTR: end of file (&1A) (observed: RDR: = PTR:, PIP R.TXT=RDR: made an empty file)
        defw #BEB6                      ; UR1: SIO B in (&BEB6) (observed)
        defw con_crt_in                 ; UR2: keyboard (observed)
        defb #05                        ; PUNCH: rotate 5 (PUN: field, bits 4-5)
        defw cpm_ext_sio_a_out          ; TTY: SIO A out (observed: PIP PUN:= sends 40 x &00, the text, &1A, 40 x &00)
        defw char_out_none              ; PTP: ignored (observed)
        defw cpm_ext_sio_b_out          ; UP1: SIO B out (observed)
        defw con_crt_out                ; UP2: screen (observed: PUN: = UP2:, PIP PUN:= showed the text)
        defb #03                        ; LIST: rotate 3 (LST: field, bits 6-7)
        defw cpm_ext_sio_a_out          ; TTY: SIO A out (observed)
        defw char_out_none              ; CRT: ignored (!) - observed: LST: = CRT:, PIP LST:= printed nothing
        defw char_list_out              ; LPT: printer (observed)
        defw cpm_ext_sio_b_out          ; UL1: SIO B out (observed)
        defb #03                        ; LISTST: rotate 3 (LST: field)
        defw #BEAD                      ; TTY: SIO A out status (&BEAD) (observed: LS.COM, busy -> 0)
        defw char_status_ready          ; CRT: always ready (observed: &FF)
        defw char_list_status           ; LPT: printer status (observed: &FF, no printer in the emulator)
        defw #BEB0                      ; UL1: SIO B out status (&BEB0) (observed: &FF)
; ----------------------------------------------------------------------
; Subroutine: con_crt_status [#C691]
; Tasks:        CONST for CON: = CRT: - a key ready? KM READ CHAR, and the key is put back
;               (KM CHAR RETURN) for CONIN. Also counts the cursor-off counter (&B04D) down:
;               after output (con_crt_out sets it to &FF and hides the cursor) the cursor comes
;               back after 255 status calls without output, so programs that poll the
;               keyboard while they print do not make the cursor flicker. Observed (CCP, STAT).
; Input:        IX = console state, A = 0
; Output:       A = &FF key ready, 0 none
; Changed:      AF
; Called by:    bios_char_io (char_io_table: CONST, CRT)
con_crt_status:
        or (ix+#00)                     ; cursor-off counter running?
        jr z,ccs_read                   ; no
        dec (ix+#00)                    ; count down ...
        call z,TXT_CUR_ON               ; ... at 0: cursor on again
ccs_read:
        call KM_READ_CHAR               ; key?
        call c,KM_CHAR_RETURN           ; yes: put it back for CONIN
        sbc a,a                         ; A = &FF key, 0 none
        ret
; ----------------------------------------------------------------------
; Subroutine: con_crt_in [#C6A4]
; Tasks:        CONIN for CON: = CRT: (also READER UR2:). While the command buffer (SET CMND
;               BUFFER &BEA4 - INSTALL's autostart string) still has characters, take the next
;               one (cci_autostart). Otherwise switch the cursor on and wait for a key with a
;               blinking cursor (wait_key_cursor). Observed: typing at A>.
; Input:        IX = console state, A = 0
; Output:       A = character
; Changed:      AF, HL
; Called by:    bios_char_io (char_io_table: CONIN CRT, READER UR2)
con_crt_in:
        or (ix+#04)                     ; autostart characters left?
        jr nz,cci_autostart             ; yes: take the next one
        or (ix+#00)                     ; cursor-off counter running?
        ld (ix+#00),#00                 ; stop it
        call nz,TXT_CUR_ON              ; it was: cursor on
        jp wait_key_cursor              ; wait for a key
; Autostart string (observed: DIR + &0D after INSTALL, at every |CPM,2 start): a key pressed
; now comes first.
cci_autostart:
        call KM_READ_CHAR               ; a key pressed?
        jr c,cci_key                    ; yes
        dec (ix+#04)                    ; one character less
        ld l,(ix+#02)                   ; HL = pointer into the string
        ld h,(ix+#03)
        ld a,(hl)                       ; A = the next character
        inc hl
        ld (ix+#02),l                   ; pointer + 1
        ld (ix+#03),h
        ret
; A key during the autostart string. Observed (key held while |CPM,2 started):
; flag &FF (the Vortex boot sector's value): the key comes first, then the string - CCP got
; "xDIR"; flag 0 (A set to 0 at bios_set_cmnd_buffer): the key cancels the rest - only "x".
cci_key:
        inc (ix+#01)                    ; autostart_flag ...
        dec (ix+#01)                    ; ... 0?
        ret nz                          ; not 0: return the key, the string goes on afterwards (observed)
        ld (ix+#04),#00                 ; 0: the key cancels the rest of the string (observed)
        ret
; ----------------------------------------------------------------------
; Subroutine: con_crt_out [#C6D9]
; Tasks:        CONOUT for CON: = CRT: (also PUNCH UP2:): hide the cursor (cursor-off counter
;               &FF, see con_crt_status), TXT OUTPUT the character C - control characters go to the
;               firmware unfiltered, so they act as CPC control codes (e.g. &1A = SET WINDOW with 4
;               parameters; after PIP PUN:= with PUN: = UP2: the further output was invisible and
;               the cursor stood top left - probably PIP's closing &1A setting a tiny window). After a
;               control character the cursor may stand outside the window; then TXT PLACE CURSOR /
;               TXT REMOVE CURSOR bring it back in (by the firmware manual the pending scroll is done
;               at once; this branch ran during the printer test, the exact trigger was not
;               isolated). Observed: all CCP, STAT and PIP output.
; Input:        IX = console state, A = 0, C = character
; Changed:      AF, HL (+ firmware)
; Called by:    bios_char_io (char_io_table: CONOUT CRT, PUNCH UP2)
con_crt_out:
        or (ix+#00)                     ; cursor-off counter running?
        call z,TXT_CUR_OFF              ; no: hide the cursor now
        ld (ix+#00),#FF                 ; (re)start it
        ld a,c                          ; the character
        call TXT_OUTPUT
        cp #20                          ; a control character?
        ret nc                          ; no: done
        call TXT_GET_CURSOR             ; H, L = the cursor position ...
        call TXT_VALIDATE               ; ... inside the window?
        ret c                           ; yes: done
        call TXT_PLACE_CURSOR           ; no: place the cursor (validated: scrolls) ...
        jp TXT_REMOVE_CURSOR            ; ... and take it away again
; ----------------------------------------------------------------------
; Subroutine: char_list_status [#C6F7]
; Tasks:        LIST status for the character I/O table of bios_listst: printer busy?
;               Code (classified statically 2026-10-25: the table entries #C6F7 / #C6FD and
;               the stubs #C712 / #C715 / #C717 point here, raw opcodes give a clean
;               instruction run up to #C717). Not observed (CP/M side, Part B).
; Output:       A = &FF printer ready, 0 busy
; Changed:      AF
; Called by:    character I/O table of bios_listst (not observed)
char_list_status:
        call MC_BUSY_PRINTER            ; CY = 1: busy
        ccf                             ; CY = 1: ready
        sbc a,a                         ; A = &FF ready, 0 busy
        ret
; ----------------------------------------------------------------------
; Subroutine: char_list_out [#C6FD]
; Tasks:        LIST output to LST: = LPT: (printer): send the character C, 50 tries of MC PRINT
;               CHAR (each with the firmware's own timeout); then "Drucker nicht bereit - Wiederholen
;               J/N ?" (message &11): J tries again, N warm boots CP/M (wboot_body) - the running
;               program is abandoned. Observed: PIP LST:= (the emulator has no printer: MC PRINT
;               CHAR succeeds at once); with CY cleared after MC PRINT CHAR 50 times (injection at
;               &C703) the question came; J went on printing, N gave a warm boot to A>.
; Input:        C = character
; Changed:      AF, B
; Called by:    character I/O table of bios_listst (not observed)
char_list_out:
        ld a,c                          ; character
        ld b,#32                        ; 50 tries
clo_retry:
        call MC_PRINT_CHAR              ; CY = 1: sent
        ret c                           ; sent
        djnz clo_retry                  ; next try
        push bc                         ; keep the character
        ld a,#11                        ; "Drucker nicht bereit" + "Wiederholen J/N ?"
        call print_error_and_ask
        pop bc
        jr nz,char_list_out             ; J: try again (observed)
        jp wboot_body                   ; N: CP/M warm boot, the program is abandoned (observed)
; Stub of the character I/O table: input without a device (READER PTR:) - returns &1A, end of
; file (as DR's manual asks for a missing reader). Observed: PIP R.TXT=RDR: with RDR: = PTR:
; gave an empty file.
char_in_eof:
        ld a,#1A                        ; &1A = end of file
        ret
; Stub of the character I/O table: status without a device - always ready (shares the ret of char_out_none).
char_status_ready:
        ld a,#FF                        ; &FF = ready; falls through into char_out_none's ret
; Stub of the character I/O table: output without a device - ignored.
char_out_none:
        ret                             ; nothing to do
; ----------------------------------------------------------------------
; Subroutine: bios_set_sio [#C718]
; Tasks:        Extended BIOS &BEA1 SET SIO: initialise the vortex RS232C interface from a
;               12-byte parameter block - both channels of the Z80 DART (control ports &FADD
;               channel A, &FADF channel B; data ports one lower) and the three counters of the
;               8253 baud rate timer (&FBDC-&FBDE, control &FBDF; each counter mode 3, binary).
;               Block: +0..2 channel A WR4, WR5, WR3; +3..5 channel B WR4, WR5, WR3; +6/7
;               counter 0 (channel A send), +8/9 counter 1 (channel A receive), +10/11 counter 2
;               (channel B), low byte first.
;               Observed: both boot sectors call it with HL = &030A (their configuration sector
;               at &0300). Port writes logged with |CPM,2: FADD 18 04 44 05 6A 03 E1, FADF the same,
;               FBDF 36, FBDC 07 00, FBDF 76, FBDD 07 00, FBDF B6, FBDE 0D 00. WR4 &44 = clock x16,
;               1 stop bit, no parity; WR5 &6A = 8 bits, Tx on, RTS; WR3 &E1 = 8 bits, auto enables,
;               Rx on. Counters 13/13/13 (Amstrad sector, |CPM,1) and 7/7/13 (Vortex sector) - the
;               INSTALL defaults 19200/19200/9600 baud, so the timer clock is about 2 MHz (2 MHz /
;               16 / 13 = 9615; derived). The VDOS 2.0 manual has "position head indirection" at
;               &BEA1; 2.11-X has SET SIO.
; Input:        HL = parameter block (12 bytes)
; Output:       sio_wr5 (see there)
; Changed:      AF, BC, HL
; Called by:    cpm_ext_set_sio (&BEA1), from the boot sectors (return &01B7 Amstrad, &0153 Vortex)
; Calls:        dart_init_channel, set_counter (falls through at the end)
bios_set_sio:
        ld bc,#FADD                     ; DART channel A control port
        call dart_init_channel          ; WR4, WR5, WR3 of channel A
        inc c                           ; &FADF: channel B
        inc c
        call dart_init_channel          ; WR4, WR5, WR3 of channel B
        ld bc,#FBDF                     ; 8253 control port
        ld a,#36                        ; counter 0, low then high byte, mode 3 (square wave), binary
        out (c),a
        ld c,#DC                        ; &FBDC: counter 0 = channel A send clock
        call set_counter                ; +6/7
        ld c,#DF                        ; control port
        ld a,#76                        ; counter 1, mode 3
        out (c),a
        ld c,#DD                        ; &FBDD: counter 1 = channel A receive clock
        call set_counter                ; +8/9
        ld c,#DF                        ; control port
        ld a,#B6                        ; counter 2, mode 3
        out (c),a
        dec c                           ; &FBDE: counter 2 = channel B clock; falls into set_counter for +10/11
; ----------------------------------------------------------------------
; Subroutine: set_counter [#C741]
; Tasks:        Load an 8253 counter: two bytes from (HL) to port BC, low byte first.
; Input:        BC = counter port, HL = the value (2 bytes)
; Output:       HL + 2
; Changed:      AF, HL
; Called by:    bios_set_sio (also falls through into it)
set_counter:
        ld a,(hl)                       ; low byte
        inc hl
        out (c),a
        ld a,(hl)                       ; high byte
        inc hl
        out (c),a
        ret
; ----------------------------------------------------------------------
; Subroutine: dart_init_channel [#C74A]
; Tasks:        Initialise one DART channel: channel reset, then WR4, WR5 and WR3 from (HL);
;               keep WR5 in sio_wr5 for the status handshake. The channel is told apart by bit
;               0 of C - 1 for both &FADD and &FADF, so both channels store at &BE02 (observed).
; Input:        BC = control port of the channel, HL = its 3 register bytes
; Output:       HL + 3
; Changed:      AF, HL
; Called by:    bios_set_sio
dart_init_channel:
        ld a,#18                        ; WR0 command 3: channel reset
        out (c),a
        ld a,#04                        ; select WR4 ...
        out (c),a
        ld a,(hl)                       ; ... clock mode, stop bits, parity
        inc hl
        out (c),a
        ld a,#05                        ; select WR5 ...
        out (c),a
        ld a,(hl)                       ; ... DTR, Tx bits, Tx enable, RTS
        inc hl
        out (c),a
        push hl
        ld hl,sio_wr5                   ; keep WR5: sio_wr5 ...
        bit 0,c                         ; bit 0 of the port: 1 for both channels (&DD, &DF) ...
        jr z,dic_store_wr5
        inc hl                          ; ... so always +1 (&BE02)
dic_store_wr5:
        ld (hl),a                       ; WR5 copy
        pop hl
        ld a,#03                        ; select WR3 ...
        out (c),a
        ld a,(hl)                       ; ... Rx bits, auto enables, Rx enable
        inc hl
        out (c),a
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_sio_a_in_status [#C772]
; Tasks:        Extended BIOS SIO channel A input status (control port &FADD): a received
;               character there? Pulses DTR while it looks (sio_in_status). Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as CONST with
;               CON: = TTY: (the CCP ran over the interface).
; Output:       CY = 1 / A = &FF: character ready; CY = 0 / A = 0: none
; Changed:      AF, BC, DE, HL
; Called by:    cpm_ext_sio_a_in_status (&BE80 extended jumpblock)
bios_sio_a_in_status:
        ld bc,#FADD                     ; DART channel A control port
        jr sio_in_status
; ----------------------------------------------------------------------
; Subroutine: bios_sio_b_in_status [#C777]
; Tasks:        Extended BIOS SIO channel B input status (control port &FADF): a received
;               character there? Pulses DTR while it looks (sio_in_status). Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as CONST with
;               CON: = UC1: (the CCP ran over the interface).
; Output:       CY = 1 / A = &FF: character ready; CY = 0 / A = 0: none
; Changed:      AF, BC, DE, HL
; Called by:    cpm_ext_sio_b_in_status (&BE80 extended jumpblock)
bios_sio_b_in_status:
        ld bc,#FADF
; ----------------------------------------------------------------------
; Subroutine: sio_in_status [#C77A]
; Tasks:        Receive status of a DART channel: a character there (RR0 bit 0)? If not,
;               switch DTR on (WR5 bit 7) - the sender may send now - look again and switch DTR
;               off again: DTR is only on while CP/M polls, a hardware handshake. Observed with I/O
;               injection: RR0 &04 (nothing) -> WR5 &EA (DTR on), RR0 &05 -> WR5 &6A (DTR off).
;               For channel A it uses the WR5 copy at &BE02 (see sio_wr5).
; Input:        BC = control port
; Output:       CY = 1 / A = &FF: character ready; CY = 0 / A = 0: none
; Changed:      AF, DE, HL
; Entered from: bios_sio_a_in_status, bios_sio_b_in_status (falls through); called by sio_in_wait
sio_in_status:
        ld hl,sio_wr5                   ; sio_wr5 ...
        bit 0,c                         ; ... by bit 0 of the port (always 1: &BE02, see dart_init_channel)
        jr z,sis_read_rr0
        inc hl
sis_read_rr0:
        in a,(c)                        ; RR0
        rrca                            ; CY = bit 0: a received character?
        sbc a,a                         ; A = &FF yes, 0 no
        ret c                           ; yes
        call dtr_on                     ; no: DTR on ...
        in a,(c)                        ; ... and look again
        rrca
        sbc a,a
        jr dtr_off                      ; DTR off again (the flags stay)
; ----------------------------------------------------------------------
; Subroutine: bios_sio_a_out_status [#C790]
; Tasks:        Extended BIOS SIO channel A output status (control port &FADD): transmit
;               buffer empty? (sio_out_status). Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as LISTST with LST: = TTY: (test
;               program LS.COM: CALL &AC2D).
; Output:       CY = 1 / A = &FF: ready to send; CY = 0 / A = 0: busy
; Changed:      AF, BC
; Called by:    cpm_ext_sio_a_out_status (&BE80 extended jumpblock)
bios_sio_a_out_status:
        ld bc,#FADD                     ; DART channel A control port
        jr sio_out_status
; ----------------------------------------------------------------------
; Subroutine: bios_sio_b_out_status [#C795]
; Tasks:        Extended BIOS SIO channel B output status (control port &FADF): transmit
;               buffer empty? (sio_out_status). Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as LISTST with LST: = UL1: (test
;               program LS.COM: CALL &AC2D).
; Output:       CY = 1 / A = &FF: ready to send; CY = 0 / A = 0: busy
; Changed:      AF, BC
; Called by:    cpm_ext_sio_b_out_status (&BE80 extended jumpblock)
bios_sio_b_out_status:
        ld bc,#FADF
; ----------------------------------------------------------------------
; Subroutine: sio_out_status [#C798]
; Tasks:        Send status of a DART channel: transmit buffer empty (RR0 bit 2)? Observed
;               with I/O injection: RR0 &00 -> A = 0 (busy), RR0 &04 -> A = &FF.
; Input:        BC = control port
; Output:       CY = 1 / A = &FF: ready to send; CY = 0 / A = 0: busy
; Changed:      AF
; Entered from: bios_sio_a_out_status, bios_sio_b_out_status (falls through); called by sio_out_wait
sio_out_status:
        in a,(c)                        ; RR0
        and #04                         ; bit 2: transmit buffer empty?
        ret z                           ; no: A = 0, CY = 0
        scf                             ; yes: A = &FF, CY = 1
        sbc a,a
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_sio_a_in [#C7A0]
; Tasks:        Extended BIOS SIO channel A input: wait for a character (sio_in_status, DTR
;               handshake), read it from the data port &FADC. Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as READER with
;               RDR: = TTY: (PIP file=RDR:) and as CONIN with CON: = TTY:.
; Output:       A = the character
; Changed:      AF, BC, DE, HL
; Called by:    cpm_ext_sio_a_in (&BE80 extended jumpblock)
bios_sio_a_in:
        ld bc,#FADD                     ; DART channel A control port
        jr sio_in_wait
; ----------------------------------------------------------------------
; Subroutine: bios_sio_b_in [#C7A5]
; Tasks:        Extended BIOS SIO channel B input: wait for a character (sio_in_status, DTR
;               handshake), read it from the data port &FADE. Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as READER with
;               RDR: = UR1: (PIP file=RDR:) and as CONIN with CON: = UC1:.
; Output:       A = the character
; Changed:      AF, BC, DE, HL
; Called by:    cpm_ext_sio_b_in (&BE80 extended jumpblock)
bios_sio_b_in:
        ld bc,#FADF
sio_in_wait:
        call sio_in_status              ; wait for a received character
        jr nc,sio_in_wait
        dec bc                          ; data port (control - 1)
        in a,(c)                        ; A = the character
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_sio_a_out [#C7B1]
; Tasks:        Extended BIOS SIO channel A output: wait until the transmit buffer is
;               empty, send C to the data port &FADC. Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as PUNCH / LIST with
;               PUN: = TTY: / LST: = TTY: (PIP) and as CONOUT with CON: = TTY:.
; Input:        C = the character
; Changed:      AF, BC
; Called by:    cpm_ext_sio_a_out (&BE80 extended jumpblock)
bios_sio_a_out:
        ld a,c                          ; the character
        ld bc,#FADD                     ; DART channel A control port
        jr sio_out_wait
; ----------------------------------------------------------------------
; Subroutine: bios_sio_b_out [#C7B7]
; Tasks:        Extended BIOS SIO channel B output: wait until the transmit buffer is
;               empty, send C to the data port &FADE. Observed with I/O injection (output/tools/sio_sim.py: IN from
;               &FADC-&FADF answered by the script; the emulator has no serial interface). Used as PUNCH / LIST with
;               PUN: = UP1: / LST: = UL1: (PIP) and as CONOUT with CON: = UC1:.
; Input:        C = the character
; Changed:      AF, BC
; Called by:    cpm_ext_sio_b_out (&BE80 extended jumpblock)
bios_sio_b_out:
        ld a,c
        ld bc,#FADF
sio_out_wait:
        push af                         ; keep the character
sow_loop:
        call sio_out_status             ; wait until the transmit buffer is empty
        jr nc,sow_loop
        pop af
        dec bc                          ; data port (control - 1)
        out (c),a                       ; send it
        ret
; ----------------------------------------------------------------------
; Subroutine: dtr_on [#C7C6]
; Tasks:        Write WR5 = the copy at (HL) with DTR (bit 7) on; second entry dtr_off: with
;               DTR off; both through write_wr5.
; Input:        BC = control port, HL = sio_wr5 entry
; Changed:      DE
; Called by:    sio_in_status
dtr_on:
        ld d,(hl)                       ; WR5 copy ...
        set 7,d                         ; ... DTR on
write_wr5:
        ld e,#05                        ; select WR5 ...
        out (c),e
        out (c),d                       ; ... and write it
        ret
dtr_off:
        ld d,(hl)                       ; WR5 copy ...
        res 7,d                         ; ... DTR off
        jr write_wr5
; ----------------------------------------------------------------------
; Subroutine: seldsk [#C7D5]
; Tasks:        CP/M BIOS SELDSK (reached through dos_seldsk / bios_seldsk): select drive C.
;               Stores it in sek_drive, returns its DPH and sends FDC SPECIFY with the drive's
;               step rate. If the drive is not the cached one (xpb_cache_drive, &FF after every
;               CAS call) and is the 3" drive, the format is detected first when
;               autodetect_format is set (rom_init and the |CPM,1 boot set it): always if E bit 0
;               = 1, else only if the XPB byte after the flag byte (auto-select) is 0. E is also
;               used as the drive number for the 3" test. Observed: on every disc access; with a
;               blank data format disc under BASIC the format was recognised (CAT: 178K frei).
; Input:        C = drive (0/1), E = see above
; Output:       HL = DPH of the drive, or 0 for a drive >= 2
; Changed:      AF, BC, DE, HL
; Called by:    dos_seldsk (&BE8F), bios_seldsk (through bios_entry)
; Calls:        dph_address, specify_for_drive, drive_flag_offset, xpb_byte, detect_format
seldsk:
        ld hl,#0000                     ; HL = 0: the error return ...
        ld a,c                          ; drive ...
        cp #02                          ; ... 0 or 1?
        ret nc                          ; no: HL = 0
        ld (sek_drive),a                ; sek_drive = C
        ld l,a                          ; L = drive
        ld a,(xpb_cache_drive)          ; the cached drive? (Z kept through the calls below)
        cp l                            ; Z = the cached drive (kept to C7F3)
        ld a,l                          ; A = drive again
        ld hl,(xpb_cache_dph)           ; (H is overwritten by dph_address)
        ld l,a                          ; (L = drive for dph_address)
        call dph_address                ; HL = DPH of drive L
        push af
        push hl
        call specify_for_drive          ; SPECIFY with this drive's step rate
        pop hl
        pop af
        ret z                           ; same drive as cached: done
        call drive_flag_offset          ; Z = E is the 3" drive
        ret nz                          ; Vortex drive: done
        ld d,a                          ; D = flag byte offset
        ld a,(autodetect_format)        ; format detection on? (set by rom_init and the |CPM,1 boot)
        or a                            ; CP/M?
        ld a,d                          ; A = flag offset
        ret z                           ; off (relative file record access): done
        push de
        rr e                            ; E bit 0 ...
        pop de
        jr c,sd_detect                  ; ... set: detect in any case
        inc a                           ; else the auto-select byte after the flag byte ...
        call xpb_byte                   ; ... (XPB byte flag offset + 1)
        or a                            ; 0 = auto-select
        ret nz                          ; not 0: keep the format
sd_detect:
        push hl                         ; keep the DPH
        call detect_format              ; detect the 3" disc's format
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: detect_format [#C811]
; Tasks:        Detect the format of the disc in the 3" drive: move the head to its current track with messages off and
;               the default retry count, read the next sector ID (READ ID) and pass its sector
;               number R to select_format (&4x system, &Cx data, else IBM). Observed under BASIC
;               (system and data format discs) and under CP/M.
; Output:       CY = 0: no ID could be read
; Changed:      AF, BC, DE, HL
; Called by:    seldsk
; Calls:        xpb_byte, bios_set_message, set_retry_default, bios_move_track, bios_set_retry_count, fdc_command_unit, select_format; falls through into select_format
detect_format:
        ld a,#16                        ; XPB byte &16: the head's current track ...
        call xpb_byte                   ; current track (XPB byte &16)
        ld d,a                          ; ... as the target: no real move, but recalibrates if needed
        ld a,#FF                        ; no messages while probing ...
        call bios_set_message           ; (keep the old setting in A, pushed next)
        push af                         ; ... keep the old setting
        call set_retry_default          ; default retry count, keep the old one
        push af
        call bios_move_track            ; seek (motor on, head position known)
        di                              ; keep the result flags in AF' ...
        ex af,af'
        pop af                          ; ... while the old retry count ...
        call bios_set_retry_count       ; old retry count back
        pop af                          ; ... and message setting come back
        call bios_set_message           ; old message setting back
        or a                            ; result flags of the seek (in AF')
        ex af,af'                       ; result flags back
        ret nc                          ; seek failed: no format change
        ld a,#4A                        ; FDC READ ID: C, H, R, N of the next sector under the head
        call fdc_command_unit           ; READ ID with the unit/head byte
        ret nc                          ; failed
        ld a,(fdc_result+5)             ; R = sector number of that ID
; ----------------------------------------------------------------------
; Subroutine: select_format [#C83A]
; Tasks:        Set the 3" drive's XPB to the format given by a sector number (AMSDOS SELECT
;               FORMAT): copy the system format XPB (xpb_3inch, 22 bytes); for a data format
;               (&Cx) or IBM format (other) then patch SPT (XPB+0), the low byte of DSM (+5) and
;               the six bytes OFF .. format gap (+13..+18) from format_params_data /
;               format_params_ibm. Does nothing for the Vortex drive (its format is fixed:
;               xpb_vortex). Observed all three, under BASIC: system disc; blank data disc (R =
;               &C1: SPT 36, DSM 179, OFF 0, sectors &C1-&C9, CAT 178K frei); blank IBM disc made
;               offline (output/ibm_blank.dsk; R = &01-&08: SPT 32, DSM 155, OFF 1, directory on
;               track 1; after one 1K file CAT: 153K frei; SAVE/LOAD work).
; Input:        A = a sector number of the format (&41 system, &C1 data, &01 IBM), E = drive
; Changed:      AF, BC, DE, HL
; Called by:    detect_format, bios_select_format
select_format:
        ld l,a                          ; L = the sector number
        call drive_flag_offset          ; Z = 3" drive
        ld a,l                          ; A = sector number again
        ret nz                          ; Vortex drive: nothing to do
        push af
        xor a                           ; HL = XPB of drive E (byte 0) ...
        call xpb_byte_address           ; HL = XPB byte 0 of drive E
        push hl
        ld de,xpb_3inch                 ; ... gets the system format ...
        ex de,hl                        ; HL = xpb_3inch, DE = the drive's XPB
        ld bc,#0016                     ; ... (22 bytes: DPB + first sector .. records per sector)
        ldir                            ; copy it
        pop hl
        pop af
        and #C0                         ; format = top two bits of the sector number
        cp #40                          ; &4x: system format, done
        ret z
sf_patch:
        ld de,format_params_data        ; data format (&Cx) ... (observed)
        cp #C0                          ; ... or IBM (else: R AND &C0 = 0, sectors 1-8)
        jr z,sf_copy                    ; data: format_params_data
        ld de,format_params_ibm         ; IBM format: format_params_ibm (observed: IBM disc, READ ID R = &06..&08)
sf_copy:
        ld a,(de)                       ; XPB+0: SPT ...
        ld (hl),a
        inc de
        ld bc,#0005                     ; ... then to XPB+5 ...
        add hl,bc
        ld a,(de)                       ; ... DSM low byte ...
        ld (hl),a
        inc de
        ld bc,#0008                     ; ... then to XPB+13 ...
        add hl,bc
        dec bc                          ; (6 bytes)
        dec bc
        ex de,hl
        ldir                            ; ... OFF (2), first sector, sectors per track, gap read/write, gap format
        ret
format_params_data:
        defb #24,#B3,#00,#00,#C1,#09,#2A,#52 ; data format: SPT 36, DSM 179, OFF 0, first sector &C1, 9 sectors, gaps &2A/&52 (observed)
format_params_ibm:
        defb #20,#9B,#01,#00,#01,#08,#2A,#50 ; IBM format: SPT 32, DSM 155, OFF 1, first sector &01, 8 sectors, gaps &2A/&50 (observed; = AMSDOS manual 9.9)
; ----------------------------------------------------------------------
; Subroutine: specify_for_drive [#C884]
; Tasks:        Send FDC SPECIFY with the step rate of drive E: the 3" step rate (high nibble of
;               the step rates byte) for a 3" drive (flag bit 5), else the Vortex step rate (low
;               nibble). Continues in bios_setup_disc (bsd_specify) with HUT/HLT from
;               specify_bytes. Observed.
; Input:        E = drive
; Changed:      AF, BC, HL, E
; Called by:    seldsk
; Calls:        drive_flag, bsd_specify
specify_for_drive:
        ld e,a
        call drive_flag                 ; A = flag byte of drive E
        bit 5,a                         ; 3" drive?
        ld a,(disc_time_constants+6)    ; step rates: high nibble 3", low nibble Vortex
        jr z,sfd_specify                ; no: the low nibble is the right one
        rlca                            ; yes: swap the nibbles (3" rate into the low nibble)
        rlca                            ; (nibbles swapped by 4 rotations)
        rlca                            ; (...)
        rlca                            ; (...)
sfd_specify:
        push af                         ; step rate byte on the stack for bsd_specify
        ld hl,specify_bytes             ; HUT, HLT/ND bytes
        jp bsd_specify                  ; FDC SPECIFY
; ----------------------------------------------------------------------
; Subroutine: read_record [#C89A]
; Tasks:        CP/M BIOS READ: read record sek_record of sek_track into the DMA buffer.
;               Deblocking after Digital Research's CP/M 2.2 sample algorithm (DEBLOCK.ASM): CP/M works
;               with 128-byte records, the disc with 512-byte sectors held in the host buffer
;               (workspace+&23E). A record is read from / written into the host buffer; the
;               buffer is written back only when another sector is needed (or at once for a
;               directory write).
;               Observed.
; Input:        IY = VDOS workspace
; Output:       A = 0: ok; else error (CY = 0)
; Changed:      AF, BC, DE, HL
; Called by:    dos_read (&BE9B), bios_read (through bios_entry)
; Calls:        rw_operation
read_record:
        ld a,(deblock_flags)            ; deblock_flags: keep hstwrt / hstact ...
        and #F0                         ; (bits 7-4 kept)
        or #32                          ; ... rsflag = 1 (read the sector), readop = 1, wrtype = 2
        ld (deblock_flags),a            ; deblock_flags
        xor a                           ; una_count = 0: no unallocated block is being written
        ld (una_count),a                ; una_count
        jr rw_operation                 ; the common part
; ----------------------------------------------------------------------
; Subroutine: write_record [#C8AA]
; Tasks:        CP/M BIOS WRITE: write the DMA buffer as record sek_record of sek_track.
;               Deblocking after Digital Research's CP/M 2.2 sample algorithm (DEBLOCK.ASM): CP/M works
;               with 128-byte records, the disc with 512-byte sectors held in the host buffer
;               (workspace+&23E). A record is read from / written into the host buffer; the
;               buffer is written back only when another sector is needed (or at once for a
;               directory write).
;               Write type C = 2 (first record of an unallocated block) starts counting the
;               block's records (una_*): while the following records continue that block the
;               sector does not have to be read first. Observed.
; Input:        C = write type: 0 normal, 1 directory, 2 unallocated block; IY = VDOS workspace
; Output:       A = 0: ok; else error (CY = 0)
; Changed:      AF, BC, DE, HL
; Called by:    dos_write (&BE9E), bios_write (through bios_entry)
; Calls:        xpb_byte, rw_operation
write_record:
        ld hl,deblock_flags
        ld a,(hl)                       ; deblock_flags: keep hstwrt, hstact, rsflag ...
        and #E0                         ; (bits 7-5 kept)
        or c                            ; ... readop = 0, wrtype = C
        ld (hl),a                       ; deblock_flags
        ld a,c                          ; write to an unallocated block?
        cp #02                          ; 2 = unallocated block?
        jr nz,wr_check_unalloc          ; no: check the block being written
        ld hl,sek_drive                 ; yes: una_count = records per block ...
        ld e,(hl)                       ; E = the drive
        ld a,#03                        ; ... (BLM + 1, XPB byte 3)
        call xpb_byte                   ; BLM (XPB byte 3)
        inc a                           ; + 1 = records per block
        ld de,una_count                 ; una_count ...
        ld (de),a                       ; una_count
        inc de                          ; ... and una_drive/track/record = sek_drive/track/record
        ld bc,#0003                     ; 3 bytes sek_drive/track/record ...
        ldir                            ; ... to una_drive/track/record
wr_check_unalloc:
        ld hl,una_count                 ; records left in the unallocated block?
        ld a,(hl)                       ; una_count ...
        or a                            ; ... 0?
        jr z,wr_alloc                   ; none: the sector must be read
        dec (hl)                        ; one record less
        inc hl
        ld de,sek_drive                 ; is the record the next one of that block (drive, track, record)?
        ld b,#03                        ; 3 bytes: drive, track, record
wr_compare_una:
        ld a,(de)                       ; sek_ byte ...
        cp (hl)                         ; ... = una_ byte?
        jr nz,wr_alloc                  ; no: read the sector
        inc de
        inc hl
        djnz wr_compare_una             ; next byte
        ld hl,una_drive                 ; yes: advance una_record ...
        ld e,(hl)                       ; E = una_drive
        inc hl
        inc hl
        inc (hl)                        ; una_record + 1
        xor a                           ; ... past the end of the track (SPT, XPB byte 0)?
        call xpb_byte                   ; records per track (SPT, XPB byte 0)
        cp (hl)                         ; end of the track?
        jr nz,wr_no_read                ; no
        ld (hl),#00                     ; yes: record 0 of the next track
        dec hl
        inc (hl)                        ; una_track + 1
wr_no_read:
        ld hl,deblock_flags             ; rsflag = 0: the sector need not be read first
        res 5,(hl)                      ; rsflag = 0
        jr rw_operation                 ; the common part
wr_alloc:
        ld hl,deblock_flags             ; rsflag = 1: read the sector before changing a record
        set 5,(hl)                      ; rsflag = 1
        inc hl                          ; una_count = 0
        ld (hl),#00                     ; una_count = 0
rw_operation:
        ld hl,deblock_flags             ; host buffer valid? ... (and valid from now on)
        bit 6,(hl)                      ; hstact: host buffer valid?
        set 6,(hl)                      ; (valid from now on)
        jr z,rwo_fill_host              ; no: fill it
        ld bc,sek_drive                 ; the wanted sector already in the host buffer? drive ...
        ld hl,hst_drive                 ; hst_drive
        ld a,(bc)                       ; sek_drive ...
        cp (hl)                         ; ... = hst_drive?
        jr nz,rwo_flush                 ; no
        ld e,a                          ; E = drive (for sek_host_sector)
        inc hl                          ; ... track ...
        inc bc
        ld a,(bc)                       ; sek_track ...
        cp (hl)                         ; ... = hst_track?
        jr nz,rwo_flush                 ; no
        call sek_host_sector            ; ... sector (record / records per sector)
        cp (hl)                         ; hst_sector?
        jr z,rwo_match                  ; yes: just copy the record
rwo_flush:
        ld a,(deblock_flags)            ; host buffer written to?
        bit 7,a                         ; hstwrt: buffer changed?
        ld a,#00                        ; A = 0: write ...
        scf                             ; (CY = 1 for the call)
        call nz,host_read_write         ; ... the host buffer back first
        ret nc                          ; write error
rwo_fill_host:
        ld hl,hst_drive                 ; hst_drive/track/sector = the wanted ones
        ld bc,sek_drive                 ; sek_drive ...
        ld a,(bc)                       ; ... = hst_drive
        ld (hl),a
        ld e,a                          ; E = drive
        inc hl
        inc bc
        ld a,(bc)                       ; sek_track ...
        ld (hl),a                       ; ... = hst_track
        call sek_host_sector            ; hst_sector = sek_record / records per sector
        ld (hl),a                       ; = hst_sector
        ld a,(deblock_flags)            ; read the sector first? (rsflag)
        bit 5,a                         ; rsflag: read first?
        ld a,#01                        ; A = 1: read ...
        scf                             ; (CY = 1 for the call)
        call nz,host_read_write         ; ... the sector into the host buffer
        ret nc                          ; read error
        ld hl,deblock_flags             ; host buffer = disc contents (hstwrt = 0)
        res 7,(hl)                      ; hstwrt = 0
rwo_match:
        ld hl,sek_drive                 ; the record's place in the host buffer:
        ld e,(hl)                       ; E = sek_drive
        inc hl
        inc hl
        ld a,#15                        ; (sek_record AND records per sector - 1) ...
        call xpb_byte                   ; records per sector (XPB byte &15) ...
        dec a                           ; ... - 1 = record mask
        and (hl)                        ; AND sek_record = record in the sector
        call host_buffer                ; HL = host buffer
        ld bc,#0080                     ; ... * 128
        or a                            ; index 0?
rwo_offset:
        jr z,rwo_copy                   ; done
        add hl,bc                       ; + 128 per record
        dec a                           ; count down
        jr rwo_offset                   ; next
rwo_copy:
        ld de,(dma_address)             ; DE = DMA buffer
        ld a,(deblock_flags)            ; read?
        bit 4,a                         ; readop?
        jr nz,rwo_ldir                  ; yes: host buffer -> DMA buffer
        set 7,a                         ; write: the host buffer is changed (hstwrt = 1) ...
        ld (deblock_flags),a            ; hstwrt = 1
        ex de,hl                        ; ... DMA buffer -> host buffer
rwo_ldir:
        call KL_LDIR                    ; copy the 128 bytes (RAM even under the ROMs)
        ld hl,deblock_flags             ; write type 1 (directory)?
        ld a,(hl)                       ; deblock_flags ...
        and #0F                         ; ... write type ...
        cp #01                          ; ... 1 (directory)?
        ld a,#00                        ; A = 0, CY = 1: ok ...
        scf                             ; (CY = 1: ok)
        ret nz                          ; ... unless directory write
        res 7,(hl)                      ; directory: write the host buffer at once
        xor a                           ; A = 0: write
        call host_read_write            ; A = 0: write
        ret nc                          ; write error
        ld a,#00                        ; ok
        ret
; ----------------------------------------------------------------------
; Subroutine: sek_host_sector [#C994]
; Tasks:        Record (BC+1) divided by the records per sector (XPB byte &15, a power of 2).
; Input:        BC = address before the record byte, HL = address before the sector byte, E = drive
; Output:       A = sector, BC and HL + 1
; Changed:      AF, BC, HL, D
; Called by:    rw_operation
sek_host_sector:
        inc bc
        inc hl
        ld a,#15                        ; records per sector (4)
        call xpb_byte                   ; records per sector
        ld d,a                          ; D = records per sector (shifted until the 1 falls out)
        ld a,(bc)                       ; the record
shs_shift:
        srl d                           ; divided by 2 per bit until the 1 falls out
        ret c
        srl a                           ; sector = record / 2 ...
        jr shs_shift                    ; ... per bit
; ----------------------------------------------------------------------
; Subroutine: host_buffer [#C9A4]
; Tasks:        HL = the 512-byte host buffer (workspace+&23E).
; Input:        IY = VDOS workspace
; Output:       HL
; Changed:      HL, F
; Called by:    rw_operation, host_read_write
host_buffer:
        ld hl,#023E                     ; host buffer offset &23E ...
        jp iy_offset_hl                 ; ... + IY
; ----------------------------------------------------------------------
; Subroutine: host_read_write [#C9AA]
; Tasks:        Read (A = 1) or write (A = 0) the host buffer as sector hst_sector of
;               hst_track on hst_drive: physical sector = first sector number (XPB byte &0F,
;               &41 system format) + hst_sector.
; Input:        A = 1 read, 0 write; IY = VDOS workspace
; Output:       as bios_read_sector / bios_write_sector
; Changed:      AF, DE, HL, C
; Called by:    rw_operation
; Calls:        xpb_byte, host_buffer, bios_read_sector, bios_write_sector; falls through into bios_read_sector
host_read_write:
        push af
        ld de,(hst_drive)               ; E = hst_drive, D = hst_track
        ld a,#0F                        ; first sector number of the format ...
        call xpb_byte                   ; first sector number (XPB byte &0F)
        ld hl,hst_sector                ; hst_sector
        add a,(hl)                      ; ... + hst_sector
        ld c,a                          ; C = physical sector
        call host_buffer                ; HL = host buffer
        pop af
        or a                            ; write?
        jr z,bios_write_sector          ; A = 0: write
; ----------------------------------------------------------------------
; Subroutine: bios_read_sector [#C9C0]
; Tasks:        Hidden RSX &84 BIOS READ SECTOR (CP/M extended BIOS function, entry &BE89):
;               read sector C (to B in multi-sector mode) of track D on drive E to HL with
;               FDC READ DATA (&66), retries and the J/N question (fdc_sector_rw). Observed
;               (every record read through host_read_write).
; Input:        E = drive, D = track, C = sector number, B = last sector (multi-sector), HL = buffer
; Output:       CY = 1, A = 0: ok; CY = 0: A = error status (disc_end)
; Changed:      AF
; Called by:    RSX &84 (rom_jumpblock), cpm_ext_read_sector (&BE89), host_read_write
; Calls:        set_eot, fdc_sector_rw
bios_read_sector:
        call set_eot                    ; EOT = this sector (or B in multi-sector mode)
        ld a,#66                        ; FDC READ DATA (MFM, skip deleted)
        jr fdc_sector_rw                ; transfer with retries
; ----------------------------------------------------------------------
; Subroutine: bios_write_sector [#C9C7]
; Tasks:        Hidden RSX &85 BIOS WRITE SECTOR: as bios_read_sector with FDC WRITE DATA (&45),
;               then a short wait (fdc_rw_wait). Observed (host buffer written back).
;               Observed through RSX &85: drive B, logical track 158 (79, side 0), sector 3, a 512-
;               byte pattern -> read back with RSX &84 identical; CY = 1, A = 0, BC/DE/HL kept.
; Input:        E = drive, D = track, C = sector number, B = last sector (multi-sector), HL = buffer
; Output:       CY = 1, A = 0: ok; CY = 0: A = error status
; Changed:      AF
; Called by:    RSX &85 (rom_jumpblock), cpm_ext_write_sector (&BE8C), host_read_write
; Calls:        set_eot, fdc_rw_wait
bios_write_sector:
        call set_eot                    ; EOT
        ld a,#45                        ; FDC WRITE DATA (MFM)
        jr fdc_rw_wait                  ; transfer, then wait
; ----------------------------------------------------------------------
; Subroutine: bios_format_track [#C9CE]
; Tasks:        Hidden RSX &86 BIOS FORMAT TRACK: FDC FORMAT A TRACK (&4D) of track D on drive E
;               with the sector header table at HL (C, H, R, N per sector) and the XPB's N, SC,
;               GPL and filler byte (fdc_rw_command).
;               Observed through RSX &86 (drive B, track 158, headers 79/0/1..9/2 at &9300) and
;               |FORMAT: CY = 1, A = 0; a fresh sector reads &E5 (the filler).
; Input:        E = drive, D = track, HL = sector headers
; Output:       CY = 1, A = 0: ok; CY = 0: A = error status
; Changed:      AF
; Called by:    RSX &86 (rom_jumpblock), cpm_ext_format_track (&BE8F)
; Calls:        fdc_rw_wait
bios_format_track:
        ld a,#4D                        ; FDC FORMAT A TRACK (MFM)
fdc_rw_wait:
        call fdc_sector_rw              ; do it ...
        push bc
        ld b,#96                        ; ... then wait a little after writing (150 loops)
frw_delay:
        push iy
        pop iy
        djnz frw_delay                  ; wait loop
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: fdc_sector_rw [#C9DE]
; Tasks:        Common sector transfer of READ SECTOR, WRITE SECTOR and FORMAT TRACK: start a
;               disc operation (disc_begin: motor on, error frame), then up to retry_count
;               times: seek the track, send the command and move the data. When bit 2 of the
;               tries left is set (with 16 tries: B = 15-12 and 7-4), the drive's "head position
;               known" bit is cleared, so the next seek recalibrates (from the code).
;               After all retries: error message (low nibble of the command: Lese-, Schreib-,
;               Formatierfehler) with the question " - Wiederholen J/N ?": J starts all tries
;               again, N gives up through disc_end.
;               Observed: normal transfers; and with injected FDC results (ST0 &40, ST1 &20 =
;               data error, at frr_done) 16 failed READs of LOAD -> "Lesefehler" (N: Break;
;               J: the load ended normally) and 16 failed WRITEs of SAVE -> "Schreibfehler"
;               (N: Break, the .$$$ stays).
; Input:        A = FDC command, HL = buffer, E = drive, D = track, C = sector, B = last sector (multi-sector)
; Output:       through disc_end: CY = 1 ok (A = 0); CY = 0 error
; Changed:      AF
; Called by:    bios_read_sector, bios_write_sector, bios_format_track
; Calls:        disc_begin, seek_track, fdc_rw_command, drive_flags_address, disc_error_dialog
fdc_sector_rw:
        call disc_begin                 ; motor on, error frame; the rest returns through disc_end
        ld (sector_buffer),hl           ; sector_buffer = HL
        ld (fdc_command),a              ; fdc_command = A
        ld a,c                          ; C = sector
        ld (fdc_sector),a               ; fdc_sector = C
fsr_retry_all:
        ld a,(retry_count)              ; B = number of tries
        ld b,a                          ; B = tries
fsr_try:
        call seek_track                 ; seek the track
        push bc
        ld a,(fdc_command)              ; send the command, move the data
        call fdc_rw_command             ; command and data phase
        pop bc
        ret c                           ; done
        jr nz,fsr_try                   ; NZ: the user answered J - try again without counting (observed: write protect, J after making the disc writable)
        dec b                           ; one try less
        jr z,fsr_failed                 ; none left: ask
        ld a,#04                        ; bit 2 of the tries left ...
        and b
        jr z,fsr_try                    ; ... clear: try again at once (with 16 tries: B = 11-8 and 3-1)
        call drive_flags_address        ; ... set (B = 15-12 and 7-4, from the code): forget the head position - the next seek recalibrates first
        res 6,(hl)
        jr fsr_try
; ----------------------------------------------------------------------
; Subroutine: recalibrate [#CA0C]
; Tasks:        Recalibrate drive E (FDC RECALIBRATE, head to track 0) and mark its head
;               position as known (flag bit 6). Observed after disc_init.
; Input:        E = drive
; Changed:      AF, BC, HL
; Called by:    seek_track
; Calls:        drive_flags_address, seek_command
recalibrate:
        push de
        call drive_flags_address        ; flag byte of drive E ...
        set 6,(hl)                      ; ... head position known from now on
        ld d,#00                        ; track 0
        ld a,#07                        ; FDC RECALIBRATE
        call seek_cmd                   ; seek with the RECALIBRATE command
        pop de
        ret
fsr_failed:
        ld a,(fdc_command)              ; all tries failed (observed with injected FDC results): message = command low nibble ...
        and #0F                         ; ... &06 Lesefehler (READ &66), &05 Schreibfehler (WRITE &45), &0D Formatierfehler (FORMAT &4D)
        call disc_error_dialog          ; "Laufwerk B: Lesefehler - Wiederholen J/N ?" (observed; also "Schreibfehler")
        jr nz,fsr_retry_all             ; J: all retry_count tries again (observed: LOAD then ended normally)
        ret                             ; N: give up - back through the disc_begin frame to disc_end, CY = 0 (observed: BASIC "Break"; a SAVE leaves its .$$$)
; ----------------------------------------------------------------------
; Subroutine: fdc_rw_command [#CA26]
; Tasks:        Send a READ DATA / WRITE DATA command with its 8 parameter bytes (unit/head,
;               C, H, R, N, EOT, GPL, DTL) or a FORMAT command with its 5 (unit/head, N, SC,
;               GPL, filler), move the data (fdc_transfer) and check the result. EN (end of
;               cylinder) in ST1 counts as success: the transfer stops at EOT.
; Input:        A = FDC command, E = drive, D = track
; Output:       CY = 1 ok; CY = 0 and Z: error; CY = 0 and NZ: try again (user answered J)
; Changed:      AF, BC, DE, HL
; Called by:    fdc_sector_rw
; Calls:        fdc_command_unit, unit_head, fdc_write_byte, fdc_write_xpb_byte, fdc_transfer, fdc_rw_result
fdc_rw_command:
        push af
        call fdc_command_unit           ; command, unit/head and (for READ/WRITE) C = physical track
        pop af
        bit 3,a                         ; FORMAT?
        jr nz,frc_format                ; FORMAT: other parameters
        ld a,e                          ; H: the head number ...
        call unit_head                  ; ... from the unit/head bits of drive E, track D
        and #04                         ; head bit (bit 2) ...
        rrc a                           ; ... to bit 0 = H
        rrc a                           ; (...)
        call fdc_write_byte             ; H
        ld a,(fdc_sector)               ; R = fdc_sector
        call fdc_write_byte             ; R
        ld a,#14                        ; N: sector size code (XPB byte &14)
        call fdc_write_xpb_byte         ; N
        ld a,(fdc_last_sector)          ; EOT = fdc_last_sector
        call fdc_write_byte             ; EOT
        ld a,#11                        ; GPL: gap length read/write (XPB byte &11)
        call fdc_write_xpb_byte         ; GPL
        ld a,#FF                        ; DTL = &FF, then the data
frc_transfer:
        call fdc_transfer               ; last command byte, then the data phase
        ei                              ; interrupts on again
        call fdc_rw_result              ; result: ST0/ST1/ST2 ...
        ret c                           ; ok
        ret nz                          ; NZ: the user answered J to a question - try again (observed)
        ld a,(fdc_result+1)             ; ST1 bit 7: end of cylinder ...
        add a,a                         ; ST1 bit 7 (EN) into CY
        ret c                           ; ... = normal end at EOT: ok (observed: a normal read on drive B gives ST0 &41, ST1 &80 - abnormal by ST0, ok by EN)
        xor a                           ; (not observed) other error: CY = 0, Z (count a try)
        ret
frc_format:
        ld a,#14                        ; (not observed) FORMAT: N (XPB byte &14) ...
        call fdc_write_xpb_byte
        ld a,#10                        ; ... SC: sectors per track (XPB byte &10) ...
        call fdc_write_xpb_byte
        ld a,#12                        ; ... GPL format (XPB byte &12) ...
        call fdc_write_xpb_byte
        ld a,#13                        ; ... filler byte (XPB byte &13) as the last byte
        call xpb_byte
        jr frc_transfer
; ----------------------------------------------------------------------
; Subroutine: fdc_transfer [#CA7A]
; Tasks:        Send the last command byte and move the data in non-DMA mode, interrupts off:
;               for each byte wait for RQM (MSR bit 7); while the FDC is in the execution phase
;               (MSR bit 5) read a byte from / write a byte to the data register. Direction by
;               bit 1 of fdc_command (1 = READ DATA &66).
; Input:        A = last command byte, BC = &FB7E (MSR)
; Output:       interrupts off; HL after the data
; Changed:      AF, HL, C
; Called by:    fdc_rw_command
; Calls:        fdc_write_byte
fdc_transfer:
        di                              ; no interrupts during the data phase (bytes come every 32 us)
        call fdc_write_byte             ; the last command byte starts the execution phase
        ld hl,(sector_buffer)           ; HL = the buffer
        ld a,(fdc_command)              ; the command: read?
        bit 1,a                         ; read (bit 1 of the command)?
        jr z,ft_write_loop              ; no: write
ft_read_loop:
        in a,(c)                        ; MSR ...
        jp p,ft_read_loop               ; ... wait for RQM
        bit 5,a                         ; execution phase over?
        ret z                           ; yes: done
        inc c                           ; data register
        in a,(c)                        ; byte from the disc ...
        ld (hl),a                       ; ... into the buffer
        dec c                           ; back to the status port
        inc hl
        jr ft_read_loop                 ; next byte
ft_write_loop:
        in a,(c)                        ; MSR ...
        jp p,ft_write_loop              ; ... wait for RQM
        bit 5,a                         ; execution phase over?
        ret z                           ; yes: done
        inc c                           ; data register
        ld a,(hl)                       ; byte from the buffer ...
        out (c),a                       ; ... to the disc
        dec c                           ; back to the status port
        inc hl
        jr ft_write_loop                ; next byte
; ----------------------------------------------------------------------
; Subroutine: bios_move_track [#CAA8]
; Tasks:        Hidden RSX &87 BIOS MOVE TRACK: start a disc operation (motor on) and move the
;               head of drive E to track D (seek_track). Observed (detect_format).
;               Observed through RSX &87: E = 1, D = 40 -> XPB ATRK (&ABDB) = &14 (20), the head on
;               cylinder 20; CY = 1, A = 0.
; Input:        E = drive, D = track
; Output:       CY = 1, A = 0: ok; CY = 0: A = error status
; Changed:      AF
; Called by:    RSX &87 (rom_jumpblock), cpm_ext_move_track (&BE92), detect_format
; Calls:        disc_begin, seek_track; falls through into seek_track
bios_move_track:
        call disc_begin                 ; motor on, error frame (disc_begin)
; ----------------------------------------------------------------------
; Subroutine: seek_track [#CAAB]
; Tasks:        Move the head of drive E to track D (FDC SEEK; second entry seek_command with A
;               = &07 RECALIBRATE). Recalibrates first if the drive's head position is not known
;               (flag bit 6). Nothing is sent if the head is already there (XPB byte &16 =
;               current physical track). Waits the step time per track plus the head settle time
;               and checks SENSE INTERRUPT STATUS; up to retry_count tries, then a fatal error
;               (disc_end) without any message - unlike a failed READ/WRITE there is no J/N
;               question. Double-sided drives: physical track = D / 2.
;               Observed: normal seeks (SENSE INTERRUPT result &21, PCN); and with injected
;               results (ST0 &70: abnormal, seek end, equipment check) 16 failed seeks -> the
;               fatal exit, BASIC shows only "Break".
; Input:        E = drive, D = track
; Output:       CY = 1; the XPB's current track updated
; Changed:      AF, BC, DE, HL
; Called by:    bios_move_track, fdc_sector_rw, recalibrate
; Calls:        drive_flags_address, recalibrate, xpb_byte_address, physical_track, seek_again, seek_wait, fdc_clear_interrupts, disc_end
seek_track:
        ld a,#0F                        ; FDC SEEK
seek_cmd:
        push de                         ; (entry with A = &07 RECALIBRATE)
        push bc
        push af
        call drive_flags_address        ; head position known?
        bit 6,(hl)                      ; head position known (flag bit 6)?
        call z,recalibrate              ; no: recalibrate first
        pop af
        ld (seek_command),a             ; seek_command = SEEK / RECALIBRATE
        ld a,#16                        ; HL = XPB byte &16: the current physical track
        call xpb_byte_address           ; HL = XPB byte &16 (current physical track)
        ld a,d                          ; the wanted physical track ...
        call physical_track             ; A = physical track of D
        cp (hl)                         ; ... already there?
        jr z,st_done                    ; already there
        ld a,(retry_count)              ; no: B = tries
        ld b,a                          ; B = tries
st_retry:
        push bc
        call seek_again                 ; send the seek, A = tracks to move
        call seek_wait                  ; wait step and settle time, SENSE INTERRUPT STATUS
        pop bc
        jr c,st_done                    ; done
        jr nz,st_retry                  ; NZ (J answered): seek again at once, no try counted (observed)
        call fdc_clear_interrupts       ; seek failed (observed with injected SENSE INTERRUPT results): clear pending FDC interrupts ...
        djnz st_retry                   ; ... and seek again, up to retry_count times
        jp disc_end                     ; no tries left: fatal error WITHOUT a message or question (observed: 16 failed seeks - BASIC shows only "Break")
st_done:
        ld a,d                          ; the head is on the wanted track now ...
        call physical_track             ; physical track ...
        ld (hl),a                       ; ... note it in the XPB
        pop bc
        pop de
        scf                             ; CY = 1: ok
        ret
; ----------------------------------------------------------------------
; Subroutine: seek_again [#CAE9]
; Tasks:        Send the seek_command again (retry) through fdc_command_unit.
; Changed:      AF, BC
; Called by:    seek_track
; Calls:        falls through into fdc_command_unit
seek_again:
        ld a,(seek_command)             ; the seek command of this call
; ----------------------------------------------------------------------
; Subroutine: fdc_command_unit [#CAEC]
; Tasks:        Send an FDC command followed by the unit/head byte of drive E (track D). Then by
;               command: READ ID (&x A) reads the result; FORMAT (&xD) returns; RECALIBRATE
;               (&x7) returns the tracks to move (= current track); else the physical track (C
;               byte / new cylinder) is sent and A = tracks to move = |new - current|.
; Input:        A = command, E = drive, D = track, HL = XPB byte &16 (seek)
; Output:       A = tracks to move (seek), or the READ ID result
; Changed:      AF, BC
; Called by:    seek_again, fdc_rw_command, detect_format
; Calls:        fdc_write_byte, fdc_write_unit, physical_track, fdc_read_result
fdc_command_unit:
        ld bc,#FB7E                     ; FDC main status register
        push af
        call fdc_write_byte             ; the command
        call fdc_write_unit             ; unit/head byte
        pop af
        and #0F                         ; command number (low nibble)
        cp #0A                          ; READ ID?
        jp z,fdc_read_result            ; yes: read its result (C, H, R, N)
        cp #0D                          ; FORMAT?
        ret z
        xor #07                         ; RECALIBRATE: target 0
        jr z,fcu_steps                  ; RECALIBRATE: steps = current track
        ld a,d                          ; else: the physical track ...
        call physical_track             ; physical track ...
        call fdc_write_byte             ; ... as C / new cylinder
fcu_steps:
        sub (hl)                        ; tracks to move = |target - current|
        ret nc
        cpl                             ; negative: negate
        inc a                           ; (...)
        ret
; ----------------------------------------------------------------------
; Subroutine: set_eot [#CB11]
; Tasks:        fdc_last_sector (EOT) = C, or B if drive E's flag bit 4 (multi-sector, one
;               call only: disc_end clears it) is set. Nothing in the ROM sets bit 4 - a caller of
;               the hidden RSX &84 / &85 (or the extended BIOS jumpblock) has to set it in the
;               drive's flag byte (drive B: &ABDD with the workspace at &A700).
;               Observed: normal calls (EOT = C); and RSX &84 from machine code with E = 1,
;               D = 0, C = 1, B = 2, HL = &9800 and bit 4 set by hand: EOT = 2, sectors 1 and 2
;               of track 0 read in one call (identical to the image), CY = 1, A = 0.
; Input:        C = sector, B = last sector, E = drive
; Output:       fdc_last_sector
; Changed:      AF
; Called by:    bios_read_sector, bios_write_sector
; Calls:        drive_flags_address
set_eot:
        push hl
        call drive_flags_address        ; HL = drive E's flag byte
        bit 4,(hl)                      ; multi-sector?
        ld a,c                          ; no: EOT = the sector
        jr z,se_store                   ; single sector: EOT = C
        ld a,b                          ; yes: EOT = B (observed: RSX &84 with C = 1, B = 2 and bit 4 set by hand - sectors 1 and 2 read in one call)
se_store:
        ld (fdc_last_sector),a          ; fdc_last_sector
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: unit_head [#CB20]
; Tasks:        Add the head bit (bit 2) to unit A for a double-sided drive (flag bit 0) and an odd track D.
; Input:        A = unit, E = drive, D = track
; Output:       A = unit/head byte
; Changed:      AF
; Called by:    fdc_write_unit, fdc_rw_command
; Calls:        drive_flag
unit_head:
        push bc
        ld b,a                          ; B = unit
        call drive_flag                 ; C = flag byte of drive E
        ld c,a                          ; C = flag byte
        ld a,b                          ; A = unit
        bit 0,c                         ; two heads?
        jr z,uh_done                    ; single-sided: no head bit
        bit 0,d                         ; odd track?
        jr z,uh_done                    ; even track: head 0
        set 2,a                         ; head 1 (observed: drive B, odd track)
uh_done:
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: physical_track [#CB33]
; Tasks:        Physical track = A / 2 on a double-sided drive (flag bit 0), else A.
; Input:        A = track, E = drive
; Output:       A
; Changed:      AF
; Called by:    seek_track, fdc_command_unit
; Calls:        drive_flag
physical_track:
        push af
        call drive_flag                 ; flag byte of drive E
        bit 0,a                         ; two heads?
        jr z,pt_done                    ; no: track = A
        pop af
        srl a                           ; yes: track / 2
        ret
pt_done:
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: seek_wait [#CB41]
; Tasks:        Wait A x step_rate ms (the head's travel), then the head settle time, then send
;               SENSE INTERRUPT STATUS and check its result (fdc_result_check).
; Input:        A = tracks moved; BC = FDC main status port (&FB7E)
; Output:       CY = 1 ok
; Changed:      AF, BC, DE, HL
; Called by:    seek_track
; Calls:        delay_ms, fdc_write_byte, fdc_result_check; falls through into fdc_result_check
seek_wait:
        push af
        ld a,(step_rate)                ; one step time ...
        call delay_ms                   ; delay step rate ms
        pop af
        dec a                           ; ... per track
        jr nz,seek_wait                 ; next track
        ld a,(disc_time_constants+5)    ; head settle time (ms)
        call delay_ms                   ; delay settle ms
        ld a,#08                        ; FDC SENSE INTERRUPT STATUS
        call fdc_write_byte             ; SENSE INTERRUPT STATUS
; ----------------------------------------------------------------------
; Subroutine: fdc_result_check [#CB57]
; Tasks:        Read the FDC result and check ST0: normal end -> CY = 1; drive not ready
;               (bit 3) at the end of a seek (bit 5) -> "Diskette fehlt" (message &07, J/N
;               question: N ends the disc operation through disc_end, J returns NZ and the
;               seek is repeated at once); other errors -> CY = 0, Z.
;               Observed: all three ways (ok; no disc in drive A with J after inserting it, and N).
; Input:        BC = FDC main status port (&FB7E)
; Output:       CY = 1 ok; CY = 0 and Z: error (count a try); CY = 0 and NZ: try again (J)
; Changed:      AF, BC, DE, HL
; Called by:    seek_wait, fdc_rw_result
; Calls:        fdc_read_result, disc_error_dialog, disc_end
fdc_result_check:
        call fdc_read_result            ; result bytes, A = ST0
        ret c                           ; normal termination
        bit 3,a                         ; not ready?
        ret z                           ; no: error (Z)
        bit 5,a                         ; seek end (ST0 bit 5) with not ready: no disc
        ret z
        ld a,#07                        ; "Laufwerk x: Diskette fehlt" (observed: CAT with drive A empty)
        jr frr_error
; ----------------------------------------------------------------------
; Subroutine: fdc_rw_result [#CB65]
; Tasks:        Result check after READ/WRITE: as fdc_result_check, plus write protected (ST1
;               bit 1) -> "Diskette hat Schreibschutz" (message &08) with the J/N question.
;               Observed: SAVE "TW" on a write-protected disc - the first refused write was the
;               directory write of make_body (OUT OPEN creating TW.$$$); J after making the disc
;               writable repeated it and the SAVE ended normally (TW.BAS).
; Input:        BC = FDC main status port (&FB7E)
; Output:       CY = 1 ok; CY = 0 and NZ: try again (J); fatal (N): disc_end
; Changed:      AF, BC, DE, HL
; Called by:    fdc_rw_command
; Calls:        fdc_result_check, disc_error_dialog, disc_end
fdc_rw_result:
        call fdc_result_check           ; result check of the transfer
        ret c                           ; ok
        ret nz                          ; NZ: try again (J)
        ld a,(fdc_result+1)             ; ST1 ...
        bit 1,a                         ; ... not writable (write protected)?
        ret z
        ld a,#08                        ; "Diskette hat Schreibschutz" (observed: SAVE on a write-protected disc)
frr_error:
        call disc_error_dialog          ; message and J/N question (observed)
        jp z,disc_end                   ; N: fatal error, end the disc operation (observed)
        ret                             ; J: return NZ - the caller tries again at once (observed)
; ----------------------------------------------------------------------
; Subroutine: bios_get_status [#CB79]
; Tasks:        Hidden RSX &88 BIOS GET STATUS: FDC SENSE DRIVE STATUS of unit A
;               (sense_drive_status) and return ST3 (bit 5 ready, bit 6 write protected, bit 4
;               track 0). Note: A is sent as the unit number as it is - drives_swapped is not
;               applied here. Observed (HELLO loader, A = 0).
;               Observed through RSX &88: unit 0 -> ST3 &20 (ready), 1 -> &29 (ready, two-sided), 2
;               / 3 -> &22 / &2B (the CPC wires only US0: units 2/3 select drives A/B again); drive
;               A empty -> CY = 1, ST3 &00. Write-protected disc: CY = 0, A = &54, fdc_result =
;               &60 - sense_drive_status judges the result like a normal command by bits 7-6 of
;               its first byte, and ST3's write-protect bit 6 looks like "abnormal". So GET STATUS
;               cannot report a write-protected disc as a status; the HELLO loader has an extra
;               branch for this case (&BF12: test bit 5 of &BE4B, not observed yet).
; Input:        A = drive (unit)
; Output:       CY = 1: A = ST3; CY = 0: error (fdc_result at &BE4B)
; Changed:      AF
; Called by:    RSX &88 (rom_jumpblock), cpm_ext_get_status (&BE95), hello_loader
; Calls:        sense_drive_status
bios_get_status:
        call sense_drive_status         ; SENSE DRIVE STATUS of unit A
        ret nc
        ld a,(fdc_result)               ; A = ST3
        ret
; ----------------------------------------------------------------------
; Subroutine: sense_drive_status [#CB81]
; Tasks:        FDC SENSE DRIVE STATUS of unit A (after clearing pending interrupts): ST3 into
;               fdc_result. Inside a disc_begin frame. Observed (HELLO loader).
; Input:        A = unit
; Output:       CY = 1: fdc_result = ST3
; Changed:      AF
; Called by:    bios_get_status
; Calls:        disc_begin, fdc_clear_interrupts, fdc_write_byte, fdc_read_result; falls through into fdc_read_result
sense_drive_status:
        call disc_begin                 ; motor on, error frame
        push af
        call fdc_clear_interrupts       ; clear pending FDC interrupts
        ld bc,#FB7E                     ; FDC main status register
        ld a,#04                        ; FDC SENSE DRIVE STATUS
        call fdc_write_byte             ; SENSE DRIVE STATUS
        pop af
        call fdc_write_byte             ; unit
; ----------------------------------------------------------------------
; Subroutine: fdc_read_result [#CB94]
; Tasks:        Read the FDC result phase into fdc_result (&BE4B..): wait until the FDC has a
;               byte to send (MSR >= &C0), then read bytes while RQM and DIO are set.
; Input:        BC = &FB7E
; Output:       A = ST0; CY = 1 if ST0 bits 7-6 = 0 (normal termination), else CY = 0, NZ
; Changed:      AF, C
; Called by:    seek_wait, fdc_result_check, sense_drive_status, fdc_clear_interrupts, fdc_command_unit
fdc_read_result:
        push hl
        ld hl,fdc_result                ; result buffer
frr_wait:
        in a,(c)                        ; MSR ...
        cp #C0                          ; ... RQM and DIO (FDC sends)?
        jr c,frr_wait                   ; not yet: wait
        jr frr_store                    ; yes: the first byte
frr_next:
        in a,(c)                        ; MSR: wait for RQM
        bit 7,a                         ; RQM?
        jr z,frr_next                   ; no: wait
        bit 6,a                         ; DIO = 0: no more result bytes
        jr z,frr_done                   ; DIO = 0: result phase over
frr_store:
        inc c                           ; data register
        in a,(c)                        ; result byte ...
        dec c                           ; back to the status port
        ld (hl),a                       ; ... into fdc_result
        inc hl
        jr frr_next                     ; next byte
frr_done:
        ld a,(fdc_result)               ; ST0 ...
        and #C0                         ; ... interrupt code (bits 7-6)
        ld a,(fdc_result)               ; A = ST0
        pop hl
        ret nz                          ; not normal: CY = 0, NZ
        scf                             ; normal: CY = 1
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_setup_disc [#CBBE]
; Tasks:        Hidden RSX &82 SETUP DISC: copy 7 time constants to disc_time_constants
;               (&BE44-&BE4A) and send FDC SPECIFY with SRT from the Vortex step rate (SRT = 16 -
;               ms/2), HUT from HL+7, HLT/ND from HL+8. Keeps the step rate of the current drive in
;               &BE5F. Second entry bsd_specify: only SPECIFY, used by specify_for_drive with the step
;               rate of the selected drive type.
;               VDOS block: byte 4 unused, byte 6 = combined step rate (3\" high nibble, Vortex low
;               nibble, ms). Callers written for AMSDOS pass byte 6 as one step rate for both drives
;               (and byte 4 as write current off time): the Amstrad CP/M boot sector passes &0C
;               (observed with |CPM,1), which wboot_body converts to &C4 on the first load; the
;               Vortex boot sector (|CPM,2) passes &C4.
;               Observed through RSX &82: a block with motor off &00F0 -> &BE44.. = 28 00 F0 00 00 14
;               C4, step rate &BE5F = 4, the disc works; HL = &C1A6 (the ROM defaults) restores it.
;               Exit CY = 0 (no status; AF, BC, DE, HL corrupt).
; Input:        HL = parameter block: motor on (word), motor off (word), unused, head settle,
;               step rates (3" high nibble, Vortex low nibble), HUT, HLT/ND
; Output:       -
; Changed:      AF, BC, DE, HL
; Called by:    disc_init (with time_constants_default), RSX &82; specify_for_drive (jp bsd_specify)
; Calls:        fdc_write_byte
bios_setup_disc:
        ld de,disc_time_constants       ; to disc_time_constants
        ld bc,#0007                     ; 7 bytes
        ldir                            ; motor on &0028, off &00FA, &00, settle &14 ms, step rates &C4 (defaults at &C1A6)
        ld a,(disc_time_constants+6)    ; step rates: high nibble 3" (12 ms), low nibble Vortex (4 ms)
        push af
; send FDC SPECIFY; step rates byte on the stack, HL = HUT/HLT bytes - second entry from specify_for_drive, which passes the 3" step rate in the low nibble for a 3" drive (flag bit 5)
bsd_specify:
        ld bc,#FB7E                     ; FDC main status register (data register at &FB7F)
        ld a,#03                        ; FDC command 3: SPECIFY
        call fdc_write_byte             ; SPECIFY command byte
        pop af
        and #0F                         ; step rate in ms (low nibble: Vortex; specify_for_drive moves the 3" rate down for a 3" drive)
        ld (step_rate),a                ; &BE5F = step rate of the selected drive (manual)
        dec a                           ; (ms-1)*8 ...
        rlca                            ; (...)
        rlca                            ; (...)
        rlca                            ; (...)
        cpl                             ; ... inverted ...
        and #F0                         ; ... high nibble = SRT = 16 - ms/2 (4 ms -> &E)
        or (hl)                         ; low nibble = head unload time from HL+7 (&01)
        call fdc_write_byte             ; SPECIFY byte 1: SRT/HUT (&E1)
        inc hl
        ld a,(hl)                       ; head load time / non-DMA from HL+8 (&03)
        jp fdc_write_byte               ; SPECIFY byte 2
; ----------------------------------------------------------------------
; Subroutine: fdc_clear_interrupts [#CBE8]
; Tasks:        Send SENSE INTERRUPT STATUS until the FDC answers ST0 = &80 (invalid command: no interrupt pending).
; Changed:      AF
; Called by:    seek_track, sense_drive_status
; Calls:        fdc_write_byte, fdc_read_result
fdc_clear_interrupts:
        push bc
        ld bc,#FB7E                     ; FDC main status register
fci_loop:
        ld a,#08                        ; FDC SENSE INTERRUPT STATUS
        call fdc_write_byte             ; SENSE INTERRUPT STATUS ...
        call fdc_read_result            ; ... its result
        cp #80                          ; &80: nothing pending any more
        jr nz,fci_loop                  ; another one pending: again
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: fdc_write_xpb_byte [#CBFA]
; Tasks:        Send XPB byte A of drive E to the FDC.
; Input:        A = XPB offset, E = drive; BC = FDC main status port (&FB7E)
; Changed:      AF, C
; Called by:    fdc_rw_command
; Calls:        xpb_byte, fdc_write_byte
fdc_write_xpb_byte:
        call xpb_byte                   ; XPB byte A of drive E
        jr fdc_write_byte               ; send it
; ----------------------------------------------------------------------
; Subroutine: fdc_write_unit [#CBFF]
; Tasks:        Send the unit/head byte of drive E: physical unit = E, exchanged when
;               drives_swapped is 1, plus the head bit for track D.
; Input:        E = drive, D = track; BC = FDC main status port (&FB7E)
; Changed:      AF, C
; Called by:    fdc_command_unit
; Calls:        unit_head, fdc_write_byte; falls through into fdc_write_byte
fdc_write_unit:
        ld a,(drives_swapped)           ; physical unit = logical drive XOR drives_swapped
        xor e                           ; swap the units if drives_swapped
        call unit_head                  ; + head bit
; ----------------------------------------------------------------------
; Subroutine: fdc_write_byte [#CC06]
; Tasks:        Send one command/parameter byte to the uPD765: wait until the main status
;               register shows RQM (bit 7); if DIO (bit 6) says the FDC wants to send, return
;               without writing (fwb_fdc_sends; observed only by injection, 2026-10-26); else write
;               A to the data register (port BC+1).
; Input:        A = byte, BC = FDC main status port (&FB7E)
; Output:       AF, BC kept
; Changed:      C
; Called by:    bios_setup_disc and the FDC command routines (fdc_rw_command, fdc_transfer, fdc_command_unit, ...)
; Entered from: fdc_write_unit (falls through)
fdc_write_byte:
        push af                         ; keep A for the write ...
        push af
fwb_wait_rqm:
        in a,(c)                        ; FDC main status register
        bit 7,a                         ; RQM?
        jr z,fwb_wait_rqm               ; wait until RQM (bit 7): FDC ready for a byte
        bit 6,a                         ; DIO (bit 6) = 1: FDC wants to send?
        jr nz,fwb_fdc_sends             ; yes: do not write the byte (guard; taken only by injection so far, see fwb_fdc_sends)
        pop af
        inc c                           ; data register (&FB7F)
        out (c),a                       ; send the byte
        dec c                           ; back to the status port
        pop af
        ret
; FDC is in its result phase (DIO = 1): the byte is dropped silently - AF comes back as on
; entry, so the caller cannot see it. Simulated 2026-10-26 by injection (main status &80 replaced
; by &D0 after the IN at &CC08, during CAT on B:, discs read-only): the SPECIFY byte &03 of
; "SPECIFY 03 E1 03" was dropped, AF = &0354 again at the return to &CBD2; the FDC then took &E1
; as a command ("invalid &01 -> 80"), VDOS read that result with SENSE INTERRUPT STATUS and went
; on normally (RECALIBRATE, SEEK, the full directory listing).
fwb_fdc_sends:
        pop af                          ; drop the second copy of AF ...
        pop af                          ; ... AF as on entry (the byte is not written) ...
        ret                             ; ... back, no error flag
; ----------------------------------------------------------------------
; Subroutine: delay_ms [#CC1C]
; Tasks:        Wait A milliseconds: per ms an inner loop of delay_ms_loops (&C1AF = 232) times
;               dec a / jr nz (4 us each, 928 us) plus the outer loop's instructions - about 1 ms.
; Input:        A = ms
; Changed:      AF
; Called by:    seek_wait
delay_ms:
        push af
        ld a,(delay_ms_loops)           ; loops per ms
dm_loop:
        dec a                           ; inner loop
        jr nz,dm_loop                   ; (one ms)
        pop af
        dec a                           ; next ms
        jr nz,delay_ms                  ; next ms
        ret

; ---- never accessed: #CC28-#CC29 (2 bytes, fill: static) ----
; ----------------------------------------------------------------------
; Subroutine: drive_a_flag [#CC28]
; Tasks:        Preload of drive_flag with drive A: E = 0, then falls through into drive_flag,
;               so A = drive A's flag byte.
;               Never called; why the entry exists is not known. Nothing in the ROM calls or
;               jumps to #CC28, it is in no jumpblock, and no program on the two discs contains
;               the bytes 28 CC (every sector of disk/464_cpm_22_vdos.dsk and
;               vortex_cpm22_44k.dsk searched). A breakpoint on #CC28 was never hit while
;               VDOS.COM, FAST, CASCOPY, DISKTOOL (formatting drive B), FILECOPY, XPATCH,
;               XPATCH30, P22, P30 and INSTALL ran under |CPM,2 (2026-10-25).
;               Never read, so classified as code by the owner (1E 00 = ld e,#00; the vortex
;               mask at this address is 0, raw and decoded bytes are the same).
; Output:       A = drive A's flag byte; E = 0
; Changed:      AF, E
; Calls:        falls through into drive_flag
drive_a_flag:
        ld e,#00                        ; drive A
; ---- end of never accessed ----

; ----------------------------------------------------------------------
; Subroutine: drive_flag [#CC2A]
; Tasks:        A = the flag byte of drive E (drive_a_flag #CC28 preloads E = 0, never called).
;               Flag bits: 0 two heads, 3 motors running (drive A's byte only), 4 multi-sector
;               for one call, 5 3" drive, 6 head position known.
; Input:        E = drive
; Output:       A
; Changed:      AF
; Called by:    specify_for_drive, unit_head, physical_track
; Calls:        drive_flag_offset, xpb_byte; falls through into xpb_byte
drive_flag:
        call drive_flag_offset          ; A = flag offset
; ----------------------------------------------------------------------
; Subroutine: xpb_byte [#CC2D]
; Tasks:        A = byte A of drive E's XPB.
; Input:        A = offset, E = drive
; Output:       A
; Changed:      AF
; Called by:    many disc BIOS routines
; Entered from: drive_flag (falls through)
; Calls:        xpb_byte_address
xpb_byte:
        push hl
        call xpb_byte_address           ; HL = its address
        ld a,(hl)                       ; A = the byte
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: drive_a_flags_address [#CC34]
; Tasks:        HL = address of drive A's flag byte (motor state bit 3).
; Output:       HL
; Changed:      AF, HL, E
; Called by:    disc_begin, disc_end, motor_event, motors_off_now
; Calls:        falls through into drive_flags_address
drive_a_flags_address:
        ld e,#00                        ; drive A
; ----------------------------------------------------------------------
; Subroutine: drive_flags_address [#CC36]
; Tasks:        HL = address of drive E's flag byte in its XPB.
; Input:        E = drive
; Output:       HL
; Changed:      AF, HL
; Called by:    seek_track, set_eot, recalibrate, disc_end, bios_select_format (A = &FF)
; Entered from: drive_a_flags_address (falls through)
; Calls:        drive_flag_offset, xpb_byte_address; falls through into xpb_byte_address
drive_flags_address:
        call drive_flag_offset          ; A = flag offset
; ----------------------------------------------------------------------
; Subroutine: xpb_byte_address [#CC39]
; Tasks:        HL = address of byte A of drive E's XPB. Looks the DPH and XPB up again when E
;               is not xpb_cache_drive.
; Input:        A = offset, E = drive
; Output:       HL
; Changed:      AF, HL
; Called by:    xpb_byte, drive_flags_address, seek_track, select_format
; Calls:        xpb_select_drive
xpb_byte_address:
        push de
        ld l,a                          ; L = offset
        ld a,(xpb_cache_drive)          ; the cached drive?
        cp e                            ; (Z: cached)
        call nz,xpb_select_drive        ; no: look its tables up
        ld de,(xpb_cache_xpb)           ; XPB of the drive ...
        ld h,#00                        ; H = 0: HL = offset
        add hl,de                       ; ... + offset
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: xpb_select_drive [#CC4B]
; Tasks:        xpb_cache_drive = E, xpb_cache_dph = its DPH, xpb_cache_xpb = the XPB address in the DPH (+10).
; Input:        E = drive
; Changed:      DE, F
; Called by:    xpb_byte_address
; Calls:        dph_address, load_hl_indirect
xpb_select_drive:
        push hl
        ld (xpb_cache_drive),de         ; xpb_cache_drive = E (D goes to &BE05, overwritten next)
        ld l,e                          ; L = drive
        call dph_address                ; its DPH ...
        ld (xpb_cache_dph),hl           ; ... cached
        ld de,#000A                     ; the DPB/XPB pointer in the DPH ...
        add hl,de                       ; DPH+10 ...
        call load_hl_indirect           ; ... = XPB address
        ld (xpb_cache_xpb),hl           ; ... cached
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: drive_flag_offset [#CC63]
; Tasks:        Offset of drive E's flag byte in its XPB, and whether E is the 3" drive (the
;               drive number equal to drives_swapped): the 3" XPB has the flag byte at &17 as
;               drive A and at &18 as drive B (setup_drive_tables), the Vortex XPB at &18.
; Input:        E = drive
; Output:       A = offset; Z = 3" drive
; Changed:      AF
; Called by:    seldsk, select_format, drive_flag, drive_flags_address
drive_flag_offset:
        ld a,(drives_swapped)           ; the 3" drive is drive drives_swapped (0 normally)
        cp e                            ; the 3" drive?
        jr nz,dfo_vortex                ; not the 3" drive: offset &18, NZ
        or a                            ; 3" drive as B?
        ld a,#18                        ; &18 ...
        jr nz,dfo_3inch                 ; drive B: &18
        dec a                           ; ... &17 as drive A
dfo_3inch:
        cp a                            ; Z = 3" drive
        ret
dfo_vortex:
        ld a,#18                        ; Vortex: &18, NZ
        ret
; ----------------------------------------------------------------------
; Subroutine: dph_address [#CC74]
; Tasks:        HL = DPH of drive L (dph_drive_a + 16 * L).
; Input:        L = drive
; Output:       HL
; Changed:      HL
; Called by:    seldsk, xpb_select_drive
dph_address:
        push de
        push af
        ld h,#00                        ; H = 0
        add hl,hl                       ; drive * 16 (DPH size) ...
        add hl,hl
        add hl,hl
        add hl,hl
        ld de,(dph_drive_a)             ; + DPH of drive A
        add hl,de
        pop af                          ; (keep A, DE)
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_set_message [#CC84]
; Tasks:        Hidden RSX &81 BIOS SET MESSAGE (CP/M extended BIOS function, entry &BE80):
;               switch the disc error messages on or off.
; Input:        A = &00 messages on, &FF messages off (stored as given)
; Output:       A = previous setting
; Changed:      A
; Called by:    RSX &81 (rom_jumpblock)
bios_set_message:
        push hl                         ; keep HL ...
        push bc                         ; ... and BC
        ld hl,messages_off              ; messages_off
        ld b,(hl)                       ; B = old setting
        ld (hl),a                       ; new setting
        ld a,b                          ; return the old one in A
        pop bc
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: disc_error_dialog [#CC8F]
; Tasks:        Report a disc error: unless messages_off, switch the motors off, print message A
;               and " - Wiederholen J/N ?", wait for J or N (other keys: beep), then switch the
;               motor on again (disc_begin's motor part). Observed with "Diskette fehlt": J
;               (after inserting the disc: CAT went on) and N (CAS call ended, BASIC: Ready).
; Input:        A = message number
; Output:       NZ: J (try again); Z: N or messages off (A = 0)
; Changed:      AF, BC, DE, HL
; Called by:    fsr_failed, fdc_result_check, fdc_rw_result
; Calls:        motors_off_now, print_error_and_ask, db_motor_on
disc_error_dialog:
        push af
        ld a,(messages_off)             ; messages off?
        or a
        jr nz,ded_silent                ; yes: no question, answer "no"
        pop af
        push hl
        push bc
        push de
        push af
        call motors_off_now             ; motors off while the user thinks
        pop af
        pop bc                          ; (the stack is rebuilt for db_motor_on: HL, BC, DE)
        push bc
        call print_error_and_ask        ; message A + question
        jp db_motor_on                  ; motor on again, registers back, NZ/Z from the answer (observed)
ded_silent:
        pop af                          ; messages off (|DERROR,0; observed: CAT with drive A empty): no message, no question - A = 0, Z = "N"
        xor a                           ; A = 0 ...
        or a                            ; ... Z: the caller takes the answer N (fatal: disc_end)
        ret
; ----------------------------------------------------------------------
; Subroutine: ask_yes_no [#CCAB]
; Tasks:        Print message A, empty the key buffer, cursor on, wait for J or N (upper or
;               lower case); any other key beeps and is not echoed; the answer J or N is echoed,
;               cursor off. Observed: J, N and a wrong key (X: beep, then N).
; Input:        A = message number
; Output:       NZ: J, Z: N
; Changed:      AF
; Called by:    print_error_and_ask
; Calls:        print_message, flush_keys_cursor_on, KM_WAIT_CHAR, to_upper, TXT_OUTPUT, print_char_cursor_off
ask_yes_no:
        call print_message
        call flush_keys_cursor_on       ; empty the key buffer, cursor on
ayn_wait:
        call KM_WAIT_CHAR               ; wait for a key
        call to_upper                   ; upper case
        cp #4A                          ; J?
        jr z,ayn_yes
        cp #4E                          ; N? (observed)
        jr z,ayn_answer
        ld a,#07                        ; other key: BEL (beep) - the key is not echoed (observed: X)
        call TXT_OUTPUT                 ; (beep)
        jr ayn_wait                     ; wait for the next key
ayn_yes:
        or a                            ; J: NZ (observed)
ayn_answer:
        jp print_char_cursor_off        ; echo the key, cursor off
; ----------------------------------------------------------------------
; Subroutine: print_error_and_ask [#CCCA]
; Tasks:        Print error message A, then ask " - Wiederholen J/N ?" (message &12), then falls
;               into print_crlf: CR LF after the answer. Observed.
; Input:        A = message number
; Output:       NZ: J, Z: N (flags kept through print_crlf)
; Changed:      AF
; Called by:    disc_error_dialog
; Calls:        print_message, ask_yes_no, print_crlf (falls in)
print_error_and_ask:
        call print_message
        ld a,#12
        call ask_yes_no
; ----------------------------------------------------------------------
; Subroutine: print_crlf [#CCD2]
; Tasks:        Print message 0 (CR LF); falls into print_message.
; Changed:      A
; Called by:    print_message_char (word wrap), dir_next_line
; Entered from: print_error_and_ask (falls through)
print_crlf:
        ld a,#00                        ; message 0 = CR LF
; ----------------------------------------------------------------------
; Subroutine: print_message [#CCD4]
; Tasks:        Print message A from message_table. Messages are byte strings ended by &FF and
;               stored one after the other; message n is found by skipping n end markers.
;               Each byte is printed by print_message_char, which decides per byte:
;               &C0-&C3       codes that insert a value (name, number DE, drive letter, number C)
;               other >= &80  nested message (byte AND &7F): print_message calls itself
;               < &80         character or control code, via TXT OUTPUT
;               &FF ends the current message and returns one level up - into the outer message
;               after its reference byte, or to the caller at the top level. A trailing &80 is
;               message 0 (CR LF), not an end marker.
;               Example &0E: " (C)1986" &A2 "VDOS 2.11-X by" &8F &80 &FF -> &A2 = msg &22
;               (3 spaces), &8F = msg &0F (" vortex GmbH" &80 &FF), &80 = msg &00 (CR LF).
; Input:        A = message number (bit 7 ignored); for the codes: DE = FCB (&C0) or
;               number (&C1), C = drive number (&C2) or number (&C3)
; Output:       -
; Changed:      none
; Called by:    rom_init, print_message_char (nested messages), print_crlf, rsx_dir, rsx_format,
;               rsx_derror, ask_yes_no, print_error_and_ask, dir_start, dir_print_entry, set_dma_again, print_crlf_message
; Calls:        print_message_char
print_message:
        push hl                         ; keep the caller's HL ...
        push bc                         ; ... BC ...
        push af                         ; ... and AF
        ld hl,message_table             ; HL = message 0
        and #7F                         ; message number n (a nested reference arrives as &80+n)
        ld b,a                          ; B = n+1 for the DJNZ ...
        inc b                           ; (DJNZ counts n+1)
        jr pm_skip_count                ; ... which comes first: n=0 skips nothing
; skip one message: read its bytes up to and including the &FF
pm_skip_byte:
        ld a,(hl)                       ; skip a message: read up to and including its &FF
        inc hl
        inc a                           ; &FF+1 = 0?
        jr nz,pm_skip_byte              ; no: next byte
pm_skip_count:
        djnz pm_skip_byte               ; n messages skipped: HL = start of message n
; print message n byte by byte until its &FF
pm_next_byte:
        ld a,(hl)                       ; next byte of message n
        inc hl
        inc a                           ; &FF (end marker)?
        jp z,pm_done                    ; yes: done
        dec a                           ; the byte again
        push hl                         ; the handler and nested messages use HL, BC, DE
        push bc
        push de
        call print_message_char         ; print the byte; a nested message re-enters print_message here
        pop de
        pop bc
        pop hl
        jr pm_next_byte                 ; next byte
; &FF reached: end of this (partial) message, back one level
pm_done:
        pop af                          ; caller's AF, BC, HL back
        pop bc
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: print_message_char [#CCFD]
; Tasks:        Print one message byte. The order of the tests decides what it is:
;               &C0  8.3 file name from the FCB at DE (8 + '.' + 3, attribute bits stripped)
;               &C1  number in DE, 3 digits right aligned (print_number_3)
;               &C2  drive letter 'A' + C
;               &C3  number in C, 3 digits (DE = C, then print_number_3)
;               other bytes with bit 7 set: nested message, jp print_message
;               a space with the cursor beyond the window's right column - 4: CR LF instead
;               (word wrap, not observed); everything else: TXT OUTPUT.
;               Because &C0-&C3 are tested first, messages &40-&43 cannot be nested (the table
;               only has &00-&3D). Two number codes give a message two parameters, e.g. msg &39
;               "<DE>K in <C> Files, ".
; Input:        A = byte (not &FF); DE, C = parameters as above
; Output:       -
; Changed:      AF, DE, HL, B
; Called by:    print_message
; Calls:        print_fcb_chars, print_number_3, print_digit, print_message, print_crlf,
;               TXT_OUTPUT, TXT_GET_WINDOW, TXT_GET_CURSOR; falls through into print_fcb_chars
print_message_char:
        cp #C0                          ; &C0: file name?
        jr nz,pmc_number_de
        ld b,#08                        ; 8 name characters from DE+1 (DE points to the FCB's user/drive byte)
        call print_fcb_chars
        ld a,#2E                        ; separator
        call TXT_OUTPUT
        ld b,#03                        ; 3 type characters: falls into print_fcb_chars
; ----------------------------------------------------------------------
; Subroutine: print_fcb_chars [#CD0D]
; Tasks:        Print the B characters after DE with bit 7 (FCB attribute bits R/O, SYS) cleared.
; Input:        DE = byte before the first character, B = count
; Output:       DE = last character printed
; Changed:      AF, DE, B
; Called by:    print_message_char (&C0; the type part falls in)
; Calls:        TXT_OUTPUT
print_fcb_chars:
        inc de                          ; next character
        ld a,(de)
        and #7F                         ; strip the attribute bit (R/O, SYS, ...)
        call TXT_OUTPUT
        djnz print_fcb_chars
        ret
; case &C1: number in DE, 3 digits (falls into print_number_3)
pmc_number_de:
        cp #C1                          ; &C1: number in DE?
        jr nz,pmc_drive_letter
; ----------------------------------------------------------------------
; Subroutine: print_number_3 [#CD1B]
; Tasks:        Print DE as 3 characters, right aligned, leading zeros as spaces (0-999; from
;               1000 the hundreds 'digit' would be a character past '9'). Hundreds and tens are
;               calls of print_digit; the units digit jumps into print_digit at &CD37 (always a
;               digit), so the RET of TXT OUTPUT there returns to print_number_3's caller.
; Input:        DE = number
; Output:       HL = units digit value
; Changed:      AF, DE, HL, B
; Called by:    print_message_char (&C1 falls in; &C3 calls it with DE = C)
; Calls:        print_digit
print_number_3:
        ld b,#20                        ; fill character for leading zeros
        ex de,hl                        ; HL = the number
        ld de,#0064
        call print_digit                ; hundreds
        ld de,#000A
        call print_digit                ; tens
        ld a,l                          ; units: always a digit
        jr pd_digit
; ----------------------------------------------------------------------
; Subroutine: print_digit [#CD2D]
; Tasks:        Print one decimal digit: HL / DE by repeated subtraction, HL = remainder. A 0
;               prints as the fill character B (a space before the first non-zero digit);
;               once a digit is printed B = '0'. Ends with jp TXT_OUTPUT (tail call).
; Input:        HL = value, DE = 100 or 10, B = fill character
; Output:       HL = remainder, B = ' ' or '0'
; Changed:      AF, HL, B
; Called by:    print_number_3 (units digit: jumps in at &CD37)
; Calls:        TXT_OUTPUT
print_digit:
        xor a                           ; A = 0 (digit counter), carry clear for SBC
pd_subtract:
        sbc hl,de                       ; subtract DE ...
        inc a                           ; ... and count ...
        jr nc,pd_subtract               ; ... until HL went below 0
        add hl,de                       ; undo the last subtraction: HL = remainder
        dec a                           ; A = the digit
        jr z,pd_print                   ; 0: print the fill character B
; a real digit (the units digit of print_number_3 enters here): zeros now print as '0'
pd_digit:
        ld b,#30                        ; a digit: from now on zeros print as '0'
pd_print:
        add a,b                         ; digit + '0', or 0 + fill character
        jr pmc_output
; case &C2: drive letter 'A' + C
pmc_drive_letter:
        cp #C2                          ; &C2: drive letter?
        jr nz,pmc_number_c
        ld a,c                          ; C = drive number 0/1 ...
        add a,#41                       ; ... -> 'A'/'B'
; shared exit: print A - the RET of TXT OUTPUT returns to our caller (tail call)
pmc_output:
        jp TXT_OUTPUT                   ; print it
; case &C3: number in C, 3 digits
pmc_number_c:
        cp #C3                          ; &C3: number in C?
        jr nz,pmc_nested_or_char
        push de
        ld e,c                          ; DE = C ...
        ld d,#00                        ; DE = C
        call print_number_3             ; ... 3 digits
        pop de
        ret
; other bytes: bit 7 set = nested message, else a character (space: word wrap check)
pmc_nested_or_char:
        bit 7,a                         ; other byte >= &80: nested message n = byte - &80 ...
        jp nz,print_message             ; ... printed by print_message (recursion)
        push af
        cp #20                          ; a space?
        jr nz,pmc_print_char            ; no: print the character
        push hl
        push de
        call TXT_GET_WINDOW             ; D = right column of the text window
        call TXT_GET_CURSOR             ; H = cursor column
        ld a,d
        sub #04                         ; right column - 4 ...
        ccf
        jr nc,pmc_space_checked         ; window narrower than 4 columns: no wrap
        cp h                            ; cursor column beyond right column - 4?
pmc_space_checked:
        pop de
        pop hl
        jr nc,pmc_print_char            ; no: print the space
        pop af
        jp print_crlf                   ; yes: CR LF instead of the space - word wrap (not observed)
; print the character or control code
pmc_print_char:
        pop af                          ; plain character or control code (CR, LF, ...)
        jp TXT_OUTPUT
; ----------------------------------------------------------------------
; Subroutine: flush_keys_cursor_on [#CD78]
; Tasks:        Read keys until the buffer is empty, then switch the cursor on.
; Changed:      AF
; Called by:    ask_yes_no, dir_next_line
flush_keys_cursor_on:
        call KM_READ_CHAR               ; key in the buffer?
        jr c,flush_keys_cursor_on       ; yes: read the next
        call TXT_CUR_ON                 ; cursor on for the answer
        ret
print_char_cursor_off:
        call TXT_OUTPUT                 ; echo the answer
        jp TXT_CUR_OFF
; ----------------------------------------------------------------------
; Subroutine: record_buffer_de [#CD87]
; Tasks:        DE = address of the 128-byte record buffer (workspace+&E0); falls into
;               workspace_offset. Observed (|REN).
; Input:        IY = VDOS workspace
; Output:       DE = workspace+&E0
; Changed:      DE, F
; Called by:    rsx_ren and the relative file commands
record_buffer_de:
        ld de,#00E0                     ; record buffer offset; on into workspace_offset
; ----------------------------------------------------------------------
; Subroutine: workspace_offset [#CD8A]
; Tasks:        Turn a workspace offset into an address.
; Input:        DE = offset, IY = VDOS workspace
; Output:       DE = IY + DE; HL kept
; Changed:      DE, F
; Called by:    rom_init, setup_drive_tables, copy_xpb and many DOS routines
; Entered from: record_buffer_de (falls through)
workspace_offset:
        push iy                         ; save IY ...
        ex (sp),hl                      ; HL = IY, caller's HL on the stack
        add hl,de
        ex de,hl                        ; DE = IY + DE
        pop hl                          ; caller's HL back
        ret
; ----------------------------------------------------------------------
; Subroutine: record_buffer_hl [#CD91]
; Tasks:        HL = address of the 128-byte record buffer (workspace+&E0); falls into
;               iy_offset_hl. Read, not observed yet (relative file commands).
; Input:        IY = VDOS workspace
; Output:       HL = workspace+&E0
; Changed:      HL, F
; Called by:    the relative file commands
record_buffer_hl:
        ld hl,#00E0                     ; record buffer offset; on into iy_offset_hl
; ----------------------------------------------------------------------
; Subroutine: iy_offset_hl [#CD94]
; Tasks:        HL = workspace (IY) + HL: address of a workspace field (twin of workspace_offset for HL).
; Input:        HL = offset; IY = VDOS workspace
; Output:       HL = IY + offset; DE kept
; Changed:      HL, F
; Called by:    CAS routines and many others
; Entered from: record_buffer_hl (falls through)
iy_offset_hl:
        push de                         ; keep DE
        push iy                         ; DE = IY ...
        pop de
        add hl,de                       ; HL = IY + offset
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: to_upper [#CD9B]
; Tasks:        Convert a lower case letter in A to upper case.
; Input:        A
; Output:       A
; Changed:      AF
; Called by:    ask_yes_no, the file name parser
to_upper:
        cp #61                          ; below 'a'?
        ret c
        cp #7B                          ; above 'z'?
        ret nc
        sub #20                         ; upper case
        ret
; ----------------------------------------------------------------------
; Subroutine: clear_memory [#CDA4]
; Tasks:        Fill a memory block with 0.
; Input:        DE = start, B = number of bytes (0 = 256)
; Output:       DE = byte after the block, A = 0, B = 0
; Changed:      AF, DE, B
; Called by:    rom_init, disc_init, rsx_field, rsx_xmon, parse_filename_fcb and others
clear_memory:
        xor a                           ; fill value 0
cm_loop:
        ld (de),a                       ; clear one byte
        inc de
        djnz cm_loop                    ; B bytes
        ret
; ----------------------------------------------------------------------
; Subroutine: disc_begin [#CDAA]
; Tasks:        Start a disc operation (called first by every sector-level routine): build a
;               frame on the stack so that the caller's RET goes to disc_end - which switches
;               the motor-off timer on and returns to the caller's caller - and keep its SP in
;               disc_frame_sp, so that a fatal error anywhere below can jump to disc_end too.
;               Then switch the motor on if it is not running and wait for the motor-on delay
;               (the ticker's event sets flag bit 3). Observed on every disc access.
; Input:        registers of the caller (kept)
; Output:       AF, BC, DE, HL kept
; Changed:      none - but the stack: after its RET the words disc_end, BC, DE, HL lie on top of the caller's own return address, so the caller's RET goes to disc_end
; Called by:    fdc_sector_rw, bios_move_track, sense_drive_status
; Calls:        stop_motor_ticker, drive_a_flags_address, start_motor_ticker
disc_begin:
        di                              ; (no interrupts while the stack is rebuilt)
        exx
        pop hl                          ; HL' = our return address (into the caller)
        exx
        push hl                         ; keep the caller's HL, DE, BC ...
        push de
        push bc
        ld (disc_frame_sp),sp           ; ... and this SP for disc_end
        exx
        ld de,disc_end                  ; the caller's RET will go to disc_end ...
        push de
        push hl                         ; ... and our RET back into the caller
        exx
        push hl                         ; the registers for the motor part
        push bc
        push de
db_motor_on:
        push af                         ; (also entered by disc_error_dialog)
        call stop_motor_ticker          ; no motor-off timer while working
        call drive_a_flags_address      ; drive A's flag byte: motor state
        bit 3,(hl)                      ; running?
        jr nz,db_return                 ; running: nothing to do
        ld bc,#FA7E                     ; no: motor on
        ld a,#01                        ; 1 = motors on
        out (c),a                       ; motor port &FA7E
        ld de,(disc_time_constants)     ; motor on delay (1/50 s)
        push hl
        call start_motor_ticker         ; the ticker's event (motor_event) sets bit 3 when it has passed
        pop hl
db_wait_spinup:
        bit 3,(hl)                      ; wait until the motor runs
        jr z,db_wait_spinup             ; not yet
db_return:
        pop af                          ; the registers of the caller of disc_begin
        pop de
        pop bc
        pop hl
        ret
; ----------------------------------------------------------------------
; Routine: disc_end [#CDE3]
; Tasks:        End of a disc operation, entered by the RET of the routine that called disc_begin
;               or by a jump after a fatal error: back to the frame (disc_frame_sp), start the
;               motor-off timer, clear the one-shot multi-sector bits of both drives and return
;               to the caller's caller with A = 0 (CY = 1), or with an error status in A (ST0
;               bit 3 or ST1, plus bit 6; HL = &BE4A) when CY = 0. Observed (success).
; Input:        disc_frame_sp; AF = the result (CY = 1 ok)
; Output:       CY = 1: A = 0; CY = 0: A = error status
; Changed:      AF; BC, DE, HL are restored from the frame (the values of disc_begin's caller)
; Called by:    every disc_begin frame; seek_track, fdc_result_check (fatal errors)
; Calls:        start_motor_ticker, drive_a_flags_address, drive_flags_address
disc_end:
        ld sp,(disc_frame_sp)           ; back to the frame
        push af
        ld de,(disc_time_constants+2)   ; motor off delay (1/50 s) ...
        call start_motor_ticker         ; ... then motor_event switches the motors off
        call drive_a_flags_address      ; HL = drive A's flags
        res 4,(hl)                      ; drive A: no multi-sector
        ld e,#01                        ; drive B ...
        call drive_flags_address        ; HL = drive B's flags
        res 4,(hl)                      ; ... neither: multi-sector holds for one disc operation only (observed: drive B's flags &51 -> &41 after the call)
        pop af                          ; the caller's registers
        pop bc
        pop de
        pop hl
        ld a,#00                        ; A = 0 ...
        ret c                           ; ... ok
de_error:
        ld hl,fdc_result                ; (not observed) error: ST0 not ready bit ...
        ld a,(hl)
        and #08
        inc hl
        or (hl)                         ; ... + ST1 + bit 6
        set 6,a
        dec hl
        dec hl
        ret
; ----------------------------------------------------------------------
; Subroutine: start_motor_ticker [#CE0F]
; Tasks:        Start the motor ticker: motor_event after DE ticks (1/50 s), once.
; Input:        DE = delay
; Changed:      AF, BC, DE, HL
; Called by:    disc_begin, disc_end
start_motor_ticker:
        ld hl,motor_ticker              ; ticker block (event block motor_event_block follows)
        ld bc,#0000                     ; no reload: one shot
        jp KL_ADD_TICKER                ; one-shot ticker DE
; ----------------------------------------------------------------------
; Subroutine: motor_event [#CE18]
; Tasks:        Event routine of the motor ticker (motor_event_block, class &80). If the
;               motors are marked running (drive A flag bit 3), the motor-off delay has passed:
;               switch them off (motors_off_now). Else the motor-on delay has passed: mark
;               them running (disc_begin waits for that) and stop the ticker. Observed.
; Changed:      AF, DE, HL
; Called by:    the firmware's ticker (KL ADD TICKER in start_motor_ticker)
; Calls:        drive_a_flags_address, motors_off_now, stop_motor_ticker; falls through into stop_motor_ticker
motor_event:
        call drive_a_flags_address      ; drive A's flag byte
        bit 3,(hl)                      ; running?
        jr nz,motors_off_now            ; yes: motor-off time is over
        set 3,(hl)                      ; no: motor-on time is over: running now
; ----------------------------------------------------------------------
; Subroutine: stop_motor_ticker [#CE21]
; Tasks:        Remove the motor ticker (KL DEL TICKER).
; Changed:      AF, DE, HL
; Called by:    disc_begin, motor_event, motors_off_now
stop_motor_ticker:
        ld hl,motor_ticker              ; motor ticker block
        jp KL_DEL_TICKER                ; remove it
; ----------------------------------------------------------------------
; Subroutine: bios_set_reg_save [#CE27]
; Tasks:        Extended BIOS &BE9E SET REG SAVE: A = 0 -> bios_entry saves the alternate
;               registers, IX and IY (bios_entry_handler, default); A = &FF -> it does not
;               (bios_entry_fast; BC' is set to the firmware's value once). VDOS also uses the entry
;               for "motor off at once" (VDOS 2.0 manual): any other A falls into motors_off_now.
;               Observed (test program RS.COM under |CPM,1): A = &FF -> A = 0 (old mode), a CONOUT
;               then ran through bios_entry_fast; A = 0 -> A = &FF, bios_entry_target back to
;               &C37C; A = &55 -> motors off, A = 0. The boot sectors call it with A = 0 (no change).
; Input:        A = 0, &FF, or any other value (motors off)
; Output:       A = previous reg_save_mode when the mode changes; the same mode: A unchanged;
;               other A (motors off): A = 0
; Changed:      AF, HL (mode change: also BC' when &FF)
; Called by:    cpm_ext_set_reg_save (&BE9E)
; Calls:        install_entry_handler / ieh_set, motors_off_now (falls in)
bios_set_reg_save:
        or a                            ; A = 0: save registers
        jr z,bsrs_set                   ; yes
        inc a                           ; A = &FF: no register save (observed)
        jr z,bsrs_no_save
; ----------------------------------------------------------------------
; Subroutine: motors_off_now [#CE2D]
; Tasks:        Switch the motors off at once: stop the motor ticker, clear "running" (drive A
;               flag bit 3) and write 0 to the motor port.
; Changed:      AF, DE, HL
; Called by:    vdos_cas_in_close, motor_event, disc_error_dialog, bios_set_reg_save (other A)
; Calls:        stop_motor_ticker, drive_a_flags_address, motor_off; falls through into motor_off
motors_off_now:
        call stop_motor_ticker          ; no more motor timing
        call drive_a_flags_address      ; HL = drive A's flags
        res 3,(hl)                      ; not running
; ----------------------------------------------------------------------
; Subroutine: motor_off [#CE35]
; Tasks:        Switch all drive motors off (write 0 to the motor port &FA7E).
; Output:       A = 0; BC kept
; Changed:      A
; Called by:    disc_init (research: also the motor off event)
; Entered from: motors_off_now (falls through)
motor_off:
        ld a,#00                        ; 0 = all motors off
        push bc
        ld bc,#FA7E                     ; drive motor port
        out (c),a                       ; 0 = all motors off
        pop bc
        ret
bsrs_no_save:
        dec a                           ; back to &FF (observed)
bsrs_set:
        ld hl,reg_save_mode             ; the current mode ...
        cp (hl)                         ; same as now?
        ret z                           ; ... unchanged: nothing to do
        push bc                         ; the mode changes (observed both ways)
        ld b,(hl)
        ld (hl),a                       ; new mode
        or a
        ld a,b                          ; A = old mode
        pop bc
        jp z,install_entry_handler      ; mode 0: install bios_entry_handler (observed: bios_entry_target &C37C again)
        di
        exx
        ld bc,(firmware_bc_alt)         ; mode &FF: BC' = the firmware's value from now on (observed)
        exx
        ld hl,bios_entry_fast           ; bios_entry_fast ...
        jp ieh_set                      ; ... into bios_entry_target
; ----------------------------------------------------------------------
; Subroutine: rsx_open [#CE5B]
; Tasks:        |OPEN,"name",len,ch: open (or create) the relative file name on channel ch with the
;               record length len (<= the channel's maximum from |FILES). The name goes into
;               the channel's FCB (block+&0D, 36 bytes); open_file, else make_file; the channel
;               is marked open (bit 7 of its number). Observed (manual example, tests).
;               Errors (observed): no |FILES -> "Feld nicht definiert"; channel not in |FILES ->
;               "Kanal nicht definiert"; already open -> "Kanal bereits offen" (manual 2.0:
;               "geoeffnet"); len > maximum -> "Feld zu lang"; channel >= 128 -> "Kanalnummer
;               falsch"; another number of parameters, wildcards or an empty name ->
;               Eingabefehler.
; Input:        A = number of parameters (3), IX = parameters (IX+0 channel, +2 len, +4 name)
; Output:       the channel block: +5/6 = len, FCB opened, bit 7 of +0 set
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "OPEN" (rom_jumpblock)
; Calls:        rel_check_channel, rsx_param, sub_de_hl, rsx_string_param, parse_filename_fcb, iy_offset_hl, copy_name, open_file, make_file
rsx_open:
        call rel_check_channel          ; HL = the channel's block +5 (current length), DE = its FCB; errors if not ready
        push hl                         ; keep block+5 ...
        push de                         ; ... and the FCB
        push hl                         ; block+5 once more
        dec hl
        ld d,(hl)                       ; DE = the maximum record length (block+3/4) ...
        dec hl
        ld e,(hl)
        call rsx_param                  ; HL = len (the next parameter)
        ex de,hl                        ; len ...
        inc hl                          ; ... + 1
        call sub_de_hl                  ; maximum - (len + 1): CY if len > maximum
        ld a,#27                        ; msg &27 "Feld zu lang" ...
        jp nc,error_message             ; ... (observed: len 60 on a channel of 50)
        pop hl                          ; block+5 ...
        ld (hl),e                       ; ... = the current record length
        inc hl
        ld (hl),d
        call rsx_string_param           ; B/HL = the file name
        call parse_filename_fcb         ; into the name FCB
        jp c,error_bad_name             ; wildcards: Eingabefehler
        ld a,(iy+#26)                   ; empty name?
        cp #20
        jp z,error_bad_name             ; yes: Eingabefehler
        ld hl,#0025                     ; the name FCB ...
        call iy_offset_hl
        pop de                          ; ... to the channel's FCB ...
        ld b,#24                        ; ... 36 bytes
        call copy_name
        call open_file                  ; open it
        jr nz,open_mark                 ; found: on
        call make_file                  ; not there: create it (observed: ADRESS.REL)
open_mark:
        pop hl                          ; block+5 ...
        ld de,#FFFB                     ; ... - 5 = the block start (the channel byte)
        add hl,de
        set 7,(hl)                      ; bit 7: channel open
        ret
; ----------------------------------------------------------------------
; Subroutine: rel_check_channel [#CEA3]
; Tasks:        Common start of |OPEN: exactly 3 parameters, |FILES defined (rel_files_flag),
;               the channel number (rel_channel_number) and its block (rel_find_channel), not
;               open yet. Falls into rel_block_pointers. Observed (|OPEN).
; Input:        A = number of parameters, IX = parameters
; Output:       HL = block+5, DE = block+&0D (the FCB); IX + 2
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    rsx_open
; Calls:        cas_entry_setup, rel_channel_number, rel_find_channel; error_message, rsx_bad_param_2
rel_check_channel:
        call cas_entry_setup            ; IY, error SP
        cp #03                          ; 3 parameters?
        jr nz,rsx_bad_param_2           ; no: Eingabefehler (observed: |OPEN with 2)
        ld a,(rel_files_flag)           ; |FILES defined (rel_files_flag)?
        or a
        ld a,#28                        ; msg &28 "Feld nicht definiert" ...
        jp z,error_message              ; ... (observed: |OPEN without |FILES, and after |FILES alone)
        call rel_channel_param          ; C = the channel number (0-127)
        call rel_find_channel           ; HL = its block
        bit 7,(hl)                      ; open already?
        ld a,#2A                        ; msg &2A "Kanal bereits offen" ...
        jp nz,error_message             ; ... (observed)
rel_block_pointers:
        ex de,hl                        ; HL = block: DE = block+5 ...
        ld hl,#0005
        add hl,de
        ex de,hl
        ld hl,#0008                     ; ... HL = block+&0D (the FCB) ...
        add hl,de
        ex de,hl                        ; ... swapped: HL = block+5, DE = FCB
        ret
; ----------------------------------------------------------------------
; Subroutine: rel_find_channel [#CECC]
; Tasks:        Find the block of channel C in the |FILES area: (rel_area)+0 = number of
;               channels, the first block at +&131, each block links to the next (+1/2).
;               Not there: "Kanal nicht definiert". Observed.
; Input:        C = channel
; Output:       HL = its block (+0: channel number, bit 7 = open)
; Changed:      AF, HL, B
; Called by:    rel_check_channel, rsx_close, rsx_field, rsx_get, rsx_put
; Calls:        load_hl_indirect; error_message
rel_find_channel:
        ld hl,(#BEB7)                   ; the |FILES area ...
        ld b,(hl)                       ; B = number of channels
        push de
        ld de,#0131                     ; ... first block at +&131
        add hl,de
        pop de
rfc_loop:
        ld a,(hl)                       ; its channel number (without the open bit) ...
        and #7F
        cp c                            ; ... the one?
        ret z                           ; yes
        inc hl                          ; no: the link (+1/2) ...
        call load_hl_indirect           ; ... to the next block
        djnz rfc_loop                   ; all channels
        ld a,#35                        ; msg &35 "Kanal nicht definiert" ...
        jp error_message                ; ... (observed: channel 3 not in |FILES)
rel_channel_param:
        call rsx_param                  ; HL = the next parameter: the channel
rel_channel_number:
        ld de,#0080                     ; 128 ...
        ex de,hl
        call sub_de_hl                  ; ... - (channel + 1): CY if channel < 128
        ld c,e                          ; C = channel
        ret c                           ; ok
        ld a,#2C                        ; msg &2C "Kanalnummer falsch" ...
        jp error_message                ; ... (observed: |OPEN on channel 200)
; ----------------------------------------------------------------------
; Subroutine: rsx_close [#CEF7]
; Tasks:        |CLOSE,ch: close the relative file on channel ch (BDOS close of the channel's
;               FCB) and clear its open bit. Not open: "Kanal nicht offen" (manual 2.0: "Kanal
;               nicht geoeffnet"). Observed.
; Input:        A = number of parameters (1), IX = parameters
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "CLOSE" (rom_jumpblock)
; Calls:        rsx_number_param, rel_channel_number, rel_find_channel, rel_block_pointers, close_file
rsx_close:
        call rsx_number_param           ; HL = ch
        call rel_channel_number         ; C = channel (< 128)
        call rel_find_channel           ; its block
        bit 7,(hl)                      ; open?
        ld a,#2B                        ; msg &2B "Kanal nicht offen" ...
        jp z,error_message              ; ... (observed: |CLOSE twice, |CLOSE of a channel never opened)
        res 7,(hl)                      ; not open any more
        call rel_block_pointers         ; DE = its FCB
        jp close_file                   ; close the file
rsx_bad_param_2:
        jp error_bad_name               ; "Eingabefehler" (observed: wrong parameter counts, field lengths 0 / 256)
; ----------------------------------------------------------------------
; Subroutine: rsx_field [#CF12]
; Tasks:        |FIELD,ch,l1,l2,...: split the record of channel ch into fields of the lengths l1,
;               l2, ... (1-255 each); their sum must not exceed the record length. The lengths
;               go into the channel's field table (block+&31, 32 bytes, cleared first, 0 =
;               end). Errors (observed): fewer than 2 parameters, a length 0 or >= 256 ->
;               Eingabefehler; sum > record length -> "Feld zu lang"; channel not open -> "Kanal
;               nicht offen"; not defined -> "Kanal nicht definiert".
; Input:        A = number of parameters, IX = parameters (last first: the lengths, then ch)
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "FIELD" (rom_jumpblock)
; Calls:        cas_entry, record_buffer_de, rsx_param, rel_channel_param, rel_find_channel, load_hl_indirect, sub_de_hl, clear_memory
rsx_field:
        call cas_entry                  ; IY, error SP
        cp #02                          ; at least 2 parameters?
        jr c,rsx_bad_param_2            ; no: Eingabefehler (observed: |FIELD,1)
        call record_buffer_de           ; the lengths are collected in the record buffer first
        dec a                           ; number of lengths ...
        push af
        ld b,a                          ; ... B = it
        ld hl,#0000                     ; sum = 0 (on the stack)
        push hl
fld_next_length:
        call rsx_param                  ; next length (the parameters come last first)
        ex de,hl
        ex (sp),hl                      ; sum + length ...
        add hl,de
        ex (sp),hl
        ex de,hl
        xor a                           ; high byte 0?
        cp h
        jr nz,rsx_bad_param_2           ; no: Eingabefehler (observed: 256)
        ld a,l
        or a                            ; 0?
        jr z,rsx_bad_param_2            ; yes: Eingabefehler (observed)
        ld (de),a                       ; into the scratch list
        inc de
        djnz fld_next_length            ; all lengths
        dec de                          ; DE = the last one stored (they are copied back in reverse: first field first)
        push de
        call rel_channel_param          ; C = the channel (the first parameter)
        call rel_find_channel           ; its block
        pop ix                          ; IX = the end of the scratch list
        pop de                          ; DE = the sum
        push hl
        push de
        ld de,#0005                     ; block+5: the current record length ...
        add hl,de
        call load_hl_indirect           ; ... HL = it
        ld a,#00                        ; 0 = not open? Only the LOW byte of the length is tested: a record length of 256, 512, ... counts as not open (observed: |OPEN ...,256 -> |FIELD "Kanal nicht offen")
        or l
        ld a,#2B                        ; msg &2B "Kanal nicht offen" ...
        jp z,error_message              ; ... (observed)
        inc hl                          ; record length + 1 ...
        pop de
        call sub_de_hl                  ; ... - sum: CY if the sum is too big
        ld a,#27                        ; msg &27 "Feld zu lang" ...
        jp nc,error_message             ; ... (observed: 60 > 47)
        pop hl
        ld de,#0031                     ; the field table at block+&31 ...
        add hl,de
        ex de,hl
        push de
        ld b,#20                        ; ... 32 bytes cleared (0 = end of the table)
        call clear_memory
        pop hl
        pop bc                          ; B = number of fields
fld_copy:
        ld a,(ix+#00)                   ; the lengths from the scratch list, last parameter = last field ...
        ld (hl),a                       ; ... into the field table
        dec ix
        inc hl
        djnz fld_copy
        ret
rel_getput_start:
        call cas_entry_setup            ; IY, error SP
        sub #03                         ; at least 3 parameters (ch, record, one string)?
        jr c,rsx_bad_param_2            ; no: Eingabefehler (observed: |GET,1,1)
        inc a                           ; A = number of strings + 1 (Z never)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_get [#CF7E]
; Tasks:        |GET,ch,rec,@a$[,@b$...]: read record rec of channel ch and give field i to the
;               i-th variable. The record (current length bytes) is read 128-byte record by
;               record (rel_read_random) into the channel buffer (block+&5A); each field is then
;               assigned by rel_assign_string (a BASIC statement var$="...", then the field bytes
;               copied into the new string). Trailing zero bytes of a field are not taken
;               (observed: "kurz" from a 50-byte field has length 4); a variable without a field
;               stays as it was; a field without a variable is skipped.
;               Errors (observed): not open -> "Kanal nicht offen"; no |FIELD -> "Feld nicht
;               segmentiert"; rec x len / 128 >= 65536 -> "Recordnummer zu gross" (variables
;               unchanged); variables that do not exist yet -> BASIC "Improper argument".
;               *** BUG: msg &37 "Record leer" (rel_no_data; the manual: error 55 "Rekord enthaelt
;               keine Daten") never appears: a record in a missing extent reads as empty, because
;               read_random_body reads anyway (Z is still set after random_seek's error exit - see
;               set_file_write_flag). Simulated 2026-10-26: |GET,1,2000 on a 47-byte file with only
;               record 1 (extent 5 missing): random_seek set (iy+&21) = &FF (&E675), Z still set at
;               &E5ED; with Z cleared there by hand (as DR's ori would) &FF stayed, rsx_get jumped
;               to rel_no_data -> "Record leer", "Ready".
; Input:        A = number of parameters (>= 3), IX = parameters
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "GET" (rom_jumpblock)
; Calls:        rel_getput_start, rsx_param, rel_channel_param, rel_find_channel, rel_record_position, rel_read_random, record_buffer_hl, add_a_hl, rel_copy_part, rel_next_record, rel_assign_string
rsx_get:
        call rel_getput_start           ; A = number of strings + 1
        push af                         ; kept
        add a,a                         ; IX + 2 x (strings + 1): past the variables, to the record number ...
        ld c,a
        ld b,#00
        add ix,bc
        push ix                         ; (the variables are at IX-2, IX-4, ...: read later from the top)
        call rsx_param                  ; HL = the record number
        push hl
        call rel_channel_param          ; C = the channel
        call rel_find_channel           ; its block
        bit 7,(hl)                      ; open?
        ld a,#2B                        ; msg &2B "Kanal nicht offen" ...
        jp z,error_message              ; ... (observed)
        push hl
        pop ix                          ; IX = the block
        pop de                          ; DE = the record number
        xor a                           ; a field table?
        or (ix+#31)
        ld a,#29                        ; msg &29 "Feld nicht segmentiert" ...
        jp z,error_message              ; ... (observed)
        ld (ix+#07),e                   ; block+7/8 = the record number
        ld (ix+#08),d
        ld c,(ix+#05)                   ; BC = the record length
        ld b,(ix+#06)
        call rel_record_position        ; the random record number (FCB+33) of byte rec x len, A = offset in that 128-byte record
        ld c,(ix+#09)                   ; BC = the buffer (block+&5A) ...
        ld b,(ix+#0A)
        push bc                         ; ... kept
get_next_record:
        call rel_read_random            ; read the 128-byte record
        push af
        ld a,(iy+#21)                   ; return code &FF?
        inc a
        jr z,rel_no_data                ; yes: "Record leer" - not reached in normal runs (the read overwrites &FF with 1); reached only with Z cleared by hand at &E5ED (simulated)
        call record_buffer_hl           ; HL = the record buffer ...
        pop af
        call add_a_hl                   ; ... + offset
        call rel_copy_part              ; copy the bytes of this 128-byte record into the channel buffer
        ld a,d                          ; all bytes of the record?
        or e
        jr z,get_assign
        call rel_next_record            ; no: next 128-byte record ...
        xor a                           ; ... from its start
        jr get_next_record
get_assign:
        ld de,#0031                     ; IX = the field table (block+&31)
        add ix,de
        pop de                          ; DE = the buffer
        pop iy                          ; IY = the parameter list behind the variables
        pop bc                          ; B = strings + 1 ...
get_next_var:
        push bc                         ; (loop count)
        dec iy                          ; next variable: HL = its descriptor (going down the list)
        ld h,(iy+#00)
        dec iy
        ld l,(iy+#00)
        ld a,(ix+#00)                   ; the field's length ...
        inc ix
        or a                            ; 0: no more fields
        jr z,get_no_field
        ld b,#00                        ; BC = the length
        ld c,a
        push iy
        push de
        push af
        call rel_assign_string          ; assign the field (DE, BC bytes) to the variable HL
        pop af
        pop hl
        call add_a_hl                   ; DE + length: the next field
        ex de,hl
        pop iy
        pop bc
        djnz get_next_var               ; next variable
        ret
get_no_field:
        pop bc                          ; more variables than fields: the rest stays as it was (observed: d$ unchanged)
        ret
rel_no_data:
        ld a,#37                        ; msg &37 "<CR><LF>Record leer" (manual 2.0: error 55 "Rekord enthaelt keine Daten"); reached only by simulation (see rsx_get), observed text "Record leer", then "Ready"
        jp error_message
; ----------------------------------------------------------------------
; Subroutine: rsx_put [#D015]
; Tasks:        |PUT,ch,rec,s1[,s2...]: write the strings into the fields of record rec of channel
;               ch. The descriptors are collected in the record buffer; the channel buffer
;               (block+&5A) is cleared, each string copied into its field (longer: cut, shorter:
;               the rest 0); then the record is written 128-byte record by record: a first or
;               last part record is read first (rel_read_random) and merged, whole 128-byte
;               records are written straight (pu_full_record). More strings than fields: the
;               rest is ignored.
;               Observed: the manual examples, 120 chars into a 100-byte field (cut), records
;               0, 1, 3, 174, 65535 x 30, 300-byte records (> 128: whole records written).
;               Errors (observed): not open, no |FIELD, record too big (as |GET); "Laufwerk A:
;               Directory voll" when the record needs a new extent and the directory is full.
;               Direct strings (|PUT,1,1,"x") work through basic_error_patch but each leaves a
;               BASIC temporary string: the 5th |PUT with 2 such strings -> "String expression
;               too complex" (observed); use @a$.
; Input:        A = number of parameters (>= 3), IX = parameters
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "PUT" (rom_jumpblock)
; Calls:        rel_getput_start, record_buffer_de, rsx_string_param, rsx_param, rel_channel_param, rel_find_channel, load_hl_indirect, rel_clear, rel_record_position, rel_read_random, rel_copy_part, rel_write_random, rel_next_record, sub_de_hl, record_buffer_hl
rsx_put:
        call rel_getput_start           ; A = number of strings + 1
        call record_buffer_de           ; the descriptors go to the record buffer
        push af
        ld b,a                          ; B = strings + 1
put_collect:
        push bc                         ; next parameter as a string ...
        call rsx_string_param
        ld a,h                          ; ... address high, low and length into the list
        ld (de),a
        inc de
        ld a,l
        ld (de),a
        inc de
        ld a,b
        ld (de),a
        inc de
        pop bc
        djnz put_collect                ; (the last one is the record number's word, overwritten below)
        pop af
        ld (de),a                       ; end of the list: the count
        push de
        call rsx_param                  ; HL = the record number
        push hl
        call rel_channel_param          ; C = the channel
        call rel_find_channel           ; its block
        bit 7,(hl)                      ; open?
        ld a,#2B                        ; msg &2B "Kanal nicht offen"
        jp z,error_message
        ex de,hl                        ; DE = the block
        ld hl,#0005
        add hl,de
        call load_hl_indirect           ; HL = the record length
        push de
        push hl
        ld hl,#005A                     ; the channel buffer (block+&5A) ...
        add hl,de
        pop de
        call rel_clear                  ; ... cleared (length bytes)
        pop de
        ld hl,#0007                     ; block+7/8 = the record number
        add hl,de
        pop bc
        ld (hl),c
        inc hl
        ld (hl),b
        ld hl,#0031                     ; the field table (block+&31) ...
        add hl,de
        ld a,(hl)
        or a                            ; ... any field?
        ld a,#29                        ; msg &29 "Feld nicht segmentiert"
        jp z,error_message
        pop ix                          ; IX = the end of the descriptor list
        push de
        push hl
        ld hl,#005A
        add hl,de
        pop de
        ex de,hl
        ld b,(ix+#00)                   ; B = the count
        dec ix
put_next_field:
        push bc                         ; the field's length ...
        ld a,(hl)
        or a                            ; ... 0: no more fields
        jr nz,put_copy_string
; More strings than fields: the rest is ignored (observed: |PUT,1,2,@x$,@y$,@z$ with 2 fields).
        pop bc                          ; (the loop count)
        jr put_write
put_copy_string:
        inc hl                          ; next field
        push hl
        ld c,(ix+#00)                   ; C = the string's length ...
        dec ix
        cp c                            ; ... longer than the field?
        jr nc,put_copy                  ; yes: only the field length (observed: 120 into 100)
        ld c,a                          ; no: the string's length (the rest stays 0)
put_copy:
        ld l,(ix+#00)                   ; HL = the string's text
        dec ix
        ld h,(ix+#00)
        dec ix
        push de
        ld b,a
        xor a                           ; an empty string?
        or c
        ld a,b
        jr z,put_field_done
        ld b,#00
        call KL_LDIR                    ; copy it into the field (KL LDIR: from RAM)
put_field_done:
        pop hl                          ; DE = the next field
        call add_a_hl
        ex de,hl
        pop hl
        pop bc
        djnz put_next_field             ; next string
put_write:
        pop ix                          ; IX = the block
        ld c,(ix+#05)
        ld b,(ix+#06)
        ld e,(ix+#07)
        ld d,(ix+#08)
        call rel_record_position        ; the random record number, A = offset in it
        ld l,(ix+#09)                   ; HL = the channel buffer
        ld h,(ix+#0A)
        push hl
        or a                            ; offset 0: starts on a 128-byte record
        jr z,put_whole_records
        call record_buffer_hl
        call rel_read_random            ; a part record: read it first ...
        ex (sp),hl
        pop bc
        push af
        add a,c
        ld c,a
        jr nc,put_first_part
        inc b
put_first_part:
        pop af                          ; A = the offset in the 128-byte record
        call rel_copy_part              ; ... merge the first bytes ...
        push hl
        call rel_write_random           ; ... and write it back
        call rel_next_record            ; next 128-byte record
put_whole_records:
        ld hl,#0080                     ; 128 or more bytes left?
        call sub_de_hl
        jr c,put_last_part              ; no: the last part
pu_full_record:
        ex de,hl                        ; a whole 128-byte record: copy it to the record buffer ...
        call record_buffer_hl
        ex de,hl
        ex (sp),hl
        ld bc,#0080
        ldir
        ex (sp),hl
        ex de,hl
        call rel_write_random           ; ... write it without reading (observed: 300-byte records)
        call rel_next_record
        jr put_whole_records
put_last_part:
        pop hl                          ; bytes left?
        ld a,d
        or e
        ret z                           ; none: done
        push hl
        call rel_read_random            ; the last part: read the record ...
        ld c,e
        ld b,d
        pop hl
        call record_buffer_de
        ldir                            ; ... merge ...
        jp rel_write_random             ; ... and write it
rel_copy_part:
        push bc                         ; copy up to 128 - A bytes (DE counts the record bytes left) from HL to (SP)
        ld b,a
        ld a,#80
        sub b
        ld b,a
rcp_loop:
        ld a,(hl)                       ; next byte: from (HL) to the address on the stack
        ex (sp),hl
        ld (hl),a
        inc hl
        ex (sp),hl
        inc hl
        dec de
        ld a,d
        or e
        jr z,rcp_done
        djnz rcp_loop
rcp_done:
        pop bc                          ; all bytes of the record (or of this 128-byte part) copied
        ret
rel_next_record:
        inc (ix+#2E)                    ; random record number (FCB+33, block+&2E) + 1
        ret nz
        inc (ix+#2F)
        ret
; ----------------------------------------------------------------------
; Subroutine: rel_record_position [#D129]
; Tasks:        Random record number of record DE of length BC: byte = DE x BC (16 x 16 -> 32
;               bits, alternate set for the high word), record = byte / 128, A = byte mod 128.
;               Record >= 65536: "Recordnummer zu gross" (msg &2D; observed: 29000 x 300).
;               The result goes to the FCB's random record (block+&2E/&2F).
; Input:        DE = record number, BC = record length, IX = block
; Output:       A = offset in the 128-byte record; FCB+33/34 set
; Changed:      AF, BC, DE, HL
; Called by:    rsx_get, rsx_put
rel_record_position:
        push bc                         ; keep BC
        ld hl,#0000
        ld a,d
        or e
        jr z,rrp_store
        di
        ld a,#10
        ld hl,#0000
        exx
        ld de,#0000
        ld hl,#0000
        exx
rrp_mul_loop:
        srl d                           ; record number x record length, 16 x 16 bits by shift and add: next bit of DE
        rr e
        jr nc,rrp_mul_next
        add hl,bc
        exx
        adc hl,de
        exx
rrp_mul_next:
        sla c                           ; the multiplicand (BC, HL') x 2
        rl b
        exx
        ex de,hl
        adc hl,hl
        ex de,hl
        exx
        dec a
        jr nz,rrp_mul_loop
        exx
        push hl
        exx
        pop de
        ei
        ld a,l
        and #7F
        ld c,a
        sla l
        rl h
        rl e
        rl d
        ld l,h
        ld h,e
        xor a
        or d
        ld a,#2D                        ; msg &2D "Recordnummer zu gross" (manual: "Rekordnummer") ...
        jp nz,error_message             ; ... if the record number does not fit 16 bits
        ld a,c
rrp_store:
        ld (ix+#2E),l                   ; the random record number (FCB+33 / +34, block+&2E / +&2F)
        ld (ix+#2F),h
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_files [#D17A]
; Tasks:        |FILES[,ch,max,...]: define the channels for relative files (pairs: channel 0-127,
;               maximum record length). The old area is released first (rel_free_area); then
;               the area is reserved below BASIC's HIMEM (&AE7B) and HIMEM lowered through BASIC
;               (rel_set_himem). Area (rel_area, &BEB7): +0 number of channels, +1/2 its size,
;               +3.. the scratch line for rel_assign_string, the blocks from +&131. Block (&5A +
;               max bytes): +0 channel (bit 7 open), +1/2 link to the next block, +3/4 maximum
;               length, +5/6 current length (|OPEN), +7/8 record number, +9/10 buffer address,
;               +&0D FCB (36 bytes, random record at +&2E/&2F), +&31 field table (32), +&5A the
;               record buffer. |FILES alone releases everything (HIMEM back).
;               Observed: |FILES,1,100,2,50 / 1,300 / 1,60,2,300; |FILES (HIMEM back to &A677).
;               Errors (observed): odd number of parameters, a channel twice, a channel >= 128
;               -> Eingabefehler (the &2C "Kanalnummer falsch" loaded at &D1A3 is lost:
;               error_bad_name loads &21 itself). A maximum length 0 is NOT refused: A = &21 is
;               loaded, but CY is clear, so the error at &D1B6 is skipped (observed: |FILES,1,0
;               and 1,0,2,5 without a message).
; Input:        A = number of parameters (even), IX = parameters
; Changed:      AF, BC, DE, HL, IX, SP (restored); IY = VDOS workspace; HIMEM; rel_files_flag
; Called by:    RSX "FILES" (rom_jumpblock)
; Calls:        cas_entry, rel_free_area, record_buffer_hl, rel_check_duplicates, rel_set_himem, rel_clear, rel_block_link
rsx_files:
        call cas_entry                  ; IY, error SP
        or a                            ; no parameters: just release the area (observed)
        jp z,rel_free_area
        rr a                            ; pairs: count / 2 ...
        jr c,files_check                ; odd: Eingabefehler (observed)
        ld b,a                          ; B = number of channels
        call record_buffer_hl           ; the pairs go to the record buffer: +0 count, then channel / maximum
        push hl
        ld (hl),b
        inc hl
        ld (cpm_ext_set_message),sp     ; SP kept in &BE80 (rel_saved_sp) ...
        ld sp,ix                        ; ... SP = IX: the parameters are popped (last first: maximum, then channel)
files_next_pair:
        pop de                          ; DE = the maximum length ...
        xor a
        cp e                            ; ... low byte 0?
        jr nz,files_store_max
        cp d                            ; and high byte 0?
        ld a,#21                        ; A = &21 (Eingabefehler) - but CY is clear here ...
        jr z,files_end_list             ; ... so this 'error' only ends the list (observed: |FILES,1,0 accepted)
files_store_max:
        ld (hl),e                       ; store the maximum
        inc hl
        ld (hl),d
        inc hl
        pop de                          ; DE = the channel
        xor a
        or d
        ld a,#2C                        ; A = &2C "Kanalnummer falsch", CY ...
        scf
        jr nz,files_end_list            ; high byte not 0: error
        bit 7,e                         ; channel >= 128?
        scf
        jr nz,files_end_list            ; yes: error (shown as Eingabefehler, observed: 128)
        ld (hl),e                       ; store the channel
        inc hl
        djnz files_next_pair            ; next pair
        or a
files_end_list:
        ld sp,(cpm_ext_set_message)     ; SP back
files_check:
        jp c,error_bad_name             ; CY: Eingabefehler
        pop hl
        push hl
        ld b,(hl)
        call rel_check_duplicates       ; DE = the total size; NC if a channel is given twice
        jp nc,error_bad_name            ; twice: Eingabefehler (observed)
        push de
        call rel_free_area              ; release an old area first
        ld hl,(#AE7B)                   ; BASIC's HIMEM ...
        ld a,#FF                        ; rel_files_flag = &FF: channels defined
        ld (rel_files_flag),a
        pop de
        push de
        or a
        sbc hl,de                       ; ... - the size = the new HIMEM
        push hl
        call rel_set_himem              ; lower BASIC's HIMEM to it
        pop hl
        inc hl                          ; the area starts above it ...
        ld (#BEB7),hl                   ; ... rel_area = its address
        pop de
        inc hl
        ld (hl),e                       ; +1/2 = its size
        inc hl
        ld (hl),d
        inc hl
        dec de
        dec de
        dec de
        call rel_clear                  ; the rest cleared
        pop hl
        ld ix,(#BEB7)                   ; IX = the area
        ld b,(hl)
        ld (ix+#00),b                   ; +0 = number of channels
        ld de,#0131                     ; the first block at +&131
        add ix,de
files_next_block:
        push ix                         ; DE = this block
        pop de
        push bc
        call rel_block_link             ; A = channel, BC = maximum, DE = the next block
        ld (ix+#00),a                   ; +0 channel (not open)
        ld (ix+#01),e                   ; +1/2 link
        ld (ix+#02),d
        ld (ix+#03),c                   ; +3/4 maximum length
        ld (ix+#04),b
        push ix
        ld bc,#005A                     ; +&5A: the buffer ...
        add ix,bc
        push ix
        pop bc
        pop ix
        ld (ix+#09),c                   ; ... its address at +9/10
        ld (ix+#0A),b
        pop bc
        push de
        pop ix
        djnz files_next_block           ; next channel
        ret
; ----------------------------------------------------------------------
; Subroutine: rel_free_area [#D225]
; Tasks:        Release the |FILES area: if rel_files_flag is set, HIMEM must still be just below
;               rel_area (else msg &1D - BASIC has moved HIMEM), then HIMEM goes back up by the
;               area's size (rel_set_himem) and the flag is cleared. Observed (|FILES twice,
;               |FILES alone).
; Changed:      AF, BC, DE, HL
; Called by:    rsx_files
rel_free_area:
        xor a                           ; channels defined (rel_files_flag)?
        ld hl,rel_files_flag
        or (hl)
        ret z                           ; no: nothing to do
        push hl
        ld de,(#AE7B)                   ; BASIC's HIMEM ...
        ld hl,(#BEB7)                   ; ... must be rel_area - 1
        dec hl
        or a
        sbc hl,de
        ld a,#1D                        ; msg &1D "MEMORY-fehler" if not (observed: MEMORY HIMEM-100, then |FILES)
        pop hl
        jp nz,error_message
        ld (hl),#00                     ; rel_files_flag = 0
        ld l,e
        ld h,d
        inc hl
        inc hl
        call load_hl_indirect           ; the area's size ...
        add hl,de                       ; ... + HIMEM = the old HIMEM
        jp rel_set_himem                ; HIMEM up again
rel_clear:
        xor a                           ; clear DE bytes from HL
        ld (hl),a
        inc hl
        dec de
        ld a,e
        or d
        jr nz,rel_clear
        ret
rel_block_link:
        inc hl                          ; from the next pair in the list: A = channel, BC = maximum, DE = the next block (this + &5A + maximum; overflow: ded_silent path)
        push de
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld c,e
        ld b,d
        ex (sp),hl
        add hl,de
        ld de,#005A
        add hl,de
        ld a,#27
        jp c,ded_silent
        ex de,hl
        pop hl
        ld a,(hl)
        ret
rel_check_duplicates:
        ld de,#0131                     ; total size of all blocks in DE; NC if a channel appears twice
rcd_channel:
        push bc                         ; next channel of the |FILES list: its block
        push bc
        call rel_block_link
        pop bc
        push hl
        jr rcd_next
rcd_compare:
        inc hl                          ; next entry: compare its channel number
        inc hl
        inc hl
        cp (hl)
        jr z,rcd_found
rcd_next:
        djnz rcd_compare                ; count the entries
        pop hl
        pop bc
        djnz rcd_channel
        scf
        ret
rcd_found:
        pop hl                          ; a channel twice: NC (from the CP)
        pop bc
        ret
rel_set_himem:
        push hl                         ; set BASIC's HIMEM to HL: FAR CALL BASIC &FC3E and &F4F5 (ROM select &80, observed: reached ROM 0)
        rst #18                         ; FAR CALL
        defw far_basic_himem_1          ;   to #FC3E [ROM 128]  (observed: reached rom0)
        pop de
        rst #18                         ; FAR CALL
        defw far_basic_himem_2          ;   to #F4F5 [ROM 128]  (observed: reached rom0)
        ret
far_basic_himem_1:
        defw #FC3E                      ; far address: to #FC3E; far address: BASIC &FC3E (ROM select &80: the on-board BASIC) - first part of setting HIMEM
        defb #80                        ;   ROM 128
far_basic_himem_2:
        defw #F4F5                      ; far address: to #F4F5; far address: BASIC &F4F5 (ROM select &80) - second part of setting HIMEM
        defb #80                        ;   ROM 128
; ----------------------------------------------------------------------
; Subroutine: rel_assign_string [#D296]
; Tasks:        Give BC bytes at DE to the BASIC string variable whose descriptor is at HL:
;               find the variable's name in BASIC's variable table (from &AE85, matching the
;               descriptor address), build the tokenized statement  &03 00 00 <name> &EF &22
;               <the bytes> &00  (string variable, '=', '"', the text) in the scratch line
;               (rel_area+3) - a '"' in the text becomes 'A' there so the literal stays valid -
;               and let BASIC run it (FAR CALL far_basic_statement): BASIC allocates a string of
;               the right length. Then the real bytes are copied into that string (so quotes
;               come through: observed 'sag "hallo"'). Trailing zero bytes are cut first.
;               Observed (|GET).
; Input:        HL = descriptor address, DE = the bytes, BC = their number
; Changed:      AF, BC, DE, HL
; Called by:    rsx_get
; Calls:        RAM_LAM, add_a_hl, far_basic_statement, load_hl_indirect
rel_assign_string:
        push hl                         ; keep descriptor, bytes, count
        push de
        push bc
        ld de,(#AE85)                   ; BASIC's variable table (&AE85 on the 464)
        ex de,hl
ras_next_var:
        inc hl                          ; skip the link ...
        inc hl
        push hl
ras_skip_name:
        rst #20                         ; RAM LAM; ... and the name (bit 7 ends it)
        inc hl
        rlca
        jr nc,ras_skip_name
        rst #20                         ; RAM LAM
        inc hl
        bit 6,a                         ; the type: bit 6 = ...
        inc hl
        jr nz,ras_skip_value
        dec hl
        push hl
        or a
        sbc hl,de                       ; the value's address = the descriptor?
        pop hl
        jr z,ras_found                  ; yes: this is the variable
        call add_a_hl
ras_skip_value:
        inc hl                          ; no: on to the next one
        pop bc
        jr ras_next_var
ras_found:
        pop hl                          ; HL = its name
        ld de,(#BEB7)                   ; the scratch line at rel_area + 3 ...
        ex de,hl
        inc hl
        inc hl
        inc hl
        push hl
        ld (hl),#03                     ; &03 00 00: a string variable (2 bytes for BASIC's address cache)
        inc hl
        ld (hl),#00
        inc hl
        ld (hl),#00
        inc hl
ras_copy_name:
        ld a,(de)                       ; the name (last letter + &80)
        ld (hl),a
        inc hl
        inc de
        rlca
        jr nc,ras_copy_name
        ld (hl),#EF                     ; &EF: '='
        inc hl
        ld (hl),#22                     ; &22: '"'
        inc hl
        pop af
        pop bc
        pop de
        push de
        push af
        ex de,hl
ras_copy_text:
        ld a,b                          ; the text ...
        or c
        jr z,ras_run
        ld a,(hl)
        cp #22                          ; ... a '"'?
        jr nz,ras_store_char
        ld a,#41                        ; yes: 'A' instead, so the literal stays valid (the real byte is copied below)
ras_store_char:
        ld (de),a                       ; into the line
        inc hl
        inc de
        dec bc
        jr ras_copy_text
ras_run:
        ex de,hl                        ; &00: end of the statement
        ld (hl),#00
        pop hl
        rst #18                         ; FAR CALL; BASIC runs it: the variable gets a string of the right length
        defw far_basic_statement        ;   to #D654 [ROM 128]  (observed: reached rom0)
        pop de
        pop hl
        ld c,(hl)                       ; its descriptor: length ...
        inc hl
        ld b,#00
        call load_hl_indirect           ; ... and address
        ex de,hl
        ld a,b
        or c
        ret z
        ldir                            ; copy the real bytes into the string (quotes included)
        ret
far_basic_statement:
        defw #D654                      ; far address: to #D654; far address: BASIC &D654 with ROM select &80 (no expansion ROM answers: the on-board BASIC) - runs the tokenized statement at HL (observed with |DERROR: DERR=<code>); also used by the relative files
        defb #80                        ;   ROM 128
; ----------------------------------------------------------------------
; Subroutine: rel_read_random [#D30D]
; Tasks:        Read a record of a relative file (read_random) with the format detection
;               switched off for the access (rel_detect_off) and on again afterwards
;               (rel_detect_on). Entry rel_write_random: the same for write_random. Read, not
;               observed (relative files: RSX commands).
; Input:        IX = the channel block; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    the relative file RSX commands
; Calls:        rel_detect_off, read_random / write_random
rel_read_random:
        call rel_detect_off
        call read_random
        jr rel_detect_on
rel_write_random:
        call rel_detect_off
        call write_random
rel_detect_on:
        push af                         ; AF kept ...
        ld a,#FF                        ; autodetect_format = &FF ...
        ld (autodetect_format),a
        pop af
        ret
rel_detect_off:
        push af                         ; AF kept ...
        xor a                           ; autodetect_format = 0 ...
        ld (autodetect_format),a
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_in_open [#D32A]
; Tasks:        CAS IN OPEN: open a file for input. Parses the name; without an extension
;               it tries "   ", BAS, BIN, BAK in this order (observed with LOAD "XYZ": four
;               searches). Opens the file, reads its first record and takes it as the AMSDOS
;               header if its checksum is right (else the file has no header: the record is
;               read again as data).
; Input:        B = length of the name, HL = name, DE = 2K buffer; IY = VDOS workspace
; Output:       CY = 1, Z = 0: HL = header (+&05 of the input header), DE = load address,
;               BC = length, A = file type;
;               CY = 0: A = error (&0E already open, &97 not found with message, ...)
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS IN OPEN &BC77)
; Calls:        in_open_check, parse_filename, set_extension, search_first, copy_name_iy,
;               open_file, init_in_header, read_record_in, checksum
; RAM:          Workspace (IY = &A700) fields of the CAS layer:
;               +&05 current user, +&06 default drive, +&23/24 SP for an error exit,
;               +&25 name FCB (32 bytes: drive, name, ext; filled by parse_filename),
;               +&45 input FCB, +&69 output FCB (36-byte CP/M FCBs; byte 0 = drive, &FF = closed),
;               +&8D input header, +&B3 output header (IX), +&E0 128-byte record buffer.
vdos_cas_in_open:
        call in_open_check              ; IX = input header; error if an input file is open
        push de                         ; keep the buffer address
        call parse_filename             ; name -> name FCB (workspace+&25)
        jp c,error_bad_name             ; bad name: "Eingabefehler"
        ld a,(iy+#2E)                   ; first extension byte &FF = no extension given?
        inc a
        jr z,cio_try_extensions         ; yes: try the default extensions
        call ix_in_header               ; an extension was given (not observed): IX = input header
        ld (ix+#00),#FF                 ; access mode &FF
        call search_first               ; search the file
        jp z,error_not_found            ; not there: "<name> wurde nicht gefunden"
        jr cio_found
cio_try_extensions:
        ld a,#0C                        ; extension index 12, counted down by 3: 9 "   ", 6 BAS, 3 BIN, 0 BAK
cio_next_extension:
        sub #03                         ; next extension
        push af
        call set_extension              ; put it into the name FCB
        push de
        call search_first               ; is there such a file?
        pop de
        jr nz,cio_found_drop            ; found
        pop af
        jr nz,cio_next_extension        ; not found: next extension, until BAK was tried
        call set_ext_blank              ; none found: blank extension again for the message ...
        jp error_not_found              ; ... "<name> wurde nicht gefunden"
cio_found_drop:
        pop af                          ; drop the extension index
cio_found:
        ld hl,#0025                     ; found: name FCB ...
        ld de,#0045                     ; ... into the input FCB:
        ld b,#24                        ; clear its 36 bytes, copy drive, name, extension
        call copy_name_iy
        call open_file                  ; open the file (directory entry -> input FCB)
        pop de                          ; DE = the 2K buffer
        call init_in_header             ; set up the input header (type ASCII, length unknown)
        ld de,#00E0                     ; read the first record ...
        call workspace_offset           ; ... into the record buffer workspace+&E0
        push de
        call read_record_in
        pop hl                          ; HL = record buffer
        jr nz,cio_return                ; empty file: no header
        ld b,#43                        ; checksum of its first &43 bytes ...
        call checksum
        ld a,(hl)                       ; ... compared with the word at +&43
        inc hl
        ld h,(hl)
        ld l,a
        call sub_de_hl
        jr nz,cio_no_header             ; wrong: an ASCII file without header
        ld de,#0092                     ; right: copy the header's first &1C bytes (user .. entry) ...
        ld hl,#00E0
        call de_hl_add_iy
        ld bc,#001C
        ldir                            ; ... to input header+&05
        ld de,#0024                     ; record +&40..+&42 ...
        add hl,de
        ld a,(hl)                       ; ... = 24-bit file length -> bytes left
        ld (ix+#21),a
        inc hl
        ld a,(hl)
        ld (ix+#22),a
        inc hl
        ld a,(hl)
        ld (ix+#23),a
        jr cio_return
cio_no_header:
        ld (iy+#65),#00                 ; no header: current record 0 again - the first record is data
cio_return:
        ld hl,#0092                     ; return the header address ...
        call iy_offset_hl
        ld e,(ix+#1A)                   ; ... DE = load address
        ld d,(ix+#1B)
        ld c,(ix+#1D)                   ; BC = length
        ld b,(ix+#1E)
        scf                             ; CY = 1, Z = 0: ok
        sbc a,a
        ld a,(ix+#17)                   ; A = file type
        ret
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_in_direct [#D3CD]
; Tasks:        CAS IN DIRECT: read the whole (rest of the) file to memory. Reads the full
;               records straight to the destination, the last part record through the
;               record buffer. Error if the file was read with CAS IN CHAR.
; Input:        HL = destination
; Output:       CY = 1: HL = entry address; CY = 0: A = error
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS IN DIRECT &BC83), observed with LOAD
; Calls:        in_check_open, shift_hl_right, read_records; falls through into cas_ok
vdos_cas_in_direct:
        call in_check_open              ; IX = input header; error if no input file
        ld a,(ix+#00)                   ; access mode
        cp #01                          ; char access already?
        jp z,error_not_open             ; yes: error &0E
        ld (ix+#00),#02                 ; access mode 2: direct
        ld e,(ix+#21)                   ; DE = bytes left
        ld d,(ix+#22)
        push de
        push hl                         ; keep the destination
        ex de,hl
        ld c,#07                        ; / 128 ...
        call shift_hl_right
        ld c,l                          ; ... BC = number of full records
        ld b,h
        pop de                          ; DE = destination
        call read_records               ; read them straight there
        pop hl                          ; HL = bytes left
        jr nc,cid_return_entry          ; read error / end: done
        ld a,l                          ; bytes in the last part record
        and #7F
        jr z,cid_return_entry           ; none
        push af
        push de
        ld de,#00E0                     ; read the last record into the record buffer ...
        call workspace_offset
        push de
        ld bc,#0001                     ; ... one record
        call read_records
        pop hl
        pop de
        pop bc                          ; B = bytes of it
        jr nc,cid_return_entry
        ld c,b                          ; copy that part to the end of the destination
        ld b,#00
        ldir
cid_return_entry:
        ld l,(ix+#1F)                   ; HL = entry address
        ld h,(ix+#20)
; Subroutine: cas_ok [#D417] - common success exit of the CAS routines: CY = 1, Z = 0, A = &FF.
; Changed:      AF
; Entered from: vdos_cas_in_direct (falls through)
cas_ok:
        scf                             ; CY = 1 ...
        sbc a,a                         ; ... A = &FF, Z = 0
        ret
; ----------------------------------------------------------------------
; Subroutine: read_records [#D41A]
; Tasks:        Read BC records of the input file to DE (128 bytes each); protected files
;               (type bit 0) are decoded with crypt_record (not observed).
; Input:        BC = records, DE = destination, IX = input header; IY = VDOS workspace
; Output:       CY = 1: all read, DE after them; else NC/NZ at the end of the file, BC = records not read
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_in_direct, in_char_get
; Calls:        read_record_in, crypt_record
read_records:
        ld a,b                          ; no more records?
        or c
        scf
        ret z                           ; yes: CY = 1, done
        call read_record_in             ; read the next record to DE
        ret nz                          ; end of file: return (BC = records not read)
        bit 0,(ix+#17)                  ; protected file?
        call nz,crypt_record            ; yes: decode the record
        ld hl,#0080                     ; next 128 bytes
        add hl,de
        ex de,hl
        dec bc
        jr read_records
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_in_char [#D431]
; Tasks:        CAS IN CHAR: read the next character. If eof_test_1a (&BE7C) is not 0
;               (|DERROR,2), &1A (CP/M end of file mark) also ends the file (CY = 0). With 0
;               (|DERROR,3, default) only the physical end counts, so MERGE of a BASIC
;               program cannot stop at a byte &1A, but an ASCII file returns the &1A padding
;               of its last record (manual appendix "Das EOF Problem"). Programs written for AMSDOS
;               expect &1A to end the file (AMSDOS always tests it).
;               Observed both: TD (2 lines in 1 record) gave 117 extra characters with 0 and
;               stopped at &1A with &FF (set by POKE).
; Output:       CY = 1: A = character; CY = 0: end of file (A = &0F) or error
; Changed:      AF, IX, IY
;               (observed with marker registers: IX = input header (&A78D), BC, DE, HL kept;
;               programs written for the firmware manual expect only A to change)
; Called by:    cas_jump_table (CAS IN CHAR &BC80), vdos_cas_test_eof
; Calls:        in_char_get
vdos_cas_in_char:
        push bc                         ; keep BC, DE, HL
        push de
        push hl
        call in_char_get                ; A = next character
        pop hl
        pop de
        pop bc
        ret nc                          ; end of file or error: return it
        push af
        ld a,(eof_test_1a)              ; &1A test on?
        or a
        jr z,cic_return                 ; no (as observed): return the character
        pop af                          ; (not observed) the character ...
        cp #1A                          ; ... &1A?
        scf
        ret nz                          ; no: CY = 1, the character
        or a                            ; yes: end of file (CY = 0)
        ret
cic_return:
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: in_char_get [#D44B]
; Tasks:        Next character from the 2K buffer; refills it with up to 16 records when it
;               is empty. Counts the 24-bit bytes-left counter down.
; Output:       CY = 1: A = character; CY = 0, A = &0F: end of file
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    vdos_cas_in_char
; Calls:        in_check_open, read_records; error_not_open
in_char_get:
        call in_check_open              ; IX = input header; error if no input file
        ld a,(ix+#00)                   ; access mode
        cp #02                          ; direct access already?
        jp z,error_not_open             ; yes: error &0E
        ld (ix+#00),#01                 ; access mode 1: char
        ld a,(ix+#21)                   ; any bytes left?
        or (ix+#22)
        or (ix+#23)
        jr z,icg_end_of_file            ; no: end of file
        ld a,(ix+#18)                   ; bytes still in the buffer?
        ld l,a
        ld h,(ix+#19)
        or h
        jr nz,icg_take_char             ; yes: take the next one
        ld e,(ix+#01)                   ; empty: refill the buffer from its start
        ld d,(ix+#02)
        ld (ix+#03),e                   ; next char = buffer start
        ld (ix+#04),d
        ld bc,#0010                     ; up to 16 records (2K)
        call read_records
        ld a,#10                        ; records read = 16 - not read ...
        sub c
        ld h,a                          ; ... * 128 = bytes in the buffer
        ld l,#00
        srl h
        rr l
        ld (ix+#18),l
        ld (ix+#19),h
        ld a,l                          ; nothing read?
        or h
        jr z,icg_end_of_file            ; yes: end of file
icg_take_char:
        dec hl                          ; one byte less in the buffer
        ld (ix+#18),l
        ld (ix+#19),h
        ld hl,#00AE                     ; bytes left of the file (24 bit) ...
        call iy_offset_hl
        ld b,#03
icg_count_down:
        ld a,(hl)                       ; ... - 1
        sub #01
        ld (hl),a
        jr nc,icg_read_char             ; no borrow: done
        inc hl
        djnz icg_count_down
icg_read_char:
        scf                             ; CY = 1
        sbc a,a
        ld l,(ix+#03)                   ; HL = next char
        ld h,(ix+#04)
        rst #20                         ; RAM LAM; read it from RAM (the ROMs are paged in)
        inc hl                          ; pointer + 1
        ld (ix+#03),l
        ld (ix+#04),h
        ret
icg_end_of_file:
        ld a,#0F                        ; end of file: A = &0F, CY = 0
        or a
        ret
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_test_eof [#D4C2]
; Tasks:        CAS TEST EOF: read the next character (vdos_cas_in_char). End of file: return
;               its flags. Else fall through into vdos_cas_return, which puts the character
;               back - the next CAS IN CHAR reads it again. Only the flags count. Observed with
;               BASIC's EOF (every EOF that is not yet the end runs vdos_cas_return).
; Input:        IY = VDOS workspace (set by cas_dispatcher); no parameters
; Output:       CY = 1: not the end yet (A = the character; the firmware says A corrupt);
;               CY = 0: end of file (A = &0F) or error, as vdos_cas_in_char returns it
;               IX = input header (workspace+&8D)
; Changed:      AF, IX, IY
; Called by:    cas_jump_table (CAS TEST EOF &BC89), observed with EOF
; Calls:        vdos_cas_in_char; falls through into vdos_cas_return
vdos_cas_test_eof:
        call vdos_cas_in_char           ; read the next character
        ret nc                          ; end of file: NC; a character was read: fall through into vdos_cas_return - put it back
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_return [#D4C6]
; Tasks:        CAS RETURN: put the last character read by CAS IN CHAR back, so that the next
;               CAS IN CHAR returns it again. Nothing is stored and no character is passed:
;               the character is still in the 2K buffer, so the routine only undoes the three
;               counters that in_char_get moved for it, in the input header (IX):
;               IX+&21..&23 bytes left in the file (24 bit) + 1   (inc_byte_count)
;               IX+&03/&04  pointer to the next character - 1     (back onto the character)
;               IX+&18/&19  bytes left in the buffer + 1
;               No checks: no open test and no test that a character was read; by the code a
;               second RETURN in a row would step back over the character before it (not
;               tested; the firmware allows only one).
;               Its main user is CAS TEST EOF: vdos_cas_test_eof falls through into it whenever
;               a character could be read, so it runs at every BASIC EOF that is not yet the
;               end (observed). Through &BC86 directly only from machine code (observed:
;               READ.ME, CAS IN CHAR twice = CR LF, CAS RETURN, CAS IN CHAR = LF again).
;               VDOS leaves IX pointing at the input header (observed: IX &1234 before, &A78D
;               after). Programs written for the firmware manual expect "All registers and
;               flags preserved".
; Input:        IY = VDOS workspace (set by cas_dispatcher; used by workspace_offset)
;               AF = only passed through: entered from vdos_cas_test_eof it holds the result
;               of vdos_cas_in_char (CY = 1, A = the character just read)
; Output:       IX = input header (workspace+&8D) - a side effect, not restored
;               AF, BC, DE, HL, IY = as on entry (observed); from vdos_cas_test_eof AF is the
;               result of CAS TEST EOF (CY = 1: not the end, A = the character)
;               Input header: pointer to the next character - 1, both counters + 1
; Changed:      IX
; Entered from: vdos_cas_test_eof (falls through), cas_jump_table (CAS RETURN &BC86)
; Calls:        workspace_offset, inc_byte_count
vdos_cas_return:
        push af                         ; keep AF (from vdos_cas_test_eof: vdos_cas_in_char's result, CY = 1, A = character), DE, HL; BC is not used
        push de
        push hl
        ld de,#008D                     ; offset of the input header in the workspace (no open check here) ...
        call workspace_offset           ; ... DE = workspace+&8D (&A78D) ...
        push de                         ; ... into IX (not restored at the end)
        pop ix
        call inc_byte_count             ; bytes left in the file (IX+&21..&23) + 1: undo in_char_get's count-down
        ld e,(ix+#03)                   ; DE = pointer to the next character (IX+&03/&04) ...
        ld d,(ix+#04)
        dec de                          ; ... - 1: back onto the character just read (it is still in the buffer) ...
        ld (ix+#03),e                   ; ... stored: the next CAS IN CHAR reads it again
        ld (ix+#04),d
        inc (ix+#18)                    ; bytes left in the buffer (IX+&18/&19) + 1 ...
        jr nz,cr_done
        inc (ix+#19)                    ; ... (carry into the high byte)
cr_done:
        pop hl                          ; HL, DE, AF back: the caller sees no change in them (nothing is returned)
        pop de
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_in_close [#D4EE]
; Tasks:        CAS IN CLOSE: close the input file (nothing to write back); also switches the motors off.
; Output:       CY = 1: ok
; Changed:      AF, DE, HL, IX, IY
;               (observed with marker registers: DE (&BE00), HL (&ABC3) and IX (input header
;               &A78D) changed; programs written for the firmware manual expect only A to change)
; Called by:    cas_jump_table (CAS IN CLOSE &BC7A), observed with LOAD/CLOSEIN
; Calls:        in_check_open, motors_off_now; falls through into vdos_cas_in_abandon
vdos_cas_in_close:
        call in_check_open              ; error if no input file
        call motors_off_now             ; motors off now
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_in_abandon [#D4F4]
; Tasks:        CAS IN ABANDON: forget the input file (input FCB drive byte = &FF).
; Input:        IY = VDOS workspace
; Output:       CY = 1
; Changed:      AF
; Called by:    cas_jump_table (CAS IN ABANDON &BC7D), vdos_cas_in_close; observed (BASIC calls it before CAT, LOAD ...)
vdos_cas_in_abandon:
        ld (iy+#45),#FF                 ; input FCB closed
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_out_open [#D4FB]
; Tasks:        CAS OUT OPEN: open a file for output. The data is written to <name>.$$$;
;               vdos_cas_out_close renames it to the real name (and an old file to .BAK).
; Input:        B = length of the name, HL = name, DE = 2K buffer; IY = VDOS workspace
; Output:       CY = 1: HL = header (+&05 of the output header); CY = 0: A = error
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS OUT OPEN &BC8C), observed with SAVE/OPENOUT
; Calls:        out_open_check, parse_filename, copy_name, init_out_header, set_ext_temp, delete_file, make_file
; RAM:          Workspace (IY = &A700) fields of the CAS layer:
;               +&05 current user, +&06 default drive, +&23/24 SP for an error exit,
;               +&25 name FCB (32 bytes: drive, name, ext; filled by parse_filename),
;               +&45 input FCB, +&69 output FCB (36-byte CP/M FCBs; byte 0 = drive, &FF = closed),
;               +&8D input header, +&B3 output header (IX), +&E0 128-byte record buffer.
vdos_cas_out_open:
        call out_open_check             ; IX = output header; error if an output file is open
        push de                         ; keep the buffer address
        call parse_filename             ; name -> name FCB
        jp c,error_bad_name             ; bad name: "Eingabefehler"
        ld hl,#0069                     ; output FCB ...
        call iy_offset_hl
        ex de,hl
        ld b,#24                        ; ... cleared (36 bytes), drive, name, extension copied from the name FCB
        call copy_name
        ex de,hl
        ex (sp),hl                      ; stack: output FCB, HL = buffer
        ex de,hl
        call init_out_header            ; set up the output header
        pop de                          ; DE = output FCB
        call set_ext_temp               ; extension "$$$": write to a temporary file
        call ix_out_header              ; IX = output header
        ld (ix+#00),#FF                 ; access mode &FF
        call delete_file                ; delete an old <name>.$$$ (observed: the empty S1.$$$ left by a failed SAVE was removed, the directory then had a single S1.BAS)
        call make_file                  ; create <name>.$$$ (directory full: error - observed with the 65th file)
        ld hl,#00B8                     ; return the header address
        call iy_offset_hl
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_out_abandon [#D531]
; Tasks:        CAS OUT ABANDON: forget the output file (nothing is written; the .$$$ file stays).
; Output:       CY = 1
; Changed:      AF, IX, IY
;               (observed with marker registers: BC, DE, HL kept, IX = output header (&A7B3);
;               programs written for the firmware manual expect IX to be kept)
; Called by:    cas_jump_table (CAS OUT ABANDON &BC92), vdos_cas_out_close; observed
vdos_cas_out_abandon:
        call out_check_open             ; error if no output file
out_mark_closed:
        ld (iy+#69),#FF                 ; output FCB closed
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_out_close [#D53B]
; Tasks:        CAS OUT CLOSE: write the rest of the buffer, close the file, give a name
;               without extension one by type (BASIC .BAS, binary .BIN, else none), write the
;               header record (not for ASCII files, type &x6), rename .$$$ to the name.
;               Nothing written: like CAS OUT ABANDON.
; Input:        IY = VDOS workspace
; Output:       CY = 1: ok
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS OUT CLOSE &BC8F), observed with SAVE/CLOSEOUT
; Calls:        out_check_open, out_flush_buffer, close_file, set_ext_bas/bin/blank, out_write_header, out_rename
vdos_cas_out_close:
        call ix_out_header              ; IX = output header
        ld a,(ix+#21)                   ; anything written?
        or (ix+#22)                     ; any bytes written? (24-bit count)
        or (ix+#23)                     ; (...)
        jr z,vdos_cas_out_abandon       ; no: just abandon
        call out_check_open             ; error if no output file
        call out_flush_buffer           ; write the rest of the buffer
        ld de,#0069                     ; close the output FCB
        call workspace_offset           ; the output FCB ...
        call close_file                 ; ... closed
        ld de,#00B8                     ; DE = header +&05 (user, name)
        call workspace_offset           ; the name FCB
        ld b,(ix+#17)                   ; B = file type
        ld a,(ix+#0E)                   ; extension given (first byte not &FF)?
        inc a                           ; (extension &FF + 1 = 0)
        jr nz,coc_header_and_rename     ; yes: keep it
        ld a,b                          ; no: by type
        and #0E                         ; file type bits 3-1 (0 = BASIC) ...
        jr nz,coc_not_basic             ; type 0 (BASIC) ...
        call set_ext_bas                ; ... .BAS
        jr coc_header_and_rename
coc_not_basic:
        cp #02                          ; ... 1 = binary?
        jr nz,coc_no_extension          ; binary?
        call set_ext_bin                ; (not observed) .BIN
        jr coc_header_and_rename
coc_no_extension:
        call set_ext_blank              ; anything else: no extension
coc_header_and_rename:
        ld a,b                          ; file type ...
        and #0F                         ; type &x6 (ASCII) ...
        cp #06                          ; ... ASCII (&x6)?
        call nz,out_write_header        ; ... has no header record, the others get one
        call out_rename                 ; .$$$ -> the real name (an old file -> .BAK)
        jp out_mark_closed              ; output FCB closed, ok
; ----------------------------------------------------------------------
; Subroutine: out_write_header [#D58B]
; Tasks:        Write the AMSDOS header as record 0 of the (closed) output file: reopen
;               it from its first extent, build the 128-byte header (&1C bytes of the output
;               header, 24-bit length at +&40, checksum of &43 bytes at +&43), write it over the
;               place holder record and close the file again.
; Input:        IX = output header; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_out_close
; Calls:        open_file, checksum, write_record_out, close_file
out_write_header:
        ld de,#0069                     ; output FCB ...
        call workspace_offset           ; output FCB
        push de
        ld hl,#000C                     ; ... from +&0C (extent, counts, blocks) ...
        add hl,de
        ex de,hl
        ld b,#18                        ; ... cleared: back to the first extent
        call clear_memory               ; cleared
        pop de
        push de
        call open_file                  ; open it again
        ld de,#00E0                     ; DE = record buffer, HL = output header +&05
        ld hl,#00B8                     ; output header+5 ...
        call de_hl_add_iy               ; ... into the record
        push de
        ld b,#43                        ; clear the first &43 bytes
        call clear_memory               ; (the rest of the record cleared)
        pop de
        push de
        ld bc,#001C                     ; copy user .. entry address (&1C bytes)
        ldir                            ; copy &1C bytes
        ld hl,#0024                     ; +&40: length (24 bit, written as 2 bytes + the cleared third)
        add hl,de
        ld a,(ix+#21)                   ; file length: bytes 0 ...
        ld (hl),a
        inc hl
        ld a,(ix+#22)                   ; ... 1 ...
        ld (hl),a
        inc hl
        pop hl                          ; checksum of bytes 0..&42 ...
        push hl
        ld b,#43                        ; checksum of &43 bytes ...
        call checksum                   ; (...)
        ld (hl),e                       ; ... stored at +&43
        inc hl
        ld (hl),d                       ; ... at +&43/&44
        pop de                          ; DE = output FCB
        call write_record_out           ; write record 0 (the current record is 0 after the reopen)
        pop de
        jp close_file                   ; close the file again
; ----------------------------------------------------------------------
; Subroutine: out_rename [#D5D7]
; Tasks:        Rename <name>.$$$ to the name in the output header. If <name> exists it
;               becomes <name>.BAK first; an old .BAK is deleted (observed: SAVE "TB" three times
;               leaves TB.BAS and TB.BAK). If the old <name> is R/O, the rename to .BAK fails
;               with "<name> hat Schreibschutz" (check_rodir) and <name>.$$$ stays on the disc
;               next to the untouched old file (observed: SAVE "RO" over an R/O RO.BAS).
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_out_close
; Calls:        copy_name_iy, search_first, rename_fcb, set_ext_bak, delete_file, rename_file, set_ext_temp
out_rename:
        ld hl,#00B8                     ; name FCB = drive, name, extension from the output header ...
        ld de,#0025                     ; name FCB
        ld b,#20                        ; 32 bytes
        call copy_name_iy               ; = name from the output header
        push de
        ld a,(iy+#69)                   ; ... with the drive of the output FCB
        ld (iy+#25),a                   ; drive byte
        call search_first               ; does <name> exist?
        jr z,or_rename                  ; no: just rename
        pop de                          ; yes (observed: SAVE of an existing name): <name> -> <name>.BAK; an R/O <name> stops here with "hat Schreibschutz" in rename_file (observed), <name>.$$$ stays
        push de
        call rename_fcb                 ; second half of the FCB = <name>
        call set_ext_bak                ; first half -> .BAK
        ld a,(iy+#25)                   ; delete an old <name>.BAK ...
        ld (iy+#35),a                   ; (FCB byte 16 = new name's drive byte)
        call delete_file                ; delete <name>.BAK
        ld (iy+#35),#00                 ; (byte 16 cleared again)
        call rename_file                ; ... and rename <name> to it
or_rename:
        pop de                          ; name FCB: <name> (from the output header)
        push de
        call rename_fcb                 ; second half (the new name) = <name>
        pop de
        call set_ext_temp               ; first half (the old name) = <name>.$$$ ...
        jp rename_file                  ; ... renamed to <name>
; ----------------------------------------------------------------------
; Subroutine: rename_fcb [#D612]
; Tasks:        Copy the 16 bytes at DE to DE+16 (new name for the BDOS rename) and clear the byte after them.
; Input:        DE = name FCB
; Output:       DE = name FCB
; Changed:      AF, BC, DE, HL
; Called by:    out_rename
rename_fcb:
        call copy_fcb_half              ; DE+16 = the 16 bytes at DE
        xor a                           ; byte after the new name = 0
        ex de,hl
        ld (de),a                       ; byte after them = 0
        ret
; ----------------------------------------------------------------------
; Subroutine: copy_fcb_half [#D619]
; Tasks:        Copy 16 bytes from DE to DE+16.
; Input:        DE
; Output:       HL = DE+16, DE = DE+32
; Changed:      BC, DE, HL, F
; Called by:    rename_fcb
copy_fcb_half:
        ld hl,#0010                     ; DE + 16 ...
        add hl,de
        ex de,hl
        ld bc,#0010                     ; 16 bytes
        ldir                            ; copy
        ret
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_out_direct [#D624]
; Tasks:        CAS OUT DIRECT: write a memory area as the file's data. Sets type, address,
;               length and entry in the header, then writes it all (out_flush_buffer with the
;               area as the "buffer").
; Input:        HL = address, DE = length, BC = entry address, A = file type
; Output:       CY = 1: ok
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS OUT DIRECT &BC98), observed with SAVE
; Calls:        out_check_open, out_flush_buffer; falls through into out_flush_buffer
vdos_cas_out_direct:
        call out_check_open             ; IX = output header; error if no output file
        push af
        ld a,(ix+#00)                   ; access mode
        cp #01                          ; char access already?
        jp z,error_not_open             ; yes: error &0E
        ld (ix+#00),#02                 ; access mode 2: direct
        pop af
        ld (ix+#17),a                   ; file type
        ld (ix+#01),l                   ; the area is the "buffer" ...
        ld (ix+#02),h                   ; buffer = the area
        ld (ix+#1A),l                   ; ... and the load address
        ld (ix+#1B),h                   ; load address
        ld (ix+#1F),c                   ; entry address
        ld (ix+#20),b                   ; entry address
        ld (ix+#18),e                   ; bytes "in the buffer" = length
        ld (ix+#19),d                   ; (bytes in the buffer = length)
        ld (ix+#1D),e                   ; length
        ld (ix+#1E),d                   ; logical length
        ld (ix+#21),e                   ; bytes written = length
        ld (ix+#22),d                   ; byte count (24 bit, high byte 0)
; ----------------------------------------------------------------------
; Subroutine: out_flush_buffer [#D65C]
; Tasks:        Write the bytes in the output buffer to the file. Before the first data a
;               place holder record is written for the header (not for ASCII files). Full
;               records are written straight; a part record goes through the record buffer
;               with ONE &1A after the data - the rest of that record is not filled, it keeps
;               whatever the record buffer held before (observed: an 80K ASCII file on drive B
;               ended with &1A "=0" CR LF "50 WHILE NOT E"). Readers that stop at &1A (CP/M,
;               |DERROR,2) see the right end; with the default (|DERROR,3) BASIC reads the rest
;               of the record as extra lines (observed: 1202 lines instead of 1200).
;               Then the buffer is empty again.
; Input:        IX = output header; IY = VDOS workspace
; Output:       CY = 1
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_out_char (buffer full), vdos_cas_out_close; entered from vdos_cas_out_direct
; Calls:        write_record_out, shift_hl_right, write_records, KL_LDIR
out_flush_buffer:
        bit 7,(ix+#1C)                  ; first write?
        jr z,ofb_write_buffer           ; no
        ld a,(ix+#17)                   ; ASCII file (type &x6)?
        and #0F                         ; file type ...
        cp #06                          ; ... ASCII?
        jr z,ofb_write_buffer           ; yes: no header
        call write_record_out           ; write a place holder for the header (record 0)
ofb_write_buffer:
        ld e,(ix+#18)                   ; DE = bytes in the buffer
        ld d,(ix+#19)                   ; bytes in the buffer
        ld l,(ix+#01)                   ; HL = buffer
        ld h,(ix+#02)                   ; buffer start
        push hl
        push de
        ex de,hl
        ld c,#07                        ; / 128 = full records
        call shift_hl_right             ; / 128 = full records
        ld c,l                          ; BC = records
        ld b,h
        call write_records              ; write them
        pop bc                          ; bytes ...
        ld a,c                          ; ... in the last part record
        and #7F                         ; bytes of the part record
        jr z,ofb_buffer_empty           ; none
        ld c,a                          ; BC = them
        ld b,#00
        ld hl,#00E0                     ; copy them to the record buffer (KL LDIR: from RAM under the ROMs) ...
        call iy_offset_hl               ; record buffer
        push hl
        ex de,hl
        call KL_LDIR                    ; copy the part (RAM)
        ld a,#1A                        ; ... followed by ONE &1A (end of file mark)
        ld (de),a                       ; only this byte: the rest of the record keeps the old contents of the record buffer (observed: 80K file on B: - after the &1A came "=0" CR LF "50 WHILE NOT E"; read back without the &1A test (|DERROR,3) these became two extra lines)
        pop de
        inc bc                          ; one record
        call write_records              ; write it
ofb_buffer_empty:
        pop hl                          ; the buffer is empty again:
        ld (ix+#18),#00                 ; 0 bytes in it
        ld (ix+#19),#00                 ; buffer empty
        ld (ix+#1C),#00                 ; first write done
        ld (ix+#03),l                   ; next char = buffer start
        ld (ix+#04),h                   ; char pointer = buffer start
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: write_records [#D6B9]
; Tasks:        Write BC records from DE to the output file; protected files are coded first (crypt_record, not observed).
; Input:        BC = records, DE = data, IX = output header; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    out_flush_buffer
; Calls:        KL_LDIR, crypt_record, write_record_out
write_records:
        ld a,b                          ; no more records?
        or c                            ; (BC = 0: done)
        ret z                           ; yes: done
        push de
        bit 0,(ix+#17)                  ; protected file?
        jr z,wr_write_one               ; no (as observed)
        push bc                         ; (not observed) copy the record to the record buffer ...
        ld hl,#00E0                     ; record buffer ...
        call iy_offset_hl
        push hl
        ex de,hl
        ld bc,#0080                     ; 128 bytes
        call KL_LDIR                    ; copy the record there (RAM, the ROMs are paged in)
        pop de
        pop bc
        call crypt_record               ; ... and code it there
wr_write_one:
        call write_record_out           ; write the record at DE
        pop de
        ld hl,#0080                     ; next 128 bytes
        add hl,de                       ; next 128 bytes
        ex de,hl
        dec bc
        jr write_records                ; next record
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_out_char [#D6E3]
; Tasks:        CAS OUT CHAR: put a character into the 2K buffer; a full buffer is written first.
; Input:        A = character
; Output:       CY = 1: ok
; Changed:      AF, IX, IY
; Called by:    cas_jump_table (CAS OUT CHAR &BC95), observed with PRINT#9
; Calls:        out_check_open, out_flush_buffer, inc_byte_count
vdos_cas_out_char:
        call out_check_open             ; IX = output header; error if no output file
        push hl                         ; keep HL, DE, BC and the character
        push de
        push bc
        push af
        ld a,(ix+#00)                   ; access mode
        cp #02                          ; direct access already?
        jp z,error_not_open             ; yes: error &0E
        ld (ix+#00),#01                 ; access mode 1: char
        ld l,(ix+#18)                   ; bytes in the buffer ...
        ld h,(ix+#19)                   ; bytes in the buffer
        ld bc,#F800                     ; ... >= &800 (2K)?
        add hl,bc                       ; + &F800: CY when 2K are full
        call c,out_flush_buffer         ; yes: write it out first
        inc (ix+#18)                    ; one byte more in the buffer
        jr nz,coc_store                 ; not full
        inc (ix+#19)                    ; (high byte + 1)
coc_store:
        call inc_byte_count             ; one byte more written
        ld l,(ix+#03)                   ; HL = next char
        ld h,(ix+#04)                   ; char pointer
        pop af                          ; store the character
        ld (hl),a                       ; store the character
        inc (ix+#03)                    ; pointer + 1
        jr nz,coc_done                  ; (pointer + 1)
        inc (ix+#04)                    ; (high byte)
coc_done:
        pop bc
        pop de
        pop hl
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: rsx_cas / rsx_cas_in / rsx_cas_out [#D724 / #D727 / #D73D]
; Tasks:        |CAS (= |TAPE): both channels to the cassette; |CAS.IN (= |TAPE.IN): the 7 input
;               entries CAS IN OPEN .. CAS TEST EOF and CAS CATALOG; |CAS.OUT (= |TAPE.OUT): the
;               5 output entries CAS OUT OPEN .. CAS OUT DIRECT. They copy the original (tape)
;               jumpblock entries back from workspace+&164 (in, 21 bytes), +&188 (catalog, 3)
;               and +&179 (out, 15). With AMSDOS that is AMSDOS's own saved copy at the same
;               offset; without AMSDOS rom_init saved it there. Parameters are ignored.
;               Observed: the jumpblock after every command (CF xx xx = RST 1 into the OS tape
;               code; CATALOG follows the input channel); |CAS:CAT -> "Press PLAY then any key:"
;               (ESC: Ready); |CAS.OUT:SAVE -> "Press REC and PLAY then any key:"; |TAPE,
;               |TAPE.IN, |TAPE.OUT = the same routines (rom_jumpblock). As in the manual (2.0),
;               which does not list |TAPE...
; Input:        A = number of parameters (ignored)
; Changed:      AF, BC, DE, HL; IY = VDOS workspace
; Called by:    RSX "CAS", "CAS.IN", "CAS.OUT", "TAPE", "TAPE.IN", "TAPE.OUT" (rom_jumpblock)
; Calls:        restore_tape_entries
rsx_cas:
        call rsx_cas_out                ; |CAS: the output channel first ...
rsx_cas_in:
        ld hl,#0164                     ; ... then the input channel: from workspace+&164 ...
        ld de,CAS_IN_OPEN               ; ... to CAS IN OPEN ...
        ld bc,#0015                     ; ... 7 entries (21 bytes)
        call restore_tape_entries
        ld hl,#0188                     ; CAS CATALOG from workspace+&188 (it follows the input channel)
        ld de,CAS_CATALOG
        ld c,#03                        ; 1 entry
        jr restore_tape_entries
rsx_cas_out:
        ld hl,#0179                     ; output: from workspace+&179 ...
        ld de,CAS_OUT_OPEN              ; ... to CAS OUT OPEN ...
        ld bc,#000F                     ; ... 5 entries (15 bytes)
restore_tape_entries:
        call load_workspace_iy          ; IY = VDOS workspace
        call iy_offset_hl               ; HL = workspace + offset: the saved entries
        ldir                            ; copy them into the CAS jumpblock (observed: CF 92 A3 ... = tape)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_disc / rsx_disc_in / rsx_disc_out [#D74F / #D752 / #D760]
; Tasks:        |DISC: both channels to the disc; |DISC.IN: the 7 input entries and CAS CATALOG;
;               |DISC.OUT: the 5 output entries. Each entry becomes RST 3 / defw workspace+&18B
;               (DF 8B A8: FAR CALL through the far address that points to cas_dispatcher).
;               Parameters are ignored. Observed: the jumpblock after every command; |DISC:CAT
;               lists drive A again. rom_init without AMSDOS uses rsx_disc too.
; Input:        A = number of parameters (ignored)
; Changed:      AF, B, DE, HL; IY = VDOS workspace
; Called by:    RSX "DISC", "DISC.IN", "DISC.OUT" (rom_jumpblock), rom_init (no AMSDOS)
; Calls:        set_disc_entries
rsx_disc:
        call rsx_disc_out               ; |DISC: the output channel first ...
rsx_disc_in:
        ld hl,CAS_IN_OPEN               ; ... then the input: from CAS IN OPEN ...
        ld b,#07                        ; ... 7 entries
        call set_disc_entries
        ld hl,CAS_CATALOG               ; CAS CATALOG ...
        inc b                           ; ... 1 entry (B = 0 after the loop)
        jr set_disc_entries
rsx_disc_out:
        ld hl,CAS_OUT_OPEN              ; output: from CAS OUT OPEN ...
        ld b,#05                        ; ... 5 entries
set_disc_entries:
        ld de,#018B                     ; far address block: workspace+&18B (&A88B) ...
        call load_workspace_iy          ; IY = VDOS workspace
        call workspace_offset           ; DE = &A88B
sde_loop:
        ld (hl),#DF                     ; RST 3 (FAR CALL) ...
        inc hl
        ld (hl),e                       ; ... defw &A88B (observed: DF 8B A8)
        inc hl
        ld (hl),d
        inc hl
        djnz sde_loop                   ; next entry
        ret
; Common end of |A / |B (set_default_drive): xpb_cache_drive = &FF, so the next access looks the
; drive tables up again. AF kept.
clear_xpb_cache:
        push af                         ; keep AF
        ld a,#FF                        ; &FF: no drive cached
        ld (xpb_cache_drive),a          ; xpb_cache_drive = &FF
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_a / rsx_b [#D780 / #D783]
; Tasks:        |A / |B: make drive A (0) / B (1) the default drive (iy+&06) and clear its login
;               byte (workspace+drive), so the next access to it logs it in again: the
;               directory is read and the allocation vector rebuilt (as after a disc change).
;               Parameters are ignored (no count check).
;               Observed: login bytes &A700/&A701 = FF FF; |A -> &A700 = 0, the next |DIR runs
;               the login (bdos_select_fcb_drive #DE61); |B -> &A706 = 1, |DIR lists B;
;               |A,5,"X" and |B,"Q" work like |A / |B. As in the manual (2.0).
; Input:        A = number of parameters (ignored)
; Output:       -
; Changed:      AF, HL; IY = VDOS workspace
; Called by:    RSX "A" / "B" (rom_jumpblock)
; Calls:        load_workspace_iy, add_a_hl; set_default_drive, clear_xpb_cache
rsx_a:
        xor a                           ; |A: drive 0
        jr set_default_drive            ; (on to set_default_drive)
rsx_b:
        ld a,#01                        ; |B: drive 1
set_default_drive:
        call load_workspace_iy          ; IY = VDOS workspace (also entered from |SELECT with a drive letter)
        ld (iy+#06),a                   ; default drive (iy+&06) = A (observed: &A706 = 1 after |B)
        push iy                         ; HL = workspace ...
        pop hl
        call add_a_hl                   ; ... + drive: the drive's login byte
        ld (hl),#00                     ; = 0: log the drive in again at its next access (observed with |A)
        jr clear_xpb_cache              ; xpb_cache_drive = &FF, return
; ----------------------------------------------------------------------
; Subroutine: rsx_dir [#D795]
; Tasks:        |DIR[,"name"]: list the directory entries of the current user that match the
;               name (default: all, "???????????") in directory order - not sorted and without
;               sizes, unlike CAT - in columns of 12 characters + 3 spaces, leaving out SYS
;               files, then the space line "<used>K in <n> Files, <free>K frei" (used / free =
;               the whole disc, n = the files listed). Only extent-0 entries are searched (dir_start
;               C = 0), so a file with several entries appears once. Page pause after 22 lines
;               (dir_next_line): ESC ends with the space line at once.
;               Observed (drive A, 26 files): |DIR (MODE 2: 5 columns), |DIR,"*.COM" (direct
;               string through basic_error_patch), |DIR,@a$, |DIR,"D*.CO?", |DIR,"NIX.*" (only
;               the space line, 0 Files), |DIR,"B:*.BAS" (drive B), SYS file hidden (|ATTRIBUT
;               S) and shown again (D), ROINTIME.DEM (2 entries) once, MODE 0 page pause + ESC
;               ("22 Files").
;               Errors (all "Eingabefehler", observed): two parameters (derr_count_check), a bad
;               name ("1:X"), a number (|DIR,5: taken as a descriptor address, no type check -
;               the error only comes from the bytes found there).
;               Differences to the manual (VDOS 2.0): the space line reads "119K in 22 Files,
;               50K frei" instead of "228K belegt, 4 Dateien, 480K frei".
; Input:        A = number of parameters (0 or 1), IX = parameters (string descriptor)
; Output:       CY = 1 (through dir_print_free / cas_ok)
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "DIR" (rom_jumpblock)
; Calls:        cas_entry, dir_start, dir_entry_address, print_message, dir_next_line, search_next, dir_print_free; falls through into dir_print_free
rsx_dir:
        call cas_entry                  ; IY, error SP
        ld bc,#0C00                     ; B = 12: entry width for dir_columns (name 8.3), C = 0: search extent 0 only - each file once (observed: ROINTIME.DEM with 2 entries listed once)
        call dir_start                  ; header line, first entry
        push bc                         ; B = columns, C = columns left in the row
rd_loop:
        jp z,dir_free_pop               ; no (more) entry: the space line
        call dir_entry_address          ; the entry found
        jr nz,rd_search_next            ; SYS file: skip
        inc (iy+#1E)                    ; one file more
        pop bc
        ld a,b                          ; first column of a row?
        cp c
        ld a,#22                        ; no: 3 spaces ...
        call nz,print_message
        call z,dir_next_line            ; yes: a new line
        ld a,#23                        ; the name (8.3 from the entry)
        call print_message
        dec c                           ; columns left in the row
        jr nz,rd_next
        ld c,b                          ; row full: all columns again
rd_next:
        push bc
rd_search_next:
        call search_next                ; next entry
        jr rd_loop                      ; loop
; End of |DIR and CAT: drop the column word and print the space line.
dir_free_pop:
        pop bc                          ; drop the column word
; ----------------------------------------------------------------------
; Subroutine: dir_print_free [#D7C5]
; Tasks:        Print "<used>K in <n> Files, <free>K frei": count the free blocks in the
;               allocation vector of the current drive (bdos_alv, DSM + 1 bits), used = all -
;               free - directory blocks (AL0/AL1), both converted from blocks to K with the
;               block shift (BSH - 3). <n> counts the listed entries, also an empty .$$$.
;               Display bug (observed): the bits are tested in the order 7, 0, 1, ..., 6 (rrc),
;               so in the last, part byte the wrong bits count. 3" system disc completely full
;               (ALV all 171 bits set, last byte &E0): bits 0 and 1 (no blocks) are taken as free
;               -> "167K in 5 Files, 2K frei" instead of 169K / 0K. Only the display is wrong;
;               get_block allocates by block number.
; Input:        C = number of files (iy+&1E); IY = VDOS workspace
; Output:       CY = 1 (cas_ok)
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_catalog, rsx_dir, dir_next_line (ESC)
; Calls:        shift_hl_left, print_message
dir_print_free:
        ld de,(dpb_dsm)                 ; DE = number of blocks (highest block + 1)
        inc de                          ; (+1 = blocks)
        ld hl,#0000                     ; free blocks = 0 ...
        push hl                         ; ... on the stack
        ld hl,(bdos_alv)                ; the allocation vector
dpf_next_byte:
        ld b,#08
        ld c,(hl)                       ; next 8 blocks
dpf_next_bit:
        ld a,d                          ; all blocks counted?
        or e
        jr z,dpf_to_k
        bit 7,c                         ; bit 7 = used?
        jr nz,dpf_rotate
        ex (sp),hl                      ; no: free + 1
        inc hl
        ex (sp),hl
dpf_rotate:
        rrc c                           ; next bit - rotated RIGHT: bits 7, 0, 1, ..., 6 are tested. Right for whole bytes, wrong for the last part byte (observed: full disc, last ALV byte &E0 = blocks 168-170 used, bits 0 and 1 counted -> "2K frei" instead of 0K)
        dec de                          ; one block less
        djnz dpf_next_bit               ; 8 bits of this byte
        inc hl                          ; next ALV byte
        jr dpf_next_byte
dpf_to_k:
        ld a,(dpb_bsh)                  ; block shift - 3 = shift from blocks to K
        sub #03
        ld c,a
        pop hl                          ; free blocks ...
        push hl
        push bc
        call shift_hl_left              ; ... in K
        pop bc
        ex (sp),hl                      ; free K on the stack, HL = free blocks
        push bc
        ex de,hl                        ; DE = free blocks
        ld hl,(dpb_dsm)                 ; all blocks ...
        inc hl
        or a
        sbc hl,de                       ; ... - free = used blocks
        push hl
        ld hl,(dpb_al)                  ; AL0/AL1: the directory's blocks
        ld bc,#1000                     ; B = 16 bits, C = count
dpf_dir_bits:
        bit 7,h                         ; directory block?
        jr z,dpf_dir_next
        inc c                           ; count it
dpf_dir_next:
        rl l                            ; next bit
        rl h
        djnz dpf_dir_bits               ; 16 bits
        pop hl                          ; used blocks ...
        or a
        sbc hl,bc                       ; ... - directory blocks
        pop bc
        call shift_hl_left              ; in K
        ex de,hl                        ; DE = used K
        ld c,(iy+#1E)                   ; C = number of files
        ld a,#39                        ; print "<CR><LF><CR><LF><DE>K in <C> Files, "
        call print_message
        pop de
        ld a,#24                        ; print "<DE>K frei<CR><LF><CR><LF>"
        call print_message
        jp cas_ok                       ; ok
; ----------------------------------------------------------------------
; Subroutine: dir_start [#D82A]
; Tasks:        Start of a directory listing (CAT and |DIR): page line counter 22, parse
;               the name parameter (none: "???????????" = all; more than one: "Eingabefehler"),
;               work out the number of columns from the window width and the caller's entry
;               width (B), put the caller's C into the extent byte of the search name (0 = only
;               extent-0 entries for |DIR, &3F = all extents for CAT), search the first entry,
;               print "Laufwerk X: User n". Observed with CAT and |DIR.
; Input:        A = number of parameters (0 or 1), IX = parameters; B = entry width (12 |DIR,
;               &11 CAT), C = extent to search (0 |DIR, &3F CAT); IY = VDOS workspace
; Output:       B = number of columns (on the stack for the caller), Z = no entry found;
;               (iy+&1E) = 0 files
; Changed:      AF, BC, DE, HL, IX
; Called by:    vdos_cas_catalog, rsx_dir
; Calls:        rsx_string_param, parse_filename_fcb, dir_columns, search_first, print_message; derr_count_check (error)
dir_start:
        ld (iy+#09),#16                 ; 22 lines until the page pause
        push bc
        or a                            ; a parameter?
        jr z,ds_no_name                 ; no
        dec a                           ; one parameter?
        jr nz,derr_count_check          ; more than one: "Eingabefehler" through derr_count_check in rsx_derror (observed: |DIR,"*.*","X")
        call rsx_string_param           ; one: its string descriptor - no type check: |DIR,5 takes &0005 as a descriptor (observed: "Eingabefehler" only because the bytes there happen to be a bad name)
        jr ds_parse
ds_no_name:
        ld b,#00                        ; no name: length 0
ds_parse:
        ld (iy+#1E),#00                 ; 0 files so far
        call parse_filename_fcb         ; name -> name FCB (observed: "1:X" -> Eingabefehler; "B:*.BAS" lists drive B)
        pop af                          ; A = the caller's B: entry width ...
        push af
        call dir_columns                ; ... number of columns from the window width (observed: MODE 2 |DIR = 5 columns, MODE 0 = 1)
        ld c,b                          ; C = columns
        pop hl                          ; L = the caller's C ...
        push bc
        ld (iy+#31),l                   ; ... = extent byte (FCB byte 12) of the search name: 0 (|DIR) or &3F = '?' (CAT)
        ld a,(iy+#26)                   ; name given?
        cp #20
        jr nz,ds_search                 ; yes
        ld de,rel_files_flag            ; no: name and extension = "???????????" (all)
        call workspace_offset
        ld b,#0B
        ld a,#3F
ds_wildcards:
        ld (de),a                       ; (the 11 bytes)
        inc de
        djnz ds_wildcards
ds_search:
        call search_first               ; search the first entry
        ld c,(iy+#25)                   ; C = drive, DE = user ...
        ld e,(iy+#05)                   ; E = current user
        ld d,#00
        ld a,#1E                        ; ... "<CR><LF>Laufwerk <drive>: User<DE><CR><LF>"
        call print_message
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: dir_entry_address [#D875]
; Tasks:        Address of the directory entry the last search found (directory record + 32 * code).
; Input:        IY = VDOS workspace
; Output:       HL = DE = entry; NZ = SYS attribute set (bit 7 of extension byte 2)
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_catalog, rsx_dir
dir_entry_address:
        ld a,(iy+#21)                   ; BDOS return code 0..3 = entry in the record ...
        rrca                            ; (...)
        rrca
        rrca
        and #60                         ; ... * 32
        ld hl,(bdos_dirbuf)             ; directory record buffer
        call add_a_hl
        ld e,l                          ; DE = entry
        ld d,h
        ld bc,#000A                     ; +&0A: second extension byte
        add hl,bc
        bit 7,(hl)                      ; bit 7 = SYS
        ret
; ----------------------------------------------------------------------
; Subroutine: dir_columns [#D88C]
; Tasks:        Number of columns of a listing: (right column of the text window + 4) /
;               (entry width + 3), at least 1. CAT: width &11 = 17 -> 2 columns in MODE 1, 1
;               in MODE 0, 4 in MODE 2 (observed in MODE 0 and 1); |DIR: 12 -> 2 in MODE 1.
; Input:        A = entry width
; Output:       B = columns
; Changed:      AF, DE, HL, B
; Called by:    dir_start
; Calls:        TXT_GET_WINDOW
dir_columns:
        add a,#03                       ; + 3: entry width with the gap
        push af
        call TXT_GET_WINDOW             ; D = right column of the window
        ld a,#04                        ; right + 4 ...
        add a,d
        pop hl
        ld b,#00                        ; ... divided by the width
dc_count:
        inc b
        sub h                           ; one column more fits?
        jr nc,dc_count
        dec b                           ; B = columns
        ret nz                          ; at least 1
        ld b,#01                        ; 0: not even one entry fits - one column anyway, the entries wrap (observed: WINDOW 1,8,1,25:CAT)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_derror [#D8A1]
; Tasks:        |DERROR[,n]: disc error and end of file settings (manual: "Abfangmoeglichkeiten
;               von Diskettenfehlern", appendix "Das EOF Problem"):
;               n = 0 / 1: messages_off = &FF / 0 (error messages and J/N questions off / on)
;               n = 2 / 3: eof_test_1a = &FF / 0 (&1A ends a file / only the physical end)
;               no parameter: DERR = the last CAS / disc error code (cas_last_error &BE82;
;               +&80 when the message was printed) - derr_variable builds the tokenized
;               BASIC 1.0 statement DERR=<code> in the record buffer and has BASIC run it.
;               Other n, more parameters, a string: "Eingabefehler".
;               Observed: |DERROR,0 + LOAD "NIX" -> no message, BASIC "File already open" (as
;               the manual says); |DERROR,1 + LOAD "NIX" -> "wurde nicht gefunden", |DERROR ->
;               DERR = 151 (23 + &80); the manual's ON ERROR GOTO example -> DERR = 23;
;               drive A empty + |DERROR,0 + CAT -> no dialog (ded_silent), DERR = 72 (&48 = FDC,
;               not ready); |DERROR,2 / 3 -> &BE7C = &FF / 0; 4, 256, -1, (1,2), "1" ->
;               Eingabefehler. As in the manual (2.0).
; Input:        A = number of parameters, IX = parameters; IY = VDOS workspace
; Output:       messages_off / eof_test_1a, or the BASIC variable DERR
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "DERROR" (rom_jumpblock); derr_count_check also from dir_start
; Calls:        cas_entry, rsx_param, record_buffer_de, BASIC &D654 (FAR CALL); error_bad_name
rsx_derror:
        or a                            ; no parameter: create the variable DERR (observed)
        jr z,derr_variable
        call cas_entry                  ; IY = workspace, error SP
        dec a                           ; exactly one parameter?
derr_count_check:
        jr nz,derr_bad_parameter        ; NZ (not exactly one parameter): "Eingabefehler"; also entered from dir_start with more than one parameter (observed)
        call rsx_param                  ; HL = its value
        or h                            ; must be below 256 (observed: 256, -1, a string -> Eingabefehler)
        jr nz,derr_bad_parameter
        ld a,l
        ld hl,messages_off              ; messages_off; eof_test_1a follows it
        cp #02                          ; n = 0 or 1?
        jr nc,derr_eof_mode             ; 2 or more: the EOF modes
        dec a                           ; 0 -> &FF (messages off), 1 -> 0 (on) (observed: &BE7B)
        ld (hl),a
        ret
derr_eof_mode:
        cp #04                          ; n = 2 or 3?
        jr nc,derr_bad_parameter        ; 4 or more: Eingabefehler (observed)
        sub #03                         ; 2 -> &FF (&1A test on), 3 -> 0 (off) (observed: &BE7C)
        inc hl                          ; eof_test_1a (&BE7C)
        ld (hl),a
        ret
derr_bad_parameter:
        jp error_bad_name               ; "Eingabefehler"
derr_variable:
        call record_buffer_de           ; DE = record buffer: build the statement DERR=<code> there (BASIC 1.0 tokens)
        push de
        ex de,hl
        ld (hl),#0D                     ; &0D: a variable without type suffix (real) ...
        inc hl                          ; ... followed by 2 bytes for BASIC's address cache ...
        ld (hl),#00
        inc hl
        ld (hl),#00
        inc hl
        ld de,derr_name                 ; ... and its name "DERR" (last letter + &80)
        ld bc,#0004
        ex de,hl
        ldir
        ex de,hl
        ld (hl),#EF                     ; &EF: the token '='
        inc hl
        ld (hl),#19                     ; &19: a one-byte integer constant follows
        inc hl
        pop de
        ld a,(#BE82)                    ; the last CAS / disc error code (cas_last_error) ...
        ld (hl),a                       ; ... is the constant
        inc hl
        ld (hl),#00                     ; &00: end of the statement
        ex de,hl                        ; HL = the statement
        rst #18                         ; FAR CALL; FAR CALL BASIC: run the statement (ROM select &80: no expansion ROM answers, so the on-board BASIC appears - observed: reached ROM 0; DERR = 151 / 23 / 72)
        defw far_basic_statement        ;   to #D654 [ROM 128]  (observed: reached rom0)
        ret
derr_name:
        defb "DER","R"+#80              ; the variable name "DERR" for derr_variable
; ----------------------------------------------------------------------
; Subroutine: vdos_cas_catalog [#D8F6]
; Tasks:        CAS CATALOG: list the directory of the current drive and user, sorted, in
;               columns, then the space used and free (observed with CAT, e.g.
;               "119K in  26 Files,  50K frei"). Collects the entries in the given buffer as
;               a table of 14-byte entries (user, name, extension, extent, records); files with
;               the SYS attribute are left out. Shares its start and end with rsx_dir.
; Input:        DE = 2K buffer
; Output:       CY = 1: ok
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    cas_jump_table (CAS CATALOG &BC9B), observed with CAT
; Calls:        cas_entry, dir_start, dir_entry_address, dir_insert_sorted, search_next,
;               dir_print_entry, dir_next_line, dir_print_free, print_message, TXT_OUTPUT
vdos_cas_catalog:
        call cas_entry                  ; IY, error SP
        push de                         ; IX = the buffer: start of the table
        pop ix
        ld a,#FF                        ; empty table: &FF end mark at its start
        ld (de),a
        ld hl,#FFF2                     ; last entry = buffer - 14 (none yet)
        add hl,de
        ld (iy+#1F),l
        ld (iy+#20),h
        xor a                           ; no name parameter: all files
        ld bc,#113F                     ; B = &11 (17): entry width with the size; C = &3F: search all extents - the table needs every entry for the size
        call dir_start                  ; print "Laufwerk A: User 0", search the first entry
        push bc
        jp z,dir_free_pop               ; none: just the space line
cc_collect:
        call dir_entry_address          ; HL, DE = the directory entry found
        jr nz,cc_next_entry             ; SYS attribute: leave it out
        ex de,hl                        ; HL = the directory entry
        call dir_insert_sorted          ; insert it into the table (sorted by user, name; one per file)
cc_next_entry:
        call search_next                ; next directory entry
        jr nz,cc_collect                ; found another
        push ix                         ; sizes: from table entry +&0C ...
        pop hl
        ld de,#000C                     ; +&0C: extent byte of the first entry
        add hl,de
        ld e,(iy+#1E)                   ; E = number of entries
        inc e                           ; (count + 1 for the loop)
cc_size_loop:
        dec e
        jr z,cc_print                   ; all done
        push hl
        rst #20                         ; RAM LAM; extent number (0-31 only: the module S2 is not counted, a file > 512K shows its size modulo 512K - observed: HUGE, 516K, shown as 512K) ...
        ld l,a                          ; (...)
        ld h,#00
        add hl,hl                       ; ... * 16 (16K per extent) ...
        add hl,hl
        add hl,hl
        add hl,hl
        ex (sp),hl
        inc hl
        rst #20                         ; RAM LAM; ... + (records + 7) / 8 ...
        ex (sp),hl                      ; (records)
        add a,#07
        srl a
        srl a
        srl a
        ld c,a
        ld b,#00
        add hl,bc
        ld c,l                          ; BC = K
        ld b,h
        pop hl
        ld (hl),b                       ; ... = size in K, stored in the entry's last two bytes
        dec hl
        ld (hl),c
        call next_entry_hl              ; next table entry
        jr cc_size_loop
cc_print:
        xor a                           ; CR LF
        call print_message
        ld a,(iy+#1E)                   ; no files?
        or a
        jp z,dir_free_pop               ; yes: just the space line
        pop bc                          ; rows from the number of columns (B from dir_start) ...
        bit 0,b                         ; one column?
        jr nz,cc_column_step
cc_rows_loop:
        srl b                           ; rows = files / columns (columns a power of 2) ...
        jr c,cc_rows_round_up           ; (...)
        srl a                           ; (...)
        jr cc_rows_loop
cc_rows_round_up:
        inc a                           ; ... rounded up
cc_column_step:
        ld de,#000E                     ; ... BC = 14 * rows: step from one column to the next
        ld b,a                          ; B = rows
        ld hl,#0000                     ; HL = 14 * rows
cc_multiply:
        add hl,de
        djnz cc_multiply
        ld c,l                          ; BC = column step
        ld b,h
        ld de,#0000                     ; DE = first entry of the row
cc_row:
        push ix
        pop hl
        add hl,de                       ; HL = it
cc_column:
        call dir_print_entry            ; print it
        add hl,bc                       ; entry in the next column
        ld a,(iy+#1F)                   ; past the last entry?
        sub l                           ; (...)
        ld a,(iy+#20)
        sbc a,h                         ; (...)
        jr c,cc_next_row                ; yes: row done
        ld a,#20                        ; column gap: 2 spaces
        call TXT_OUTPUT
        call TXT_OUTPUT
        jr cc_column
cc_next_row:
        call next_entry_de              ; next row
        ld a,e                          ; all rows done?
        sub c                           ; (...)
        ld a,d
        sbc a,b                         ; (...)
        jp nc,dir_print_free            ; yes: the space line
        call dir_next_line              ; CR LF (page full: wait for a key)
        jr cc_row
; ----------------------------------------------------------------------
; Subroutine: dir_print_entry [#D9A7]
; Tasks:        Print one table entry: "NAME    .EXT   nK" and '#' after it for a read-only
;               file (bit 7 of the first extension byte), else a space.
; Input:        HL = table entry
; Changed:      AF
; Called by:    vdos_cas_catalog
; Calls:        print_message (&23, &04), TXT_OUTPUT
dir_print_entry:
        push hl
        push de
        ex de,hl                        ; DE = entry
        ld a,#23                        ; print the name
        call print_message
        ld a,#20                        ; (CAT prints it after the name)
        call TXT_OUTPUT                 ; a space
        ld hl,#0009                     ; first extension byte ...
        add hl,de                       ; (+9)
        rst #20                         ; RAM LAM
        push af                         ; ... kept (bit 7 = read-only)
        inc hl                          ; size in K at +&0C ...
        inc hl
        inc hl
        rst #20                         ; RAM LAM
        ld e,a
        inc hl
        rst #20                         ; RAM LAM
        ld d,a                          ; (DE = size)
        ld a,#04                        ; ... "<DE>K"
        call print_message
        pop de
        ld a,#23                        ; '#' for read-only ...
        bit 7,d
        jr nz,dpe_flag_char
        ld a,#20                        ; ... else a space
dpe_flag_char:
        call TXT_OUTPUT                 ; '#' or space
        pop de
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: dir_next_line [#D9D6]
; Tasks:        CR LF; after 22 rows wait for a key first (page pause); ESC there ends the
;               listing at once with the space line, any other key goes on. Observed both: CAT
;               in MODE 0 (one column) of 64 files - space bar continues, ESC prints
;               " 64K in  64 Files, 105K frei" at once.
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_catalog, rsx_dir
; Calls:        flush_keys_cursor_on, KM_WAIT_CHAR, print_crlf, TXT_CUR_OFF, dir_print_free
dir_next_line:
        dec (iy+#09)                    ; one line less on this page
        jr nz,dnl_crlf                  ; page not full: CR LF
        ld (iy+#09),#16                 ; page full: 22 lines again (observed: CAT of 64 files in MODE 0)
        call flush_keys_cursor_on
        call KM_WAIT_CHAR               ; wait for a key
        push af
        call print_crlf
        call TXT_CUR_OFF
        pop af
        cp #FC                          ; ESC (&FC)? (observed)
        jp nz,print_crlf                ; no: go on
        pop af                          ; yes: drop our return into the listing ... (observed)
        jp dir_print_free               ; ... and print the space line at once
dnl_crlf:
        jp print_crlf                   ; CR LF
; ----------------------------------------------------------------------
; Subroutine: dir_insert_sorted [#D9F9]
; Tasks:        Insert a directory entry into the catalog table, sorted by user, name,
;               extension; for a file with several extents only one entry is kept (the one
;               with the higher extent, whose records give the size).
; Input:        HL = directory entry, IX = table; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_catalog
; Calls:        dir_compare_names, KL_LDDR, KL_LDIR
dir_insert_sorted:
        push ix                         ; DE = first table entry
        pop de
        jr dis_compare
dis_next:
        call next_entry_de              ; next table entry
dis_compare:
        call dir_compare_names          ; compare with it
        jr c,dis_next                   ; the new one sorts after it: go on
        jr z,dis_copy                   ; same file with a higher or equal extent: overwrite the table entry with this one
        push hl                         ; insert: move the rest of the table up by 14 bytes
        push de
        ld l,(iy+#1F)                   ; last table entry ...
        ld h,(iy+#20)
        call next_entry_hl              ; ... one further on
        ld (iy+#1F),l                   ; (the table grows by one entry)
        ld (iy+#20),h
        push hl
        inc hl                          ; bytes from the insert point to the end ...
        or a
        sbc hl,de                       ; (...)
        ld b,h                          ; BC = them
        ld c,l
        pop hl
        ld d,h                          ; DE = HL + 14: destination
        ld e,l
        call next_entry_de
        call KL_LDDR                    ; move them up (RAM, from the end)
        pop de
        pop hl
        inc (iy+#1E)                    ; one file more
dis_copy:
        ld bc,#000E                     ; copy user, name, extension, extent, S1 ...
        call KL_LDIR                    ; (RAM)
        inc hl                          ; ... and put the record count (+&0F) over S1
        ld a,(hl)
        dec de
        ld (de),a
        inc de
        ret
; ----------------------------------------------------------------------
; Subroutine: dir_compare_names [#DA3A]
; Tasks:        Compare the 12 bytes user/name/extension (bit 7 ignored) of a directory entry
;               with a table entry; on equal names the extents (byte 12 only, not the module
;               S2: for a file > 512K the last entry of module 0 (extent 31) wins over the
;               entries of module 1 - CAT then shows 512K, observed with a 516K file).
; Input:        HL = directory entry, DE = table entry
; Output:       CY = the new entry sorts after the table entry; Z = same file with a higher or
;               equal extent (overwrite); NZ NC = insert here. Same file with a lower extent:
;               returns straight to dir_insert_sorted's caller (the new entry is ignored).
; Changed:      AF, BC
; Called by:    dir_insert_sorted
dir_compare_names:
        push hl
        push de
        ld b,#0C                        ; 12 bytes: user, name, extension
dcn_loop:
        ex de,hl                        ; table byte ...
        rst #20                         ; RAM LAM; (RAM)
        and #7F                         ; ... without bit 7
        ex de,hl
        ld c,(hl)                       ; directory byte ...
        res 7,c                         ; ... without bit 7
        cp c                            ; equal?
        jr nz,dcn_done                  ; no: the order is decided (CY = sort after)
        inc de
        inc hl
        djnz dcn_loop                   ; next byte
        ex de,hl
        ld a,(de)                       ; the directory entry's extent (byte 12; the module S2 in byte 14 is not compared)
        push af
        rst #20                         ; RAM LAM; the table entry's extent (RAM)
        ld d,a
        pop af
        cp d                            ; higher or equal? (lower: the pops below drop the caller's return, so dir_insert_sorted returns at once and the table entry stays)
        jr nc,dcn_same                  ; yes: Z - the caller overwrites the table entry with the new one
        pop de                          ; no: the table entry has the higher extent - drop the registers and dir_insert_sorted's return ...
        pop hl
        pop bc
        ret
dcn_same:
        xor a                           ; same name: Z
dcn_done:
        pop de
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: next_entry_hl [#DA5E]
; Tasks:        HL + 14: next catalog table entry.
; Input:        HL = a catalog table entry
; Changed:      HL, F
next_entry_hl:
        push de
        ld de,#000E                     ; 14 bytes per entry
        add hl,de
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: next_entry_de [#DA65]
; Tasks:        DE + 14: next catalog table entry.
; Input:        DE = a catalog table entry
; Changed:      DE, HL, F
next_entry_de:
        ex de,hl
        call next_entry_hl              ; (DE + 14)
        ex de,hl
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_ren [#DA6B]
; Tasks:        |REN,"new","old": rename the file old to new on the same disc. No wildcards.
;               Order of the checks: the new name (wildcards: Eingabefehler; exists: "<new>
;               existiert bereits"), then the old name (wildcards or another drive than the
;               new name: Eingabefehler), then the BDOS rename (not found: "<old> wurde nicht
;               gefunden"; R/O: "<old> hat Schreibschutz").
;               The new name is written from the parsed string, so the old entry's attribute
;               bits are lost: a SYS file is visible again after the rename (observed; R/O
;               files cannot be renamed at all).
;               Observed (drive B): |REN,"NEU.BAS","T.BAS"; new exists ("NEU     .BAS existiert
;               bereits", also for |REN,"W.BAS","W.BAS"); old missing ("Q       .BAS wurde nicht
;               gefunden"); "N*.BAS" / "X.B?S" / "A:Z","B:X" / one / three parameters / "" ->
;               Eingabefehler; "B:Z.BAS","X.BAS" with B current; R/O old -> "Z       .BAS hat
;               Schreibschutz"; SYS old -> new name visible.
;               As in the manual (2.0), which does not mention the lost attributes.
; Input:        A = number of parameters (2), IX = parameters: IX+0 old name, IX+2 new name
; Output:       CY = 1 ok; errors through cas_error_exit
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "REN" (rom_jumpblock)
; Calls:        rsx_two_params, rsx_string_param, parse_filename_check, search_first, record_buffer_de, de_hl_add_iy, rename_file; error_exists, error_not_found, rsx_bad_param
rsx_ren:
        call rsx_two_params             ; two parameters; B/HL = the last one: the OLD name
        push hl                         ; keep the old name's string ...
        push bc                         ; ... (B = length)
        call rsx_string_param           ; B/HL = the first parameter: the NEW name
        call parse_filename_check       ; parse it into the name FCB
        push de                         ; DE = name FCB
        jr c,rsx_bad_param              ; wildcards in the new name: Eingabefehler (observed: "N*.BAS")
        call search_first               ; does the new name exist already?
        jp nz,error_exists              ; yes: "<new> existiert bereits" (observed)
        pop hl                          ; HL = name FCB (the new name) ...
        call record_buffer_de           ; ... DE = record buffer (workspace+&E0) ...
        ld bc,#0010                     ; ... 16 bytes: drive, name, extension, extent ...
        ldir                            ; ... kept there
        pop bc                          ; B/HL = the old name's string again
        pop hl
        ld a,(iy+#25)                   ; the new name's drive byte ...
        push af                         ; ... kept
        call parse_filename_check       ; parse the old name into the name FCB
        jr c,rsx_bad_param              ; wildcards in the old name: Eingabefehler (observed: "X.B?S")
        pop bc                          ; B = the new name's drive
        ld a,(iy+#25)                   ; the old name's drive ...
        cp b                            ; ... the same?
        jr nz,rsx_bad_param             ; no: Eingabefehler (observed: "A:Z.BAS","B:X.BAS")
        ld hl,#00E1                     ; from the kept new name without its drive byte (record buffer+1) ...
        ld de,#0036                     ; ... to name FCB+&11: the new name for the BDOS rename ...
        call de_hl_add_iy
        ld bc,#000F                     ; ... name, extension, extent and 4 more (15 bytes; attribute bits are clear: the parsed name)
        ldir
        ld (iy+#35),#00                 ; FCB+16 (the new name's drive byte) = 0
        call rename_file                ; BDOS rename (R/O old file: "hat Schreibschutz", observed)
        jp z,error_not_found            ; not found: "<old> wurde nicht gefunden" (observed)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_era [#DAB3]
; Tasks:        |ERA,"name": delete every file of the current user that matches the name
;               (wildcards * and ? allowed, drive letter allowed: "A:EX2.BAS" from drive B).
;               Through the BDOS delete (delete_body): the matching entries are deleted in
;               directory order; an R/O entry stops the command with "<name> hat
;               Schreibschutz" - entries before it are already deleted, those after it stay.
;               Observed (drive B, in memory): |ERA,"X.BAS" -> "X       .BAS wurde nicht
;               gefunden"; |ERA,"T1.BAS"; |ERA,"T?.BAS" with T0 W, T2 R/O, T3 W -> T0 deleted,
;               "T2      .BAS hat Schreibschutz", T2 and T3 stay; after |ATTRIBUT W again T2 and
;               T3 deleted; |ERA,"A:EX2.BAS" from B; |ERA,"*.*" -> "0K in 0 Files, 704K frei".
;               Errors "Eingabefehler" (observed): no parameter, two parameters, "", ".BAS"
;               (empty name), "1:X". No "Break" after a message (RSX, not CAS).
;               As in the manual (2.0).
; Input:        A = number of parameters (1), IX = parameters (string descriptor)
; Output:       CY = 1 ok; error exits through cas_error_exit
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "ERA" (rom_jumpblock)
; Calls:        rsx_one_param, parse_filename_check, delete_file, error_not_found
rsx_era:
        call rsx_one_param              ; exactly one parameter, B/HL = its string (rsx_one_param falls through into rsx_string_param)
        call parse_filename_check       ; name -> name FCB, wildcards allowed, empty name: Eingabefehler
        call delete_file                ; BDOS delete: all matching entries; an R/O one: "hat Schreibschutz" (check_rodir, observed)
        jp z,error_not_found            ; none matched: "<name> wurde nicht gefunden" (observed)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_code [#DAC0]
; Tasks:        |CODE,n: code_key (&BE79) = n (any 16-bit value; 0 = no key). With a key,
;               protected files (SAVE ,P) are coded with it: crypt_record XORs every byte with
;               the 2 key bytes (low, high, ...) and crypt_table_13, instead of crypt_table and
;               crypt_table_13. The key is not stored in the file; a wrong key decodes to garbage.
;               Observed: |CODE,12325 (&3025) + SAVE "PC",P and SAVE "PN",P without key; RUN "PC"
;               with the key and RUN "PN" without -> "OK CODE"; both files decoded offline
;               to the same BASIC line; |CODE,1 + RUN "PC" -> "Syntax error in 12334" (garbage);
;               -1, 32767, 32768, &FFFF accepted (16 bits: the manual's -32768..32767 is the same
;               range); |CODE,"x" accepted - the key is then the string descriptor's address
;               (observed &B09C), no type check; no or two parameters -> Eingabefehler.
; Input:        A = number of parameters (1), IX = parameters
; Output:       code_key
; Changed:      AF, HL, IX, IY
; Called by:    RSX "CODE" (rom_jumpblock)
; Calls:        rsx_number_param
rsx_code:
        call rsx_number_param           ; HL = n (exactly one parameter)
        ld (code_key),hl                ; code_key = n (observed: 12325 -> 25 30)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_number_param [#DAC7]
; Tasks:        Common start of an RSX command with exactly one number: cas_entry_setup, then
;               HL = the parameter's value (rsx_param); another count: "Eingabefehler"
;               (falls into rsx_bad_param). Observed (|USER).
; Input:        A = number of parameters, IX = parameters
; Output:       HL = the value; IY = VDOS workspace
; Changed:      AF, HL, IX, IY
; Called by:    rsx_user, rsx_code
rsx_number_param:
        call cas_entry_setup            ; IY, error SP
        dec a                           ; exactly one parameter?
        jp z,rsx_param                  ; yes: HL = its value; else on into rsx_bad_param (observed: |USER, |USER,1,2)
rsx_bad_param:
        jp error_bad_name               ; "Eingabefehler" - shared error exit of rsx_ren, rsx_code and rsx_attribut (observed with |REN)
; ----------------------------------------------------------------------
; Subroutine: rsx_attribut [#DAD1]
; Tasks:        |ATTRIBUT,"name","x": set one attribute of a file. x (one character, upper
;               or lower case) from attribute_letters: S = SYS (hidden in CAT/|DIR), D = DIR
;               (shown), R = R/O (not deletable / renamable / writable), W = R/W. S/D work on
;               bit 7 of extension byte 2, R/W on bit 7 of extension byte 1; the other bit is
;               kept (R and S are independent). The file is opened (open_file); its FCB gets the
;               bit and set_attributes writes FCB bytes 0-11 into every entry of that file
;               (all extents). A wildcard name changes only the FIRST matching file: the open
;               puts the found name into the FCB.
;               Observed (drive A): "r" -> CAT "EX1     .BAS   2K#", |ERA "hat Schreibschutz";
;               "s" -> hidden in |DIR, still R/O; "D" -> shown; "W" -> deletable again;
;               ROINTIME.DEM (2 entries) S -> hidden in CAT (both entries); "D*.COM" S -> only
;               DDT.COM hidden; "B:W.BAS" from drive A.
;               Errors (observed): "X", "RW", "" as attribute, one or three parameters ->
;               Eingabefehler; "NIX.BAS" -> "wurde nicht gefunden"; "" as name -> "        .
;               wurde nicht gefunden" (no empty name check: parse_filename_fcb, not _check).
;               Manual (2.0): |ERA of an R/O file prints "PIP    .COM nur lesbar"; 2.11-X prints
;               "<name> hat Schreibschutz".
; Input:        A = number of parameters (2), IX = parameters: IX+0 attribute, IX+2 name
; Output:       CY = 1 ok; errors through cas_error_exit
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "ATTRIBUT" (rom_jumpblock)
; Calls:        rsx_two_params, to_upper, rsx_string_param, parse_filename_fcb, open_file, iy_offset_hl, set_attributes; error_not_found, rsx_bad_param
rsx_attribut:
        call rsx_two_params             ; two parameters; B/HL = the last one: the attribute
        dec b                           ; exactly one character?
        jr nz,rsx_bad_param             ; no: Eingabefehler (observed: "RW", "")
        rst #20                         ; RAM LAM; A = the character (RAM)
        call to_upper                   ; upper case (observed: "r", "s")
        ld b,#04                        ; 4 letters ...
        ld hl,attribute_letters         ; ... in attribute_letters "SDRW"
attr_search:
        cp (hl)                         ; this letter?
        jr z,attr_found                 ; yes: B = 4 (S), 3 (D), 2 (R), 1 (W)
        inc hl
        djnz attr_search
        jr rsx_bad_param                ; not a known letter: Eingabefehler (observed: "X")
attr_found:
        dec b                           ; B = 3 S, 2 D, 1 R, 0 W: bit 1 = which byte (SYS / R/O), bit 0 = the bit value
        push bc                         ; keep it
        call rsx_string_param           ; B/HL = the file name (IX+2)
        call parse_filename_fcb         ; into the name FCB - no empty name check (observed: "" -> not found with a blank name)
        call open_file                  ; BDOS open: the file's entry (extent 0) into the FCB; wildcards: the first match
        jp z,error_not_found            ; not found: "<name> wurde nicht gefunden" (observed)
        pop de                          ; D = the letter code
        ld hl,#002E                     ; name FCB byte 9 (workspace+&2E): extension byte 1, the R/O bit ...
        ld a,d
        rra                             ; code bit 1 ...
        and #01
        jr z,attr_set_bit               ; clear (R, W): byte 9
        inc hl                          ; set (S, D): byte 10, extension byte 2 = the SYS bit
attr_set_bit:
        ld a,d                          ; code bit 0 ...
        rra                             ; (rra: bit 0 into CY, which and #01 had cleared ...)
        rra                             ; (... rra: CY into bit 7)
        and #80                         ; D = &80 (S, R: set) or 0 (D, W: clear)
        ld d,a
        call iy_offset_hl               ; HL = the byte in the name FCB
        ld a,(hl)                       ; the extension character ...
        and #7F                         ; ... without its attribute bit ...
        or d                            ; ... with the new one
        ld (hl),a
        jp set_attributes               ; write FCB bytes 0-11 into every entry of the file (observed: both entries of ROINTIME.DEM)
attribute_letters:
        defb "SDRW"                     ; S D R W: index 3 2 1 0 after the search (bit 1: byte, bit 0: value)
; ----------------------------------------------------------------------
; Subroutine: rsx_user [#DB16]
; Tasks:        |USER,n: current user (iy+&05) = n, 0-15 (not in the manual 2.0). The drive is
;               not changed, no login.
;               Observed: |USER,9 -> "Laufwerk A: User  9"; 15, 0 accepted; 16, 256, -1, &10, no or
;               two parameters, "3" (a string's descriptor address is >= 256) -> Eingabefehler. A
;               file saved in user 9 is not seen (|DIR) nor deleted (|ERA: "wurde nicht gefunden")
;               from user 0.
; Input:        A = number of parameters (1), IX = parameters
; Output:       (iy+&05) = the user
; Changed:      AF, HL, IX, IY
; Called by:    RSX "USER" (rom_jumpblock)
; Calls:        rsx_number_param, error_bad_name
rsx_user:
        call rsx_number_param           ; HL = n
        ld a,h                          ; high byte 0?
        or a
        jp nz,error_bad_name            ; no: Eingabefehler (observed: 256, -1, a string)
        ld a,l                          ; n ...
        cp #10                          ; ... below 16?
        jp nc,error_bad_name            ; no: Eingabefehler (observed: 16, &10)
        ld (iy+#05),a                   ; current user = n (observed)
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_select [#DB28]
; Tasks:        |SELECT,"[user][drive]" and |DRIVE (the same routine): parse the string -
;               spaces skipped, letters upper case:
;               user = one digit, or two digits "1x" (10-15) or "0x"; >= 16: Eingabefehler;
;               then an optional drive letter A/B (set_default_drive: also a new login);
;               a letter first: only the drive, the rest of the string is ignored;
;               after the drive letter the rest is ignored too.
;               The user is set before the drive letter is checked, so "3C" leaves user 3 set
;               and then reports "Eingabefehler".
;               Observed: "6" (User 6), "5B" (B, User 5), "15", "07a" (A, User 7), " 3 ",
;               "12 B", "4BX" (B, User 4); |DRIVE,"A". Errors (Eingabefehler): "16", "20", "C",
;               "", "   ", "1/", "3C" (user 3 kept), no or two parameters.
;               Manual (2.0): |SELECT,"B5" = user 5 on drive B. In 2.11-X "B5" only selects
;               drive B (observed: user unchanged); the user must come first: "5B".
; Input:        A = number of parameters (1), IX = parameters (string)
; Output:       (iy+&05) = user, (iy+&06) = drive
; Changed:      AF, DE, HL, B, IX, IY
; Called by:    RSX "SELECT" and "DRIVE" (rom_jumpblock)
; Calls:        rsx_one_param, next_nonspace, set_user, set_default_drive; rsx_bad_param, error_bad_name
rsx_select:
        call rsx_one_param              ; B/HL = the string
        call next_nonspace              ; first character (spaces skipped, upper case)
        jr nc,rsx_bad_param             ; none: Eingabefehler (observed: "", "   ")
        cp #30                          ; below '0'?
        jr c,sel_error                  ; yes: Eingabefehler
        cp #3A                          ; a digit?
        jr nc,sel_drive                 ; no (a letter): drive only (observed: "B5" -> drive B, user unchanged)
        sub #30                         ; the first digit ...
        ld d,a                          ; ... D = user so far
        call next_nonspace              ; next character
        jr nc,set_user                  ; none: user = D (observed: "6", " 3 ")
        cp #30                          ; below '0'?
        jr c,sel_error                  ; yes: Eingabefehler (observed: "1/")
        cp #3A                          ; a digit?
        jr nc,sel_user_drive            ; no: user = D, then the drive letter (observed: "5B")
        sub #30                         ; the second digit
        ld e,#0A                        ; tens: 10 ...
        dec d                           ; (first digit - 1 ...)
        jr z,sel_two_digits             ; ... if the first digit was 1 (user 10-19, checked below)
        ld e,#00                        ; else tens 0 ...
        inc d                           ; ... only if the first digit was 0
        jr nz,sel_error                 ; 2-9 with a second digit: Eingabefehler (observed: "20")
sel_two_digits:
        add a,e                         ; user = tens + second digit ...
        cp #10                          ; ... below 16?
        jr nc,sel_error                 ; no: Eingabefehler (observed: "16")
        ld d,a                          ; D = user
        call next_nonspace              ; another character?
        jr c,sel_user_drive             ; yes: user, then the drive letter (observed: "07a", "12 B")
set_user:
        ld (iy+#05),d                   ; current user = D (also entered by CALL from sel_user_drive)
        ret
sel_user_drive:
        call set_user                   ; user first - it stays set even if the drive letter is wrong (observed: "3C")
sel_drive:
        sub #41                         ; the drive letter - 'A' ...
        cp #02                          ; ... A or B?
        jp c,set_default_drive          ; yes: default drive, new login (the rest of the string is ignored: "4BX")
sel_error:
        jp error_bad_name               ; Eingabefehler (observed: "C", "3C", "20", "16")
; ----------------------------------------------------------------------
; Subroutine: rsx_reset [#DB70]
; Tasks:        |RESET: close the output file properly (CAS OUT CLOSE: the rest of the buffer and
;               the directory entry are written, the .$$$ renamed), close the input file, and
;               clear the login bytes of both drives, so the next access logs each disc in
;               again. For a disc change while files are open (manual: "like CTRL+C under
;               CP/M"). A close without an open file takes the CAS error exit (&0E, no
;               message), which returns here: in_check_open / out_check_open call
;               cas_entry_setup themselves (observed: cas_error_exit RETs to #DB76).
;               Observed: no file open -> nothing printed, &BE82 = &0E, &A700/&A701 = 0;
;               OPENOUT "R1" + PRINT #9,"hallo" + |RESET -> R1 written and readable ("hallo"),
;               a later PRINT #9 -> "Break" (BASIC still thinks it is open); OPENIN + |RESET ->
;               LINE INPUT #9 "EOF met"; |RESET,5,"X": parameters ignored. As in the manual.
; Input:        A = number of parameters (ignored)
; Output:       -
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "RESET" (rom_jumpblock), rsx_x, rsx_format
; Calls:        load_workspace_iy, vdos_cas_out_close, vdos_cas_in_close
rsx_reset:
        call load_workspace_iy          ; IY = VDOS workspace
        call vdos_cas_out_close         ; close the output file (writes it; not open: error &0E, back here)
        call vdos_cas_in_close          ; close the input file (not open: error &0E, back here)
        ld (iy+#00),#00                 ; drive A's login byte = 0: log in again at its next access
        ld (iy+#01),#00                 ; drive B's login byte = 0
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_x [#DB82]
; Tasks:        |X: swap drives A and B: |RESET (close files, new login of both), toggle
;               drives_swapped (0 <-> 1) and copy the XPBs into the drives' DPB slots again
;               (setup_drive_tables: the 3" XPB as B gets the Vortex layout of its last 3
;               bytes). The XPB copy resets the current track bytes and the flag bytes (head
;               position unknown: the next seek recalibrates).
;               Observed: |A:|X:CAT -> "Laufwerk A" lists the Vortex disc, |B:CAT the 3" disc,
;               &BE7F 0 -> 1 -> 0; |X,1,2 = |X (parameters ignored). As in the manual (2.0).
; Input:        A = number of parameters (ignored)
; Output:       -
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "X" (rom_jumpblock)
; Calls:        rsx_reset, sdt_copy_xpbs
rsx_x:
        call rsx_reset                  ; close the files, both drives log in again
        ld hl,drives_swapped            ; drives_swapped ...
        dec (hl)                        ; ... 1 -> 0 ...
        jr z,x_copy_xpbs                ; (was 1: now 0, normal)
        ld (hl),#01                     ; ... 0 -> &FF: set 1 (swapped)
x_copy_xpbs:
        jp sdt_copy_xpbs                ; copy the XPBs to the DPB slots for the new assignment (observed)
; ----------------------------------------------------------------------
; Subroutine: rsx_format [#DB90]
; Tasks:        |FORMAT,n: format the disc in drive n (1 = A, 2 = B). |RESET, motors off, then
;               "Laufwerk X: Diskette eingelegt J/N ?" (N: nothing). Parameters in the host
;               buffer (IX): +0 drive, +1 SC sectors per track, +2 tracks, +3 first sector ID,
;               +4 sides - 1, +5 N, +6 side counter, +7 interleave step (SC+1)/2, +8 step - 1,
;               +&20 the sector header table. From the drive's XPB: first sector, SC, N.
;               3" drive (drive number = drives_swapped): "Format (S,D) ?" - S: system format
;               (IDs &41-&49), D: data format (&C1-&C9), always 40 tracks, one side (MTRK is not
;               read); ESC: abort; another key: beep. Other drive: tracks = MTRK + 1, sides from
;               the flag byte bit 0. All tracks of side 0, then side 1; progress "Seite s Spur t".
;               Sectors in the order 1,6,2,7,3,8,4,9,5 (fmt_headers, interleave 2). Only the
;               tracks are written (filler &E5): the directory is empty without more work.
;               Observed: |FORMAT,2 N (nothing), J -> "Seite 1 Spur 79", |DIR "0K in 0 Files,
;               704K frei"; |FORMAT,1 J, X (ignored), ESC (abort, disc untouched); S -> CAT
;               "169K frei", D -> "178K frei"; write-protected disc -> "Seite 0 Spur  0",
;               "Laufwerk A: Diskette hat Schreibschutz - Wiederholen J/N ?", N -> Ready; after
;               |X: |FORMAT,2 asks "Format (S,D) ?". Errors: no / two parameters, 0, 3 ->
;               Eingabefehler; 257 is taken as 1 (only the low byte is checked).
;               Manual (2.0): "FORMAT (S,D) ?" before the J/N question and "Init-Seite"; 2.11-X
;               asks J/N first and prints "Seite".
; Input:        A = number of parameters (1), IX = parameters
; Output:       -
; Changed:      AF, BC, DE, HL, IX, IY
; Called by:    RSX "FORMAT" (rom_jumpblock)
; Calls:        rsx_number_param, rsx_reset, motors_off_now, host_buffer, ask_yes_no, print_message, specify_for_drive, xpb_byte_address, flush_keys_cursor_on, KM_WAIT_CHAR, to_upper, TXT_OUTPUT, print_char_cursor_off, fmt_headers, bios_format_track
rsx_format:
        call rsx_number_param           ; HL = n
        dec l                           ; drive = n - 1 ...
        ld a,l
        cp #02                          ; ... 0 or 1? (only L: 257 counts as 1, observed)
        jp nc,error_bad_name            ; no: Eingabefehler (observed: 0, 3)
        push af
        call rsx_reset                  ; close the files, both drives log in again
        call motors_off_now
        call host_buffer                ; IX = host buffer: the format parameters
        push hl
        pop ix
        pop af
        ld (ix+#00),a                   ; +0 = drive
        ld c,a                          ; C = drive for the message
        push bc
        ld a,#25                        ; "Laufwerk X: Diskette eingelegt J/N ?"
        call ask_yes_no
        ld a,#00                        ; CR LF
        call print_message
        pop bc
        ret z                           ; N: nothing done (observed)
        ld a,(ix+#00)                   ; FDC SPECIFY for the drive
        call specify_for_drive
        ld e,(ix+#00)
        ld a,#0F                        ; from XPB byte &0F ...
        call xpb_byte_address
        ld a,(hl)                       ; ... the first sector ID ...
        ld (ix+#03),a                   ; ... +3
        inc hl
        ld a,(hl)                       ; SC, sectors per track ...
        ld (ix+#01),a                   ; ... +1
        inc a                           ; (SC + 1) / 2 ...
        srl a
        ld (ix+#07),a                   ; ... +7: interleave step (5 for 9 sectors)
        dec a
        ld (ix+#08),a                   ; ... +8: step - 1
        inc hl
        inc hl
        inc hl
        inc hl
        ld a,(hl)                       ; XPB byte &14: N, the sector size code ...
        ld (ix+#05),a                   ; ... +5
        inc hl
        inc hl
        ld a,(drives_swapped)           ; the 3" drive (drive number = drives_swapped)?
        xor e
        jr nz,fmt_vortex                ; no: tracks and sides from the XPB
        ld a,#3C                        ; "Format (S,D) ? " (observed; asked after the J/N question)
        call print_message
        call flush_keys_cursor_on
fmt_ask_format:
        call KM_WAIT_CHAR               ; wait for a key
        call to_upper
        ld e,#41                        ; S: first sector &41 (system format)
        cp #53
        jr z,fmt_3inch
        cp #44                          ; D?
        set 7,e                         ; D: &C1 (data format)
        jr z,fmt_3inch
        cp #FC                          ; ESC?
        ret z                           ; yes: abort, nothing formatted (observed)
        ld a,#07                        ; another key: beep and wait again (observed: X)
        call TXT_OUTPUT
        jr fmt_ask_format
fmt_3inch:
        call print_char_cursor_off      ; echo S / D
        xor a
        call print_message              ; CR LF
        ld (ix+#03),e                   ; +3 = first sector &41 / &C1
        ld (ix+#02),#28                 ; +2 = 40 tracks (fixed: the 3" XPB as drive A has no MTRK byte)
        xor a                           ; one side
        jr fmt_start
fmt_vortex:
        inc hl                          ; XPB +&17: MTRK, the last track ...
        ld a,(hl)
        inc a                           ; ... + 1 = tracks ...
        inc hl
        ld (ix+#02),a                   ; ... +2 (80 for the Vortex drive)
        ld a,(hl)                       ; flag byte bit 0 ...
        and #01                         ; ... = sides - 1
fmt_start:
        ld (ix+#04),a                   ; +4 = sides - 1
        ld (ix+#06),#00                 ; +6 = side 0 first
        ld d,#00                        ; D = logical track 0 (side 0: 0, 2, 4, ...)
fmt_side:
        ld b,#00                        ; B = physical track 0
        ld e,(ix+#00)                   ; E = drive
fmt_track:
        push de                         ; keep logical track and drive ...
        push bc
        ld a,(ix+#06)                   ; the side ...
        push af
        add a,#EF                       ; C = side + &EF: the drive-letter code of the message prints it as '0' / '1'
        ld c,a
        ld e,b                          ; DE = physical track
        ld d,#00
        ld a,#26                        ; "<CR>Seite s Spur t" (observed: "Seite 1 Spur 79")
        call print_message
        pop af
        pop bc
        ld d,b                          ; D = physical track (C of the sector headers), A = side (H)
        call fmt_headers                ; the sector header table
        pop de                          ; D = logical track, E = drive
        push bc
        call bios_format_track          ; FORMAT A TRACK
        pop bc
        jr nc,fmt_done                  ; error (N answered): stop (observed: write protect)
        inc d                           ; next logical track ...
        ld a,(ix+#04)                   ; double-sided?
        or a
        jr z,fmt_next_track
        inc d                           ; yes: + 2 (the other side's tracks are the odd ones)
fmt_next_track:
        inc b                           ; next physical track
        ld a,(ix+#02)                   ; all tracks?
        cp b
        jr nz,fmt_track                 ; no: next
        ld d,#01                        ; side 1: logical tracks 1, 3, 5, ...
        inc (ix+#06)                    ; next side
        ld a,(ix+#04)                   ; one more side?
        cp (ix+#06)
        jr z,fmt_side                   ; yes: format it
fmt_done:
        xor a                           ; CR LF and return
        jp print_message
; ----------------------------------------------------------------------
; Subroutine: fmt_headers [#DC76]
; Tasks:        Build the sector header table for FORMAT A TRACK at IX+&20: SC entries of C, H,
;               R, N with R = first sector + 0, step, 1, 1+step, 2, ... (step = (SC+1)/2): for 9
;               sectors 1,6,2,7,3,8,4,9,5 - the order on the original Vortex disc. Observed (|FORMAT).
; Input:        D = cylinder (C), A = head (H), IX = format parameters
; Output:       HL = the table (IX+&20)
; Changed:      AF, HL
; Called by:    rsx_format
; Calls:        fmt_header
fmt_headers:
        push de                         ; keep D
        ld e,a                          ; E = H
        push bc
        push ix
        pop hl
        ld bc,#0020                     ; table at IX+&20 ...
        add hl,bc
        push hl
        ld b,(ix+#01)                   ; B = SC entries
        ld c,(ix+#05)                   ; C = N
        xor a                           ; index 0 first
        jr fh_even
fh_odd:
        add a,(ix+#07)                  ; index + step
        call fmt_header
        dec b
        jr z,fh_done
        sub (ix+#08)                    ; index - (step - 1)
fh_even:
        call fmt_header                 ; entry for this index
        dec b
        jr nz,fh_odd
fh_done:
        pop hl                          ; HL = the table
        pop bc
        pop de
        ret
fmt_header:
        push af                         ; one entry C, H, R, N: R = first sector + index
        add a,(ix+#03)
        ld (hl),d
        inc hl
        ld (hl),e
        inc hl
        ld (hl),a
        inc hl
        ld (hl),c
        inc hl
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: bios_select_format [#DCAE]
; Tasks:        Hidden RSX &83 BIOS SELECT FORMAT (CP/M BIOS extended function), with two
;               VDOS extras:
;               A = &FF: HL = address of drive E's flag byte (drive_flags_address)
;               A = &FE: toggle fast_flag (&BE7C): 0 -> TXT RESET, else the |FAST patch
;               else:    select_format - set the 3" drive's XPB to the format of sector
;               number A (&41 system, &C1 data, &01 IBM); this part takes the same
;               values as AMSDOS's SELECT FORMAT, so callers written for AMSDOS work
;               Observed through RSX &83: A = &FF, E = 1 -> HL = &ABDD; A = &C1, E = 0 -> the 3" XPB
;               gets the data format (DSM &AA -> &B3, first sector &C1), A = &41 -> back; A = &FE ->
;               fast_flag &BE7C = &FF and IND TXT WRITE CHAR -> fast_write_stub (no mode check),
;               again -> 0 and TXT RESET. Under BASIC &BE7C is eof_test_1a: A = &FE also switches
;               the &1A end of file test (a side effect; the function is meant for CP/M).
; Input:        A, E = drive
; Changed:      AF, BC, DE, HL
; Called by:    RSX &83 (rom_jumpblock), cpm_ext_select_format (&BE86)
; Calls:        drive_flags_address, select_format, TXT_RESET, fast_install
bios_select_format:
        cp #FF
        jp z,drive_flags_address
        cp #FE
        jp nz,select_format
        ld hl,fast_flag
        ld a,(hl)
        cpl
        ld (hl),a
        or a
        jp z,TXT_RESET
        jp fast_install
; ----------------------------------------------------------------------
; Subroutine: init_in_header [#DCC5]
; Tasks:        Set up the input header for a newly opened file: as init_header from the
;               input FCB, then a byte count of &800000 ("unknown, very long") until the
;               file's own header says better.
; Input:        DE = 2K buffer, IX = input header; IY = VDOS workspace
; Changed:      AF, BC, HL
; Called by:    vdos_cas_in_open
; Calls:        init_header
init_in_header:
        ld hl,#0046                     ; name source: input FCB+1
        call init_header                ; common part on the input FCB
        ld (ix+#23),#80                 ; bytes left = &800000 (a file without header: read until the end)
        ret
; ----------------------------------------------------------------------
; Subroutine: init_out_header [#DCD0]
; Tasks:        Set up the output header for a newly opened file (init_header from the output FCB).
; Input:        DE = 2K buffer, IX = output header; IY = VDOS workspace
; Changed:      AF, BC, HL
; Called by:    vdos_cas_out_open
; Calls:        falls through into init_header
init_out_header:
        ld hl,#006A                     ; name source: output FCB+1
; ----------------------------------------------------------------------
; Subroutine: init_header [#DCD3]
; Tasks:        Header (IX) layout: +&00 access mode (0/&FF = no access yet, 1 = char, 2 = direct),
;               +&01 2K buffer, +&03 next char in the buffer, +&05 the AMSDOS-style header that
;               CAS IN/OUT OPEN return in HL (+&05 user, +&06 name and ext, +&17 file type,
;               +&18 bytes in the buffer, +&1A load address, +&1C first block flag &FF,
;               +&1D length, +&1F entry address), +&21-&23 24-bit byte count (input: bytes left,
;               output: bytes written).
;               Sets access mode 0, buffer and char pointer = DE, clears the header from +&05,
;               copies user and 11 name/ext bytes, load address = buffer, type &16 (ASCII),
;               first block flag &FF.
; Input:        HL = workspace offset of FCB+1 (name), DE = 2K buffer, IX = header; IY = VDOS workspace
; Changed:      AF, BC, HL
; Entered from: init_out_header (falls through)
init_header:
        call iy_offset_hl               ; HL = FCB+1 (name and extension)
        ld (ix+#00),#00                 ; access mode 0: nothing read or written yet
        ld (ix+#01),e                   ; buffer address
        ld (ix+#02),d                   ; buffer address
        ld (ix+#03),e                   ; next char = start of the buffer
        ld (ix+#04),d                   ; char pointer = buffer start
        push de
        push hl
        push ix                         ; DE = IX + 5: the AMSDOS-style header ...
        pop hl
        ld de,#0005                     ; header +&05 ...
        add hl,de
        ex de,hl
        push de
        ld b,#21                        ; ... clear &21 bytes of it
        call clear_memory               ; cleared
        pop de
        pop hl
        ld a,(iy+#05)                   ; header +&00 = current user
        ld (de),a                       ; user
        inc de
        ld bc,#000B                     ; header +&01..+&0B = name and extension (11 bytes)
        ldir                            ; copy name and extension
        pop de                          ; DE = buffer
        ld (ix+#1A),e                   ; load address = buffer (CAS IN OPEN returns it in DE)
        ld (ix+#1B),d                   ; load address = buffer
        ld (ix+#17),#16                 ; file type &16: ASCII (a file with a header overwrites it)
        ld (ix+#1C),#FF                 ; first block flag &FF: the first record is still to be read / written
        ret
; ----------------------------------------------------------------------
; Subroutine: inc_byte_count [#DD12]
; Tasks:        Add 1 to the 24-bit byte count at IX+&21..&23.
; Input:        IX = header
; Changed:      F
; Called by:    vdos_cas_out_char, vdos_cas_return
inc_byte_count:
        inc (ix+#21)                    ; low byte + 1
        ret nz                          ; no overflow: done
        inc (ix+#22)                    ; middle byte
        ret nz
        inc (ix+#23)                    ; high byte
        ret
; ----------------------------------------------------------------------
; Subroutine: in_open_check [#DD1E]
; Tasks:        CAS IN OPEN: entry setup, IX = input header; error if a file is already open for input.
; Input:        IY = VDOS workspace
; Output:       IX = input header; IY = workspace; returns only if the input FCB is closed
; Changed:      AF, IX, IY
; Called by:    vdos_cas_in_open
; Calls:        ix_in_header, cas_entry_setup; error_not_open
in_open_check:
        ld a,(iy+#45)                   ; A = drive byte of the input FCB (&FF = closed)
        call ix_in_header               ; IX = input header
        jr open_check_closed            ; shared test
; ----------------------------------------------------------------------
; Subroutine: out_open_check [#DD26]
; Tasks:        CAS OUT OPEN: entry setup, IX = output header; error if a file is already open for output.
; Input:        IY = VDOS workspace
; Output:       IX = output header; IY = workspace
; Changed:      AF, IX, IY
; Called by:    vdos_cas_out_open
; Calls:        ix_out_header, cas_entry_setup; error_not_open
out_open_check:
        ld a,(iy+#69)                   ; A = drive byte of the output FCB (&FF = closed)
        call ix_out_header              ; IX = output header
open_check_closed:
        call cas_entry_setup            ; IY, error SP
        inc a                           ; &FF + 1 = 0: closed?
        ret z                           ; yes: go on opening
        jp error_not_open               ; no: error &0E (file already open)
; ----------------------------------------------------------------------
; Subroutine: ix_in_header [#DD34]
; Tasks:        IX = input header (workspace+&8D).
; Input:        IY = VDOS workspace
; Output:       IX; DE kept
; Changed:      F, IX
ix_in_header:
        ld ix,#008D                     ; offset of the input header
        jr ix_add_iy                    ; shared add
; ----------------------------------------------------------------------
; Subroutine: ix_out_header [#DD3A]
; Tasks:        IX = output header (workspace+&B3).
; Input:        IY = VDOS workspace
; Output:       IX; DE kept
; Changed:      F, IX
ix_out_header:
        ld ix,#00B3                     ; offset of the output header
ix_add_iy:
        push de
        push iy                         ; DE = IY ...
        pop de
        add ix,de                       ; IX = IY + offset
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: out_check_open [#DD46]
; Tasks:        Entry setup of the output routines: IX = output header; error &0E if no output file is open.
; Output:       IX = output header; IY = workspace; AF kept
; Changed:      F, IX, IY
; Called by:    vdos_cas_out_close, vdos_cas_out_abandon, vdos_cas_out_char, vdos_cas_out_direct
; Calls:        cas_entry_setup, ix_out_header; error_not_open
out_check_open:
        call cas_entry_setup            ; IY, error SP
        call ix_out_header              ; IX = output header
        push af
        ld a,(iy+#69)                   ; A = drive byte of the output FCB
check_fcb_open:
        inc a                           ; &FF + 1 = 0: not open?
        jp z,error_not_open             ; yes: error &0E
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: in_check_open [#DD56]
; Tasks:        Entry setup of the input routines: IX = input header; error &0E if no input file is open.
; Output:       IX = input header; IY = workspace; AF kept
; Changed:      AF, IX, IY
; Called by:    vdos_cas_in_close, vdos_cas_in_direct, in_char_get
; Calls:        cas_entry_setup, ix_in_header; error_not_open
in_check_open:
        call cas_entry_setup            ; IY, error SP
        call ix_in_header               ; IX = input header
        push af
        ld a,(iy+#45)                   ; A = drive byte of the input FCB
        jr check_fcb_open               ; the same test as for output
; ----------------------------------------------------------------------
; Subroutine: cas_entry_setup [#DD62]
; Tasks:        Common start of every CAS routine: IY = workspace, remember the SP of the
;               CAS routine's return (for cas_error_exit), clear the error code.
; Output:       IY = workspace; (iy+&23/24) = SP the error exit returns with; AF, HL kept
; Changed:      F, IY
; Called by:    in_open_check, out_open_check, in_check_open, out_check_open, cas_entry
; RAM:          &BE82 = 0 (last CAS error), &BE04 = &FF (meaning open)
cas_entry_setup:
        call load_workspace_iy          ; IY = VDOS workspace
        push hl
        ld hl,#0006                     ; SP + 6 (HL pushed, return to the check routine, return to the CAS routine) ...
        add hl,sp                       ; ... = address of the CAS routine's own return address
        ld (iy+#23),l                   ; save it: cas_error_exit loads SP from here and RETs to the CAS caller
        ld (iy+#24),h                   ; the SP for cas_error_exit
        pop hl
        push af
        xor a                           ; return code 0
        ld (#BE82),a                    ; &BE82 = 0: no error yet
        dec a                           ; xpb_cache_drive = &FF: look the drive tables up again
        ld (xpb_cache_drive),a          ; &BE04 = &FF (purpose not yet known)
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: cas_entry [#DD7C]
; Tasks:        cas_entry_setup for routines without a file (CAS CATALOG, |DIR).
; Changed:      F, IY
; Called by:    vdos_cas_catalog, rsx_dir
cas_entry:
        call cas_entry_setup            ; IY, error SP
        ret
; ----------------------------------------------------------------------
; Subroutine: rsx_two_params [#DD80]
; Tasks:        Common start of an RSX command with exactly two parameters (entry rsx_one_param:
;               exactly one): cas_entry_setup (IY, error SP), "Eingabefehler" for another number,
;               then fall through into rsx_string_param: B, HL = the LAST parameter's string
;               (IX+0 - BASIC passes the parameters last first), IX + 2 for the next one.
;               Observed: |ERA (one; none or two -> Eingabefehler), |ATTRIBUT (two).
; Input:        A = number of parameters, IX = parameters
; Output:       B = length, HL = text of the last parameter; IX + 2; IY = VDOS workspace
; Changed:      AF, HL, B, IX, IY
; Called by:    rsx_era, rsx_ren, rsx_attribut, ...
; Calls:        cas_entry_setup, error_bad_name; falls through into rsx_string_param
rsx_two_params:
        dec a                           ; two parameters: one less, then the same check as for one
rsx_one_param:
        call cas_entry_setup            ; IY = workspace, error SP (errors return to the RSX caller)
        dec a
        jp nz,error_bad_name            ; not the expected number: "Eingabefehler" (observed); else fall through into rsx_string_param
; ----------------------------------------------------------------------
; Subroutine: rsx_string_param [#DD88]
; Tasks:        Take the next RSX parameter as a BASIC string descriptor: B = length, HL = text.
; Input:        IX = parameter list
; Output:       B, HL; IX + 2
; Changed:      HL, B, IX
; Called by:    RSX commands with a file name
; Entered from: rsx_two_params (falls through)
; Calls:        rsx_param, load_hl_indirect
rsx_string_param:
        call rsx_param                  ; HL = descriptor address
        ld b,(hl)                       ; B = string length
        inc hl
        jp load_hl_indirect             ; HL = string address
; ----------------------------------------------------------------------
; Subroutine: rsx_param [#DD90]
; Tasks:        HL = the next parameter word from the RSX parameter list.
; Input:        IX
; Output:       HL; IX + 2
; Changed:      HL, IX
; Called by:    rsx_string_param, rsx_derror, rsx_cpm
rsx_param:
        ld l,(ix+#00)                   ; low byte ...
        inc ix
        ld h,(ix+#00)                   ; ... high byte
        inc ix
        ret
; ----------------------------------------------------------------------
; Subroutine: crypt_record [#DD9B]
; Tasks:        Code / decode a 128-byte record of a protected file (type bit 0) in place: each
;               byte XOR an 11-byte table (crypt_table) XOR a 13-byte table (crypt_table_13), or
;               with a |CODE string set (&BE79/&BE7A not 0) XOR that 2-byte code instead of the
;               11-byte table. The same operation codes and decodes. Observed with SAVE ,P and
;               LOAD of the protected file (no |CODE).
; Input:        DE = record (RAM)
; Changed:      AF, HL
; Called by:    read_records, write_records
; Calls:        RAM_LAM
crypt_record:
        push ix
        push bc
        push de
        push de                         ; the record pointer on the stack
        ld de,#0101                     ; D, E = counters of the two tables (1: start them at once)
        ld b,#80                        ; 128 bytes
cr_next_byte:
        dec d                           ; first table used up?
        jr nz,cr_second_table
        ld a,(code_key)                 ; a |CODE key (code_key)?
        ld d,a
        ld a,(code_key+1)
        or d
        jr z,cr_rom_table               ; no: the ROM table
        ld d,#02                        ; yes (observed with |CODE,12325): 2 key bytes ...
        ld ix,code_key                  ; ... from code_key (low, high, low, ...)
        jr cr_second_table              ; on with the 13-byte table
cr_rom_table:
        ld d,#0B                        ; 11 bytes ...
        ld ix,crypt_table               ; ... crypt_table
cr_second_table:
        dec e                           ; second table used up?
        jr nz,cr_crypt
        ld e,#0D                        ; yes: 13 bytes ...
        ld hl,crypt_table_13            ; ... crypt_table_13
cr_crypt:
        ex (sp),hl                      ; HL = record pointer ...
        rst #20                         ; RAM LAM; ... byte from RAM (RST 4: the ROMs are paged in)
        ex (sp),hl
        xor (ix+#00)                    ; XOR first table ...
        xor (hl)                        ; ... XOR second table
        ex (sp),hl
        ld (hl),a                       ; back into the record
        inc hl
        ex (sp),hl
        inc hl                          ; next byte of both tables
        inc ix
        djnz cr_next_byte
        pop de
        pop de
        pop bc
        pop ix
        ret
crypt_table_13:
        defb #E2,#9D,#DB,#1A            ; 13 bytes (second table)
        defb "B)9","F"+#80
        defb #B3,#C6,#90,#45,#8A
crypt_table:
        defb #49,#B1,#36,#F0,#2E,#1E,#06,#2A ; 11 bytes (first table, without |CODE)
        defb #28,#19,#EA
; ----------------------------------------------------------------------
; Subroutine: bdos_call_name [#DDF6]
; Tasks:        Calls of VDOS's internal BDOS functions (a small CP/M BDOS in the ROM):
;               HL = function body, DE = FCB. Stores the FCB address in &BE24 (here: the
;               current FCB; the same RAM holds the KM DISARM BREAK address during the boot),
;               clears the return code (iy+&21) and iy+&19, calls the body with bdos_return as
;               its return address. Entries: FCB = name FCB (+&25), input FCB (+&45), output
;               FCB (+&69), DE, or the FCB of the last call (bdos_call_again).
; Input:        HL = function body; IY = VDOS workspace
; Output:       A = return code (iy+&21)
; Changed:      DE, F
; Called by:    search_first, rename_file, read_record_in, write_record_out, open_file, ...
bdos_call_name:
        ld de,#0025                     ; FCB = name FCB
        jr bdos_call_offset
bdos_call_in:
        ld de,#0045                     ; FCB = input FCB
        jr bdos_call_offset
bdos_call_out:
        ld de,#0069                     ; FCB = output FCB
bdos_call_offset:
        call workspace_offset           ; DE = IY + offset
bdos_call_fcb:
        ld (bdos_fcb),de                ; current FCB
bdos_call_again:
        ld (iy+#19),#00                 ; (iy+&19) = 0: sequential/read flags cleared
        ld (iy+#21),#00                 ; return code 0
        ld de,bdos_return               ; the body returns through bdos_return ...
        push de
        push hl                         ; ... and is entered by RET
        ret
; Subroutine: bdos_return [#DE18] - return path of a BDOS function: restore FCB byte 0 (drive), A = return code.
; Changed:      HL, A
; Input:        IY = VDOS workspace
bdos_return:
        ld hl,(bdos_fcb)                ; current FCB
        ld a,(iy+#14)                   ; its drive byte back (bdos_select_fcb_drive put the user there)
        ld (hl),a                       ; (back into byte 0)
        ld a,(iy+#21)                   ; A = return code
        ret
; ----------------------------------------------------------------------
; Subroutine: bdos_select_fcb_drive [#DE23]
; Tasks:        Select the drive of the current FCB (after Digital Research's CP/M 2.2 BDOS routine reselect / selectdisk / initialize):
;               keep its drive byte (iy+&14) and put the current user there (the directory
;               compare includes it), SELDSK, copy the DPH's addresses (XLT, DIRBUF, DPB, CSV,
;               ALV) and the 15-byte DPB to &BE09-&BE23. On the first select of a drive
;               (workspace byte IY+drive = 0) log it in: clear the allocation vector, mark the
;               directory blocks, cdrmax = 3, and read the whole directory - each used entry
;               marks its blocks (scan_disk_map) and raises cdrmax. The allocation vector is
;               only rebuilt here: blocks given to a file whose extent was never written stay
;               used until the next login (observed after "Diskette voll"). Observed.
; Input:        IY = VDOS workspace
; Output:       error Eingabefehler for a bad drive
; Changed:      AF, BC, DE, HL, IX
; Called by:    the BDOS function bodies
; Calls:        dos_seldsk, shift_hl_right_3, bios_home, set_end_dir, read_dir, end_of_dir, get_dir_ptr, scan_disk_map, set_cdrmax
bdos_select_fcb_drive:
        ld hl,(bdos_fcb)                ; current FCB ...
        ld a,(hl)                       ; ... its drive byte ...
        ld (iy+#14),a                   ; ... kept
        ld c,(iy+#05)                   ; the current user ...
        ld (hl),c                       ; ... into byte 0 (compared with the directory entries' user byte)
        ld c,a                          ; C = drive
        push bc
        call #BE8F                      ; SELDSK
        ld a,h                          ; HL = 0: no such drive
        or l                            ; (HL = 0?)
        jr z,bsfd_bad_drive
        ld (bdos_dph),hl                ; bdos_dph
        ld e,(hl)                       ; XLT ...
        inc hl
        ld d,(hl)                       ; DE = XLT
        ld (bdos_xlt),de                ; ... bdos_xlt
        ld de,#0007                     ; DPH+8: DIRBUF, DPB, CSV, ALV ...
        add hl,de                       ; (DPH + 8)
        ld de,bdos_dirbuf               ; ... to &BE0D-&BE14
        ld bc,#0008                     ; 8 bytes
        ldir
        ld hl,(bdos_dpb)                ; the DPB (XPB) ...
        ld de,dpb_spt                   ; ... first 15 bytes to &BE15-&BE23
        ld bc,#000F                     ; 15 bytes
        ldir
        pop hl                          ; login byte of the drive: IY + drive
        ld h,#00                        ; HL = drive
        call iy_offset_hl               ; IY + drive
        ld a,(hl)                       ; login byte
        or a                            ; logged in already?
        ret nz                          ; yes: done
        dec (hl)                        ; now logged in (&FF)
login_drive:
        ld hl,(dpb_dsm)                 ; (also entered after a disc change) ALV size: DSM / 8 + 1 bytes ...
        call shift_hl_right_3           ; / 8
        inc hl
        ld b,h                          ; BC = bytes
        ld c,l
        ld hl,(bdos_alv)                ; ... cleared
        push hl
ld_clear:
        ld (hl),#00                     ; clear the ALV ...
        inc hl
        dec bc
        ld a,b                          ; (count)
        or c
        jr nz,ld_clear
        pop hl                          ; the directory blocks ...
        ld de,(dpb_al)                  ; ... (AL0/AL1) are used
        ld (hl),e                       ; AL0 ...
        inc hl
        ld (hl),d                       ; ... AL1
        call bios_home                  ; head to track 0
        ld hl,(bdos_dph)                ; cdrmax (DPH+2) = 3
        inc hl
        inc hl
        ld (hl),#03                     ; cdrmax = 3 ...
        inc hl
        ld (hl),#00                     ; ... (high byte)
        call set_end_dir                ; dir_count = &FFFF (before the first entry)
ld_scan:
        ld c,#FF                        ; next directory entry, C = &FF: set up its checksum
        call read_dir                   ; next entry
        call end_of_dir                 ; end of the directory?
        ret z                           ; yes: logged in
        call get_dir_ptr                ; the entry ...
        ld a,#E5                        ; ... unused (&E5)?
        cp (hl)                         ; unused?
        jr z,ld_scan                    ; yes: next
        ld c,#01                        ; no: mark its blocks as used ...
        call scan_disk_map              ; mark its blocks
        call set_cdrmax                 ; ... and note it in cdrmax
        jr ld_scan                      ; loop
bsfd_bad_drive:
        call bdos_return                ; no such drive: drive byte back into the FCB (observed: LOAD "C:X", C = 2) ...
        jr error_bad_name               ; ... "Eingabefehler" (observed; BASIC then shows "Break")
; ----------------------------------------------------------------------
; Subroutine: read_record_in [#DEAF]
; Tasks:        Read the next record of the input file to DE (BDOS read sequential).
; Input:        DE = destination; IY = VDOS workspace
; Output:       Z: ok; NZ: end of file
; Changed:      AF, HL
; Called by:    vdos_cas_in_open, read_records
; Calls:        set_dma_de, bdos_call_in
read_record_in:
        push bc
        push de
        call set_dma_de                 ; DMA = DE
        ld hl,read_seq_body             ; read sequential ...
        call bdos_call_in               ; ... on the input FCB
        or a                            ; Z = ok
        pop de
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: write_record_out [#DEBE]
; Tasks:        Write the record at DE to the output file (BDOS write sequential); directory full: error.
; Input:        DE = record; IY = VDOS workspace
; Changed:      AF, HL
; Called by:    out_write_header, out_flush_buffer, write_records
; Calls:        set_dma_de, bdos_call_out; error_dir_full
write_record_out:
        push bc
        push de
        call set_dma_de                 ; DMA = DE
        ld hl,write_seq_body            ; write sequential ...
        call bdos_call_out              ; ... on the output FCB
        dec a                           ; return code 1: no directory entry for a new extent ... (observed: 63 files + a file growing past 16K)
        jp z,error_dir_full             ; ... "Directory voll" (observed)
        pop de
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: set_dma_de [#DED0]
; Tasks:        DMA (record buffer of the disc routines) = DE; kept at &BE2A.
; Input:        DE
; Changed:      BC
; Calls:        dos_setdma
set_dma_de:
        ld c,e                          ; BC = DE ...
        ld b,d                          ; (BC = DE for SETDMA)
        ld (bdos_dma),de                ; ... remembered
        jr set_dma_bc                   ; SETDMA
set_dma_again:
        ld bc,(bdos_dma)                ; the last DMA address
set_dma_bc:
        jp #BE98                        ; set it
error_read_only:
        ld a,#19                        ; msg &19 "<name> hat Schreibschutz", name at DE (observed, from check_rodir)
        jr error_message
error_exists:
        ld a,#18                        ; msg &18 "<name> existiert bereits", name from the name FCB (not observed; used by |REN)
        jr error_with_name
; ----------------------------------------------------------------------
; Subroutine: error_not_found .. cas_error_exit [#DEE7]
; Tasks:        Error exits of the CAS routines. Print the message (unless messages_off),
;               then cas_error_exit: &BE82 = code, SP = the one saved by cas_entry_setup, RET:
;               straight back to the CAS caller with CY = 0, A = code (+&80 when the message
;               was printed). Codes = message numbers: &17 not found, &18 exists, &19 read-only,
;               &21 bad name (Eingabefehler), &15 disc full, &16 directory full; &0E (file not
;               open / open as the other kind) has no message.
; Input:        IY = VDOS workspace; A = code (entry error_message); DE = name for the message (entry error_with_name: the name FCB)
; Output:       CY = 0, A = error code
; Changed:      does not return to its caller: SP = the CAS caller's frame (cas_entry_setup), RET to the CAS caller
; Entered from: the CAS routines
; Calls:        print_message
error_not_found:
        ld a,#17                        ; msg &17: "<name> wurde nicht gefunden"
error_with_name:
        ld de,#0025                     ; DE = name FCB for <name>
        call workspace_offset           ; DE = name FCB
error_message:
        call test_messages_off          ; messages on?
        call z,print_message            ; yes: print it
error_disc_status:
        jr nz,error_exit_code           ; NZ: messages off - or a disc error from read_buffer (A = BIOS status; the BIOS asked already): exit with A (observed: N to "Diskette fehlt" - BASIC shows only Ready)
        or #80                          ; printed: code + &80
error_exit_code:
        call test_messages_off          ; A = code again
        jr cas_error_exit               ; (exit)
; Z = disc messages on (messages_off = 0); A kept.
test_messages_off:
        ld b,a                          ; keep the code
        ld a,(messages_off)             ; messages off?
        or a
        ld a,b                          ; code back (Z: messages off)
        ret
error_bad_name:
        ld a,#21                        ; msg &21: "Eingabefehler"
        jr error_message                ; print and exit
error_disc_full:
        ld a,#15                        ; msg &15: "Diskette voll" (observed: the blocks of the failed extent stay used in the ALV - CAT 0K/2K, a small SAVE fails too - until the drive is logged in again: after a reset or a disc change, observed)
        jr error_with_drive             ; with the drive
error_dir_full:
        ld a,#16                        ; msg &16: "Directory voll" (observed: SAVE of the 65th file - make_file found no empty entry; nothing is left on the disc)
error_with_drive:
        ld hl,(bdos_fcb)                ; C = the current FCB's drive (for <drive> in the message; observed: the output FCB, IY+&69) ...
        ld c,(hl)                       ; C = drive byte
        inc hl
        ex de,hl                        ; ... DE = its name
        jr error_message                ; print and exit
; ----------------------------------------------------------------------
; Routine: error_disc_changed [#DF17]
; Tasks:        The disc of an open file was changed (read_dir: directory checksum differs):
;               mark the file closed, log the drive out (login byte = 0) and end the CAS call
;               with message &0A "Laufwerk A: Diskette wurde gewechselt" / "TCH . wurde
;               geschlossen". BASIC still thinks the file is open: the next read gets error
;               &0E, which BASIC 1.0 reports as "EOF met".
;               Observed: OPENIN "TCH", disc changed, OPENOUT "TCH2" -> message, "Break".
; Input:        HL = workspace offset of the file's FCB (&45 / &69), IX = its header
; Entered from: read_dir
error_disc_changed:
        call iy_offset_hl               ; FCB address of the open file
        ld c,(hl)                       ; C = its drive byte
        ld (hl),#FF                     ; file closed (&FF)
        ex de,hl                        ; DE = FCB (for the name in the message)
        ld a,c
        push iy                         ; login byte of the drive (IY + drive) ...
        pop hl
        call add_a_hl
        ld (hl),#00                     ; ... = 0: logged out, the next access logs the new disc in
        ld a,#0A                        ; msg &0A: "Laufwerk <drive>: Diskette wurde gewechselt" / "<name> wurde geschlossen"
        jr error_message
error_not_open:
        ld a,#0E                        ; code &0E: file not open (or open as the other kind), no message
        or a                            ; CY = 0
cas_error_exit:
        ld (#BE82),a                    ; last CAS error
        ld l,(iy+#23)                   ; SP saved by cas_entry_setup ...
        ld h,(iy+#24)                   ; (high byte)
        ld sp,hl                        ; SP of the CAS caller's frame
        ret                             ; ... RET to the CAS caller
parse_filename_check:
        call parse_filename_fcb         ; parse (observed: |ERA), then the empty name check
        push af
pf_check_empty:
        ld a,(iy+#26)                   ; first name character a space?
        cp #20                          ; space: empty name
        jr z,error_bad_name             ; yes: "Eingabefehler"
        pop af                          ; CY = wildcards in the name
        ret
; ----------------------------------------------------------------------
; Subroutine: parse_filename [#DF46]
; Tasks:        Parse a file name into the name FCB (workspace+&25) with parse_filename_fcb;
;               no extension given: extension bytes = &FF (vdos_cas_in_open then tries the
;               extensions, vdos_cas_out_close picks one); an empty name is an error.
; Input:        HL = name (RAM), B = length; IY = VDOS workspace
; Output:       DE = name FCB; CY = wildcards (? or *)
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_in_open, vdos_cas_out_open, dir_start, RSX commands
; Calls:        parse_filename_fcb, error_bad_name
parse_filename:
        call parse_filename_fcb         ; parse into the name FCB
        push af                         ; keep the wildcard flag
        push de
        ld hl,#0009                     ; extension (FCB bytes 9-11) ...
        add hl,de                       ; (+9)
        push hl
        ld b,#03                        ; ... all three spaces?
        ld a,#20                        ; space?
pf_ext_loop:
        cp (hl)                         ; extension byte a space?
        pop de
        jr nz,pf_done                   ; no: an extension was given
        push de
        inc hl
        djnz pf_ext_loop                ; next
        ld b,#03                        ; yes: &FF &FF &FF = "no extension"
        ld a,#FF                        ; &FF ...
        pop de
pf_no_ext:
        ld (de),a                       ; ... into the 3 extension bytes
        inc de
        djnz pf_no_ext
pf_done:
        pop de
        jr pf_check_empty               ; empty name check
; ----------------------------------------------------------------------
; Subroutine: parse_filename_fcb [#DF68]
; Tasks:        Parse [d:]name[.ext] into the 32-byte name FCB (workspace+&25): drive byte
;               (given letter A-P - 'A', or the default drive iy+&06), 8 name and 3 extension
;               characters, upper case, padded with spaces; '*' fills the rest of the part with
;               '?'. Spaces before a part are skipped; a character below &20 or a drive that is
;               not a letter gives "Eingabefehler" - so "1:NAME" (AMSDOS user number) is
;               refused (observed). Delimiters (delimiter_table) end a part. A name longer than
;               8 characters is cut (observed: TOOLONGNAME -> TOOLONGN).
; Input:        HL = name (RAM), B = length; IY = VDOS workspace
; Output:       DE = name FCB; CY = wildcards
; Changed:      AF, BC, DE, HL
; Called by:    parse_filename, parse_filename_check
; Calls:        workspace_offset, clear_memory, next_nonspace, check_delimiter, copy_name_part, read_name_char
parse_filename_fcb:
        ld de,#0025                     ; DE = name FCB
        call workspace_offset           ; name FCB address
        push de
        push bc
        ld b,#20                        ; cleared (32 bytes)
        call clear_memory               ; cleared
        pop bc
        pop de
        push de
        push hl
        push bc
pff_find_colon:
        call next_nonspace              ; look for a ':' in the whole name ...
        jr nc,pff_default_drive         ; end of the name: no drive given
        cp #3A                          ; ':'?
        scf                             ; (CY)
        jr z,pff_drive_given            ; yes: a drive is given
        ld a,b                          ; more characters?
        or a                            ; characters left?
        jr nz,pff_find_colon            ; yes: go on searching
pff_default_drive:
        ld a,(iy+#06)                   ; no ':': default drive
        ld (de),a                       ; drive byte
        inc de
pff_drive_given:
        pop bc                          ; name pointer and length back
        pop hl
        jr nc,pff_name                  ; no drive given: the name
        call next_nonspace_checked      ; the drive letter ...
        sub #41                         ; ... A = 0, B = 1, ...
        cp #10                          ; ... only a letter A-P
        jp nc,error_bad_name            ; not a letter A-P
        ld (de),a                       ; drive byte
        inc de
        call read_name_char             ; the ':' must follow
        cp #3A                          ; ':' after the letter?
        jp nz,error_bad_name            ; no: error
pff_name:
        ld a,#08                        ; name: up to 8 characters
        call copy_name_part             ; copy the name part
pff_skip_to_dot:
        call next_char                  ; skip the rest of the name up to '.' ...
        push af
        cp #2E                          ; '.'?
        jr z,pff_extension              ; '.': the extension
        pop af
        jr c,pff_skip_to_dot            ; more characters: skip
        push af
pff_extension:
        pop af
        ld a,#03                        ; extension: up to 3 characters
        call copy_name_part             ; copy the extension part
        pop hl                          ; any '?' in name or extension?
        push hl
        inc hl
        ld a,#3F                        ; '?' ...
        ld bc,#000B                     ; ... in the 11 name bytes?
        cpir                            ; (search)
        scf                             ; CY = 0 ...
        ccf                             ; (...)
        pop de
        ret nz                          ; no: CY = 0
        scf                             ; yes: CY = 1
        ret
; ----------------------------------------------------------------------
; Subroutine: copy_name_part [#DFCC]
; Tasks:        Copy up to A characters of a name part to DE (spaces before it skipped; entry
;               cnp_next: not skipped), ending at a delimiter or the end; '*' fills the rest
;               with '?', else the rest is filled with spaces.
; Input:        A = length, HL/B = name, DE = FCB part
; Output:       DE after the part
; Changed:      AF, BC, DE, HL
; Called by:    parse_filename_fcb
; Calls:        next_nonspace_checked, next_char_checked
copy_name_part:
        push af
        call next_nonspace_checked      ; first character, spaces skipped
        jr cnp_check                    ; check it
cnp_next:
        push af
        call next_char_checked          ; next character
cnp_check:
        ld c,#20                        ; filler: space
        jr nc,cnp_fill                  ; end of the part: fill
        cp #2A                          ; '*'?
        ld c,#3F                        ; filler: '?'
        jr z,cnp_fill                   ; yes: fill with '?'
        ld (de),a                       ; store the character
        inc de
        pop af
        dec a                           ; room for more?
        jr nz,cnp_next                  ; next character
        ret
cnp_fill:
        pop af                          ; A = places left
        or a                            ; none left?
        ret z
        ex de,hl                        ; (DE = destination)
cnp_fill_loop:
        ld (hl),c                       ; fill them
        inc hl
        dec a                           ; fill
        jr nz,cnp_fill_loop             ; (count)
        ex de,hl                        ; (back)
        ret
; ----------------------------------------------------------------------
; Subroutine: next_nonspace [#DFF2]
; Tasks:        Next character of the name that is not a space.
; Input:        HL, B = rest of the name
; Output:       CY = 1: A = character; CY = 0: end
; Changed:      AF, HL, B
; Called by:    parse_filename_fcb, next_nonspace_checked
next_nonspace:
        call next_char                  ; next character
        ret nc
        cp #20                          ; space?
        scf                             ; no: CY = 1 with it
        ret nz
        jr next_nonspace                ; space: skip it (observed: LOAD "  EX2" - leading spaces are ignored)
; ----------------------------------------------------------------------
; Subroutine: next_char [#DFFC]
; Tasks:        Next character of the name (upper case), or the end.
; Input:        HL, B
; Output:       CY = 1: A = character (HL + 1, B - 1); CY = 0, A = 0: end
; Changed:      AF, HL, B
; Called by:    next_nonspace, next_char_checked
next_char:
        ld a,b                          ; characters left?
        or a
        ret z
        call read_name_char             ; read one
        scf                             ; CY = 1
        ret
; ----------------------------------------------------------------------
; Subroutine: read_name_char [#E004]
; Tasks:        Read a name character from RAM (RST 4), bit 7 off, upper case; control characters are "Eingabefehler".
; Input:        HL, B
; Output:       A; HL + 1, B - 1
; Changed:      AF, HL, B
; Called by:    next_char, parse_filename_fcb
; Calls:        to_upper, error_bad_name
read_name_char:
        rst #20                         ; RAM LAM; from RAM (the ROMs are paged in)
        and #7F                         ; attribute bit off
        cp #20                          ; control character?
        jp c,error_bad_name             ; yes: "Eingabefehler"
        inc hl
        dec b                           ; one less
        jp to_upper                     ; upper case
; ----------------------------------------------------------------------
; Subroutine: next_char_checked [#E011]
; Tasks:        Next character (next_char, entry next_nonspace_checked: next_nonspace) and test
;               it against delimiter_table: a delimiter ends the part and is left for the next
;               part.
; Input:        HL, B
; Output:       CY = 1: A = name character; CY = 0: end or delimiter
; Changed:      AF, HL, B
; Called by:    copy_name_part
next_char_checked:
        call next_char                  ; next character
        jr check_delimiter              ; delimiter check
next_nonspace_checked:
        call next_nonspace              ; next non-space character
check_delimiter:
        ret nc                          ; end of the name: CY = 0
        push hl
        push bc
        ld hl,delimiter_table           ; delimiters: count, characters
        ld b,(hl)                       ; B = number of delimiters
cd_loop:
        inc hl
        cp (hl)                         ; this one?
        jr z,cd_delimiter               ; equal: a delimiter
        djnz cd_loop                    ; next
        pop bc                          ; not a delimiter: CY = 1
        pop hl
        scf                             ; (CY = 1: a name character)
        ret
cd_delimiter:
        pop bc
        pop hl
        dec hl                          ; a delimiter: give it back (HL - 1, B + 1) ...
        inc b                           ; (one character more left)
        or a                            ; ... CY = 0
        ret
delimiter_table:
        defb #12,#5F,#7F                ; 18 delimiters: _ DEL % ( ) / } ] | \ { [ < > = : ; .
        defb "%()/}]|"
        defb #5C
        defb "{[<>=:;."
; ----------------------------------------------------------------------
; Subroutine: dm_position [#E043]
; Tasks:        Index in the FCB's disk map of the block holding virtual_record (after Digital Research's CP/M 2.2 BDOS routine dm_position): vrecord >> BSH + (extval << (7 - BSH)).
; Input:        IY = VDOS workspace
; Output:       A = index
; Changed:      AF, BC, HL
; Called by:    index_block, write_seq_body
dm_position:
        ld hl,dpb_bsh                   ; block shift ...
        ld b,(hl)                       ; B = block shift
        ld a,(virtual_record)           ; ... vrecord / records per block
dmp_shift:
        or a                            ; (vrecord shifted right ...)
        rra                             ; (...)
        djnz dmp_shift                  ; ... BSH times
        push af
        ld a,#08                        ; 8 - BSH ...
        sub (hl)                        ; 8 - BSH ...
        ld b,a                          ; ... B = shift count for extval
        ld a,(iy+#12)                   ; extval (extent within the FCB's extent group) ...
        jr dmp_ext_count                ; (count first)
dmp_ext_shift:
        or a                            ; extval shifted left
        rla                             ; (...)
dmp_ext_count:
        djnz dmp_ext_shift              ; count
        pop bc                          ; ... shifted + the block in the extent
        add a,b                         ; + the block in the extent
        ret
; ----------------------------------------------------------------------
; Subroutine: get_disk_map [#E05F]
; Tasks:        Disk map entry BC of the current FCB (one byte per block when DSM < 256, else two) (after Digital Research's CP/M 2.2 BDOS routine getdm).
; Input:        BC = index
; Output:       HL = block number
; Changed:      AF, DE, HL
; Called by:    index_block, write_seq_body
; Calls:        test_single_map
get_disk_map:
        ld hl,(bdos_fcb)                ; the FCB ...
        call test_single_map            ; Z: one byte per block
        ld de,#0010                     ; FCB disk map (bytes 16-31) ...
        add hl,de                       ; (+16: disk map)
        add hl,bc                       ; ... + index
        jr z,gdm_single                 ; single: one byte
        add hl,bc                       ; two bytes per entry - used for a disc format with DSM >= 256 (e.g. a driver that installs its own DPH / DPB); observed 2026-10-26 with a 2K-block DPB (DSM &15F), see test_single_map
        push hl
gdm_single:
        ld l,(hl)                       ; L = block (one byte)
        ld h,#00
        ret z
        pop bc
        inc bc
        ld a,(bc)
        ld h,a
        ret
; ----------------------------------------------------------------------
; Subroutine: index_block [#E077]
; Tasks:        actual_record = block number of virtual_record from the FCB's disk map (after Digital Research's CP/M 2.2 BDOS routine index).
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    read_seq_body, write_seq_body
; Calls:        dm_position, get_disk_map
index_block:
        call dm_position                ; index
        ld c,a                          ; BC = it
        ld b,#00
        call get_disk_map               ; its block number ...
        ld (actual_record),hl           ; ... = actual_record
        ret
; ----------------------------------------------------------------------
; Subroutine: test_allocated [#E084]
; Tasks:        Z if actual_record = 0 (the block is not allocated) (after Digital Research's CP/M 2.2 BDOS routine allocated).
; Output:       Z / NZ, HL
; Changed:      AF, HL
; Called by:    read_seq_body, write_seq_body
test_allocated:
        ld hl,(actual_record)           ; actual_record ...
        ld a,l                          ; ... 0?
        or h
        ret
; ----------------------------------------------------------------------
; Subroutine: block_to_record [#E08A]
; Tasks:        actual_record = block << BSH + (virtual_record AND BLM): the record number on the disc (after Digital Research's CP/M 2.2 BDOS routine atran).
; Changed:      AF, HL, C
; Called by:    read_seq_body, write_seq_body
; Calls:        shift_hl_left
block_to_record:
        ld a,(dpb_bsh)                  ; block shift ...
        ld c,a
        ld hl,(actual_record)           ; actual_record (block) ...
        call shift_hl_left              ; ... << BSH
        ld a,(dpb_blm)                  ; block mask ...
        ld c,a
        ld a,(virtual_record)           ; ... AND vrecord ...
        and c
        or l                            ; ... OR the record's low bits
        ld l,a
        ld (actual_record),hl           ; = record on the disc
        ret
; ----------------------------------------------------------------------
; Subroutine: get_extent_address [#E0A2]
; Tasks:        HL = address of the FCB's extent byte (FCB+12) (after Digital Research's CP/M 2.2 BDOS routine getexta).
; Output:       HL
; Changed:      DE, HL, F
; Called by:    many BDOS bodies
get_extent_address:
        ld hl,(bdos_fcb)                ; the FCB ...
        ld de,#000C                     ; ... + 12 (extent)
        add hl,de
        ret
; ----------------------------------------------------------------------
; Subroutine: get_fcb_counts [#E0AA]
; Tasks:        DE = address of the FCB's record count (rc, +15), HL = of its current record (cr, +32) (after Digital Research's CP/M 2.2 BDOS routine getfcba).
; Output:       DE, HL
; Changed:      DE, HL, F
; Called by:    get_fcb_values, set_fcb_values
get_fcb_counts:
        call get_extent_address
        inc hl                          ; (+3: rc at +15)
        inc hl
        inc hl
        ex de,hl                        ; DE = rc address
        ld hl,#0011                     ; + 17 = cr at +32
        add hl,de
        ret
; ----------------------------------------------------------------------
; Subroutine: get_fcb_values [#E0B6]
; Tasks:        Load virtual_record (cr), record_count (rc) and extval (extent AND EXM, iy+&12) from the FCB (after Digital Research's CP/M 2.2 BDOS routine getfcb).
; Input:        IY = VDOS workspace
; Changed:      AF, DE, HL
; Called by:    read_seq_body, write_seq_body, open_next_extent
; Calls:        get_fcb_counts, get_extent_address
get_fcb_values:
        call get_fcb_counts             ; DE = rc, HL = cr
        ld a,(hl)                       ; cr ...
        ld (virtual_record),a           ; ... = virtual_record
        ld a,(de)                       ; rc ...
        ld (record_count),a             ; ... = record_count
        call get_extent_address         ; extent ...
        ld a,(dpb_exm)                  ; ... AND EXM ...
        and (hl)
        ld (iy+#12),a                   ; ... = extval
        ret
; ----------------------------------------------------------------------
; Subroutine: dir_entry_offset [#E0CC]
; Tasks:        A = offset of entry dir_count in its directory record: (dir_count AND 3) * 32.
; Output:       A (Z: first entry of a record)
; Changed:      AF, B
; Called by:    get_dir_ptr, read_dir
dir_entry_offset:
        ld a,(dir_count)                ; dir_count low ...
        and #03                         ; ... AND 3 = entry in the record ...
        ld b,#05                        ; ... * 32
deo_shift:
        add a,a                         ; (shift)
        djnz deo_shift
        ret
; ----------------------------------------------------------------------
; Subroutine: check_rodir [#E0D7]
; Tasks:        Error "<name> hat Schreibschutz" if the directory entry found (entry check_rofile:
;               the FCB at HL) has the R/O attribute (extension byte 1, bit 7) (after Digital Research's CP/M 2.2 BDOS routine check_rodir / check_rofile).
;               Observed: SAVE of a name whose old file is R/O - the rename to .BAK (rename_body) stops here.
; Changed:      AF, DE, HL, B
; Called by:    rename_body, delete_body, write_seq_body (FCB)
; Calls:        get_dir_ptr, error_read_only
check_rodir:
        call get_dir_ptr
check_rofile:
        ld de,#0009                     ; R/O attribute (FCB / entry byte 9, bit 7)?
        add hl,de
        bit 7,(hl)
        ret z                           ; no: ok
        or a                            ; yes: CY = 0 for the SBC ... (observed: SAVE over an R/O file, from rename_body)
        ld de,#0009                     ; ... back from byte 9 to the entry's start ...
        sbc hl,de
        ex de,hl                        ; ... DE = the directory entry: its name for the message
        jp error_read_only              ; "<name> hat Schreibschutz" (observed: "RO      .BAS hat Schreibschutz", "Break")
; ----------------------------------------------------------------------
; Subroutine: get_dir_ptr [#E0EB]
; Tasks:        HL = address of directory entry dir_count in the directory buffer (after Digital Research's CP/M 2.2 BDOS routine getdptra).
; Output:       HL, A = offset
; Changed:      AF, HL, B
; Called by:    many BDOS bodies
; Calls:        dir_entry_offset, add_a_hl; falls through into add_a_hl
get_dir_ptr:
        ld hl,(bdos_dirbuf)             ; directory buffer ...
        call dir_entry_offset           ; ... + entry offset
; ----------------------------------------------------------------------
; Subroutine: add_a_hl [#E0F1]
; Tasks:        HL = HL + A.
; Input:        A, HL
; Output:       HL
; Changed:      HL
; Called by:    get_dir_ptr, write_seq_body, error_disc_changed
add_a_hl:
        push af
        add a,l                         ; HL + A ...
        ld l,a
        jr nc,aah_done                  ; (carry)
        inc h                           ; (...)
aah_done:
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: get_module [#E0F9]
; Tasks:        HL = address of the FCB's module byte s2 (+14), A = its value (after Digital Research's CP/M 2.2 BDOS routine getmodnum). Bit 7 = file write flag (set: nothing written since open).
; Output:       A, HL
; Changed:      AF, DE, HL
; Called by:    clear_module, set_file_write_flag, close_extent, write_seq_body
get_module:
        ld hl,(bdos_fcb)                ; the FCB ...
        ld de,#000E                     ; ... + 14 (module s2)
        add hl,de
        ld a,(hl)                       ; A = it
        ret
; ----------------------------------------------------------------------
; Subroutine: clear_module [#E102]
; Tasks:        FCB module byte = 0 (after Digital Research's CP/M 2.2 BDOS routine clrmodnum).
; Changed:      AF, DE, HL
; Called by:    open_body, make_body, search_first_body
clear_module:
        call get_module
        ld (hl),#00                     ; module = 0
        ret
; ----------------------------------------------------------------------
; Subroutine: set_file_write_flag [#E108]
; Tasks:        Set bit 7 of the FCB's module byte: not written since open (after Digital Research's CP/M 2.2 BDOS routine setfwf).
;               *** BUG: DR's setfwf sets the bit with ORI, which also clears Z (the result is not 0);
;               SET 7,(HL) here leaves the flags alone. random_seek's error exit (&E678) relies on NZ
;               so that read_random_body / write_random_body skip the transfer; with Z still set they
;               read anyway and overwrite the error code &FF with 1, so |GET never reports "Record
;               leer" (observed; simulated with Z cleared at &E5ED, see rsx_get).
;               *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): at &E678 jp &ED12 instead of jp
;               set_file_write_flag, and at &ED12 (14 free NOPs): call get_module / ld a,(hl) /
;               or #80 / ld (hl),a / ret (8 bytes; NZ like DR). Only the error exit changes.
; Changed:      AF, DE, HL
; Called by:    open_copy, make_entry, open_next_extent; random_seek's error exit (jp at &E678)
set_file_write_flag:
        call get_module
        set 7,(hl)                      ; not written since open
        ret
; ----------------------------------------------------------------------
; Subroutine: compare_cdrmax [#E10E]
; Tasks:        CY if dir_count < cdrmax (DPH+2: entries in use up to there) (after Digital Research's CP/M 2.2 BDOS routine compcdr).
; Output:       CY, DE = dir_count, HL = DPH+3
; Changed:      AF, DE, HL
; Called by:    set_cdrmax, search_next_entry, dir_checksum
compare_cdrmax:
        ld de,(dir_count)               ; DE = dir_count
        ld hl,(bdos_dph)                ; DPH ...
        inc hl                          ; ... +2: cdrmax
        inc hl
        ld a,e                          ; dir_count - cdrmax
        sub (hl)
        inc hl
        ld a,d                          ; (high bytes)
        sbc a,(hl)
        ret
; ----------------------------------------------------------------------
; Subroutine: set_cdrmax [#E11D]
; Tasks:        cdrmax = dir_count + 1 if dir_count >= cdrmax (after Digital Research's CP/M 2.2 BDOS routine setcdr).
; Changed:      AF, DE, HL
; Called by:    bdos_select_fcb_drive (login), make_entry
; Calls:        compare_cdrmax
set_cdrmax:
        call compare_cdrmax             ; dir_count < cdrmax?
        ret c                           ; below: done
        inc de                          ; cdrmax = dir_count + 1
        ld (hl),d                       ; (high byte)
        dec hl
        ld (hl),e                       ; (low byte)
        ret
; ----------------------------------------------------------------------
; Subroutine: sub_de_hl [#E126]
; Tasks:        HL = DE - HL, CY = borrow (after Digital Research's CP/M 2.2 BDOS routine subdh).
; Input:        DE, HL
; Output:       HL, CY
; Changed:      AF, HL
; Called by:    dir_checksum, read_dir
sub_de_hl:
        push de                         ; (keep DE)
        or a                            ; (CY = 0)
        ex de,hl                        ; HL = DE, DE = HL ...
        sbc hl,de                       ; ... HL = DE - HL
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: new_checksum [#E12D]
; Tasks:        Directory record checksum (entry dir_checksum, C = &FF: store it): for records
;               below CKS compare the sum of the record in the buffer with the checksum vector,
;               or store it. A difference (inside cdrmax) means the disc was changed.
;               (after Digital Research's CP/M 2.2 BDOS routine newchecksum / checksum)
; Input:        C = &FF store, else compare
; Output:       CY = 1 ok / stored; CY = 0 checksum differs
; Changed:      AF, DE, HL, C
; Called by:    write_dir (store), read_dir
; Calls:        dir_record, sub_de_hl, dirbuf_sum, compare_cdrmax
new_checksum:
        ld c,#FF                        ; C = &FF: store
dir_checksum:
        call dir_record                 ; the directory record number ...
        ex de,hl
        ld hl,(dpb_cks)                 ; ... below CKS?
        call sub_de_hl
        ccf                             ; no: not checked, ok
        ret c
        push bc
        call dirbuf_sum                 ; A = sum of the record
        ld de,(bdos_csv)                ; CSV ...
        call dir_record
        add hl,de                       ; ... + record number
        pop bc
        inc c                           ; C = &FF: store
        jr nz,dcs_compare
        ld (hl),a                       ; (login, directory write)
        scf
        ret
dcs_compare:
        cp (hl)                         ; compare
        scf
        ret z                           ; equal: ok
        call compare_cdrmax             ; (not observed) different: beyond cdrmax it does not count
        ccf
        ret
; ----------------------------------------------------------------------
; Subroutine: set_dma_dirbuf [#E156]
; Tasks:        DMA = the directory buffer (after Digital Research's CP/M 2.2 BDOS routine setdir).
; Changed:      BC
; Called by:    write_dir, read_dir
; Calls:        dos_setdma
set_dma_dirbuf:
        ld bc,(bdos_dirbuf)
        jp #BE98                        ; SETDMA
; ----------------------------------------------------------------------
; Subroutine: end_of_dir [#E15D]
; Tasks:        Z if dir_count = &FFFF: end of the directory / nothing found (after Digital Research's CP/M 2.2 BDOS routine end_of_dir).
; Output:       Z
; Changed:      AF, HL
; Called by:    many BDOS bodies
end_of_dir:
        ld hl,(dir_count)               ; dir_count ...
        inc hl                          ; ... + 1 = 0?
        ld a,h
        or l
        ret
; ----------------------------------------------------------------------
; Subroutine: set_end_dir [#E164]
; Tasks:        dir_count = &FFFF (after Digital Research's CP/M 2.2 BDOS routine set_end_dir).
; Changed:      HL
; Called by:    login, search, read_dir
set_end_dir:
        ld hl,#FFFF                     ; &FFFF ...
        ld (dir_count),hl               ; ... = dir_count
        ret
; ----------------------------------------------------------------------
; Subroutine: get_alloc_bit [#E16B]
; Tasks:        Bit of block DE in the allocation vector, rotated into bit 0 (after Digital Research's CP/M 2.2 BDOS routine getallocbit).
; Input:        DE = block
; Output:       A (bit 0), HL = ALV byte, B = rotations
; Changed:      AF, BC, DE, HL
; Called by:    set_alloc_bit, get_block
; Calls:        shift_hl_right_3
get_alloc_bit:
        ld a,e                          ; bit number in the byte + 1
        and #07
        inc a
        ld c,a                          ; ... C = B = rotations
        ld b,a
        ex de,hl                        ; byte = block / 8 ...
        call shift_hl_right_3           ; ... / 8 = byte
        ex de,hl
        ld hl,(bdos_alv)                ; ... in the ALV
        add hl,de
        ld a,(hl)                       ; the byte
gab_rotate:
        rlca                            ; rotate the bit into bit 0
        djnz gab_rotate
        ld b,c                          ; B = rotations (for the way back)
        ret
; ----------------------------------------------------------------------
; Subroutine: set_alloc_bit [#E180]
; Tasks:        Set block BC's bit in the allocation vector to E (0 free, 1 used) (after Digital Research's CP/M 2.2 BDOS routine setallocbit). Entry sab_rotate: A with the new bit 0, B rotations back.
; Input:        BC = block, E = 0/1
; Changed:      AF, BC, HL
; Called by:    scan_disk_map, get_block
; Calls:        get_alloc_bit
set_alloc_bit:
        push de                         ; keep the value E
        ld e,c                          ; DE = block
        ld d,b
        call get_alloc_bit              ; its bit in bit 0
        and #FE                         ; cleared ...
        pop de                          ; (value)
        or e                            ; ... set to E
sab_rotate:
        rrca                            ; rotate back ...
        djnz sab_rotate
        ld (hl),a                       ; ... into the ALV
        ret
; ----------------------------------------------------------------------
; Subroutine: scan_disk_map [#E18F]
; Tasks:        Mark the blocks of the directory entry dir_count as used (C = 1) or free (C = 0) (after Digital Research's CP/M 2.2 BDOS routine scandm).
; Input:        C = 1 / 0
; Changed:      AF, BC, DE, HL
; Called by:    login, delete_body
; Calls:        get_dir_ptr, test_single_map, set_alloc_bit
scan_disk_map:
        call get_dir_ptr
        ld de,#0010                     ; its disk map (bytes 16-31)
        add hl,de
        push bc
        ld c,#11                        ; 16 entries
sdm_next:
        pop de
        dec c                           ; all 16?
        ret z
        push de                         ; (keep the count)
        call test_single_map            ; one byte per block?
        jr nz,sdm_double
        push bc                         ; yes: BC = block
        push hl
        ld c,(hl)                       ; (C = block, B = 0)
        ld b,#00
        jr sdm_block
sdm_double:
        dec c                           ; two bytes per block - for a format with DSM >= 256 (observed with the 2K-block DPB: login / SAVE / ERA), see test_single_map
        push bc
        ld c,(hl)
        inc hl
        ld b,(hl)
        push hl
sdm_block:
        ld a,c                          ; block 0 = unused entry
        or b
        jr z,sdm_skip
        ld hl,(dpb_dsm)                 ; a valid block (<= DSM)?
        ld a,l                          ; block <= DSM?
        sub c
        ld a,h
        sbc a,b                         ; (...)
        call nc,set_alloc_bit           ; yes: mark it
sdm_skip:
        pop hl                          ; next map byte
        inc hl
        pop bc
        jr sdm_next                     ; loop
; ----------------------------------------------------------------------
; Subroutine: set_attributes [#E1C2]
; Tasks:        BDOS set file attributes (Digital Research CP/M 2.2 BDOS function 30, setattr):
;               write bytes 0-11 of the name FCB (drive/user, name, extension with the attribute
;               bits) into every directory entry that matches it, and write the directory.
;               Observed (|ATTRIBUT). The earlier name delete_matching (research: "|ERA") was wrong:
;               nothing is deleted, and |ERA uses delete_file.
; Input:        the name FCB (workspace+&25); IY = VDOS workspace
; Output:       A = return code + 1 (0 = not found: Z)
; Changed:      AF, DE, HL
; Called by:    rsx_attribut
; Calls:        bdos_call_name with set_attributes_body
set_attributes:
        ld hl,set_attributes_body       ; the body ...
        jr bdos_name_call               ; ... on the name FCB, A + 1
; ----------------------------------------------------------------------
; Subroutine: rename_file [#E1C7]
; Tasks:        BDOS rename: name FCB (old name, new name at +16).
; Input:        IY = VDOS workspace
; Changed:      AF, DE, HL
; Called by:    out_rename
; Calls:        bdos_call_name
rename_file:
        ld hl,rename_body               ; rename body
bdos_name_call:
        call bdos_call_name             ; call the body on the name FCB
        inc a
        ret
set_attributes_body:
        call bdos_select_fcb_drive      ; select the drive (observed)
        call search_ext                 ; search name and extension (12 bytes; attribute bits ignored)
sa_loop:
        call end_of_dir                 ; end of the directory?
        ret z                           ; yes: done
        ld c,#00                        ; from FCB byte 0 ...
        ld e,#0C                        ; ... 12 bytes (drive/user, name, extension) ...
        call copy_dir                   ; ... into the entry, write the directory record
        call search_next_entry          ; next matching entry (the other extents)
        jr sa_loop                      ; loop
; ----------------------------------------------------------------------
; Subroutine: rename_body [#E1E5]
; Tasks:        BDOS rename (after Digital Research's CP/M 2.2 BDOS routine rename): for every entry matching the old
;               name (FCB bytes 0-11) copy the new name (FCB bytes 16-27, drive byte set to the
;               old one's) into it and write the directory. Observed (out_rename).
; Input:        IY = VDOS workspace
; Output:       return code = dirloc (&FF: not found)
; Changed:      AF, BC, DE, HL, IX
; Called by:    rename_file (through bdos_call_name)
; Calls:        bdos_select_fcb_drive, search_ext, end_of_dir, check_rodir, copy_dir, search_next_entry
rename_body:
        call bdos_select_fcb_drive
        call search_ext                 ; search name, type and extent mask (12 bytes)
        ld hl,(bdos_fcb)                ; the old drive/user byte ...
        ld a,(hl)
        ld de,#0010
        add hl,de
        ld (hl),a                       ; ... also for the new name
rn_loop:
        call end_of_dir
        jp z,return_dirloc              ; no (more) entry: return dirloc
        call check_rodir                ; R/O entry: error
        ld c,#10                        ; copy the new name (12 bytes from FCB+16) ...
        ld e,#0C
        call copy_dir                   ; ... into the entry, write the directory
        call search_next_entry          ; next matching entry
        jr rn_loop
; ----------------------------------------------------------------------
; Subroutine: search_first [#E209]
; Tasks:        BDOS search first on the name FCB.
; Input:        IY = VDOS workspace
; Output:       Z: not found; NZ: found (entry in the directory record)
; Changed:      AF, DE, HL
; Called by:    vdos_cas_in_open, out_rename, dir_start
; Calls:        bdos_call_name
search_first:
        ld hl,search_first_body         ; function body
        call bdos_call_name
        inc a                           ; &FF + 1 = 0: not found
        ret
; ----------------------------------------------------------------------
; Subroutine: search_first_body [#E211]
; Tasks:        BDOS search first (after Digital Research's CP/M 2.2 BDOS routine searchfirst): module byte 0 unless the
;               extent is '?', select the drive, search with 15 bytes (name, type, extent, s1, s2).
; Input:        IY = VDOS workspace
; Output:       return code = entry 0-3 in the record, &FF none
; Changed:      AF, BC, DE, HL, IX
; Called by:    search_first (through bdos_call_name)
; Calls:        get_extent_address, clear_module, bdos_select_fcb_drive, search_name
search_first_body:
        call get_extent_address
        ld a,(hl)                       ; extent byte '?'?
        cp #3F
        call nz,clear_module
        call bdos_select_fcb_drive      ; select the FCB's drive
        jr search_name                  ; search 15 bytes
; ----------------------------------------------------------------------
; Subroutine: search_next [#E21F]
; Tasks:        BDOS search next (same FCB).
; Input:        IY = VDOS workspace
; Output:       Z: no more
; Changed:      AF, DE, HL
; Called by:    vdos_cas_catalog, rsx_dir
; Calls:        bdos_call_again
search_next:
        ld hl,search_next_body          ; body: search next
        call bdos_call_again            ; on the FCB of the running search
        inc a                           ; &FF + 1 = 0: Z = no more
        ret
; ----------------------------------------------------------------------
; Subroutine: search_next_body [#E227]
; Tasks:        BDOS search next: the FCB of the running search (iy+&16/&17) again, then search_next_entry.
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL, IX
; Called by:    search_next (through bdos_call_again)
; Calls:        bdos_select_fcb_drive, search_next_entry
search_next_body:
        ld l,(iy+#16)                   ; the FCB of the running search ...
        ld h,(iy+#17)
        ld (bdos_fcb),hl                ; ... is the current FCB again
        call bdos_select_fcb_drive      ; select its drive
        jr search_next_entry            ; search on
; ----------------------------------------------------------------------
; Subroutine: search_ext [#E235]
; Tasks:        Start a directory search for the current FCB (after Digital Research's CP/M 2.2 BDOS routine search): compare C bytes
;               (search_ext 12: name, type, extent; search_name 15: + s1, s2), '?' matches any
;               character, the extent is compared with EXM masked; FCB byte 0 = &E5 finds an
;               empty entry. dirloc = &FF, from the first entry.
;               Workspace (IY) fields of the BDOS: +&00/+&01 drive A/B logged in (&FF), +&12 extval,
;               +&13 search length, +&14 the FCB's drive byte (bdos_return puts it back), +&16/&17
;               FCB of the running search, +&18 FCB copied to the directory, +&19 bit 2 read mode,
;               bit 3 sequential, +&1A dirloc, +&1B disk map index, +&21 return code (lret).
; Input:        C = compare length (search); IY = VDOS workspace
; Output:       return code (iy+&21) = entry number in its record (0-3) or &FF; dir_count
; Changed:      AF, BC, DE, HL, IX
; Called by:    the BDOS bodies
; Calls:        set_end_dir, bios_home, read_dir, end_of_dir, compare_cdrmax, get_dir_ptr
search_ext:
        ld c,#0C                        ; 12 bytes (name, type, extent)
        jr search
search_name:
        ld c,#0F                        ; 15 bytes
search:
        ld (iy+#13),c                   ; search length
        ld (iy+#1A),#FF                 ; dirloc = &FF
        ld hl,(bdos_fcb)                ; the FCB of this search (search next uses it)
        ld (iy+#16),l
        ld (iy+#17),h
        call set_end_dir                ; from before the first entry ...
        call bios_home                  ; ... head to the directory
search_next_entry:
        ld c,#00                        ; next entry (C = 0: compare the checksum)
        call read_dir
        call end_of_dir                 ; end of the directory: not found
        jr z,sne_not_found
        ld e,(iy+#16)                   ; searching an empty entry?
        ld d,(iy+#17)
        ld a,(de)
        cp #E5
        jr z,sne_compare                ; yes: every entry counts
        push de
        call compare_cdrmax             ; beyond the last used entry (cdrmax)?
        pop de
        jr nc,sne_not_found             ; yes: not found
sne_compare:
        call get_dir_ptr
        ld c,(iy+#13)                   ; compare length
        ld b,#00
sne_byte:
        ld a,c                          ; all compared?
        or a
        jr z,sne_found                  ; yes: found
        ld a,(de)                       ; FCB byte '?': matches
        cp #3F
        jr z,sne_byte_ok
        ld a,b
        cp #0D                          ; byte 13 (s1): not compared
        jr z,sne_byte_ok
        cp #0C                          ; byte 12: the extent
        ld a,(de)
        jr z,sne_extent
        sub (hl)                        ; other bytes: equal apart from bit 7 (attributes)?
        and #7F
        jr nz,search_next_entry         ; no: next entry
        jr sne_byte_ok
sne_extent:
        push bc                         ; extent: compare with the extent mask ...
        ld c,(hl)
        push bc
        push af
        ld a,(dpb_exm)                  ; EXM ...
        cpl                             ; ... inverted: the extent bits that must match
        ld b,a
        ld a,c                          ; directory extent ...
        and b                           ; ... masked
        ld c,a
        pop af
        and b                           ; FCB extent masked ...
        sub c                           ; ... minus the directory's
        and #1F                         ; ... (5 bits)
        pop bc
        pop bc
        jr nz,search_next_entry         ; different: next entry
sne_byte_ok:
        inc de                          ; next byte
        inc hl
        inc b                           ; (index)
        dec c                           ; (count)
        jr sne_byte                     ; loop
sne_found:
        ld a,(dir_count)                ; found: return code = entry number in the record (0-3)
        and #03
        ld (iy+#21),a                   ; ... = return code
        ld hl,#001A                     ; dirloc ...
        call iy_offset_hl               ; dirloc ...
        ld a,(hl)                       ; (...)
        rla                             ; ... first find: clear it
        ret nc                          ; not the first find
        xor a
        ld (hl),a                       ; dirloc = 0
        ret
sne_not_found:
        call set_end_dir                ; not found: dir_count = &FFFF ...
        ld a,#FF                        ; ... return code &FF
        jr set_return_code
return_dirloc:
        ld a,(iy+#1A)                   ; return code = dirloc
        jr set_return_code              ; set it
; ----------------------------------------------------------------------
; Subroutine: set_return_1 [#E2CA]
; Tasks:        Return code (iy+&21) = 1 (end of file / no space); entry set_return_code: = A.
; Input:        IY = VDOS workspace
; Changed:      A
; Called by:    read_seq_body, write_seq_body, open_next_extent
set_return_1:
        ld a,#01                        ; return code 1
set_return_code:
        ld (iy+#21),a                   ; lret
        ret
; ----------------------------------------------------------------------
; Subroutine: delete_file [#E2D0]
; Tasks:        BDOS delete file (FCB at DE).
; Input:        DE = FCB; IY = VDOS workspace
; Changed:      AF, DE, HL
; Called by:    vdos_cas_out_open, out_rename
; Calls:        bdos_call_fcb
delete_file:
        push de
        ld hl,delete_body               ; delete body
        jr bdos_fcb_call
; ----------------------------------------------------------------------
; Subroutine: close_file [#E2D6]
; Tasks:        BDOS close file (FCB at DE).
; Input:        DE = FCB; IY = VDOS workspace
; Changed:      AF, DE, HL
; Called by:    vdos_cas_out_close, out_write_header
; Calls:        bdos_call_fcb
close_file:
        push de
        ld hl,close_body                ; close body
        jr bdos_fcb_call
; ----------------------------------------------------------------------
; Subroutine: open_file [#E2DC]
; Tasks:        BDOS open file (FCB at DE).
; Input:        DE = FCB; IY = VDOS workspace
; Changed:      AF, HL
; Called by:    vdos_cas_in_open, out_write_header
; Calls:        bdos_call_fcb
open_file:
        push de
        ld hl,open_body                 ; open body
bdos_fcb_call:
        call bdos_call_fcb              ; call the body on FCB DE; return code &FF + 1 = 0: Z
        inc a                           ; &FF + 1 = 0: Z = not found
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: delete_body [#E2E6]
; Tasks:        BDOS delete (after Digital Research's CP/M 2.2 BDOS routine delete): every entry matching the FCB (12
;               bytes) is marked unused (&E5), its blocks freed in the ALV, and the directory
;               written. Observed (out_rename: an old .BAK).
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL, IX
; Called by:    delete_file (through bdos_call_fcb)
; Calls:        bdos_select_fcb_drive, search_ext, end_of_dir, check_rodir, get_dir_ptr, scan_disk_map, write_dir, search_next_entry
delete_body:
        call bdos_select_fcb_drive
        call search_ext
del_loop:
        call end_of_dir                 ; end of the directory?
        jp z,return_dirloc              ; no (more) entry
        call check_rodir                ; R/O: error
        call get_dir_ptr
        ld (hl),#E5                     ; entry unused
        ld c,#00                        ; its blocks free again
        call scan_disk_map
        call write_dir                  ; write the directory record
        call search_next_entry          ; next matching entry
        jr del_loop
; ----------------------------------------------------------------------
; Subroutine: get_block [#E307]
; Tasks:        Find a free block as close as possible to block BC (alternately below and
;               above it), mark it used (after Digital Research's CP/M 2.2 BDOS routine get_block).
; Input:        BC = block near which to allocate
; Output:       HL = block, 0: disc full
; Changed:      AF, BC, DE, HL
; Called by:    write_seq_body
; Calls:        get_alloc_bit, sab_rotate
get_block:
        ld d,b                          ; DE = right pointer, BC = left pointer
        ld e,c
gb_left:
        ld a,c                          ; left at 0?
        or b                            ; left = 0?
        jr z,gb_right
        dec bc                          ; one block down
        push de                         ; (right, left kept)
        push bc
        ld e,c                          ; DE = left
        ld d,b
        call get_alloc_bit              ; its bit
        bit 0,a                         ; free?
        jr z,gb_take                    ; free: take it
        pop bc                          ; (back)
        pop de
gb_right:
        ld hl,(dpb_dsm)                 ; right at DSM?
        ld a,e                          ; right ...
        sub l
        ld a,d
        sbc a,h                         ; ... < DSM?
        jr c,gb_up                      ; no: go up
        ld a,c                          ; left not at 0: go on
        or b                            ; (left > 0?)
        jr nz,gb_left                   ; search on
        ld hl,#0000                     ; no free block: 0
        ret
gb_up:
        inc de                          ; one block up
        push bc                         ; (left, right kept)
        push de
        call get_alloc_bit              ; its bit
        bit 0,a                         ; free?
        jr z,gb_take                    ; free: take it
        pop de
        pop bc
        jr gb_left                      ; search on
gb_take:
        set 0,a                         ; take it: mark used
        call sab_rotate                 ; set it (sab_rotate)
        pop hl                          ; HL = the block
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: copy_fcb [#E342]
; Tasks:        Copy the whole FCB (32 bytes; entry copy_dir: E bytes from FCB+C) into the
;               directory entry dir_count and write the directory record (after Digital Research's CP/M 2.2 BDOS routine copy_fcb / copy_dir).
;               Entries seek_copy (write the record of dir_count), write_dir (write the buffer).
; Input:        copy_dir: C = FCB offset, E = length; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    make_entry, rename_body, close_extent
; Calls:        get_dir_ptr, seek_dir, new_checksum, set_dma_dirbuf, write_buffer, set_dma_again
copy_fcb:
        ld c,#00                        ; C = 0 (from byte 0) ...
        ld e,#20                        ; ... 32 bytes
copy_dir:
        push de
        call get_dir_ptr                ; HL = the directory entry
        ex de,hl                        ; DE = it
        ld b,#00
        ld hl,(bdos_fcb)                ; FCB + C ...
        add hl,bc
        pop bc                          ; BC = length
        ld b,#00
        ldir                            ; copy into the entry
seek_copy:
        call seek_dir                   ; directory record of dir_count
write_dir:
        call new_checksum               ; store its checksum
        call set_dma_dirbuf             ; DMA = directory buffer
        ld c,#01                        ; write type 1: directory (written at once)
        call write_buffer
        jp set_dma_again                ; the caller's DMA again
; ----------------------------------------------------------------------
; Subroutine: open_body [#E367]
; Tasks:        BDOS open (after Digital Research's CP/M 2.2 BDOS routine open): module 0, search the name (15 bytes),
;               copy the entry into the FCB (open_copy) with the FCB's own extent byte; if the
;               entry is a later extent than asked, rc = 128 (full extent). Observed.
; Input:        IY = VDOS workspace
; Changed:      AF, BC, DE, HL, IX
; Called by:    open_file (through bdos_call_fcb)
; Calls:        clear_module, bdos_select_fcb_drive, search_name, end_of_dir, open_copy
open_body:
        call clear_module
        call bdos_select_fcb_drive      ; select the FCB's drive
open_search:
        call search_name                ; search 15 bytes
        call end_of_dir                 ; not found?
        ret z
open_copy:
        call get_extent_address         ; the FCB's extent byte ...
        ld a,(hl)
        push af
        push hl
        ld de,(bdos_fcb)                ; FCB ...
        call get_dir_ptr                ; ... = the directory entry (32 bytes)
        push hl
        ld bc,#0020
        ldir
        call set_file_write_flag        ; not written since open
        pop de
        ld hl,#000C                     ; the entry's extent ...
        add hl,de
        ld c,(hl)
        ld hl,#000F                     ; ... and record count
        add hl,de
        ld b,(hl)
        pop hl
        pop af                          ; the FCB's own extent back
        ld (hl),a
        cp c                            ; same extent: rc of the entry
        jr z,oc_set_rc
        ld b,#00                        ; an earlier extent than the entry's: rc = 0 ... (observed with EXM = 3: drive B)
        jr nc,oc_set_rc
        ld b,#80                        ; ... a later one: rc = 128 (full)
oc_set_rc:
        inc hl
        inc hl
        inc hl
        ld (hl),b                       ; rc
        ret
merge_zero:
        ld a,(hl)                       ; two-byte disk map entry: take the other's if 0 - for a format with DSM >= 256 (observed with the 2K-block DPB, see test_single_map)
        inc hl
        or (hl)
        dec hl
        ret nz
        ld a,(de)
        ld (hl),a
        inc de
        inc hl
        ld a,(de)
        ld (hl),a
        dec de
        dec hl
        ret
; ----------------------------------------------------------------------
; Subroutine: close_body [#E3B4]
; Tasks:        BDOS close (after Digital Research's CP/M 2.2 BDOS routine close): if the file was written (module bit 7
;               clear), find its directory entry and merge the disk maps of FCB and entry
;               (an entry 0 takes the other's; a difference is an error), take the higher
;               extent with its record count, write the entry. Entry close_extent: without the
;               drive select (open_next_extent). Observed.
;               Merge error (observed by changing the FCB's block from &A3 to &A4 before the
;               second close of a SAVE): merge_error only decrements the return code, which
;               search_name has set to the entry's position in its record (0-3) - here 3 -> 2,
;               so the caller sees "ok" (bdos_fcb_call: A = 3, NZ). Only an entry at position
;               0 would give &FF. The entry is not written. vdos_cas_out_close does not check
;               the code anyway - the SAVE ended normally.
; Input:        IY = VDOS workspace; bdos_fcb = the FCB
; Output:       return code (iy+&21): 0 / the entry position = ok, &FF not found (or merge error at position 0)
; Changed:      AF, BC, DE, HL, IX
; Called by:    close_file (through bdos_call_fcb), open_next_extent
; Calls:        bdos_select_fcb_drive, get_module, search_name, end_of_dir, get_dir_ptr, test_single_map, merge_zero, seek_copy
close_body:
        call bdos_select_fcb_drive
close_extent:
        ld (iy+#21),#00                 ; return code 0
        ld hl,#0000                     ; dir_count = 0
        ld (dir_count),hl               ; dir_count = 0
        call get_module                 ; written since open?
        bit 7,a
        ret nz                          ; no: nothing to do
        call search_name                ; its directory entry
        call end_of_dir
        ret z                           ; not found: &FF
        call get_dir_ptr                ; disk maps of entry (DE) and FCB (HL), 16 bytes
        ld bc,#0010                     ; +16: disk map ...
        add hl,bc
        ex de,hl                        ; ... DE = the entry's
        ld hl,(bdos_fcb)
        add hl,bc                       ; HL = the FCB's
        ld b,#10                        ; 16 bytes
ce_merge:
        call test_single_map            ; one byte per block?
        jr nz,ce_merge_double
        ld a,(hl)                       ; FCB entry 0: take the directory's ...
        or a                            ; FCB byte 0?
        ld a,(de)
        jr nz,ce_fcb_zero
        ld (hl),a                       ; yes: the directory's
ce_fcb_zero:
        or a                            ; ... directory entry 0: take the FCB's
        jr nz,ce_compare
        ld a,(hl)                       ; (directory 0: the FCB's)
        ld (de),a                       ; (...)
ce_compare:
        cp (hl)                         ; equal now?
        jr nz,merge_error               ; no: merge error
        jr ce_next
ce_merge_double:
        call merge_zero                 ; two bytes per block - for a format with DSM >= 256 (observed with the 2K-block DPB, see test_single_map)
        ex de,hl
        call merge_zero
        ex de,hl
        ld a,(de)
        cp (hl)
        jr nz,merge_error
        inc de
        inc hl
        ld a,(de)
        cp (hl)
        jr nz,merge_error
        dec b
ce_next:
        inc de                          ; next map byte
        inc hl
        djnz ce_merge                   ; 16
        ld bc,#FFEC                     ; back to the extent bytes
        add hl,bc                       ; (back to +12)
        ex de,hl
        add hl,bc                       ; (...)
        ld a,(de)                       ; the higher extent ...
        cp (hl)
        jr c,ce_copied                  ; lower than the FCB's: keep
        ld (hl),a                       ; ... into the entry ...
        ld bc,#0003                     ; (+3: rc)
        add hl,bc
        ex de,hl
        add hl,bc
        ld a,(hl)                       ; ... with its record count
        ld (de),a                       ; (...)
ce_copied:
        ld (iy+#18),#FF                 ; FCB copied to the directory
        jp seek_copy                    ; write the entry
merge_error:
        dec (iy+#21)                    ; return code - 1 (observed: 3 -> 2): it holds the entry's position in its directory record (0-3, set by search_name), so only position 0 gives &FF - as in DR CP/M 2.2 (mergerr: dcr lret)
        ret                             ; without writing the entry (observed: the entry on the disc keeps its block; bdos_fcb_call returns A = 3, NZ = "ok"; the SAVE ended with Ready)
; ----------------------------------------------------------------------
; Subroutine: make_file [#E426]
; Tasks:        BDOS make file (FCB at DE); no directory entry free: error.
; Input:        DE = FCB; IY = VDOS workspace
; Changed:      AF, HL
; Called by:    vdos_cas_out_open
; Calls:        bdos_call_fcb; error_dir_full
make_file:
        push de
        ld hl,make_body                 ; body: make
        call bdos_call_fcb              ; on FCB DE
        inc a
        jp z,error_dir_full             ; no entry: "Directory voll" (observed: OUT OPEN of the 65th file on a 64-entry disc)
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: make_body [#E433]
; Tasks:        BDOS make (after Digital Research's CP/M 2.2 BDOS routine make): module 0, select, find an empty entry (FCB
;               pointing at empty_fcb, the byte &E5 at &E469), clear the FCB from byte 15 on,
;               note the entry in cdrmax, copy the FCB into it, write the directory. Entry
;               make_entry: without module clear and select (open_next_extent). Observed.
; Input:        IY = VDOS workspace
; Output:       return code &FF: no empty entry ("Directory voll")
; Changed:      AF, BC, DE, HL, IX
; Called by:    make_file (through bdos_call_fcb), open_next_extent
; Calls:        clear_module, bdos_select_fcb_drive, search, end_of_dir, clear_memory, set_cdrmax, copy_fcb, set_file_write_flag
make_body:
        call clear_module
        call bdos_select_fcb_drive
make_entry:
        ld hl,(bdos_fcb)                ; keep the FCB address
        push hl
        ld hl,empty_fcb                 ; search for an empty entry (byte 0 = &E5) ...
        ld (bdos_fcb),hl
        ld c,#01                        ; ... 1 byte compared
        call search
        call end_of_dir
        pop de                          ; the FCB again
        ld (bdos_fcb),de
        ret z                           ; none: return code &FF
        ld hl,#000F                     ; FCB from byte 15 on ...
        add hl,de
        push hl
        ld b,#11
        ex de,hl
        call clear_memory               ; ... cleared (17 bytes)
        pop hl
        dec hl
        dec hl
        ld (hl),a                       ; byte 13 (s1) = 0
        call set_cdrmax                 ; entry in use from now on
        call copy_fcb                   ; FCB into the entry, written
        jp set_file_write_flag          ; not written since open
empty_fcb:
        defb #E5                        ; &E5 (the PUSH HL opcode): byte 0 of the FCB that finds an empty entry
; ----------------------------------------------------------------------
; Subroutine: open_next_extent [#E46A]
; Tasks:        Go to the next extent of the file (after Digital Research's CP/M 2.2 BDOS routine open_reel): close the
;               current one, extent + 1 (and module + 1 after 31); within the same extent group
;               (EXM) only the values change, else open the next extent or - when writing -
;               make it. Observed (30K file: second extent; 516K file on drive B: module 1,
;               writing and reading).
; Input:        IY = VDOS workspace
; Output:       return code 0 ok, 1 end of file / no entry
; Changed:      AF, BC, DE, HL, IX
; Called by:    read_seq_body, write_seq_body
; Calls:        close_extent, end_of_dir, get_extent_address, search_name, make_entry, open_copy, get_fcb_values, set_return_1, set_file_write_flag
open_next_extent:
        ld (iy+#18),#00                 ; not yet copied
        call close_extent               ; close the current extent
        call end_of_dir                 ; close failed
        ret z
        call get_extent_address         ; extent + 1 ...
        ld a,(hl)
        inc a
        and #1F                         ; ... (0-31)
        ld (hl),a
        jr z,one_next_module            ; overflow: next module
        ld b,a                          ; same extent group (EXM) ...
        ld a,(dpb_exm)
        and b
        and (iy+#18)                    ; ... and copied to the directory?
        jr z,one_open                   ; no: open the next physical extent
        jr one_copy                     ; yes: still the same directory entry (EXM = 3 on drive B: 4 extents of 16K per entry; observed)
one_next_module:
        inc hl                          ; extent wrapped from 31 to 0: HL = FCB+12 (EX) -> FCB+14 (S2, the module; observed: file > 512K on drive B)
        inc hl
        inc (hl)                        ; module + 1 (observed: S2 &00 -> &01 when writing, &80 -> &81 when reading; bit 7 = not written since open)
        ld a,(hl)
        and #0F                         ; modules 0-15 only (16 x 512K = 8M, the CP/M 2.2 file limit) ...
        jr z,one_error                  ; ... module 16: error - unreachable: 16 x 512K = 8M, larger than any VDOS drive (708K max); the internal BDOS runs only under BASIC
one_open:
        call search_name                ; open the next extent
        call end_of_dir                 ; found
        jr nz,one_copy
        bit 2,(iy+#19)                  ; reading: no more extents = end of file
        jr nz,one_error
        call make_entry                 ; writing: make it
        call end_of_dir                 ; Z: make found no empty entry ... (observed: the 65th directory entry for the second extent of a growing file)
        jr z,one_error                  ; ... error
        jr one_values
one_copy:
        call open_copy                  ; the entry into the FCB (observed: drive B)
one_values:
        call get_fcb_values             ; new vrecord, rcount, extval
        xor a                           ; return code 0
        jp set_return_code
one_error:
        call set_return_1               ; return code 1, not written (observed: directory full)
        jp set_file_write_flag
; ----------------------------------------------------------------------
; Subroutine: read_seq_body [#E4BB]
; Tasks:        BDOS read sequential (after Digital Research's CP/M 2.2 BDOS routine seqdiskread / diskread): read record cr of the
;               current extent into the DMA buffer and advance cr; at the end of a full extent
;               (128 records) go to the next one. An unallocated block or the last record means
;               end of file. Observed.
; Input:        IY = VDOS workspace
; Output:       return code 0 ok, 1 end of file
; Changed:      AF, BC, DE, HL, IX
; Called by:    read_record_in (through bdos_call_in)
; Calls:        bdos_select_fcb_drive, get_fcb_values, open_next_extent, index_block, test_allocated, block_to_record, seek_record, read_buffer, set_fcb_values
read_seq_body:
        call bdos_select_fcb_drive
        set 3,(iy+#19)                  ; sequential ...
read_seq_core:
        set 2,(iy+#19)                  ; ... read (entry for random reads)
        call get_fcb_values             ; vrecord, rcount, extval
        ld a,(virtual_record)           ; record within the records of the extent?
        ld hl,(record_count)
        cp l
        jr c,rs_record_ok               ; yes: read it
        cp #80                          ; extent not full: end of file
        jp nz,set_return_1
        call open_next_extent           ; full: next extent ...
        xor a                           ; ... from its first record
        ld (virtual_record),a
        ld a,(iy+#21)                   ; end of file?
        or a
        jp nz,set_return_1
rs_record_ok:
        call index_block                ; block of the record
        call test_allocated             ; not allocated: end of file
        jp z,set_return_1
        call block_to_record            ; record number on the disc
        call seek_record                ; track and sector
        call read_buffer                ; read it (deblocking) to the DMA buffer
        jp set_fcb_values               ; cr + 1, rc into the FCB
; ----------------------------------------------------------------------
; Subroutine: write_seq_body [#E4FA]
; Tasks:        BDOS write sequential (after Digital Research's CP/M 2.2 BDOS routine seqdiskwrite / diskwrite): write the DMA
;               buffer as record cr; a record in an unallocated block gets a new block next to
;               the previous one (get_block) - if none is free VDOS jumps straight to "Diskette
;               voll" (DR returns code 2): the blocks already taken by this extent are then
;               used in the ALV but not in the directory (observed: lost until the next login).
;               Raises rc, clears the not-written flag, opens the next extent after record 127.
;               Observed.
; Input:        IY = VDOS workspace
; Output:       return code 0 ok, 1 no directory entry / extent full
; Changed:      AF, BC, DE, HL, IX
; Called by:    write_record_out (through bdos_call_out)
; Calls:        bdos_select_fcb_drive, check_rofile, get_fcb_values, index_block, test_allocated, dm_position, get_disk_map, get_block, error_disc_full, block_to_record, seek_record, write_buffer, get_module, set_fcb_values, open_next_extent; falls through into set_fcb_values
write_seq_body:
        call bdos_select_fcb_drive
        set 3,(iy+#19)                  ; sequential ...
write_seq_core:
        res 2,(iy+#19)                  ; ... write (entry for random writes)
        ld hl,(bdos_fcb)
        call check_rofile               ; R/O file: error
        call get_fcb_values             ; vrecord, rcount, extval
        ld a,(virtual_record)           ; record 128: extent full
        cp #80
        jp nc,set_return_1              ; record 128 of a full extent (no next extent made): return code 1 (observed after "no empty entry")
        call index_block                ; block of the record
        call test_allocated             ; allocated?
        ld c,#00                        ; write type 0 (normal) ...
        jr nz,ws_write                  ; ... yes: write it
        call dm_position                ; no: its disk map index
        ld (iy+#1B),a
        ld bc,#0000                     ; block near: 0 for the first ...
        or a
        jr z,ws_get_block
        ld c,a                          ; ... else the previous block
        dec bc
        call get_disk_map
        ld b,h
        ld c,l
ws_get_block:
        call get_block                  ; a free block
        ld a,l
        or h
        jp z,error_disc_full            ; none: "Diskette voll"
        ld (actual_record),hl           ; actual_record = the new block
        ex de,hl
        ld hl,(bdos_fcb)                ; into the FCB's disk map ...
        ld bc,#0010
        add hl,bc
        call test_single_map            ; ... one or two bytes per entry
        ld a,(iy+#1B)
        jr nz,ws_double
        call add_a_hl                   ; index ...
        ld (hl),e                       ; ... single byte
        jr ws_new_block
ws_double:
        ld c,a                          ; two bytes - for a format with DSM >= 256 (observed with the 2K-block DPB: SAVE of 18K, see test_single_map)
        ld b,#00
        add hl,bc
        add hl,bc
        ld (hl),e
        inc hl
        ld (hl),d
ws_new_block:
        ld c,#02                        ; write type 2: first record of a new block
ws_write:
        ld a,(iy+#21)                   ; error so far?
        or a
        ret nz
        push bc
        call block_to_record            ; record number on the disc
        call seek_record                ; track and sector
        pop bc
        call write_buffer               ; write it (deblocking, write type C)
        ld a,(virtual_record)           ; beyond rc?
        ld hl,record_count
        cp (hl)
        jr c,ws_written
        ld (hl),a                       ; rc = record + 1
        inc (hl)
ws_written:
        push af
        call get_module                 ; written since open
        res 7,(hl)
        pop af
        cp #7F                          ; the last record of the extent ...
        jr nz,set_fcb_values
        bit 3,(iy+#19)                  ; ... in sequential mode?
        jr z,set_fcb_values
        call set_fcb_values             ; yes: cr, rc into the FCB ...
        call open_next_extent           ; ... and the next extent
        ld a,(iy+#21)                   ; ok?
        or a
        jr nz,ws_ok
        dec a                           ; cr = &FF (+1 = 0 in set_fcb_values)
        ld (virtual_record),a
ws_ok:
        ld (iy+#21),#00                 ; return code 0: this record is written even if the next extent could not be made (observed) - the next write finds the extent full
; ----------------------------------------------------------------------
; Subroutine: set_fcb_values [#E59E]
; Tasks:        cr = virtual_record (+1 in sequential mode), rc = record_count (after Digital Research's CP/M 2.2 BDOS routine setfcb).
; Input:        IY = VDOS workspace
; Changed:      AF, DE, HL
; Called by:    read_seq_body, write_seq_body
; Calls:        get_fcb_counts
set_fcb_values:
        call get_fcb_counts
        ld a,(virtual_record)           ; vrecord ...
        bit 3,(iy+#19)                  ; sequential?
        jr z,sfv_store                  ; no: as it is
        inc a                           ; yes: + 1
sfv_store:
        ld (hl),a                       ; = cr
        ex de,hl
        ld a,(record_count)             ; rcount ...
        ld (hl),a                       ; = rc
        ret
; ----------------------------------------------------------------------
; Subroutine: read_random [#E5B2]
; Tasks:        Read the record of the random record number (FCB+33) - entry of the relative files (after Digital Research's CP/M 2.2 BDOS routine randiskread / randiskwrite). Read, not observed (no relative files used).
; Input:        IX = the channel block (FCB at IX+&0D, record buffer through record_buffer_de); IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    relative file RSX commands (|GET, |PUT; research)
; Calls:        random_call
read_random:
        push de
        push hl
        push bc
        push af
        ld hl,read_random_body
        call random_call
        jr rr_return
; ----------------------------------------------------------------------
; Subroutine: write_random [#E5BE]
; Tasks:        Write the record of the random record number (FCB+33) - entry of the relative files (after Digital Research's CP/M 2.2 BDOS routine randiskread / randiskwrite). Read, not observed (no relative files used).
; Input:        IX = the channel block (FCB at IX+&0D); IY = VDOS workspace
; Changed:      none
; Called by:    relative file RSX commands (|GET, |PUT; research)
; Calls:        random_call
write_random:
        push de
        push hl
        push bc
        push af
        ld hl,write_random_body
        call random_call
rr_return:
        pop af
        pop bc
        pop hl
        pop de
        ret
random_call:
        push ix                         ; (not observed) record buffer, FCB at IX+13, call the body
        call record_buffer_de
        call set_dma_de
        ld de,#000D
        add ix,de
        push ix
        pop de
        call bdos_call_fcb
        pop ix
        ret
read_random_body:
        call bdos_select_fcb_drive      ; (not observed)
        res 1,(iy+#15)
        call random_seek
        call z,read_seq_core            ; Z: read the record - also after random_seek's error exit, because set_file_write_flag keeps Z (bug; observed with F = &64 and (iy+&21) = &FF for a missing extent)
        ret
write_random_body:
        call bdos_select_fcb_drive      ; (not observed)
        set 1,(iy+#15)
        call random_seek
        call z,write_seq_core
        ret
random_seek:
        res 3,(iy+#19)                  ; (not observed) extent and module of the random record; open / make it (DR rseek)
        ld de,(bdos_fcb)
        ld hl,#0021
        add hl,de
        ld a,(hl)
        and #7F
        push af
        ld a,(hl)
        rla
        inc hl
        ld a,(hl)
        rla
        and #1F
        ld c,a
        ld a,(hl)
        rra
        rra
        rra
        rra
        and #0F
        ld b,a
        pop af
        ld hl,RAM_LAM
        add hl,de
        ld (hl),a
        ld hl,#000C
        add hl,de
        ld a,c
        sub (hl)
        jr nz,rsk_other_extent
        ld hl,JP_BC
        add hl,de
        ld a,b
        sub (hl)
        and #7F
        jr z,rsk_ok
rsk_other_extent:
        push bc                         ; another extent: close the current one first (error -> return code 3)
        push de
        call close_extent
        pop de
        pop bc
        ld l,#03
        ld a,(iy+#21)
        inc a
        jr z,rsk_error
        ld hl,#000C
        add hl,de
        ld (hl),c
        ld hl,JP_BC
        add hl,de
        ld (hl),b
        call open_search
        ld a,(iy+#21)
        inc a
        jr nz,rsk_ok
        bit 1,(iy+#15)
        ld l,#FF
        jr z,rsk_error
        call make_entry
        ld a,(iy+#21)
        inc a
        jr z,rsk_dir_full
rsk_ok:
        xor a                           ; ok: return code 0
        jp set_return_code
rsk_error:
        push hl                         ; error (code L: 3 close failed, &FF extent missing): module = &C0, the return code, then set_file_write_flag (keeps Z - the bug)
        call get_module
        ld (hl),#C0
        pop hl
        ld (iy+#21),l
        jp set_file_write_flag
rsk_dir_full:
        ld a,#16                        ; no directory entry left for the new extent: msg &16 "Directory voll"
        jp error_message
; ----------------------------------------------------------------------
; Subroutine: read_dir [#E680]
; Tasks:        Next directory entry (after Digital Research's CP/M 2.2 BDOS routine read_dir): dir_count + 1
;               (end after DRM: &FFFF); at the first entry of a record read the record into the
;               directory buffer and check (C = 0) or store (C = &FF) its checksum. VDOS
;               addition: a checksum difference means the disc was changed - if a file is open
;               on the drive it is closed with "Diskette wurde gewechselt", "<name> wurde
;               geschlossen" (error_disc_changed), else the drive is logged in again
;               (login_drive) - which also rebuilds the allocation vector - and the directory
;               read continues. Observed: all three (normal; change with a file open; change
;               without, CAT shows the new disc).
; Input:        C = &FF login, 0 search; IY = VDOS workspace
; Changed:      AF, BC, DE, HL, IX
; Called by:    login, search
; Calls:        sub_de_hl, set_end_dir, dir_entry_offset, seek_dir, set_dma_dirbuf, read_buffer, dir_checksum, set_dma_again, error_disc_changed, login_drive
read_dir:
        ld de,(dpb_drm)                 ; DRM ...
        ld hl,(dir_count)               ; ... dir_count + 1
        inc hl
        ld (dir_count),hl
        call sub_de_hl                  ; beyond DRM?
        jr nc,rd_record                 ; no
        call set_end_dir                ; yes: end
        ret
rd_record:
        call dir_entry_offset           ; first entry of a record?
        or a
        ret nz                          ; no: the record is in the buffer
        push bc
        call seek_dir                   ; seek its record
        call set_dma_dirbuf             ; DMA = directory buffer
        call read_buffer                ; read it
        pop bc
        call dir_checksum               ; check / store the checksum
        push af
        call set_dma_again              ; the caller's DMA again
        pop af
        ret c                           ; checksum ok
rd_disc_changed:
        ld a,(iy+#14)                   ; disc changed (observed): the input file's drive?
        cp (iy+#45)
        jr nz,rdc_output
        call ix_in_header               ; IX = input header ... (observed: the open input file was on the drive)
        ld hl,#0045
        jr rdc_close
rdc_output:
        cp (iy+#69)                     ; ... or the output file's drive?
        jp nz,rdc_relog
        call ix_out_header
        ld hl,#0069
rdc_close:
        ld a,(ix+#00)                   ; file open on it?
        inc a
        jp nz,error_disc_changed        ; yes: close it, message (observed)
rdc_relog:
        ld hl,(dir_count)               ; no file open: log the drive in again ... (observed: CAT after a disc change; this also frees the blocks lost by "Diskette voll")
        push hl
        call login_drive
        pop hl
        ld (dir_count),hl               ; ... and go on with this entry
        jr rd_record
; ----------------------------------------------------------------------
; Subroutine: read_buffer [#E6DD]
; Tasks:        Read (entry write_buffer: write, C = write type) the record of the last SETTRK /
;               SETSEC to / from the DMA buffer through the DOS indirections; a disc error ends
;               the CAS function through the error exit (&DEF5).
; Input:        write_buffer: C = 0 normal, 1 directory, 2 new block; IY = VDOS workspace
; Changed:      AF, BC, DE, HL
; Called by:    read_seq_body, write_seq_body, read_dir, write_dir
; Calls:        dos_read, dos_write
read_buffer:
        call #BE9B
        jr rb_check
write_buffer:
        call #BE9E
rb_check:
        or a                            ; ok?
        ret z
        jp error_disc_status            ; disc error (observed after N): error exit with the BIOS status
; ----------------------------------------------------------------------
; Subroutine: dir_record [#E6EA]
; Tasks:        HL = dir_count / 4: the directory record of the current entry.
; Output:       HL
; Changed:      HL, F
; Called by:    dir_checksum, seek_dir
; Calls:        shift_hl_right
dir_record:
        ld hl,(dir_count)               ; dir_count ...
        push bc
        ld c,#02                        ; ... / 4
        call shift_hl_right             ; (shift right 2)
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: seek_dir [#E6F5]
; Tasks:        Seek the directory record of dir_count (entry seek_record: record actual_record):
;               track = record / SPT + OFF (SETTRK), sector = record MOD SPT translated by the
;               XLT (SECTRAN, SETSEC) (after Digital Research's CP/M 2.2 BDOS routine seekdir / seek).
; Changed:      AF, BC, DE, HL
; Called by:    read_dir, copy_fcb, read_seq_body, write_seq_body
; Calls:        dir_record, dos_settrk, bios_sectran, dos_setsec
seek_dir:
        call dir_record                 ; dir record ...
        ld (actual_record),hl           ; ... = actual_record
seek_record:
        ld de,(dpb_spt)                 ; SPT
        ld hl,(actual_record)           ; record number ...
        ld a,h
        ld c,l
        ld hl,#0000                     ; ... divided by SPT (16 bits, restoring division)
        ld b,#10
sr_divide:
        rl c                            ; (one bit)
        rla                             ; (...)
        adc hl,hl                       ; (...)
        sbc hl,de                       ; (...)
        jr nc,sr_next                   ; (...)
        add hl,de                       ; (...)
sr_next:
        ccf                             ; (quotient bit)
        djnz sr_divide                  ; 16 bits
        rl c                            ; quotient = track within the data area
        rla                             ; (...)
        ld d,a                          ; DE = quotient
        ld e,c
        push hl                         ; remainder = sector
        ld hl,(dpb_off)                 ; + reserved tracks
        add hl,de
        ld b,h                          ; BC = track
        ld c,l
        call #BE92                      ; SETTRK
        ld de,(bdos_xlt)                ; XLT
        pop bc                          ; BC = sector
        call bios_sectran               ; sector translation
        ld c,l                          ; BC = translated sector
        ld b,h
        jp #BE95                        ; SETSEC
; ----------------------------------------------------------------------
; Subroutine: load_hl_indirect [#E732]
; Tasks:        HL = word at HL.
; Input:        HL = address of the word
; Output:       HL; AF kept
; Changed:      HL
load_hl_indirect:
        push af
        ld a,(hl)                       ; low byte ...
        inc hl
        ld h,(hl)                       ; ... high byte
        ld l,a                          ; HL = word
        pop af
        ret
; ----------------------------------------------------------------------
; Subroutine: test_single_map [#E739]
; Tasks:        Z if DSM < 256: one byte per block number in the disk map (NZ: two bytes).
;               VDOS's own DPBs all have DSM < 256 (3" system DSM 170, data 179, IBM 155, Vortex 176;
;               the format detection patches only the low byte), so with them the one-byte paths are
;               taken. The two-byte paths (get_disk_map, scan_disk_map / sdm_next, merge_zero,
;               ce_merge_double, ws_double - the DR BDOS algorithm) are used as soon as a drive has a
;               DPB with DSM >= 256, e.g. when a user's driver for another disc format installs its
;               own DPH / DPB (larger capacity or smaller blocks).
;               Observed 2026-10-26 that way (all in RAM, on a blank draft disc in B:): drive B's XPB
;               at &ABC5 set to a 704K format with 2K blocks (BSH 4, BLM &0F, EXM 0, DSM &15F, AL0
;               &C0; SPT / DRM / CKS / OFF unchanged) and its ALV pointer (DPH+14, &AB5C) moved to
;               &4000 (44 bytes; the ALV at &A8A7 has room for 177 blocks only - such a driver has to
;               provide its own). Then CAT -> "0K in 0 Files, 700K frei"; SAVE "T.BIN",B,&4100,&4800
;               (18K, 2 extents) -> "T.BIN 19K", "20K in 1 Files, 680K frei", ALV FF F0; LOAD back ->
;               all 18432 bytes identical; |ERA -> 700K frei again. All six two-byte ranges ran.
; Output:       Z / NZ
; Changed:      AF
; Called by:    get_disk_map, scan_disk_map, close_extent, write_seq_body
test_single_map:
        push hl
        ld hl,(dpb_dsm)                 ; DSM ...
        ld a,h                          ; ... high byte 0?
        or a
        pop hl
        ret
; ----------------------------------------------------------------------
; Subroutine: dirbuf_sum [#E741]
; Tasks:        A = sum of the 128 bytes in the directory buffer (the record's checksum).
; Output:       A
; Changed:      AF, HL, B
; Called by:    dir_checksum
dirbuf_sum:
        ld b,#80                        ; 128 bytes ...
        ld hl,(bdos_dirbuf)             ; ... of the directory buffer
        xor a                           ; sum = 0
ds_loop:
        add a,(hl)                      ; add
        inc hl
        djnz ds_loop                    ; (128)
        ret
; ----------------------------------------------------------------------
; Subroutine: shift_hl_left [#E74C]
; Tasks:        HL = HL << C.
; Input:        HL, C
; Changed:      HL, F, C
shift_hl_left:
        inc c                           ; C = 0?
shl_loop:
        dec c                           ; (...)
        ret z                           ; done
        add hl,hl                       ; HL * 2
        jr shl_loop                     ; loop
; ----------------------------------------------------------------------
; Subroutine: shift_hl_right_3 [#E752]
; Tasks:        HL = HL / 8.
; Input:        HL = the value
; Output:       HL
; Changed:      HL, F
; Called by:    login (ALV size), get_alloc_bit
; Calls:        shift_hl_right
shift_hl_right_3:
        push bc
        ld c,#03                        ; 3 bits
        call shift_hl_right             ; shift
        pop bc
        ret
; ----------------------------------------------------------------------
; Subroutine: shift_hl_right [#E75A]
; Tasks:        HL = HL >> C.
; Input:        HL, C
; Changed:      HL, F, C
shift_hl_right:
        inc c                           ; C = 0?
shr_loop:
        dec c                           ; (...)
        ret z                           ; done
        srl h                           ; HL / 2
        rr l
        jr shr_loop                     ; loop
; ----------------------------------------------------------------------
; Subroutine: copy_name_iy [#E763]
; Tasks:        copy_name with HL and DE as workspace offsets.
; Input:        HL, DE = offsets, B = bytes to clear; IY = VDOS workspace
; Output:       DE = destination
; Changed:      AF, BC, DE, HL
; Called by:    vdos_cas_in_open, out_rename
; Calls:        falls through into copy_name
copy_name_iy:
        call de_hl_add_iy
; ----------------------------------------------------------------------
; Subroutine: copy_name [#E766]
; Tasks:        Clear B bytes at DE, then copy drive, name and extension (12 bytes) from HL to DE.
; Input:        HL = source FCB, DE = destination, B = bytes to clear
; Output:       DE kept
; Changed:      AF, BC, HL
; Called by:    vdos_cas_out_open
; Entered from: copy_name_iy (falls through)
copy_name:
        push de
        call clear_memory               ; clear B bytes at DE
        pop de
        push de
        ld bc,#000C                     ; 12 bytes: drive, name, extension
        ldir                            ; copy
        pop de
        ret
; ----------------------------------------------------------------------
; Subroutine: checksum [#E773]
; Tasks:        DE = sum of the B bytes at HL (AMSDOS header checksum).
; Input:        HL, B
; Output:       DE = sum, HL after the bytes
; Changed:      AF, DE, HL, B
; Called by:    vdos_cas_in_open, out_write_header
checksum:
        ld de,#0000                     ; DE = 0
cs_loop:
        ld a,e                          ; add the byte ...
        add a,(hl)
        ld e,a                          ; (low)
        inc hl
        jr nc,cs_next                   ; (carry into D)
        inc d                           ; (...)
cs_next:
        djnz cs_loop                    ; B bytes
        ret
; ----------------------------------------------------------------------
; Subroutine: de_hl_add_iy [#E780]
; Tasks:        DE = IY + DE, HL = IY + HL.
; Input:        DE, HL = offsets; IY = VDOS workspace
; Changed:      DE, HL, F
de_hl_add_iy:
        call workspace_offset           ; DE = IY + DE ...
        jp iy_offset_hl                 ; ... HL = IY + HL
; ----------------------------------------------------------------------
; Subroutine: set_ext_blank .. set_extension [#E786]
; Tasks:        Put an extension into the FCB at DE (bytes 9-11) from extension_table:
;               set_ext_bak 0, set_ext_bin 3, set_ext_bas 6, set_ext_blank 9 "   ", set_ext_temp 12 "$$$".
; Input:        DE = FCB (set_extension: A = index)
; Output:       AF changed; BC, DE, HL kept
; Changed:      AF
; Called by:    vdos_cas_in_open, vdos_cas_out_open, vdos_cas_out_close, out_rename
set_ext_blank:
        ld a,#09                        ; "   "
        jr set_extension
set_ext_temp:
        ld a,#0C                        ; "$$$"
        jr set_extension
set_ext_bak:
        xor a                           ; "BAK"
        jr set_extension
set_ext_bas:
        ld a,#06                        ; "BAS"
        jr set_extension
set_ext_bin:
        ld a,#03                        ; "BIN"
set_extension:
        push de
        push hl
        push bc
        ld hl,#0009                     ; FCB + 9: the extension ...
        add hl,de
        ex de,hl                        ; DE = it
        ld hl,extension_table           ; the table ...
        add a,l                         ; ... + A
        ld l,a                          ; (...)
        adc a,h                         ; (carry)
        sub l
        ld h,a
        ld bc,#0003                     ; 3 bytes
        ldir                            ; copy
        pop bc
        pop hl
        pop de
        ret
extension_table:
        defb "BAKBINBAS   $$$"          ; "BAK", "BIN", "BAS", "   ", "$$$": 3 bytes each, index 0/3/6/9/12
; ----------------------------------------------------------------------
; Data: message_table [#E7BF]
; Contents:     62 messages &00-&3D (&E7BF-&E9E1) for print_message, each ended by &FF.
;               &80+n = message n nested, &C0 file name (DE), &C1 number DE, &C2 drive letter
;               (C), &C3 number C. Each msg_xx comment shows its parts and the expanded text.
;               Read as data, so they are scrambled in the raw ROM like all data.
message_table:
        defb #0D,#0A,#FF                ; msg &00: <CR> <LF>
msg_01:
        defb "Diskette "                ; msg &01: "Diskette "
        defb #FF
msg_02:
        defb "voll"                     ; msg &02: "voll"
        defb #FF
msg_03:
        defb "fehler"                   ; msg &03: "fehler"
        defb #FF
msg_04:
        defb #C1,#4B,#FF                ; msg &04: <DE> "K" = "<DE>K"
msg_05:
        defb #9A,#9C,#83,#FF            ; msg &05: &1A &1C &03 = "<CR><LF>Laufwerk <drive>: Schreibfehler"
msg_06:
        defb #9A                        ; msg &06: &1A "Lese" &03 = "<CR><LF>Laufwerk <drive>: Lesefehler"
        defb "Lese"
        defb #83,#FF
msg_07:
        defb #8B                        ; msg &07: &0B "fehlt" = "<CR><LF>Laufwerk <drive>: Diskette fehlt"
        defb "fehlt"
        defb #FF
msg_08:
        defb #8B,#9B,#FF                ; msg &08: &0B &1B = "<CR><LF>Laufwerk <drive>: Diskette hat Schreibschutz"
msg_09:
        defb "ke","="+#80               ; msg &09: "ke" &3D "e CP/M " &01 = "keine CP/M Diskette "
        defb "e CP/M "
