; ----------------------------------------------------------------------
; Subroutine: xmon_disc_monitor [#EA9E]
; Tasks:        XMON command @ (manual: "Diskettenmonitor", no RETURN): the disc monitor. Writes
;               back the host buffer, invalidates the XPB cache, sets &BE00 = &FF (so that
;               xmon_command_done returns to xdm_status_prompt instead of "*"), switches the disc
;               error messages off (bios_set_message &FF) and keeps the old setting and sek_drive
;               on the stack; SP is kept in &BE09 (bdos_dph, borrowed - every key starts from it).
;               Then xdm_select_drive selects the current drive, sets T = dpb_off, S = 0,
;               B = host buffer - &80 and shows the status line and ">" (it does not return; the
;               call &EB27 behind it is dead code). The key loop xdm_key: ESC leaves, keys below
;               'A' are ignored, others are echoed and looked up in xmon_disc_command_table; an
;               unknown letter is erased again (&08, &10). xdm_exit writes back the host buffer,
;               restores sek_drive and messages_off, sets &BE00 = 0 and the XPB cache invalid and
;               ends in xmon_command_done ("*").
;               VDOS 2.11-X differs from the manual (2.0): the status line is
;               "L:dd  T:tt  S:rr  B:aaaa  G:gg" - S is the 128-byte record of the track (from 0,
;               not a physical sector &41..), B the DMA address, and G (block number) is new; the
;               values live in sek_drive / sek_track / sek_record / dma_address, not in &BEC1-&BEC5.
;               The command table has F and G besides the manual's L S T B R W C A P D.
;               Observed 2026-10-26 from BASIC (B: = the Vortex disc copy, nothing written):
;               @ -> "L:01  T:02  S:00  B:A8BA  G:00", ">"; '1' ignored; 'Z' echoed and erased;
;               ESC -> "*", &BE00 = 0, &BE04 = &FF, sek_drive = 1, messages_off = 0 again; &BE09 stays
;               &BFF0 (bdos_dph is not restored - harmless under BASIC). All 12 commands, ">>" and
;               "E:xx" observed from BASIC (see each xdm_cmd_*).
;               Under CP/M (observed 2026-10-26, |CPM,2 + XMON.COM, the Vortex disc copy as A:):
;               the three BIOS branches - bios_seldsk at the start (DPH &AFA6, status line
;               "L:00  T:02  S:00  B:AD26  G:00": the workspace is at IY = &AB68 there), bios_read
;               (R) and bios_write (W of a free record, read back, the original written back); before
;               @ &BE09 was &0000 - CP/M's BDOS from the disc does not use VDOS's bdos_dph.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      everything; &BE00, &BE04, &BE09, &BE15-&BE23, sek_drive / sek_track / sek_record,
;               dma_address, messages_off (restored at the exit)
; Calls:        flush_host_buffer, bios_set_message, xdm_select_drive, xdm_status_line,
;               xmon_out_char, xmon_get_key, xmon_find_command; ends in xmon_command_done
xmon_disc_monitor:
        call flush_host_buffer          ; write back the host buffer if it holds unwritten data (observed: nothing to write, CY = 1)
        ld a,#FF                        ; &FF ...
        ld (xpb_cache_drive),a          ; ... XPB cache invalid: the next SELDSK looks the drive up again
        ld (#BE00),a                    ; ... &BE00 = &FF: the disc monitor runs (xmon_command_done returns to xdm_status_prompt)
        call bios_set_message           ; disc error messages off (A = &FF) - the disc monitor reports errors itself; A = the old setting ...
        push af                         ; ... kept on the stack (observed &00)
        ld a,(sek_drive)                ; the current drive (sek_drive, observed 1) ...
        push af                         ; ... kept on the stack too (restored by xdm_exit)
        ld (#BE09),sp                   ; keep SP (observed &BFF0) in &BE09 (bdos_dph, borrowed): every key starts from it
        call xdm_select_drive           ; select drive A = sek_drive and show the status line - does not return (ends with jp xdm_status_prompt, observed)

; ---- never accessed: #EAB8-#EABA (3 bytes, fill: static) ----
        call xdm_read_record            ; never reached: xdm_select_drive always ends with a jump (no reference to &EAB8 found) - dead code, the sector read at the start (a leftover?); [static]
; ---- end of never accessed ----

xdm_status_prompt:
        call xdm_status_line            ; the status line "L:dd  T:tt  S:rr  B:aaaa  G:gg" (observed L:01 T:02 S:00 B:A8BA G:00) ...
        ld a,#3E                        ; ... and the ">" prompt
        call xmon_out_char              ; ...
xdm_key:
        ld sp,(#BE09)                   ; SP back to the saved one (drops what a command left)
        call xmon_get_key               ; wait for a key (upper case); Z = ESC
        jr z,xdm_exit                   ; ESC: leave the disc monitor (observed)
        cp #41                          ; below 'A' ...
        jr c,xdm_key                    ; ... ignored, no echo (observed: '1')
        push af                         ; keep the key ...
        call xmon_out_char              ; ... echo it
        pop af                          ; A = the key
        ld de,xmon_disc_command_table   ; the disc monitor's command table
        call xmon_find_command          ; found: jump to the command (it ends in xmon_command_done -> xdm_status_prompt); not found: back here, NZ (observed: 'Z')
        ld a,#08                        ; not a command: cursor back ...
        call xmon_out_char              ; ...
        ld a,#10                        ; ... and &10 (delete the character at the cursor): the echo is gone again (observed: only ">" stays)
        call xmon_out_char              ; ...
        jr xdm_key                      ; next key
xdm_exit:
        call flush_host_buffer          ; ESC: write back the host buffer (observed: nothing to write; also under CP/M: back to "*", sek_drive / messages_off restored) ...
        pop af                          ; ... the drive from the start ...
        ld (sek_drive),a                ; ... back to sek_drive (observed 1)
        pop af                          ; ... the old message setting ...
        ld (messages_off),a             ; ... back to messages_off (observed 0)
        xor a                           ; 0 ...
        ld (#BE00),a                    ; ... &BE00 = 0: main monitor again
        dec a                           ; &FF ...
        ld (xpb_cache_drive),a          ; ... XPB cache invalid again
        jp xmon_command_done            ; new line, "*" prompt (observed); &BE09 keeps the disc monitor's SP (observed &BFF0)
; Disc monitor command table for xmon_find_command (same layout as xmon_command_table): a count
; byte (12), then per command the key and the routine address. Observed: the 12 keys read while
; looking up 'Z' (not found); the addresses are read only for a found key (not yet). F and G are
; not in the manual; P is the main monitor's xmon_cmd_printer.
xmon_disc_command_table:
        defb #0C                        ; 12 entries (count byte), then key + routine address each - the manual lists L S T B R W C A P D, not F and G
        defb #4C,#9C,#EB                ; L: drive -> &EB9C
        defb "T_","k"+#80               ; T: track -> &EB5F
        defb "S~","k"+#80               ; S: record -> &EB7E
        defb #42,#91,#EB                ; B: buffer address -> &EB91
        defb #52,#97,#EC                ; R: read -> &EC97
        defb "W=","k"+#80               ; W: write -> &EB3D
        defb #44,#9D,#EC                ; D: dump -> &EC9D
        defb #43,#FD,#EC                ; C: change (as S) -> &ECFD
        defb #41,#03,#ED                ; A: text -> &ED03
        defb #46,#09,#ED                ; F: (not in the manual) -> &ED09
        defb #50,#F0,#F9                ; P: printer echo -> xmon_cmd_printer &F9F0 (the main monitor's P; observed: &BEFF 0 -> 1 -> 0)
        defb "Gf","l"+#80               ; G: (not in the manual) -> &EC66
; ----------------------------------------------------------------------
; Subroutine: xmon_cpm_mode [#EB22]
; Tasks:        Test whether XMON runs under CP/M: A = xmon_cpm_flag (manual: 0 = VDOS active,
;               &FF = CP/M active), Z = VDOS. Observed: Z from BASIC. What sets &FF is not
;               found in the code read so far (the CP/M command XMON).
; Output:       A = xmon_cpm_flag; Z = VDOS / BASIC, NZ = CP/M
; Changed:      AF
; Called by:    rsx_xmon, more XMON code (not analysed)
xmon_cpm_mode:
        ld a,(xmon_cpm_flag)            ; the CP/M flag
        or a                            ; Z = 0 = VDOS
        ret                             ; Z = VDOS / BASIC, NZ = CP/M
; ----------------------------------------------------------------------
; Subroutine: xdm_read_record [#EB27]
; Tasks:        Disc monitor: read the 128-byte record sek_record of sek_track on sek_drive into
;               dma_address through the CP/M deblocking (VDOS's read_record under BASIC, BIOS READ
;               under CP/M). First the host buffer is marked invalid (deblock_flags bit 6), so the
;               sector really comes from the disc. Error: the return address is dropped and
;               xdm_disc_error prints "E:xx" (the manual: "ERR:xx"), then the status line.
;               Observed 2026-10-26: R with L:01 T:02 S:00 B:4000 -> the first directory record of
;               B: (P22.COM, P30.COM, F1Z.BIN, F1Z.BAS) at &4000-&407F; R on track &A0 (none on the
;               disc) -> "E:45".
; Output:       CY = 1 ok (returns); error: does not return (status line, ">")
; Changed:      everything (READ)
; Called by:    xdm_cmd_read, xdm_cmd_dump, xdm_cmd_block (through xdm_cmd_read), the dead call at
;               &EAB8
; Calls:        xmon_cpm_mode, read_record / bios_read; error: xdm_disc_error
xdm_read_record:
        ld hl,deblock_flags             ; deblocking flags ...
        res 6,(hl)                      ; ... host buffer not valid (hstact = 0): the sector is read from the disc again, not taken from the host buffer
        call xmon_cpm_mode              ; under CP/M ...
        jr z,xrr_basic                  ; ... BASIC: VDOS's READ directly
        call bios_read                  ; CP/M: through the BIOS jumpblock (observed 2026-10-26 under CP/M: R on T:02 S:00 -> the directory record, back AF = &0001: A = 0 CP/M ok, CY = 1)
        jr xrr_check                    ; to the common test
xrr_basic:
        call read_record                ; READ: record sek_record of sek_track (drive sek_drive) into dma_address (observed: T2 S0 of B: -> the first directory record at &4000)
xrr_check:
        ret c                           ; ok: back (observed)
        pop hl                          ; error (observed: T A0 -> A = &45): drop the return address (the caller's jp xds_done is skipped) ...
        jr xdm_disc_error               ; ... and report it
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_write [#EB3D]
; Tasks:        Disc monitor command W (manual: write the buffer into the sector L / T / S): WRITE the
;               128-byte buffer as record sek_record of sek_track through the deblocking with write
;               type 1 ("directory"), so the host sector is written to the disc at once (VDOS's
;               write_record under BASIC, BIOS WRITE under CP/M). Then the status line; an error
;               goes to xdm_disc_error ("E:xx").
;               Observed 2026-10-26 on the B: copy (output/xmon_o_test.dsk, in memory only, never
;               saved): GB0 (T:9E S:10, a free record: 128 x E5), F 5A, W, F 00, R -> 128 x 5A; then
;               F E5, W, F 00, R -> 128 x E5 again (the original). A: untouched.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything (WRITE); the disc
; Calls:        xmon_cpm_mode, write_record / bios_write; ends in xds_done or xdm_disc_error
xdm_cmd_write:
        ld c,#01                        ; C = 1: write type "directory" - the deblocking writes the host sector to the disc at once
        call xmon_cpm_mode              ; under CP/M ...
        jr z,xcw_basic                  ; ... BASIC: VDOS's WRITE directly
        call bios_write                 ; CP/M: through the BIOS jumpblock (observed under CP/M: W of T:9E S:10 on the disc copy, back AF = &0045: A = 0, CY = 1; read back with R)
        jr xcw_check                    ; to the common test
xcw_basic:
        call write_record               ; WRITE: the buffer (dma_address) as record sek_record of sek_track (observed: T:9E S:10 of the B: copy, &5A x 128, then E5 back)
xcw_check:
        jp c,xds_done                   ; ok: new line, status line, ">" (observed); error: "E:xx"
; Disc monitor disc error (manual: "ERR:xx"; 2.11-X prints "E:xx"): new line, "E:" and the error
; code in hex, then the status line and ">". The code is VDOS's: FDC errors have bit 6 set (manual,
; "Fehlercodes": bit 5 CRC, 4 overrun, 3 not ready, 2 sector not found, 1 write protect, 0 no ID).
; Observed 2026-10-26: TA0 (">>", but T stays A0 - the T bug) then R on the 80-track B: copy ->
; "E:45" (bits 6, 2, 0: sector / ID not found - there is no track &A0), after the retries.
xdm_disc_error:
        push af                         ; keep the error code (A) ...
        call xmon_out_lf_cr             ; new line
        ld a,#45                        ; "E:" ...
        call xdm_out_key_colon          ; ...
        pop af                          ; ... + the error code as two hex digits (the manual says "ERR:xx")
        call xmon_hex_byte              ; ...
        jp xds_done                     ; new line, status line, ">"
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_track [#EB5F]
; Tasks:        Disc monitor command T (manual: "Txx" - set the track): edit sek_track
;               (xmon_input_byte), check it with xdm_check_block (">>" past the last block), then
;               read the record at once (xdm_cmd_read). Reserved tracks (below dpb_off) are always
;               accepted - the status line shows no G there.
;               Observed 2026-10-26 (B:, OFF 2, SPT &24, BSH 5, DSM &B0): T00 -> "T:00  S:00  B:4000"
;               (no G); T05 -> "G:03"; TA0 -> ">>" with "T:A0  G:B1"; T02 back.
;               *** BUG: the track is stored before the check (&EB65), so after ">>" the invalid
;               track stays set and the next R / W / D uses it (the manual: "geändert wurde dann
;               selbstverständlich nichts"). The G command has the same order (&EC8C).
;               *** BUGFIX PROPOSAL: keep the old track and put it back in xdm_error, or check first
;               - needs more bytes than T has; possibly the 14 zero bytes at &ED12-&ED1F (still to
;               be checked whether they are free).
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything; sek_track, the buffer
; Calls:        xmon_input_byte, xdm_check_block; ends in xdm_cmd_read or xdm_error
xdm_cmd_track:
        ld a,(sek_track)                ; default: the current track (sek_track) ...
        call xmon_input_byte            ; ... edit it (RETURN; ESC ends the command)
        ld (sek_track),a                ; *** BUG: stored before the check - an invalid track stays set although ">>" follows (observed: TA0 -> ">>" and "T:A0  G:B1")
        call xdm_check_block            ; past the last block: ">>" (observed TA0)
        jp xdm_cmd_read                 ; read the record at once, status line (observed T00, T05)
; ----------------------------------------------------------------------
; Subroutine: xdm_check_block [#EB6E]
; Tasks:        Disc monitor: check that T / S lie on the disc - the block (xdm_block_number) must
;               not be above dpb_dsm; a reserved track is always fine. Past the end: jp xdm_error
;               (">>"), the return address stays on the stack until xdm_key resets SP.
;               Observed 2026-10-26: T05 (block 3) ok; TA0 (block &B1, DSM &B0) -> ">>".
; Output:       returns only when ok
; Changed:      AF, BC, DE, HL
; Called by:    xdm_cmd_track, xdm_cmd_dump (next track), xdm_cmd_go
; Calls:        xdm_block_number; error: xdm_error
xdm_check_block:
        call xdm_block_number           ; the block of T / S; a reserved track (NC) is always fine (observed T00: no G field)
        ret nc                          ; reserved track: ok
        ld de,(dpb_dsm)                 ; DE = the highest block (dpb_dsm, observed &B0) + 1 ...
        inc de                          ; ...
        or a                            ; ...
        sbc hl,de                       ; ... block - (DSM + 1)
        jp nc,xdm_error                 ; block > DSM: ">>" (observed TA0: block &B1; the extra return address is dropped by xdm_key's LD SP)
        ret                             ; ok (observed T05: block 3)
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_record [#EB7E]
; Tasks:        Disc monitor command S (manual: "Sxx" - set the sector; 2.11-X: the 128-byte record
;               of the track, from 0): edit sek_record (xmon_input_byte), reject a value of
;               records per track (dpb_spt low byte) or more with ">>" (xdm_error), else store it and
;               read the record at once (xdm_cmd_read). The manual's sector numbers &41.. / &C1.. /
;               &01.. and its automatic format change belong to VDOS 2.0.
;               Observed 2026-10-26 (B:, SPT &24): S23 -> record read, "S:23  G:01"; S24 -> ">>",
;               S stays 23.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything; sek_record, the buffer
; Calls:        xmon_input_byte; ends in xdm_cmd_read or xdm_error
xdm_cmd_record:
        ld a,(sek_record)               ; default: the current record (sek_record) ...
        call xmon_input_byte            ; ... edit it (RETURN; ESC ends the command)
        ld de,(dpb_spt)                 ; E = records per track (dpb_spt low byte, observed &24)
        cp e                            ; the record must be below it ...
        jr nc,xdm_error                 ; ... else ">>", nothing changed (observed: S24 -> ">>", S stays 23)
        ld (sek_record),a               ; the new record (observed S23 -> "S:23  G:01") ...
        jp xdm_cmd_read                 ; ... read at once, status line
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_buffer [#EB91]
; Tasks:        Disc monitor command B (manual: "Babcd" - set the buffer address): edit dma_address
;               with xmon_input_word (default the current one), store it, show the status line.
;               The buffer is what R reads into, W writes from, and D / C / A / F work on.
;               Observed 2026-10-26: B4000 -> "L:01  T:02  S:00  B:4000  G:00"; B + ESC -> status
;               line and ">" again (through xmon_command_done, &BE00 = &FF), B stays &4000.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      AF, C, HL; dma_address
; Calls:        xmon_input_word; ends in xds_done
xdm_cmd_buffer:
        ld hl,(dma_address)             ; default: the current buffer address (dma_address) ...
        call xmon_input_word            ; ... edit it (RETURN / ','; ESC ends the command: back to the status line and ">", the old address stays - observed)
        ld (dma_address),hl             ; ... the new buffer (DMA) address for R / W / D / C / A / F (observed &4000)
        jr xds_done                     ; new line, status line (observed "B:4000"), ">"
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_drive [#EB9C]
; Tasks:        Disc monitor command L (manual: "Lxx" - set the drive, 00 = A, 01 = B): edit sek_drive
;               (xmon_input_byte) and fall into xdm_select_drive: SELDSK, DPB copy, T = dpb_off,
;               S = 0 and B back to the host buffer - &80 (a B set before is lost). No record is read.
;               A drive without DPH: ">>", sek_drive unchanged.
;               Observed 2026-10-26: L00 -> "L:00  T:02  S:00  B:A8BA  G:00" (A:, the 3" disc);
;               L05 -> ">>", sek_drive stays 0; L01 back (B:).
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything; sek_drive, sek_track, sek_record, dma_address, &BE15-&BE23
; Calls:        xmon_input_byte; falls into xdm_select_drive
xdm_cmd_drive:
        ld a,(sek_drive)                ; default: the current drive (sek_drive) ...
        call xmon_input_byte            ; ... edit it (RETURN; ESC ends the command); falls into xdm_select_drive (observed L00, L05, L01)
; ----------------------------------------------------------------------
; Subroutine: xdm_select_drive [#EBA2]
; Tasks:        Disc monitor: select drive A (SELDSK: VDOS's seldsk under BASIC, bios_seldsk under
;               CP/M), copy its XPB's DPB part (15 bytes) to the DPB copy &BE15, set T = dpb_off
;               (the first data track), S = record 0 and B = dma_address = host buffer - &80; then
;               new line, status line and ">" (xds_done -> xdm_status_prompt). No DPH (HL = 0):
;               xdm_error - status line and ">>". Never returns: both ends jump.
;               Also the end of the L command (xdm_cmd_drive falls into it).
;               Observed 2026-10-26: @ with drive 1 -> DPH &AB4E, T = 2, S = 0, B = &A8BA; L00 (A:),
;               L05 (no drive: ">>", sek_drive kept), L01.
; Input:        A = the drive
; Changed:      everything; &BE15-&BE23, sek_track, sek_record, dma_address
; Calls:        xmon_cpm_mode, seldsk / bios_seldsk, host_buffer, xmon_out_lf_cr, xdm_status_line;
;               continues in xdm_status_prompt / xdm_key
xdm_select_drive:
        ld c,a                          ; C = the drive
        call xmon_cpm_mode              ; under CP/M ...
        jr z,xds_basic                  ; ... BASIC: VDOS's SELDSK directly
        call bios_seldsk                ; CP/M: through the BIOS jumpblock (observed under CP/M at the start of @: drive 0 -> the CP/M DPH &AFA6; status line "L:00  T:02  S:00  B:AD26  G:00")
        jr xds_check                    ; to the DPH test
xds_basic:
        call seldsk                     ; SELDSK (observed: drive 1 -> DPH &AB4E)
xds_check:
        ld a,l                          ; HL = DPH ...
        or h
        jp z,xdm_error                  ; ... 0: no such drive -> ">>", sek_drive unchanged (observed: L05)
        ld hl,(xpb_cache_xpb)           ; the drive's XPB (the DPB part) ...
        ld de,dpb_spt                   ; ... copied to the DPB copy &BE15 (dpb_spt ...) ...
        ld bc,#000F                     ; ... 15 bytes
        ldir                            ; ...
        ld a,(dpb_off)                  ; T = the first track after the reserved ones (dpb_off, observed 2) ...
        ld (sek_track),a                ; ...
        xor a                           ; ... S = record 0
        ld (sek_record),a               ; ...
        call host_buffer                ; B = the host buffer (observed &A93A) ...
        ld de,#FF80                     ; ... - &80 ...
        add hl,de                       ; ...
        ld (dma_address),hl             ; ... as the DMA address (observed &A8BA): a 128-byte record buffer just below the host buffer
xds_done:
        call xmon_out_lf_cr             ; new line ...
        jp xdm_status_prompt            ; ... status line and ">" prompt
; Disc monitor input error (manual: ">>"): status line with the unchanged values, then ">>" as
; the prompt. Reached from S, T, L and G when a value is out of range. Observed: S24.
xdm_error:
        call xmon_out_lf_cr             ; error (observed: S24): new line ...
        call xdm_status_line            ; ... the status line (unchanged values) ...
        ld a,#3E                        ; ... and ">>" (manual: an input error; the next command is echoed behind it - observed ">>D4000,02")
        call xmon_out_char
        ld a,#3E
        call xmon_out_char
        jp xdm_key                      ; next key
; ----------------------------------------------------------------------
; Subroutine: xdm_status_line [#EBED]
; Tasks:        Disc monitor: print the status line "L:dd  T:tt  S:rr  B:aaaa  G:gg" and a new line:
;               L = sek_drive, T = sek_track, S = sek_record (128-byte record of the track),
;               B = dma_address, G = the CP/M block of T / S (xdm_block_number; only from the first
;               data track on). Observed: "L:01  T:02  S:00  B:A8BA  G:00".
; Changed:      AF, BC, DE, HL
; Calls:        xdm_out_byte_field, xdm_out_word_field, xdm_block_number, xdm_out_a_field,
;               xmon_out_lf_cr
xdm_status_line:
        ld hl,sek_drive                 ; L, T, S from sek_drive, sek_track, sek_record (in this order in RAM)
        ld e,#4C                        ; "L:" + the drive
        call xdm_out_byte_field
        ld e,#54                        ; "T:" + the track
        call xdm_out_byte_field
        ld e,#53                        ; "S:" + the 128-byte record of the track (not a physical sector: the manual's S:41 is VDOS 2.0)
        call xdm_out_byte_field
        ld hl,dma_address               ; dma_address ...
        ld e,#42                        ; ... "B:" + the buffer address
        call xdm_out_word_field
        call xdm_block_number           ; the block number of T / S - CY = 1 only from the first track after the reserved ones ...
        jr nc,xsl_done                  ; ... else no G field (read)
        ld a,l                          ; A = the block (low byte) ...
        ld e,#47                        ; ... "G:" + the block (not in the manual; observed G:00)
        call xdm_out_a_field
xsl_done:
        jp xmon_out_lf_cr               ; new line
xdm_out_byte_field:
        ld a,(hl)                       ; A = the byte at HL, HL to the next one
        inc hl
xdm_out_a_field:
        push hl                         ; keep HL ...
        push af                         ; ... and the value
        ld a,e                          ; the field letter (E) ...
        call xdm_out_key_colon          ; ... and ':'
        pop af
        call xmon_hex_byte              ; the value as two hex digits
xdm_field_gap:
        call xmon_out_two_tabs          ; two spaces to the next field
        pop hl
        ret
xdm_out_word_field:
        ld c,(hl)                       ; BC = the word at HL ...
        inc hl
        ld b,(hl)
        inc hl
        push hl                         ; HL to the next one (kept)
        push bc                         ; the value
        ld a,e                          ; the field letter (E) ...
        call xdm_out_key_colon          ; ... and ':'
        pop hl                          ; HL = the value ...
        call xmon_hex_word              ; ... as four hex digits
        jr xdm_field_gap                ; two spaces, HL back
xdm_out_key_colon:
        call xmon_out_char              ; the letter in A ...
        ld a,#3A                        ; ... and ':'
        jp xmon_out_char
; ----------------------------------------------------------------------
; Subroutine: xdm_block_number [#EC3E]
; Tasks:        Disc monitor: the CP/M allocation block of the current track / record:
;               ((sek_track - dpb_off) * records per track + sek_record) >> dpb_bsh. Records per
;               track is the low byte of dpb_spt only (DJNZ; fine below 256). A reserved track
;               (sek_track < dpb_off): NC, no block. Observed: T = 2 = dpb_off, S = 0 -> block 0.
; Output:       CY = 1: HL = the block; NC: a reserved track
; Changed:      AF, BC, DE, HL
; Called by:    xdm_status_line, the G command (&EC66, not analysed)
; Calls:        add_a_hl, shift_hl_right
xdm_block_number:
        ld hl,(sek_track)               ; HL = the track (sek_track) ...
        ld h,#00
        ld de,(dpb_off)                 ; ... minus the reserved tracks (dpb_off) ...
        or a
        sbc hl,de
        ccf                             ; ... CY = 1: track >= dpb_off
        ret nc                          ; a reserved track: NC, no block
        ld a,(dpb_spt)                  ; B = records per track (low byte of dpb_spt) ...
        ld b,a
        ex de,hl                        ; DE = the data track number
        ld hl,#0000                     ; HL = DE * records per track ...
xbn_multiply:
        add hl,de                       ; HL = data track x records per track (DJNZ)
        djnz xbn_multiply
        ld a,(sek_record)               ; ... + the record ...
        call add_a_hl
        ld a,(dpb_bsh)                  ; ... >> the block shift (dpb_bsh) ...
        ld c,a
        call shift_hl_right             ; ... = the block number
        scf                             ; CY = 1: HL = the block
        ret
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_block [#EC66]
; Tasks:        Disc monitor command G (not in the manual - new in 2.11-X with the G field): go to a
;               CP/M block. Edit the block (one byte, default the current one), turn it into a record
;               (block << dpb_bsh), divide by records per track: T = dpb_off + quotient, S = remainder;
;               check it (xdm_check_block, ">>" past dpb_dsm) and fall into xdm_cmd_read (the first
;               record of the block is read at once).
;               Observed 2026-10-26 (B:, OFF 2, SPT &24, BSH 5, DSM &B0): G03 -> "T:04  S:18  G:03";
;               GB1 -> ">>" with "T:9F  S:0C  G:B1"; G00 -> T:02 S:00.
;               *** BUG (as in xdm_cmd_track): T and S are stored before the check, so after ">>"
;               the position past the end stays set. Blocks above 255 cannot be entered (byte input).
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything; sek_track, sek_record, the buffer
; Calls:        xdm_block_number, xmon_input_byte, shift_hl_left, xdm_check_block; falls into
;               xdm_cmd_read
xdm_cmd_block:
        call xdm_block_number           ; the current block (on a reserved track L is no block - read) ...
        ld a,l                          ; ... as the default ...
        call xmon_input_byte            ; ... edit it: one byte, so only blocks 0-255 (RETURN; ESC ends the command)
        ld l,a                          ; HL = the block ...
        ld h,#00                        ; ...
        ld a,(dpb_bsh)                  ; ... << the block shift (dpb_bsh) ...
        ld c,a                          ; ...
        call shift_hl_left              ; ... = its first record from the first data track on
        ld de,(dpb_spt)                 ; DE = records per track (dpb_spt)
        ld bc,#0000                     ; BC = 0: the track count
xdb_divide:
        or a                            ; record / records per track by subtraction ...
        sbc hl,de
        inc bc                          ; ... BC = tracks + 1 ...
        jr nc,xdb_divide                ; ... until it goes below 0
        dec bc                          ; one too many: BC = the data track
        add hl,de                       ; HL = the record within the track (the remainder)
        push hl                         ; keep it
        ld hl,(dpb_off)                 ; the reserved tracks (dpb_off) ...
        add hl,bc                       ; ... + the data track ...
        ld a,l                          ; ...
        ld (sek_track),a                ; ... = T (*** BUG as in T: stored before the check - observed GB1: ">>" with T:9F S:0C)
        pop hl                          ; the record ...
        ld a,l                          ; ...
        ld (sek_record),a               ; ... = S (observed G03 -> T:04 S:18)
        call xdm_check_block            ; past the last block: ">>" (observed GB1); else falls into xdm_cmd_read
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_read [#EC97]
; Tasks:        Disc monitor command R (manual: read the sector L / T / S into the buffer): read the
;               record (xdm_read_record), then the status line. Also the end of T, S and G (they
;               read the new record at once). Observed 2026-10-26: R -> directory record at &4000.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Calls:        xdm_read_record; ends in xds_done
xdm_cmd_read:
        call xdm_read_record            ; read the record into the buffer (error: "E:xx" and back to the prompt)
        jp xds_done                     ; new line, status line, ">" (observed)
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_dump [#EC9D]
; Tasks:        Disc monitor command D (manual: "Dabcd<ENTER>" or "Dabcd,xx<ENTER>" - dump the buffer,
;               optionally xx records): the address (default dma_address) is dumped for &80 bytes
;               with xmon_dump_lines (hex / ASCII, a key pauses, ESC ends). With ',' a count follows
;               (default 1): after each record S + 1 (next track at the end of the track, checked by
;               xdm_check_block), the status line, xdm_read_record into the buffer and the next dump.
;               The dump address stays the same - it should be the buffer for the count to make
;               sense. Observed 2026-10-26: D + RETURN -> &4000-&407F (the directory record); D,12
;               -> S 0, 1, 2, 3, 4 dumped (status line before each), SPACE paused, ESC ended at S 4;
;               S23 then D,02 -> T:02 S:23, then T:03 S:00 G:01 (the change to the next track).
;               Not observed: a read error.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      everything; sek_record, sek_track, the buffer
; Calls:        xmon_input_word, xmon_out_comma, xmon_input_byte, xmon_out_lf_cr, xmon_dump_lines,
;               xdm_check_block, xdm_status_line, xdm_read_record; ends in xds_done
xdm_cmd_dump:
        ld hl,(dma_address)             ; default: the buffer address (dma_address)
        call xmon_input_word            ; the dump address (RETURN: one record, observed; ',': a count follows, observed; ESC ends the command)
        ld a,#01                        ; count 1 ...
        jp c,xdd_start                  ; ... RETURN: dump one record (observed)
        push hl                         ; ',': keep the address ...
        call xmon_out_comma             ; ','
        ld a,#01                        ; default count 1 ...
        call xmon_input_byte            ; ... the number of records (observed &12: the default 01 with '2' shifted in)
        pop hl                          ; HL = the address
xdd_start:
        ex de,hl                        ; DE = address + &80: one record ...
        ld hl,xmon_ram_reader           ; ...
        add hl,de                       ; ...
        ex de,hl                        ; HL = address, DE = end
        ld b,a                          ; B = the count
        call xmon_out_lf_cr             ; new line
xdd_record:
        push hl                         ; keep address, end and count ...
        push de
        push bc
        call xmon_dump_lines            ; ... dump the 128 bytes (8 lines; a key pauses, ESC ends - observed)
        pop bc
        pop de
        pop hl
        jp nc,xds_done                  ; ended with ESC: status line, ">" (observed)
        dec b                           ; count down ...
        jp z,xds_done                   ; ... done: status line, ">" (observed with count 1)
        inc b                           ; (B back)
        push hl                         ; keep address, end and count again
        push de
        push bc
        ld de,(dpb_spt)                 ; E = records per track (dpb_spt low byte)
        ld a,(sek_record)               ; next record ...
        inc a
        ld (sek_record),a               ; ...
        cp e                            ; ... past the end of the track?
        jr nz,xdd_next                  ; no: go on (observed S 1, 2, 3, 4)
        xor a                           ; yes: record 0 ...
        ld (sek_record),a
        ld hl,sek_track                 ; ... of the next track
        inc (hl)
        call xdm_check_block            ; past the last block: ">>" (xdm_check_block)
xdd_next:
        call xmon_out_lf_cr             ; new line
        call xdm_status_line            ; the status line of the new record (observed "L:01  T:02  S:03  B:4000  G:00")
        call xmon_out_lf_cr             ; new line
        call xdm_read_record            ; read it into the buffer (error: "E:xx", back to ">")
        pop bc                          ; address, end, count back ...
        pop de
        pop hl
        djnz xdd_record                 ; ... next record

; ---- never accessed: #ECFA-#ECFC (3 bytes, fill: static) ----
        jp xds_done                     ; never reached (read): after the INC B at xdd_record B is 2 or more, so DJNZ always jumps; the loop ends only at &ECC5 / &ECC9 - dead code; [static]
; ---- end of never accessed ----

; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_change [#ECFD]
; Tasks:        Disc monitor command C (manual: "Cabcd" - change bytes in the buffer, "entspricht voll
;               dem Monitorbefehl S"): HL = dma_address and jump into xmon_cmd_substitute behind its
;               LD HL,(xmon_subst_address) - the buffer is only the default; any address can be
;               given. Ends with ESC (xmon_input_byte -> xmon_command_done -> the status line).
;               Side effect: xmon_subst_address is left at the next address (observed &4002), so
;               the main monitor's S starts there later.
;               Observed 2026-10-26: C + RETURN (4000), RETURN (00 kept), 51 (&4001 &50 -> &51), ESC
;               -> "L:01  T:02  S:00  B:4000  G:00", ">".
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      the bytes changed; xmon_subst_address
; Calls:        continues in xmon_cmd_substitute (&F70E)
xdm_cmd_change:
        ld hl,(dma_address)             ; default: the buffer address (dma_address) ...
        jp xss_input                    ; ... into the main monitor's S behind its LD HL (observed: 4000 kept, 4001 &50 -> &51, ESC -> status line, ">")
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_text [#ED03]
; Tasks:        Disc monitor command A (manual: "Aabcd" - enter a string): HL = dma_address and jump
;               into xmon_cmd_ascii behind its LD HL,(xmon_fill_address): the address (default the
;               buffer) is stored in xmon_fill_address (also the main A / F default afterwards), the
;               text goes there. Ends in xmon_command_done -> the status line.
;               The main A's bug applies here too: the input buffer overwrites XMON's low-RAM copy
;               &AD76-&AD8A (observed: 21 spaces after A4000,VDOS; restored to 00 by hand after the
;               test, so &0080-&0094 stayed 00).
;               Observed 2026-10-26: A + RETURN (4000), "VDOS" -> &4000-&4003 = 56 44 4F 53, status
;               line, ">".
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      the bytes written; xmon_fill_address, xmon_text_length, &ACA5-&ADA3
; Calls:        continues in xmon_cmd_ascii (&FCC8)
xdm_cmd_text:
        ld hl,(dma_address)             ; default: the buffer address (dma_address) ...
        jp xca_input                    ; ... into the main monitor's A behind its LD HL (observed: A4000,VDOS -> 56 44 4F 53; xmon_fill_address = &4000)
; ----------------------------------------------------------------------
; Subroutine: xdm_cmd_fill [#ED09]
; Tasks:        Disc monitor command F (not in the manual): fill memory - xmon_fill_range ("start,end,
;               value", the main F's routine) with the buffer address as the default start; then the
;               status line. The start is kept in xmon_fill_address (shared with A / F).
;               Observed 2026-10-26: F + RETURN (4000), 407F, E5 -> &4000-&407F = E5, &4080 untouched.
; Input:        entered from xmon_find_command (xmon_disc_command_table)
; Changed:      the bytes filled; xmon_fill_address
; Calls:        xmon_fill_range; ends in xds_done
xdm_cmd_fill:
        ld hl,(dma_address)             ; default start: the buffer address (dma_address)
        call xmon_fill_range            ; "start,end,value" and fill (the main F's routine; observed F4000,407F,E5 -> &4000-&407F = E5)
        jp xds_done                     ; new line, status line, ">"
; 14 x NOP (raw 00) &ED12-&ED1F up to rsx_xmon: no jump / call / pointer to them found (static
; search) - most likely free space, usable for bugfixes. Run on purpose 2026-10-26 (PC set to
; &ED12, breakpoint at &ED20): 14 NOPs, registers unchanged.
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
        nop
; ----------------------------------------------------------------------
; Subroutine: rsx_xmon [#ED20]
; Tasks:        |XMON: start the Z80 machine code monitor (manual "Der VDOS Befehl |XMON").
;               MODE 2 with |FAST text output. When started from BASIC (&BEDD = 0) it skips
;               the CP/M part. It clears the firmware-ROM switch (X) and &BEE0, clears
;               &BF00-&BF17, notes this ROM as the ROM shown at &C000 (xmon_rom), saves RAM
;               &0080-&0094 (xmon_save_low_ram), and saves the caller's SP. It points RST 6
;               (&0030) through a FAR CALL to xmon_breakpoint (&F8D9; breakpoints are RST 6).
;               Then it falls into xmon_command_loop: prompt "*", wait for a command key.
;               Observed 2026-10-25 from BASIC up to the "*" prompt: screen cleared, MODE 2,
;               &0030 = FD E5 DF D0 BE, xmon_break_far = D9 F8 05, xmon_rom = 5,
;               xmon_saved_sp = &BFF4, &BEF8 = &BF80; it then waits in wait_key_cursor.
;               Under CP/M (observed 2026-10-26: |CPM,2, then XMON at A>): XMON.COM sets
;               xmon_cpm_flag (&BEDD) = &FF, SP = &5000, finds "XMON" in this ROM's name table
;               ((&C004)) and jumps to the address of its jumpblock entry with BC = 0 (no file).
;               rsx_xmon then shows "(0100  0000  0100)" (the TPA start, length 0) before the "*".
; Input:        the RSX parameters (A, IX) are not looked at; under CP/M BC = the length of the
;               file XMON.COM loaded (0 without a file name)
; Called by:    RSX "XMON" (rom_jumpblock &C04E); XMON.COM under CP/M (direct jump)
; Calls:        SCR_SET_MODE, rsx_fast, xmon_cpm_mode, clear_memory, KL_CURR_SELECTION,
;               xmon_save_low_ram, xmon_set_far_jump, xmon_out_char, xmon_get_key,
;               xmon_show_file_info (CP/M)
rsx_xmon:
        xor a                           ; A = 0 ...
        ld (#BE00),a                    ; ... to &BE00 (an XMON / disc monitor byte; not in the manual's tables, meaning open)
        push af                         ; AF (A = 0) stays on the caller's stack (below xmon_saved_sp) - read: the ESC exit pops it
        push bc                         ; keep BC over the mode change
        ld a,#02                        ; MODE 2 ...
        call SCR_SET_MODE               ; ... (clears the screen)
        call rsx_fast                   ; |FAST: fast text output in MODE 2
        pop bc                          ; BC back
        call xmon_cpm_mode              ; Z: VDOS / BASIC (xmon_cpm_flag = 0; observed)
        jr z,xmon_init                  ; BASIC: skip the CP/M part (observed both ways: from BASIC it jumps; under CP/M with XMON.COM it falls through)
        ld hl,#0100                     ; CP/M (xmon_cpm_flag = &FF, set by XMON.COM; observed 2026-10-26): HL = DE = &0100 (the TPA start) ...
        ld e,l                          ; (DE = &0100)
        ld d,h
        call xmon_show_file_info        ; ... shown by xmon_show_file_info as "(HL BC DE)" (observed: "(0100  0000  0100)", BC = 0 from XMON.COM - no file loaded)
        call xmon_out_lf_cr             ; new line, then the "*" prompt
xmon_init:
        xor a                           ; A = 0 ...
        ld (xmon_firmware_rom),a        ; ... X switch off: RAM at &0000-&3FFF, not the firmware ROM
        ld (xmon_bank),a                ; ... xmon_bank = 0: no RAM bank (command Z)
        ld de,#BF00                     ; clear the breakpoint work area &BF00-&BF17 (24 bytes, observed) ...
        ld b,#18                        ; 24 bytes ...
        call clear_memory               ; ... set to 0
        call KL_CURR_SELECTION          ; A = this ROM's number ...
        ld (xmon_rom),a                 ; ... is the ROM shown at &C000 (observed 5)
        call xmon_save_low_ram          ; copy RAM &0080-&0094 to &AD76
        ld (xmon_saved_sp),sp           ; the caller's SP (observed &BFF4)
        ld sp,#BF80                     ; a stack below &BF80 for the set-up ...
        ld (xmon_user_sp),sp            ; ... which is also the user SP for G / T (observed &BF80)
        ld bc,xmon_breakpoint           ; RST 6 target: xmon_breakpoint ...
        ld de,xmon_break_far            ; ... reached through the far address at &BED0
        ld hl,USER_RESTART              ; RST 6 (&0030) becomes ...
        ld (hl),#FD                     ; ... PUSH IY (FD E5) ...
        inc hl                          ; &0031 ...
        ld (hl),#E5                     ; ... = &E5 (second byte of PUSH IY)
        inc hl                          ; HL = &0032 for the RST 3 / DEFW written by xmon_set_far_jump
        call xmon_set_far_jump          ; ... RST 3 / DEFW &BED0 (observed: &0030 = FD E5 DF D0 BE)
; XMON command loop: SP back to the caller's stack (xmon_saved_sp), prompt "*", wait for a
; command key. Research: the commands come back here (not observed yet).
xmon_command_loop:
        ld sp,(xmon_saved_sp)           ; back to the caller's stack ...
xmon_prompt:
        ld a,#2A                        ; ... the prompt "*" (observed); I and O jump in here, without the LD SP
        call xmon_out_char              ; "*"
xmon_next_key:
        call xmon_get_key               ; wait for a command key (observed); Z = ESC
        jr nz,xmon_command_key          ; not ESC: a command key
        call xmon_out_lf_cr             ; ESC (observed 2026-10-25): new line ...
        pop af                          ; ... A = the byte rsx_xmon left on the caller's stack (observed AF = &0044) ...
        cp #40                          ; ... below "@" ...
        call c,TXT_RESET                ; ... then TXT RESET (undoes |FAST)
        call xmon_cpm_mode              ; from BASIC ...
        jp z,xmon_exit_basic            ; ... clear BASIC's input buffer &ACA4 (200 bytes) and return to BASIC
        rst #00                         ; RESET; under CP/M: RST 0 (&0000 = JP WBOOT): warm boot (observed 2026-10-26: ESC at "*" after XMON.COM -> CP/M's "A>" again)
; XMON command key: keys below "@" are ignored without an echo. Others are echoed and looked
; up in xmon_command_table; a found key jumps to its routine (does not come back here). An
; unknown key is rubbed out again (cursor back, delete, beep) and the next key is read.
; Observed: 'R' found; '\' not found (echo, &08, &10, &07, back to xmon_next_key).
xmon_command_key:
        cp #40                          ; below "@" (digits, signs, control keys) ...
        jr c,xmon_next_key              ; ... are ignored: next key
        push af                         ; keep the key ...
        call xmon_out_char              ; echo the key
        pop af                          ; ... A = the key again
        ld de,xmon_command_table        ; look it up ...
        call xmon_find_command          ; ... found: jumps to the command, does not return here
        ld a,#08                        ; unknown key (observed '\'): cursor back over the echo ...
        call xmon_out_char              ; &08: cursor left
        ld a,#10                        ; ... &10: delete the character at the cursor ...
        call TXT_OUTPUT                 ; (TXT OUTPUT: control code, not echoed to the printer)
        ld a,#07                        ; ... &07: beep
        call TXT_OUTPUT                 ; beep
        jr xmon_next_key                ; next key
; ----------------------------------------------------------------------
; Subroutine: xmon_find_command [#EDB2]
; Tasks:        Look up key A in a command table (a count byte, then per entry the key and a
;               routine address) and jump to the routine.
;               Found: the routine address replaces the return address on the stack (ex (sp),hl)
;               and RET jumps there - the routine runs on the caller's stack as if the caller had
;               jumped to it, with HL = the caller's HL and DE = the caller's return address.
;               Not found: returns with HL unchanged, DE = the end of the table, NZ.
;               Observed: 'R' -> xmon_cmd_registers &F9A7 (DE = &EDA1, SP back to &BFF4); '\' not
;               found -> back to &EDA1 with DE = &EDFC.
; Input:        A = the key, DE = the table
; Output:       not found: HL unchanged, DE = table end, NZ (found: does not return)
; Changed:      B, DE, flags (found: also HL / stack as described)
; Called by:    xmon_command_key (xmon_command_table); research: also the disc monitor (&EAD8)
;               with its own table - not observed
; Calls:        load_hl_indirect
xmon_find_command:
        ex de,hl                        ; HL = the table, DE = the caller's HL
        ld b,(hl)                       ; B = number of entries
        inc hl                          ; HL = the first entry
xfc_next:
        cp (hl)                         ; this entry's key?
        inc hl                          ; HL = its routine address
        jr z,xfc_found                  ; yes: jump there
        inc hl                          ; no: over the address ...
        inc hl                          ; (2 bytes)
        djnz xfc_next                   ; ... to the next entry
        ex de,hl                        ; not found (observed with '\'): HL back, DE = table end ...
        ret                             ; ... and back to the caller, NZ
xfc_found:
        call load_hl_indirect           ; HL = the routine (observed: &F9A7 for 'R')
        ex (sp),hl                      ; it replaces the return address on the stack; HL = the return address
        ex de,hl                        ; HL = the caller's HL again, DE = the return address
        ret                             ; jump to the routine
; XMON command table for xmon_find_command: a count byte (18), then per command the key (upper
; case) and the address of its routine. Observed: all 18 keys read while looking up a key that
; is not in the table ('\'); 'R' found as entry 11 (-> xmon_cmd_registers). Z is not in the
; manual's command list.
xmon_command_table:
        defb #12                        ; 18 entries
        defb "B"
        defw xmon_cmd_breakpoints
        defb "D"
        defw xmon_cmd_dump
        defb "F"
        defw xmon_cmd_fill
        defb "G"
        defw xmon_cmd_go
        defb "I"
        defw xmon_cmd_input
        defb "O"
        defw xmon_cmd_output
        defb "L"
        defw xmon_cmd_list
        defb "S"
        defw xmon_cmd_substitute
        defb "P"
        defw xmon_cmd_printer
        defb "T"
        defw xmon_cmd_trace
        defb "R"
        defw xmon_cmd_registers
        defb "M"
        defw xmon_cmd_move
        defb "A"
        defw xmon_cmd_ascii
        defb "X"
        defw xmon_cmd_firmware
        defb "Y"
        defw xmon_cmd_rom_select
        defb "C"
        defw xmon_cmd_search
        defb "Z"
        defw xmon_cmd_z
        defb "@"
        defw xmon_disc_monitor
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_rom_select [#EDFC]
; Tasks:        XMON command Y (manual): list the upper ROMs and select the one XMON shows at
;               &C000 (xmon_rom; &FC-&FF = the RAM / screen memory). The list is |ROMCAT's table
;               without its "Himem" line (romcat_rom_list: the ROM-header reader is copied to
;               &BF00 - over xmon_break_area, so breakpoints set before Y are lost). Then "Y" and
;               the number (xmon_input_byte, default the current xmon_rom; ESC keeps it). Under
;               CP/M it does nothing (no list, no input): xmon_rom stays this ROM (5), so under
;               CP/M XMON always shows VDOS at &C000 - its memory commands there read the ROM.
;               Observed 2026-10-25: the list (ROMs 0-7, VDOS as ROM 5 "V ROM", AMSDOS as ROM 7
;               "CPM ROM"); Y FF -> DC000 showed the screen RAM; Y 07 -> DC000,C03F showed AMSDOS
;               (01 00 05 00 72 C0 ...); Y + ESC -> xmon_rom unchanged. VDOS's access map stayed
;               clean in all three. Observed 2026-10-26 under CP/M (XMON.COM after |CPM,2): Y ->
;               "*Y", new line, "*", xmon_rom = 5 unchanged.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL
; Calls:        xmon_cpm_mode, romcat_rom_list, TXT_OUTPUT, xmon_input_byte;
;               ends in xmon_command_done
xmon_cmd_rom_select:
        call xmon_cpm_mode              ; under CP/M ...
        jr nz,xrs_done                  ; ... no list, no change (observed 2026-10-26 under CP/M: "*Y", new line, "*"; xmon_rom stays 5)
        call romcat_rom_list            ; the ROM list of |ROMCAT without the Himem line (observed)
        ld a,#59                        ; "Y" ...
        call TXT_OUTPUT                 ; "Y" (screen only)
        ld a,(xmon_rom)                 ; ... and the current ROM number as the default ...
        call xmon_input_byte            ; ... read the new one (observed "FF")
        ld (xmon_rom),a                 ; the ROM XMON shows at &C000
xrs_done:
        jp xmon_command_done            ; new line, back to the prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_z [#EE15]
; Tasks:        XMON command Z (not in the manual): select the bank of the Vortex RAM expansion
;               that XMON's memory accesses use. Shows the current setting as a number (0 = off,
;               1-8 = bank 0-7), reads a new one (xmon_input_byte) and stores it in xmon_bank:
;               0 = off, else &20 + (number - 1). The memory access routine (&FB7C) writes
;               xmon_bank to port &FBBD, the bank port of the Vortex RAM expansion (owner):
;               bits 7 and 6 are ignored, bit 5 = expansion on, bits 2-0 = bank.
;               Observed 2026-10-25: "Z" shows "Z00", input "03" + RETURN -> xmon_bank = &22;
;               "Z" again shows "Z03" (bank 2 + 1), RETURN keeps &22.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC
; Calls:        xmon_input_byte; ends in xmon_command_done
xmon_cmd_z:
        ld a,(xmon_bank)                ; current bank setting
        or a                            ; off: show 0 (observed)
        jr z,xz_show                    ; 0 = off: show 00
        and #07                         ; on: show bank + 1 ... (observed: &22 -> 3)
        inc a                           ; bank 0-7 is shown as 1-8
xz_show:
        call xmon_input_byte            ; show it, read the new number (observed: "03")
        or a                            ; 0: off
        jr z,xz_store                   ; 0: store 0 = off
        dec a                           ; 1-8 -> bank 0-7 ...
        and #07                         ; (only bits 2-0)
        set 5,a                         ; ... with bit 5 = on (observed: 3 -> &22)
xz_store:
        ld (xmon_bank),a                ; new bank setting
        jp xmon_command_done            ; done: new line, back to the prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_set_far_jump [#EE2F]
; Tasks:        Build a FAR CALL to routine BC of this ROM: at HL write RST 3 / DEFW DE, at DE
;               the far address (BC, this ROM's number). Observed for RST 6: HL = &0032,
;               DE = &BED0, BC = &F8D9 -> &0032 = DF D0 BE, &BED0 = D9 F8 05.
; Input:        HL = where the RST 3 goes, DE = the 3-byte far address, BC = the target
; Output:       HL = DE + 2, DE = HL + 2 (swapped and advanced), A = this ROM
; Changed:      AF, DE, HL
; Called by:    rsx_xmon, more XMON code (not analysed)
; Calls:        KL_CURR_SELECTION
xmon_set_far_jump:
        ld (hl),#DF                     ; RST 3 (FAR CALL) ...
        inc hl                          ; HL = the DEFW ...
        ld (hl),e                       ; ... DEFW DE: the far address ...
        inc hl                          ; ... low byte E ...
        ld (hl),d                       ; ... high byte D
        call KL_CURR_SELECTION          ; A = this ROM
        ex de,hl                        ; HL = the far address
        ld (hl),c                       ; routine address ...
        inc hl                          ; (C = low ...
        ld (hl),b                       ; ... B = high)
        inc hl                          ; the third byte of the far address:
        ld (hl),a                       ; ... and ROM number
        ret                             ; done: RST 3 at HL, far address at DE
xmon_input_line:
        ld de,xmon_decoded              ; the text goes to xmon_decoded (&ACA5) ...
        push de                         ; keep the buffer start
        ld b,c                          ; ... first filled with C spaces (C = &FF from A: &ACA5-&ADA3 - this also overwrites the low-RAM save area &AD76-&AD8A, see xmon_cmd_ascii) ...
        ld a,#20                        ; A = space ...
        call cm_loop                    ; ... B times from DE (cm_loop)
        ld b,#00                        ; ... B = characters so far
        pop de                          ; DE = the buffer start = the next character's place
xil_key:
        call xmon_get_key               ; next key (upper case): ESC ends the command (observed) ...
        jp z,xmon_command_done          ; ESC: end the whole command (new line, "*")
        cp #0D                          ; ... RETURN: done, B = the length (observed)
        ret z                           ; RETURN: back, B = number of characters, the text at &ACA5
        cp #7F                          ; DEL (&7F)? ...
        jr nz,xil_char                  ; no DEL: a character
        xor a                           ; ... with no characters: ignored (observed) ...
        cp b                            ; B = 0?
        jr z,xil_key                    ; yes: nothing to delete
        dec b                           ; ... else one back: a space into the buffer, cursor left ...
        dec de                          ; the place of the last character ...
        ld a,#20                        ; ... is a space again ...
        ld (de),a
        ld a,#08                        ; ... &08: cursor left ...
        call TXT_OUTPUT                 ; ... (screen only)
        ld a,#10                        ; ... and &10 (delete the character on the screen) (observed)
        jr xil_echo                     ; &10 is echoed below: it deletes the character under the cursor
xil_char:
        ld l,a                          ; a character: buffer full (B = C)? then ignored (observed: the 256th of 256) ...
        ld a,c                          ; C = the maximum ...
        cp b                            ; ... reached? ...
        jr z,xil_key                    ; ... yes: the key is ignored
        inc b                           ; ... else count it, store it ...
        ld a,l                          ; A = the character again ...
        ld (de),a                       ; ... into the buffer ...
        inc de                          ; ... next place
xil_echo:
        call TXT_OUTPUT                 ; ... and echo it
        jr xil_key                      ; next key
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_firmware [#EE79]
; Tasks:        XMON command X (manual): switch "firmware ROM at &0000-&3FFF" on / off for
;               XMON's memory accesses. It only inverts xmon_firmware_rom (0 <-> &FF); it does not
;               touch the gate array, so the CPU's own ROM state stays as it is. The memory access
;               routine applies the switch for each byte it reads (&FBEB-&FBF5: lower ROM bit
;               cleared when the switch is on).
;               Observed 2026-10-25: X with 0 -> &FF, X with &FF -> 0 (entry 14 of
;               xmon_command_table); emulator: lower ROM stays off.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF
; Calls:        ends in xmon_command_done
xmon_cmd_firmware:
        ld a,(xmon_firmware_rom)        ; the switch ...
        cpl                             ; ... inverted (0 <-> &FF, observed both ways) ...
        ld (xmon_firmware_rom),a        ; ... and stored; falls into xmon_command_done
; End of an XMON command: new line, then back to the "*" prompt - or, if &BE00 is not 0, to
; xdm_status_prompt (the disc monitor's status line and ">"; read). &BE00 = &FF while the disc
; monitor runs (set by xmon_disc_monitor, cleared by xdm_exit - observed 2026-10-26).
; Observed after Z: &BE00 = 0 -> xmon_command_loop.
xmon_command_done:
        call xmon_out_lf_cr             ; new line
        ld a,(#BE00)                    ; &BE00 = 0: main monitor (observed) ...
        or a                            ; (A = &BE00)
        jp z,xmon_command_loop          ; ... back to the "*" prompt
        jp xdm_status_prompt            ; else back into the disc monitor: xdm_status_prompt (observed: ESC in B's input; &BE00 = &FF while @ runs)
; ----------------------------------------------------------------------
; Subroutine: xmon_hex_digit [#EE8D]
; Tasks:        Convert an upper-case hex character to its value. Not a hex digit: beep (&07 to
;               TXT OUTPUT) and NC. Observed 2026-10-25: '0' -> 0, '3' -> 3 (CY = 1) and a non-hex
;               key in xmon_input_byte (beep, NC).
; Input:        A = character (upper case)
; Output:       CY = 1: A = 0-15; NC: not a hex digit (after the beep)
; Changed:      AF
; Called by:    xmon_input_byte, xmon_input_word, more XMON code (not analysed)
; Calls:        TXT_OUTPUT
xmon_hex_digit:
        cp #41                          ; letter? ...
        jr c,xhd_value                  ; '0'-'9' (and other keys below 'A'): straight on
        sub #07                         ; ... 'A'-'F' follow '9'
xhd_value:
        sub #30                         ; value
        cp #10                          ; 0-15: CY = 1, done (observed)
        ret c                           ; CY: A = the digit's value
        push af                         ; not a hex digit (observed): beep (&07) ...
        ld a,#07                        ; &07 ...
        call TXT_OUTPUT                 ; ... beep
        pop af                          ; A = the key - &30 (meaningless), NC
        ret                             ; ... and return NC
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_breakpoints [#EEA0]
; Tasks:        XMON command B (manual): show and change the 8 breakpoints B1-B8. Shows "-B1-" ...
;               "-B8-" and the addresses, then edits them in place from left to right with
;               xmon_edit_word (as R; RETURN or ',' take a value, ESC ends B at once - the entries
;               done so far stay changed). Each entry in xmon_break_area is 3 bytes: the address
;               (low, high) and the byte found at that address when it was set. B only stores; it
;               writes nothing into the program. xmon_run (G / T) reads the byte again at every
;               start and puts it back after the stop, so the byte B stores is never used.
;               The byte is read with ld a,(de) as the CPU sees it, not through xmon_read_byte: X,
;               Y and Z do not apply, and for an address from &C000 on it would read VDOS itself
;               (not tried: it would pollute the access map).
;               Observed 2026-10-26 (area set to 0 first, as after the start): 8 x RETURN -> each
;               entry 00 00 01 (the byte at &0000); B1 = 4000, B2 = 4001 ',' and ESC at B3 ->
;               00 40 30 / 01 40 31, B3-B8 kept; set back to 0000 afterwards.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; xmon_break_area
; Calls:        xmon_out_lf_cr, xmon_out_minus, xmon_out_char, xmon_out_four_tabs, xmon_hex_byte,
;               TXT_OUTPUT, xmon_edit_word; ends in xmon_command_done
xmon_cmd_breakpoints:
        call xmon_out_lf_cr             ; new line
        ld a,#30                        ; the names: '1' ... '8' ...
xcb_name:
        inc a                           ; ... "-B" digit "-" and four tabs (observed: "-B1-" ... "-B8-")
        push af                         ; keep the digit
        call xmon_out_minus             ; "-"
        ld a,#42                        ; "B"
        call xmon_out_char
        pop af                          ; the digit ...
        push af                         ; (kept again for the loop test)
        call xmon_out_char              ; ... '1'-'8'
        call xmon_out_minus             ; "-"
        call xmon_out_four_tabs         ; to the next column
        pop af                          ; A = the digit
        cp #38                          ; ... up to '8'
        jr nz,xcb_name                  ; not yet '8': the next name
        call xmon_out_lf_cr             ; next line: the 8 addresses ...
        ld hl,#BF01                     ; ... entry n at xmon_break_area + 3 * n: address low, high, saved byte
        ld b,#08                        ; 8 entries
xcb_value:
        ld a,(hl)                       ; ... high byte, low byte ...
        call xmon_hex_byte              ; high byte (entry + 1) ...
        dec hl                          ; ... then the low byte (entry + 0)
        ld a,(hl)
        call xmon_hex_byte              ; = the address as 4 hex digits
        inc hl                          ; ... next entry (3 bytes on) ...
        inc hl                          ; (HL from entry + 0 ...
        inc hl
        inc hl                          ; ... to the next entry + 1)
        push bc                         ; ... four tabs
        call xmon_out_four_tabs         ; to the next column
        pop bc
        djnz xcb_value                  ; next entry
        ld a,#0D                        ; CR: back to the start of the value line
        call TXT_OUTPUT                 ; (screen only: the line stays)
        ld b,#08                        ; edit the 8 entries in place (as R) ...
        ld hl,#BF00                     ; HL = B1's entry
xcb_entry:
        ld e,(hl)                       ; ... HL = the entry's address ...
        inc hl                          ; (the high byte ...
        ld d,(hl)                       ; ... D)
        ex de,hl                        ; HL = the old address = the default, DE = entry + 1
        push bc                         ; keep the counter
        call xmon_edit_word             ; ... edit it (RETURN / ',' take it; ESC ends B, the entries done so far stay changed - observed)
        pop bc                          ; ... store it at once ...
        ex de,hl                        ; HL = entry + 1, DE = the new address
        dec hl                          ; entry + 0 ...
        ld (hl),e                       ; ... low byte ...
        inc hl
        ld (hl),d                       ; ... high byte at entry + 1
        inc hl                          ; entry + 2 ...
        ld a,(de)                       ; ... and keep the byte now at that address (read directly as the CPU sees it, not through xmon_read_byte - observed: &30 from &4000, &01 from &0000)
        ld (hl),a                       ; ... = the byte at the new address
        inc hl                          ; next entry
        djnz xcb_entry                  ; next entry
        call xmon_out_lf_cr             ; new line, "*" prompt (observed)
        jp xmon_command_done            ; "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_dump [#EEFF]
; Tasks:        XMON command D (manual): hex / ASCII dump. Reads the start address (default: where
;               the last dump ended, xmon_dump_address); ',' reads the end address, RETURN instead
;               dumps &100 bytes (from &FF00 on: up to &FFF0). Lines of 16 bytes are printed as
;               long as a line starts below the end address: address, the bytes in hex, the bytes
;               as characters ('.' below &20 and from &7F). A key pauses, the next one continues,
;               ESC ends.
;               Observed 2026-10-25: D0000,003F (X on: firmware ROM, 4 lines up to &003F),
;               D0000,0100 (X off: RAM, 16 lines &0000-&00FF; xmon_dump_address = &0100 afterwards),
;               D0000 + RETURN (default &0100 overtyped; end = start + &100, 16 lines), D + RETURN
;               (default "0100" taken, &0100-&01FF), D0000,0200 with pause / continue / ESC, and D
;               ended with ESC in the address input (no dump, back to "*").
;               Read, not observed: the &FFxx start (it would read ROM 5 - not to be run).
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL
; Calls:        xmon_input_word, xmon_out_comma, xmon_out_lf_cr, xmon_dump_lines;
;               ends in xmon_command_loop
xmon_cmd_dump:
        ld hl,(xmon_dump_address)       ; default: the address after the last dump
        call xmon_input_word            ; start address (observed "0000"); CY = ended with RETURN, NC = ','
        jr c,xd_start_only              ; RETURN: no end address (observed D0000)
        call xmon_out_comma             ; ',': echo it ...
        ld d,h                          ; ... default end = start ...
        ld e,l                          ; (DE = start)
        call xmon_input_word            ; ... read the end address (observed "003F", "0100")
        ex de,hl                        ; DE = end, HL = start
        jr xd_dump                      ; dump start..end
xd_start_only:
        ld de,#FFF0                     ; start only: end &FFF0 if the start is &FFxx (read) ...
        ld a,h                          ; start &FFxx? ...
        inc a                           ; ... (H + 1 = 0) ...
        jr z,xd_dump                    ; ... yes: end &FFF0
        ld de,#0100                     ; ... else start + &100 (observed: &0000 -> end &0100)
        ex de,hl                        ; HL = &100, DE = start ...
        add hl,de                       ; ... + start ...
        ex de,hl                        ; ... DE = the end, HL = the start
xd_dump:
        call xmon_out_lf_cr             ; new line
        call xmon_dump_lines            ; the lines
        jp xmon_command_loop            ; back to the "*" prompt (observed)
; ----------------------------------------------------------------------
; Subroutine: xmon_dump_lines [#EF28]
; Tasks:        Dump lines of 16 bytes from HL, one more as long as the next line starts below DE:
;               the address, two tabs, the 16 bytes in hex (each followed by a tab), a tab, the 16
;               bytes as characters ('.' for &00-&1F and &7F-&FF), new line. xmon_dump_address = the
;               start of the next line. Between lines a key pauses (it is used up by KM READ CHAR);
;               then xmon_get_key waits: ESC returns at once (Z), any other key continues.
;               Observed 2026-10-25: 4 and 16 lines; D0000,0200 with SPACE after line &0060 and
;               SPACE again (continued), then SPACE after line &00F0 and ESC (ended at &0100).
; Input:        HL = start, DE = end
; Output:       CY = 1 at the end; Z = ended by ESC
; Changed:      AF, BC, HL
; Called by:    xmon_cmd_dump
; Calls:        xmon_hex_word, xmon_out_two_tabs, xmon_read_byte, xmon_hex_byte, xmon_out_tab,
;               xmon_out_char, xmon_out_lf_cr, KM_READ_CHAR, xmon_get_key
xmon_dump_lines:
        call xmon_hex_word              ; line address (4 hex digits) ...
        call xmon_out_two_tabs          ; ... two tabs
        ld bc,#0010                     ; 16 bytes per line ...
        add hl,bc                       ; HL = the next line's start
        ld (xmon_dump_address),hl       ; ... the next line's start is the default for the next D
        and a                           ; CY = 0
        sbc hl,bc                       ; HL = this line's start again
        push hl                         ; kept for the character part
        ld b,c                          ; B = 16
xdl_hex:
        call xmon_read_byte             ; hex part: the byte ...
        call xmon_hex_byte              ; ... as two hex digits ...
        call xmon_out_tab               ; ... and a tab
        inc hl                          ; next address
        djnz xdl_hex                    ; next byte
        call xmon_out_tab               ; a tab before the characters
        pop hl                          ; the same 16 bytes ...
        ld b,#10                        ; 16 characters
xdl_char:
        call xmon_read_byte             ; ... as characters
        cp #20                          ; control character ...
        jr c,xdl_dot                    ; ... -> '.'
        cp #7F                          ; &20-&7E: shown as it is ...
        jr c,xdl_show                   ; below &7F: show it
xdl_dot:
        ld a,#2E                        ; ... else '.'
xdl_show:
        call xmon_out_char              ; the character (or '.')
        inc hl                          ; next address
        djnz xdl_char                   ; next character
        call xmon_out_lf_cr             ; end of the line
        call KM_READ_CHAR               ; key pressed? (observed: none, and SPACE to pause)
        jr nc,xdl_check_end             ; no key: end test
        call xmon_get_key               ; yes: pause until the next key (observed) ...
        ret z                           ; ... ESC ends the dump (observed), another key continues (observed)
xdl_check_end:
        push hl                         ; keep the next line's start
        and a                           ; CY = 0
        sbc hl,de                       ; next line start below the end?
        pop hl                          ; HL back
        jr c,xmon_dump_lines            ; yes: next line
        scf                             ; done: CY = 1
        ret                             ; back to xmon_cmd_dump
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_fill [#EF74]
; Tasks:        XMON command F (manual): "F addr1,addr2,value" - fill memory from addr1 to addr2
;               (inclusive) with value, through xmon_fill_range. Defaults: addr1 = xmon_fill_address
;               (shared with A), addr2 = addr1, value = 00.
;               Observed 2026-10-26: F4000,400F,AA -> &4000-&400F = AA, &4010 kept (the default
;               start shown was 9000, from A9000); F4020,4010,BB -> only &4020 (end below start: one
;               byte); F + 3 x RETURN -> F4020,4020,00 (one byte); F4030 + ESC at the end address ->
;               nothing written, xmon_fill_address = &4030.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; xmon_fill_address
; Calls:        xmon_fill_range; ends in xmon_command_done
xmon_cmd_fill:
        ld hl,(xmon_fill_address)       ; default start: xmon_fill_address (shared with A - observed: 9000 after A9000)
        call xmon_fill_range            ; read the range and the value, fill
        jp xmon_command_done            ; "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_fill_range [#EF7D]
; Tasks:        Read "start,end,value" and fill start..end (inclusive) through xmon_write_byte (X /
;               Y do not matter for writes; Z's bank does). The start is stored in xmon_fill_address
;               as soon as it is read. The loop writes first and compares after, so an end below
;               the start writes exactly one byte (observed).
; Input:        HL = the default start
; Changed:      AF, BC, DE, HL; xmon_fill_address
; Called by:    xmon_cmd_fill, xdm_cmd_fill (the disc monitor's F, observed 2026-10-26)
; Calls:        xmon_input_word, xmon_out_comma_screen, xmon_input_byte_0, xmon_write_byte
xmon_fill_range:
        call xmon_input_word            ; the start address (RETURN / ',' - ESC ends the command) ...
        ld (xmon_fill_address),hl       ; ... kept at once as the next default (observed: &4030 after ESC at the end address)
        call xmon_out_comma_screen      ; ',' (screen only)
        ld d,h                          ; the end address, default = the start ...
        ld e,l                          ; (DE = HL = start)
        call xmon_input_word            ; HL = the end (RETURN / ',' - ESC ends the command)
        call xmon_out_comma_screen      ; ','
        ex de,hl                        ; HL = start, DE = end
        push de                         ; keep end ...
        push hl                         ; ... and start over the value input
        call xmon_input_byte_0          ; the value (default 00)
        pop hl                          ; HL = start ...
        pop de                          ; ... DE = end; A = the value
xfr_loop:
        call xmon_write_byte            ; write it ...
        push hl                         ; ... below the end? ...
        and a                           ; CY = 0
        sbc hl,de                       ; HL - end: CY = 1 while the address is below the end
        pop hl                          ; HL back (flags kept)
        inc hl                          ; ... next address ...
        jr c,xfr_loop                   ; ... yes: on - so start to end inclusive; an end below the start writes one byte (observed)
        ret                             ; done
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_go [#EFA2]
; Tasks:        XMON command G (manual): "G addr" - run the user program at addr with the user
;               registers (R) until a breakpoint (B) or an RST 6 (&F7) in the program, then show
;               the registers and return to the "*" prompt. The address becomes xmon_user_pc; its
;               byte is kept in xmon_run_byte; then xmon_run with DE = &EDA1 (left by
;               xmon_find_command), a negative trace count, so the first stop ends G.
;               Observed 2026-10-26 (program 3E 12 / 01 56 34 / 00 / F7 at &4000): B1 = 4005,
;               G4000 -> stop at 4005, AF 1200 BC 3456 SP BF80; B1 = 0, G4000 -> stop at the F7
;               (XP 4006 - the PC points at the RST 6 itself, so G with the default would run it
;               again); B1 = 4005, G4005 -> no breakpoint at the start, stop at 4006.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      everything; xmon_user_*, xmon_break_area, &0030-&0034, &BEE5-&BEEB, &BEFA
; Calls:        xmon_input_word, xmon_out_lf_cr; continues in xmon_run
xmon_cmd_go:
        ld hl,(xmon_user_pc)            ; default: xmon_user_pc
        call xmon_input_word            ; the start address (RETURN / ',' - ESC ends the command) ...
        ld (xmon_user_pc),hl            ; ... becomes the user PC
        ld a,(hl)                       ; keep the byte at the start (read directly) in xmon_run_byte (observed &3E)
        ld (xmon_run_byte),a            ; (put back by xmon_breakpoint at xmon_run_address)
        call xmon_out_lf_cr             ; new line, then run: DE = &EDA1 here (the return address left by xmon_find_command) - negative, so G stops at the first breakpoint
        jp xmon_run                     ; run the program (HL = the start)
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_input [#EFB5]
; Tasks:        XMON command I (manual): "I name.typ" - load a binary file to the address it was
;               saved from, through the CAS jumpblock (VDOS's disc functions; after |CAS.IN the tape
;               - manual, not tried: no tape image), and show "(load length entry)". Not under CP/M.
;               The 2K buffer passed to CAS IN OPEN is DE = &EFBE, a leftover return address (RAM
;               under the ROM, the screen); I does not use it, but it becomes the "load address"
;               of a file without header.
;               Observed 2026-10-26: I + RETURN (empty name) -> "*"; INIX.BIN -> "NIX     .BIN wurde
;               nicht gefunden"; IB:F1Z.BIN -> (BF00  0050  0000), &BF00-&BF4F = the file;
;               IB:READ.ME (no AMSDOS header) -> (EFBE  0000  0000) and nothing loaded: VDOS
;               reports length 0 and CAS IN DIRECT reads only the low 16 bits of its byte count
;               (&800000), i.e. 0 records - so I cannot load a file without header.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; the loaded memory; xmon_run_address (scratch)
; Calls:        xmon_cpm_mode, xmon_input_filename, CAS_IN_OPEN, CAS_IN_DIRECT, xmon_show_file_info,
;               CAS_IN_CLOSE, CAS_IN_ABANDON, xmon_out_lf_cr; ends in xmon_command_loop (&ED78)
xmon_cmd_input:
        call xmon_cpm_mode              ; under CP/M ...
        jp nz,xmon_command_done         ; ... I does nothing (no CAS functions there - read)
        call xmon_input_filename        ; the file name (at most 16 characters; empty: end) -> HL = name, B = length, DE = &EFBE (a return address, used as the 2K buffer)
        call CAS_IN_OPEN                ; open it (VDOS through the CAS jumpblock / |CAS.IN: tape) ...
        jr nc,xci_abandon               ; ... not found (VDOS printed "<name> wurde nicht gefunden"): end (observed)
        push de                         ; keep DE = load address ...
        push bc                         ; ... and BC = length from the header
        ex de,hl                        ; HL = the load address: load the whole file there ...
        call CAS_IN_DIRECT              ; ... CAS IN DIRECT (HL = entry address afterwards)
        pop bc                          ; BC = length ...
        pop de                          ; ... DE = load address
        jr nc,xci_abandon               ; load error: abandon (not observed)
        ex de,hl                        ; HL = load address, DE = entry address
        call xmon_show_file_info        ; show "(load length entry)" (observed: (BF00 0050 0000))
        call CAS_IN_CLOSE               ; close the file ...
xci_abandon:
        call CAS_IN_ABANDON             ; ... and abandon it (also after the close; on the error paths only this)
xmon_file_done:
        ld hl,(xmon_run_address)        ; HL back (kept by xmon_input_filename)
        call xmon_out_lf_cr             ; new line ...
        jp xmon_prompt                  ; ... and the "*" prompt (xmon_command_loop behind its LD SP)
xmon_show_file_info:
        push de                         ; keep the entry address (DE) ...
        push bc                         ; ... and the length (BC)
        call xmon_out_lf_cr             ; new line
        call xmon_out_open              ; "(" ...
        call xmon_hex_word              ; ... HL = the load address ...
        call xmon_out_two_tabs          ; ...
        pop hl                          ; ... the length ...
        call xmon_hex_word              ; ...
        call xmon_out_two_tabs          ; ...
        pop hl                          ; ... the entry address ...
        call xmon_hex_word              ; ...
        jp xmon_out_close               ; ... ")"
; ----------------------------------------------------------------------
; Subroutine: xmon_input_filename [#EFFC]
; Tasks:        Read a file name for I / O: keep HL in xmon_run_address (scratch; I takes it back),
;               then xmon_input_text with at most 16 characters (upper case; an empty name ends the
;               command). Falls into xmon_input_text (C = 16).
; Output:       HL = the name (&ACA5), B = its length; DE = the caller's return address (left by
;               xmon_input_text's POP / PUSH)
; Called by:    xmon_cmd_input, xmon_cmd_output
xmon_input_filename:
        ld (xmon_run_address),hl        ; keep HL (in xmon_run_address - used here as a scratch word)
        ld c,#10                        ; at most 16 characters
xmon_input_text:
        call xmon_input_line            ; read the text line (C = the maximum length) ...
        ld hl,xmon_text_length          ; ... the length to xmon_text_length (&ACA4) ...
        ld a,b                          ; A = the length ...
        or a                            ; ... Z = empty ...
        ld (hl),a                       ; ... stored (also when 0)
        pop de                          ; ... empty: drop the return address and end the command (observed: A with RETURN only writes nothing)
        jp z,xmon_command_done          ; empty: end the caller (A) at once
        push de                         ; ... else back with HL = the text (&ACA5)
        inc hl                          ; HL = &ACA5, the text
        ret                             ; back to A, B = the length
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_output [#F011]
; Tasks:        XMON command O (manual): "O name.typ addr,length,entry" - save memory as a binary
;               file (type 2, AMSDOS header) through the CAS jumpblock (VDOS's disc functions; after
;               |CAS.OUT the tape - manual, not tried). Not under CP/M. The three values are read
;               with xmon_input_word, each offering the value before it as its default: first HL
;               from CAS OUT OPEN (the header buffer, &A7B8), then the start, then the length. O
;               shows no message of its own; errors end silently in xco_abandon.
;               The 2K buffer passed to CAS OUT OPEN is DE = &F01A, a leftover return address (as
;               in I; RAM under the ROM, the screen) - whether VDOS uses it was not checked.
;               Observed 2026-10-26 (disc copy output/xmon_o_test.dsk in B:, never saved):
;               OB:XT.BIN,4000,0032,4000 -> XT.BIN with header type 2, load &4000, length &0032,
;               entry &4000; F4000,4031,00 and IB:XT.BIN -> (4000  0032  4000), the 50 bytes back.
;               *** BUG: ESC in one of the three inputs jumps from xmon_input_word straight to
;               xmon_command_done - the output file stays open (observed with ESC in the address
;               input: OB:XE.BIN + ESC left "XE.$$$" in the directory; length / entry: read). The
;               next O then fails silently (CAS OUT OPEN: file already open) and only its
;               xco_abandon frees the channel; a third O works again (observed: XF.BIN written
;               correctly). The "XE.$$$" entry stays on the disc.
;               *** BUGFIX PROPOSAL: abandon the output file before opening it - needs 3 more bytes
;               (and CAS_OUT_ABANDON with no file open must be harmless in VDOS - not checked); no
;               free space found in O.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; xmon_run_address (scratch, through xmon_input_filename)
; Calls:        xmon_cpm_mode, xmon_input_filename, CAS_OUT_OPEN, xmon_out_comma_screen,
;               xmon_input_word, CAS_OUT_DIRECT, CAS_OUT_CLOSE, CAS_OUT_ABANDON; ends in
;               xmon_file_done (&EFD7)
xmon_cmd_output:
        call xmon_cpm_mode              ; under CP/M ...
        jp nz,xmon_command_done         ; ... O does nothing (no CAS functions there - read, as I)
        call xmon_input_filename        ; the file name (at most 16 characters; empty: end) -> HL = name, B = length, DE = &F01A (a return address, passed as the 2K buffer)
        call CAS_OUT_OPEN               ; open the output file (VDOS: "name.$$$" in the directory, observed) - HL = the header buffer afterwards (&A7B8, the default shown next) ...
        jr nc,xco_abandon               ; ... not opened (observed: a file still open from an O ended with ESC): abandon, no message
        call xmon_out_comma_screen      ; ","
        call xmon_input_word            ; the start address (default HL = &A7B8 from CAS OUT OPEN; ESC ends the command - the file stays open, see the bug note in the header)
        push hl                         ; keep the start address
        call xmon_out_comma_screen      ; ","
        call xmon_input_word            ; the length (default: the start just entered)
        push hl                         ; keep the length
        call xmon_out_comma_screen      ; ","
        call xmon_input_word            ; the entry address (default: the length just entered)
        ld c,l                          ; BC = the entry address ...
        ld b,h
        pop de                          ; DE = the length ...
        pop hl                          ; HL = the start address ...
        ld a,#02                        ; A = 2: file type binary
        call CAS_OUT_DIRECT             ; ... write the whole block with its AMSDOS header (observed: type 2, &4000, &0032, &4000)
        jr nc,xco_abandon               ; write error: abandon (not observed)
        call CAS_OUT_CLOSE              ; close the file: "name.$$$" becomes "name.typ" (observed)
        jr xmon_file_done               ; done: new line, "*" prompt
xco_abandon:
        call CAS_OUT_ABANDON            ; error: abandon the output file (observed: the 2nd O after ESC - CAS OUT OPEN failed); the "name.$$$" entry stays on the disc
        jr xmon_file_done               ; done: new line, "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_list [#F048]
; Tasks:        XMON command L (manual): disassemble. Reads the start address (default
;               xmon_list_address); ',' reads the end address and lists while the next instruction
;               starts below it. RETURN after the start instead is the count mode: the count &16
;               is shown and counted down to 0, and 0 still shows a line - so 23 lines, not 22
;               (observed). Each line: xmon_list_line. Between lines a key pauses (xmon_list_pause:
;               the next key continues, ESC ends - observed). Ends in xmon_command_done.
;               Observed 2026-10-25: L0000,0010 (X on: the firmware's restarts), L4000,4148 (all
;               244 base opcodes &00-&FF without CB / DD / ED / FD, output/xmon_l/base_opcodes.bin),
;               L40F8,4119 and L4100,4101. 2026-10-26 (output/xmon_l/mini_test.bin): L4000 +
;               RETURN (23 lines, &4000-&401C), L4000,7FFF with SPACE (pause), SPACE (go on),
;               SPACE, ESC (end, "*" prompt).
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL
; Calls:        xmon_input_word, xmon_out_comma_screen, xmon_out_lf_cr, xmon_list_line,
;               KM_READ_CHAR, xmon_list_pause
xmon_cmd_list:
        ld hl,(xmon_list_address)       ; default: where the last L ended
        call xmon_input_word            ; start address; CY = RETURN, NC = ','
        ld (xmon_list_address),hl       ; the start is also the next default
        ld d,h                          ; default end = start
        ld e,l                          ; (DE = start)
        ld a,#16                        ; RETURN: count mode, &16 + 1 = 23 lines (observed) ...
        jr c,xl_next                    ; RETURN: list 23 lines from the start
        call xmon_out_comma_screen      ; ',': echo it ...
        call xmon_input_word            ; ... the end address (observed)
        ex de,hl                        ; DE = end, HL = start
        xor a                           ; count 0: list up to the end address
xl_next:
        push af                         ; keep the count ...
        push de                         ; ... and the end address
        call xmon_out_lf_cr             ; new line for each instruction
        xor a                           ; no index prefix yet
        ld (xmon_decoded+4),a           ; (xmon_decoded+4 = index prefix &64 IX / &65 IY)
        ld de,xmon_decoded              ; decode into xmon_decoded ...
        call xmon_list_line             ; ... and show one instruction
        call KM_READ_CHAR               ; key pressed? ...
        call c,xmon_list_pause          ; ... yes: pause, ESC ends (observed)
        ld hl,(xmon_list_address)       ; the next instruction
        pop de                          ; DE = the end ...
        pop af                          ; ... A = the count again
        or a                            ; counting? (observed both ways)
        jr z,xl_check_end               ; count 0: end test
        dec a                           ; yes: one less, next line (observed; at 0 the end test follows with end = start, so it stops)
        jr xl_next                      ; next line
xl_check_end:
        push hl                         ; below the end address? ...
        and a                           ; CY = 0
        sbc hl,de                       ; next address - end: CY = 1 while below the end
        pop hl                          ; HL back (flags kept)
        jr c,xl_next                    ; ... yes: next line
        jp xmon_command_done            ; done: new line, "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_list_line [#F089]
; Tasks:        Disassemble the instruction at HL into one line: address, the instruction bytes in
;               hex (padded to 5 bytes), the mnemonic (4 characters) and up to two operands.
;               Decoding (into xmon_decoded: length - 1, mnemonic, operand 1, operand 2, index
;               prefix): &00-&3F from xmon_opcodes_00; &40-&7F built from the bits (HALT for &76,
;               else LD r,r'); &80-&BF built from the bits (ADD / ADC / SBC A,r; SUB / AND / XOR /
;               OR / CP r); &C0-&FF from xmon_opcodes_c0, except CB (&F0D4), ED (&F1B1: &40-&7B from
;               xmon_opcodes_ed40, &7C and up at &F1C5, below &40 invalid) and DD / FD (&F1F8 /
;               &F1F4: index prefix in xmon_decoded+4, xmon_index_opcodes, DD CB, JP (IX)).
;               xmon_list_address = the next instruction. Observed 2026-10-25/26 with test files
;               in output/xmon_l/: every base, CB, ED and DD / FD path (all lines as expected; the
;               display weaknesses are noted at the branches and in todo.md, "Bugfix proposals").
; Input:        HL = address (= xmon_list_address), DE = xmon_decoded
; Changed:      AF, BC, DE, HL
; Called by:    xmon_cmd_list
; Calls:        xmon_hex_word, xmon_out_two_tabs, cm_loop, xmon_read_byte, xmon_hex_byte,
;               xmon_out_char, xmon_out_tab, xmon_out_comma, xmon_list_operand
xmon_list_line:
        call xmon_hex_word              ; the address ...
        call xmon_out_two_tabs          ; ... two tabs
        push de                         ; DE = xmon_decoded (from the caller): keep it
        ld a,#FF                        ; xmon_decoded+0..+3 = &FF ...
        ld b,#04                        ; 4 bytes: length, mnemonic, operand 1, operand 2 ...
        call cm_loop                    ; ... = &FF ("none")
        pop de                          ; DE = xmon_decoded+0
        inc a                           ; ... then length 0 (1 byte) and no index prefix
        ld (de),a                       ; +0 = 0: length - 1 = 0 (1 byte, until a table says more)
        ld (xmon_decoded+4),a           ; +4 = 0: no index prefix
xll_opcode:
        call xmon_read_byte             ; the opcode (also after DD / FD, &F264 - read)
        cp #40                          ; &00-&3F: table (observed)
        jp c,xll_table_00               ; &00-&3F: from xmon_opcodes_00
        bit 7,a                         ; &80-&FF: on at xll_80
        jp nz,xll_80                    ; &80-&FF
        inc de                          ; &40-&7F (observed): ...
        ld c,a                          ; C = the opcode
        cp #76                          ; ... &76 = HALT (mnemonic &09) ...
        ld a,#09                        ; (A = HALT; flags still from the CP)
        jr z,xll_store                  ; &76: HALT, no operands
        ld a,#08                        ; ... else LD (&08) r,r': registers from bits 5-3 and 2-0
        ld b,#00                        ; B = 0: operand 1 = register number (bits 5-3) + 0
        jr xll_two_regs                 ; mnemonic LD, operand 1 = bits 5-3, operand 2 = bits 2-0
xll_80:
        cp #C0                          ; &C0-&FF: on at xll_c0
        jp nc,xll_c0                    ; &C0-&FF: the prefixes and xmon_opcodes_c0
        inc de                          ; &80-&BF (observed): mnemonic = bits 5-3 (ADD ... CP) ...
        ld c,a                          ; C = the opcode
        and #38                         ; bits 5-3 ...
        rra                             ; ... down to bits 2-0: ...
        rra
        rra
        ld (de),a                       ; ... +1 = mnemonic 0-7 = ADD ADC SUB SBC AND XOR OR CP
        inc de                          ; DE = +2 (operand 1)
        ex de,hl                        ; (HL = +2 for the store)
        ld (hl),#07                     ; ... operand 1 = A ...
        ex de,hl                        ; DE = +2 again; A still = the mnemonic
        cp #04                          ; ... SUB / AND / XOR / OR / CP: only the register (no "A,") ...
        jr nc,xll_reg                   ; mnemonic 4-7 (AND XOR OR CP): operand 1 = the register instead of A
        cp #02                          ; mnemonic 2 = SUB ...
        jr z,xll_reg                    ; ... likewise only the register
        jr xll_next_operand             ; ... ADD / ADC / SBC: "A," then the register
; CB prefix (observed 2026-10-26, output/xmon_l/cb_test.bin, all 256 CB opcodes as expected):
; length 2; the second byte decides: &00-&2F rotates (mnemonic &0A + bits 5-3: RLC RRC RL RR
; SLA SRA), &30-&37 = the undocumented SLL -> "-??-" without operands, &38-&3F SRL, &40-&FF
; BIT / RES / SET b,r (mnemonic &10 + bits 7-6, operand 1 = name &08 + bits 5-3 = "0"-"7").
; Operand register always from bits 2-0 (B C D E H L (HL) A).
xll_cb:
        ld a,#01                        ; CB prefix: length - 1 = 1 ...
        ld (de),a                       ; +0 = 1: 2 bytes
        inc de                          ; DE = +1 (mnemonic)
        inc hl                          ; ... the second byte
        call xmon_read_byte             ; A = the byte after CB
        cp #40                          ; &40 and up: BIT / RES / SET
        jr nc,xll_cb_bits               ; &40-&FF
        ld c,a                          ; &00-&3F: C = opcode, mnemonic base &0A (RLC)
        ld b,#0A                        ; B = base for xll_bits_53
        cp #30                          ; &00-&2F: RLC ... SRA, mnemonic = &0A + bits 5-3 (observed)
        jr c,xll_bits_53                ; &00-&2F: mnemonic &0A + bits 5-3, operand 1 = bits 2-0
        sub #08                         ; &30-&3F: minus 8 ...
        cp #30                          ; ... &38-&3F (now &30-&37) = SRL: mnemonic &0A + 6 = &10 (observed)
        jr nc,xll_bits_53               ; &38-&3F (now &30-&37): bits 5-3 = 6 -> &10 SRL
        ld a,#2F                        ; &30-&37 = SLL (undocumented): "-??-" (&2F), no operands (observed)
        jr xll_store                    ; store it as the mnemonic, no operand
xll_cb_bits:
        ld c,a                          ; BIT / RES / SET: C = opcode ...
        and #C0                         ; ... mnemonic = &10 + bits 7-6 (&11 BIT, &12 RES, &13 SET) ...
        rlca                            ; bits 7-6 ...
        rlca                            ; ... to bits 1-0 (1 BIT, 2 RES, 3 SET) ...
        add a,#10                       ; ... + &10
        ld b,#08                        ; ... operand 1 base &08 = name "0" (bit number)
xll_two_regs:
        ld (de),a                       ; mnemonic ...
        inc de                          ; DE = the next field
        ld a,c                          ; A = the opcode
xll_bits_53:
        and #38                         ; ... operand 1 = B + bits 5-3 ... (CB rotates: here it is the mnemonic)
        rra                             ; bits 5-3 ...
        rra
        rra                             ; ... down to bits 2-0 ...
        add a,b                         ; ... + B (the base) ...
        ld (de),a                       ; ... stored
xll_next_operand:
        inc de                          ; DE = the next field
xll_reg:
        ld a,c                          ; ... next operand = bits 2-0 (the register)
        and #07                         ; the register number 0-7 = the operand name B C D E H L (HL) A
xll_store:
        ld (de),a                       ; store the last decoded byte, then show the line
        jr xll_show                     ; show the line
xll_table_00:
        ld hl,xmon_opcodes_00           ; &00-&3F: xmon_opcodes_00
xll_table:
        ld b,#00                        ; entry = HL + 3 * A ...
        ld c,a                          ; BC = A = the opcode's index ...
        add hl,bc                       ; ... HL + 3 * BC ...
        add hl,bc
        add hl,bc                       ; ... = the entry
        ld a,(hl)                       ; byte 0: bits 7-6 = length - 1 ...
        ld c,a                          ; C = byte 0
        and #C0                         ; bits 7-6 ...
        rlca                            ; ... to bits 1-0 ...
        rlca
        ld (de),a                       ; ... = +0: length - 1 ...
        ld b,a                          ; ... (B too)
        inc de                          ; DE = +1
        ld a,c                          ; ... bits 5-0 = mnemonic
        and #3F                         ; the mnemonic number ...
        ld (de),a                       ; ... to +1
        inc de                          ; DE = +2
        inc hl                          ; byte 1: operand 1
        ld a,(hl)                       ; operand 1 code ...
        ld (de),a                       ; ... to +2
        inc de                          ; DE = +3
        inc hl                          ; byte 2: operand 2
        ld a,(hl)                       ; operand 2 code ...
        ld (de),a                       ; ... to +3
xll_show:
        ld de,xmon_decoded              ; show it: B = length ...
        ld hl,(xmon_list_address)       ; HL = the instruction's first byte
        ld a,(de)                       ; +0 = length - 1 ...
        inc a                           ; ... + 1 ...
        ld b,a                          ; ... B = the length
        call xmon_read_byte             ; first byte: DD / FD prefix? (observed: no)
        cp #FD                          ; FD ...
        jr z,xll_show_index             ; ... or ...
        cp #DD                          ; ... DD: the prefix byte is not in the length yet
        jr nz,xll_bytes                 ; no prefix: show the bytes
xll_show_index:
        inc b                           ; index prefix (observed): one byte more ...
        inc de                          ; DE = +1 ...
        inc de                          ; ... DE = +2 (operand 1)
        ld a,(de)                       ; ... and one more if operand 1 or 2 is (HL) = (IX+d) (the displacement)
        cp #06                          ; (HL)?
        jr z,xll_show_disp              ; yes: + the displacement byte
        inc de                          ; DE = +3 (operand 2) ...
        ld a,(de)                       ; ... (HL)?
        cp #06                          ; (code &06 = (HL))
        jr nz,xll_show_first            ; no: no displacement
xll_show_disp:
        inc b                           ; one more byte: d
xll_show_first:
        ld de,xmon_decoded              ; back to the first byte for the hex output
        call xmon_read_byte             ; A = the first byte again
xll_bytes:
        ld c,b                          ; C = length; the bytes in hex ...
xll_byte_loop:
        call xmon_hex_byte              ; the byte as two hex digits (no space between the bytes) ...
        inc hl                          ; ... next address ...
        call xmon_read_byte             ; ... its byte ...
        djnz xll_byte_loop              ; ... B times
        ld (xmon_list_address),hl       ; the next instruction
        ld b,c                          ; B = the length again
        ld a,#05                        ; pad: (5 - length) times ...
        sub b                           ; 5 - length ...
        ld b,a                          ; ... times
xll_pad:
        call xmon_out_two_tabs          ; ... two tabs (two columns per byte)
        djnz xll_pad                    ; (a 5-byte instruction gets no padding)
        inc de                          ; DE = +1 (the mnemonic number)
        ld a,(de)                       ; the mnemonic: xmon_mnemonics + 4 * n ...
        push de                         ; keep DE
        ld de,xmon_mnemonics            ; the table ...
        ld h,#00                        ; ... HL = the number ...
        ld l,a
        add hl,hl                       ; ... * 4 ...
        add hl,hl
        add hl,de                       ; ... + the table = its 4 characters
        ld b,#04                        ; ... 4 characters ...
xll_mnem_loop:
        ld a,(hl)                       ; a character ...
        inc hl
        call xmon_out_char              ; ... out (a &09 in the table is a tab)
        djnz xll_mnem_loop              ; 4 of them
        call xmon_out_tab               ; ... and a tab
        pop de                          ; DE = +1 again
        ld hl,xmon_operand_names        ; operand 1 (HL = the name table, which is also the H the &F9 code shows - see xmon_list_operand) ...
        push hl                         ; keep the table address
        inc de                          ; DE = +2 ...
        ld a,(de)                       ; ... A = operand 1's code ...
        call xmon_list_operand          ; ... printed (&FF: nothing)
        pop hl                          ; HL = the table again
        inc de                          ; DE = +3
        ld a,(de)                       ; operand 2: none? ...
        cp #FF                          ; &FF ...
        ret z                           ; ... no second operand: the line is done
        call xmon_out_comma             ; ... else ',' and operand 2
        ld a,(de)                       ; operand 2's code ...
        jp xmon_list_operand            ; ... printed; returns to the caller
xll_c0:
        cp #CB                          ; &C0-&FF: CB? ...
        jp z,xll_cb                     ; CB: own decoder
        cp #ED                          ; ... ED? ...
        jr z,xll_ed                     ; ED: own decoder
        cp #DD                          ; ... DD? ...
        jr z,xll_dd                     ; DD: index prefix IX
        cp #FD                          ; ... FD? ...
        jr z,xll_fd                     ; FD: index prefix IY
        ld hl,xmon_opcodes_c0           ; ... else xmon_opcodes_c0 (observed)
        sub #C0                         ; index &00-&3F into the table
        jp xll_table                    ; decode it from the table
xll_ed:
        inc hl                          ; ED: the second byte (observed: all 256)
        call xmon_read_byte             ; A = the byte after ED
        cp #7C                          ; &7C and up: block instructions, else invalid (observed)
        jr nc,xll_ed_high               ; &7C-&FF: block instructions or invalid
        cp #40                          ; below &40: invalid "-??-" (observed)
        jr c,xll_invalid                ; &00-&3F: invalid
        sub #40                         ; &40-&7B: xmon_opcodes_ed40 (observed)
        ld hl,xmon_opcodes_ed40         ; index &00-&3B into xmon_opcodes_ed40 ...
        jp xll_table                    ; ... decoded like a base opcode
; ED &7C-&FF (observed 2026-10-26, all 132 as expected): &A0-&BB with bit 2 = 0 are the 16 block
; instructions, mnemonic &36 + (bits 4-3 * 4 + bits 1-0): LDI CPI INI OUTI / LDD CPD IND OUTD /
; LDIR CPIR INIR OTIR / LDDR CPDR INDR OTDR; everything else is "-??-" - except ED &8B, which
; shows OTDR (no Z80 instruction; OTDR = ED &BB, which the formula already gives).
; *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): the special case cp #8B is wrong; patch the
; *** operand at &F1C6 &8B -> &00 (A >= &7C here, so it never matches; ED &8B then shows "-??-");
; *** in the scrambled ROM file offset &31C6 &AB -> &20.
xll_ed_high:
        cp #8B                          ; ED &8B: special case ...
        jr nz,xll_ed_block              ; not &8B: the block range test
        ld a,#45                        ; ... mnemonic &45 OTDR (observed: ED 8B -> "OTDR")
        jr xll_ed_store                 ; store mnemonic &45
xll_ed_block:
        cp #A0                          ; below &A0 or &BC and up: invalid ...
        jr c,xll_invalid                ; below &A0: invalid
        cp #BC                          ; &BC and up ...
        jr nc,xll_invalid               ; ... invalid
        bit 2,a                         ; ... and bit 2 set (&A4-&A7, &AC-&AF, &B4-&B7): invalid
        jr nz,xll_invalid               ; &x4-&x7 / &xC-&xF: invalid
        ld c,a                          ; C = opcode; B = bits 4-3 * 4 ...
        rra                             ; bits 4-3 ...
        and #0C                         ; ... to bits 3-2 (row * 4) ...
        ld b,a                          ; ... in B
        ld a,c                          ; ... + bits 1-0 ...
        and #03                         ; bits 1-0 (column) ...
        or b                            ; ... + row * 4 = 0-15
        add a,#36                       ; ... + &36 (LDI): the block mnemonic (observed: all 16)
xll_ed_store:
        ld hl,xmon_decoded              ; length - 1 = 1 (2 bytes), mnemonic A, no operands (still &FF)
        ld (hl),#01                     ; +0 = 1: 2 bytes ...
        inc hl                          ; ... +1 = ...
        ld (hl),a                       ; ... the mnemonic; +2 / +3 stay &FF (no operands)
        dec hl                          ; HL = +0 ...
        ex de,hl                        ; ... DE = +0
        jp xll_show                     ; show the line
xll_invalid:
        ld a,#2F                        ; invalid: mnemonic &2F "-??-" (observed)
        jr xll_ed_store                 ; store it, 2 bytes
; DD / FD prefix (observed 2026-10-26, output/xmon_l/ddfd_test.bin, 95 lines as expected): the
; prefix (&64 IX / &65 IY) goes to xmon_decoded+4 and the byte after the opcode to xmon_index_disp.
; - DD / FD CB d op: own decoder (&F20F): rotates / BIT / RES / SET on (IX+d), 4 bytes.
; - DD / FD E9: JP (IX) / JP (IY) (&F267).
; - the 38 opcodes of xmon_index_opcodes: decoded by the base decoder (jp xll_opcode);
;   xmon_list_operand turns HL into IX / IY and (HL) into (IX+&dd), xll_show adds the prefix and
;   the displacement to the length.
; - anything else: "-??-".
; Display weaknesses (observed): an invalid DD / FD xx (and DD CB d with an odd op) shows 3 bytes,
; one too many; DD CB d 36 (SLL) shows SRL; the undocumented DD CB ops with a register show as the
; plain (IX+d) form; the displacement is shown unsigned. See todo.md, "Bugfix proposals".
xll_fd:
        ld a,#65                        ; FD: index prefix &65 = IY (observed)
        jr xll_index                    ; (DD: A = &64 below)
xll_dd:
        ld a,#64                        ; DD: index prefix &64 = IX (observed)
xll_index:
        ld (xmon_decoded+4),a           ; keep the prefix in xmon_decoded+4 (also the base for the IX / IY names) ...
        inc hl                          ; ... the byte after the opcode ...
        inc hl                          ; HL = prefix + 2 ...
        call xmon_read_byte             ; ... that byte = d for (IX+d) instructions
        ld (xmon_index_disp),a          ; ... = the displacement d, if the instruction has one (observed)
        dec hl                          ; the opcode after the prefix
        call xmon_read_byte             ; HL = prefix + 1: the opcode ...
        ld c,a                          ; ... C = the opcode
        cp #CB                          ; DD CB d op?
        jp nz,xll_index_op              ; not CB: E9, the index list or invalid
        ld a,#01                        ; DD CB: length - 1 = 1; xll_show adds the prefix and the displacement: 4 bytes
        ld (de),a                       ; +0 = 1 (2 bytes; + prefix + d added in xll_show = 4)
        inc de                          ; DE = +1
        inc hl                          ; ... op = the fourth byte
        inc hl                          ; HL = prefix + 3: the CB opcode (after d)
        call xmon_read_byte             ; A = op
        ld c,a                          ; C = op
        bit 0,a                         ; odd op: invalid (only bit 0 is checked - observed: the undocumented even ops with a register, e.g. 00 / 02 / 04, show as RLC (IX+d))
        jp nz,xll_invalid               ; odd op: invalid
        cp #3F                          ; &40 and up: BIT / RES / SET
        jr nc,xll_ixcb_bits             ; &40 and up (op = &3F is odd, already gone): BIT / RES / SET
        srl a                           ; rotates: y = bits 5-3 ...
        srl a                           ; bits 5-3 ...
        srl a                           ; ... down: y = 0-7
        cp #07                          ; ... y = 7 (SRL) -> 6, as mnemonic &0A + 6 = &10 is SRL; SLL (y = 6) gives &10 too, so DD CB d 36 shows SRL (observed)
        jr nz,xll_ixcb_rot              ; y <> 7: mnemonic &0A + y
        dec a                           ; y = 7 (SRL): 6, as &0A + 6 = &10 is SRL - y = 6 (SLL) gives SRL too
xll_ixcb_rot:
        add a,#0A                       ; mnemonic &0A + y ...
        ld (de),a                       ; +1 = the mnemonic
        inc de                          ; DE = +2
        ld a,#06                        ; ... operand 1 = (HL) -> (IX+d) / (IY+d)
        ld (de),a                       ; +2 = &06 = (HL), shown as (IX+d) / (IY+d)
        jp xll_show                     ; show the line
xll_ixcb_bits:
        rlca                            ; BIT / RES / SET: mnemonic &10 + bits 7-6 ...
        rlca                            ; bits 7-6 to bits 1-0 ...
        and #03                         ; ... 1 BIT, 2 RES, 3 SET ...
        add a,#10                       ; ... + &10 = &11-&13
        ld (de),a                       ; +1 = the mnemonic
        inc de                          ; DE = +2
        ld a,c                          ; ... operand 1 = the bit number: name &08 + bits 5-3 ...
        rra                             ; bits 5-3 ...
        rra
        rra                             ; ... down ...
        and #07                         ; ... the bit number 0-7 ...
        add a,#08                       ; ... as name &08-&0F ("0"-"7")
        ld (de),a                       ; +2 = the bit number
        inc de                          ; DE = +3
        ld a,#06                        ; ... operand 2 = (HL) -> (IX+d) / (IY+d)
        ld (de),a                       ; +3 = (IX+d) / (IY+d)
        jp xll_show                     ; show the line
xll_index_op:
        cp #E9                          ; DD / FD E9: JP (IX) / JP (IY)?
        jr z,xll_index_jp               ; E9: JP (IX) / JP (IY)
        ld b,#26                        ; else: is the opcode one of the 38 in xmon_index_opcodes? ...
        push hl                         ; keep HL (prefix + 1)
        ld hl,xmon_index_opcodes        ; the 38 allowed opcodes ...
xll_index_find:
        cp (hl)                         ; ... this one?
        jr z,xll_index_found            ; yes: decode it
        inc hl                          ; next entry ...
        djnz xll_index_find             ; ... 38 times
        pop hl                          ; not found: invalid, "-??-" - shown as 3 bytes (length 2 + the prefix), one byte too many (observed: DD 00 / DD 76 / DD 7C)
        jp xll_invalid                  ; not in the list: "-??-"
xll_index_found:
        pop hl                          ; found: decode the opcode with the base decoder; xmon_list_operand turns HL / (HL) into IX / IY / (IX+d) (observed)
        jp xll_opcode                   ; decode the opcode at HL (prefix + 1) with the base decoder; xmon_decoded+4 still holds the prefix
xll_index_jp:
        xor a                           ; JP (IX) / (IY): prefix flag 0, length - 1 = 0 (xll_show adds the prefix) ...
        ld (xmon_decoded+4),a           ; prefix flag 0: "(IX)" is a name of its own, no (IX+d) / IX conversion
        ld (de),a                       ; +0 = 0 (1 byte; xll_show adds the prefix)
        inc de                          ; DE = +1
        ld a,#17                        ; ... mnemonic &17 JP ...
        ld (de),a                       ; +1 = JP
        inc de                          ; DE = +2
        dec hl                          ; ... the prefix again: DD -> name &19 "(IX)", FD -> &1A "(IY)" (observed)
        call xmon_read_byte             ; HL = the prefix byte
        cp #DD                          ; DD? ...
        ld a,#19                        ; ... name &19 "(IX)" ...
        jr z,xll_index_jp_reg           ; ... yes
        inc a                           ; FD: name &1A "(IY)"
xll_index_jp_reg:
        ld (de),a                       ; +2 = the operand
        jp xll_show                     ; show the line
; ----------------------------------------------------------------------
; Subroutine: xmon_list_operand [#F280]
; Tasks:        Print one operand of the instruction being listed. Code &00-&7F: the n-th name of
;               xmon_operand_names (counted; HL = the table), with (HL) -> (IX+d) / (IY+d) and HL ->
;               IX / IY after an index prefix (&F2A7 / &F2C2, read). Code &80 and up (the instruction
;               bytes are read back before xmon_list_address): &C0-&F8 = RST address (bits 5-3, two
;               hex digits), &F9 = "(&nn)" - BUG: it jumps to the output without reading the byte,
;               so it shows H = &F4 (the high byte of xmon_operand_names) instead of the port:
;               OUT (n),A and IN A,(n) always show (&F4) (observed 2026-10-25 with D3 12 and D3 56),
;               &FA = "(&nn)" with the byte read (the same output done right), &FB = relative jump
;               target "&nnnn", &FC = "&nn", &FD = "(&nnnn)", &FE = "&nnnn", &FF = no operand.
;               &FE and &FB also store the word in xmon_branch_target.
; Input:        A = operand code, HL = xmon_operand_names
; Changed:      AF, BC, HL
; Called by:    xmon_list_line
; Calls:        xmon_out_char, xmon_out_amp, xmon_out_open, xmon_out_close, xmon_hex_byte,
;               xmon_hex_word, xmon_read_byte
xmon_list_operand:
        bit 7,a                         ; &80 and up: special operand
        jr nz,xlo_special               ; &80 and up: special codes
        ld b,a                          ; B = the name number
        cp #06                          ; (HL)? ...
        jr z,xlo_hl_ind                 ; (HL): maybe (IX+d)
        cp #13                          ; ... HL?
        jr z,xlo_hl                     ; HL: maybe IX / IY
xlo_name:
        ld a,b                          ; the n-th name: count ...
xlo_name_a:
        ld b,#00                        ; entry with A = name number (also called for IX / IY, read)
xlo_count:
        cp b                            ; ... names until B = n ...
        jr z,xlo_print                  ; the n-th name reached: print it
xlo_skip:
        bit 7,(hl)                      ; ... skip one name (to its bit-7 character)
        inc hl                          ; next character ...
        jr z,xlo_skip                   ; ... until the one with bit 7 has been passed
        inc b                           ; one name more
        jr xlo_count                    ; compare again
xlo_print:
        ld a,(hl)                       ; print the name up to its bit-7 character
        and #7F                         ; without bit 7 ...
        call xmon_out_char              ; ... out
        bit 7,(hl)                      ; last character of the name? ...
        inc hl                          ; (next)
        jr z,xlo_print                  ; ... no: on
        ret                             ; done
xlo_hl_ind:
        ld a,(xmon_decoded+4)           ; (HL): no index prefix -> "(HL)"; else "(IX+" / "(IY+" and the displacement (both observed)
        or a                            ; A = the prefix: 0, &64 or &65
        jr z,xlo_name                   ; no prefix: the name "(HL)"
        sub #64                         ; prefix &64 / &65 -> name &17 "(IX+" / &18 "(IY+" ...
        add a,#17                       ; &64 / &65 -> &17 "(IX+" / &18 "(IY+"
        call xlo_name_a                 ; print it
        ld a,(xmon_index_disp)          ; ... then "&" xmon_index_disp ")" (observed; shown unsigned: d = -3 -> "(IX+&FD)")
xlo_amp_byte:
        push af                         ; "&", the byte A ...
        call xmon_out_amp               ; "&" ...
        pop af                          ; ... the byte ...
        call xmon_hex_byte              ; ... as two hex digits
        jp xmon_out_close               ; ... and ")"
xlo_hl:
        ld a,(xmon_decoded+4)           ; HL: no index prefix -> "HL"; else "IX" / "IY" (both observed)
        or a                            ; A = the prefix
        jr z,xlo_name                   ; no prefix: the name "HL"
        sub #64                         ; prefix &64 / &65 -> name &15 "IX" / &16 "IY" (observed)
        add a,#15                       ; &64 / &65 -> &15 "IX" / &16 "IY"
        jr xlo_name_a                   ; print it
xlo_special:
        cp #F9                          ; &80-&F8: RST address ...
        jr c,xlo_rst                    ; &80-&F8: an RST
; *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): operand code &F9 = (n) of OUT (n),A / IN A,(n)
; *** (the only users: entries &D3, &DB) jumps straight to xlo_port without reading the byte, so
; *** H = &F4 is shown. Patch, 1 byte, no new space: the jr displacement at &F2D3 &57 -> &02
; *** (jr z,&F2D6: read the last two bytes like &FA-&FE; the inc a chain then reaches xlo_port
; *** with H = n); in the scrambled ROM file offset &32D3 &5F -> &0A. Code &FA, which does this
; *** already, is used by no table entry.
        jr z,xlo_port                   ; &F9 "(n)": BUG - straight to the output, the byte is not read: H = &F4 (observed)
        inc a                           ; &FF: no operand
        ret z                           ; &FF + 1 = 0: no operand
        ld hl,(xmon_list_address)       ; &FA-&FE: H, L = the last two instruction bytes ...
        dec hl                          ; HL = the last instruction byte
        push af                         ; keep the code (+1)
        call xmon_read_byte             ; the last byte ...
        ld c,a                          ; ... in C ...
        dec hl                          ; ... and the one before it ...
        call xmon_read_byte             ; ... its byte ...
        ld l,a                          ; ... L = the byte before ...
        ld h,c                          ; ... H = the last byte: HL = the word nn (H alone = n or e)
        pop af                          ; A = code + 1 again
        inc a                           ; &FE "&nnnn" (observed) ...
        jr nz,xlo_fd                    ; not &FE: on
        call xmon_out_amp               ; &FE: "&" ...
        ld (xmon_branch_target),hl      ; ... also kept as xmon_branch_target
        jp xmon_hex_word                ; ... nnnn
xlo_fd:
        inc a                           ; &FD "(&nnnn)" (observed)
        jr nz,xlo_fc                    ; not &FD: on
        call xmon_out_open              ; &FD: "(" ...
        call xmon_out_amp               ; ... "&" ...
        call xmon_hex_word              ; ... nnnn ...
        jp xmon_out_close               ; ... ")"
xlo_fc:
        inc a                           ; &FC "&nn" (observed)
        jr nz,xlo_fb                    ; not &FC: on
        call xmon_out_amp               ; &FC: "&" ...
        ld a,h                          ; ... the last byte = n ...
        jp xmon_hex_byte                ; ... as two hex digits
xlo_fb:
        inc a                           ; &FB relative jump: target = next address + e (observed forward) ...
        jr nz,xlo_port                  ; not &FB: &FA (port)
        ld b,#00                        ; &FB: BC = e (the last byte) ...
        ld c,h                          ; ... (C = e) ...
        ld hl,(xmon_list_address)       ; ... HL = the next instruction ...
        bit 7,c                         ; ... e negative?
        jr nz,xlo_back                  ; yes: subtract
        add hl,bc                       ; no: next + e
xlo_target:
        ld (xmon_branch_target),hl      ; ... kept as xmon_branch_target, shown as "&nnnn"
        call xmon_out_amp               ; "&" ...
        jp xmon_hex_word                ; ... the target as 4 hex digits
xlo_back:
        ld a,c                          ; negative e: C = -e, target = next address - (-e) (observed: 18 FE at &4000 -> &4000, 20 80 at &4004 -> &3F86)
        cpl                             ; e negative: complement ...
        inc a                           ; ... C = -e (two's complement) ...
        ld c,a                          ; ... = -e (positive)
        xor a                           ; CY = 0 for the SBC
        sbc hl,bc                       ; next - (-e)
        jr xlo_target                   ; keep and show it
xlo_port:
        call xmon_out_open              ; &FA (and the buggy &F9): "(", then "&" H ")"
        ld a,h                          ; the port byte n (H from the word read above; the &F9 path comes here without that read: H = &F4)
        jr xlo_amp_byte                 ; "&nn)"
xlo_rst:
        and #38                         ; RST: the address in bits 5-3, two hex digits (observed "RST 08" ... "RST 38")
        jp xmon_hex_byte                ; the RST address as two hex digits ("08", "38")
; XMON disassembler: the mnemonics, 4 characters each (padded with &09 = tab), &46 entries; entry n
; at xmon_mnemonics + 4 * n (xmon_list_line, &F16C). 00 ADD 01 ADC 02 SUB 03 SBC 04 AND 05 XOR 06 OR
; 07 CP 08 LD 09 HALT 0A RLC 0B RRC 0C RL 0D RR 0E SLA 0F SRA 10 SRL 11 BIT 12 RES 13 SET 14 POP 15
; PUSH 16 EX 17 JP 18 INC 19 DEC 1A NOP 1B RLCA 1C RRCA 1D DJNZ 1E RLA 1F JR 20 RRA 21 DAA 22 CPL 23
; SCF 24 CCF 25 CALL 26 RST 27 RET 28 POP 29 OUT 2A PUSH 2B EXX 2C IN 2D DI 2E EI 2F "-??-" (invalid)
; 30 NEG 31 RETN 32 IM 33 RETI 34 RRD 35 RLD 36 LDI 37 CPI 38 INI 39 OUTI 3A LDD 3B CPD 3C IND
; 3D OUTD 3E LDIR 3F CPIR 40 INIR 41 OTIR 42 LDDR 43 CPDR 44 INDR 45 OTDR. Read: all entries except
; 14 / 15, the unused duplicates of POP / PUSH (the tables use 28 / 2A; L tests 2026-10-25/26).
xmon_mnemonics:
        defb "ADD",#09                  ; &00: ADD
        defb "ADC",#09                  ; &01: ADC
        defb "SUB",#09                  ; &02: SUB
        defb "SBC",#09                  ; &03: SBC
        defb "AND",#09                  ; &04: AND
