; XMON disassembler: the operand names, each ended by bit 7; operand code n (&00-&29) = the n-th
; name, found by counting (xmon_list_operand). 00 B 01 C 02 D 03 E 04 H 05 L 06 (HL) 07 A 08-0F 0-7
; 10 AF 11 BC 12 DE 13 HL 14 SP 15 IX 16 IY 17 "(IX+" 18 "(IY+" 19 (IX) 1A (IY) 1B (BC) 1C (DE)
; 1D "ERR:" 1E (SP) 1F AF' 20 I 21 M 22 NC 23 NZ 24 P 25 PE 26 PO 27 Z 28 R 29 (C). Codes &80 and
; up are not names (xmon_list_operand: &C0-&F8 RST address, &F9 / &FA (n), &FB relative jump,
; &FC n, &FD (nn), &FE nn, &FF none). Read completely (L test 2026-10-25).
xmon_operand_names:
        defb "B"+#80
        defb "C"+#80
        defb "D"+#80
        defb "E"+#80
        defb "H"+#80
        defb "L"+#80
        defb "(HL",")"+#80
        defb "A"+#80
        defb "0"+#80
        defb "1"+#80
        defb "2"+#80
        defb "3"+#80
        defb "4"+#80
        defb "5"+#80
        defb "6"+#80
        defb "7"+#80
        defb "A","F"+#80
        defb "B","C"+#80
        defb "D","E"+#80
        defb "H","L"+#80
        defb "S","P"+#80
        defb "I","X"+#80
        defb "I","Y"+#80
        defb "(IX","+"+#80
        defb "(IY","+"+#80
        defb "(IX",")"+#80
        defb "(IY",")"+#80
        defb "(BC",")"+#80
        defb "(DE",")"+#80
        defb #0D,#0A,"ERR",":"+#80
        defb "(SP",")"+#80
        defb "AF","'"+#80
        defb "I"+#80
        defb "M"+#80
        defb "N","C"+#80
        defb "N","Z"+#80
        defb "P"+#80
        defb "P","E"+#80
        defb "P","O"+#80
        defb "Z"+#80
        defb "R"+#80
        defb "(C",")"+#80
; XMON disassembler: the entries of the opcodes &00-&3F, 3 bytes each (xmon_list_line, &F10B):
; byte 0 bits 7-6 = length - 1, bits 5-0 = mnemonic (xmon_mnemonics); byte 1 / byte 2 = operand 1
; / operand 2 (xmon_operand_names codes, &80 and up special, &FF = none). E.g. &01: 88 11 FE =
; 3 bytes, LD, BC, nn. Opcodes &40-&BF have no table (LD r,r' / HALT and the ALU group are built
; from the opcode bits). Read completely (L test 2026-10-25).
xmon_opcodes_00:
        defb #1A,#FF,#FF                ; &00: NOP - 1 byte
        defb #88,#11,#FE                ; &01: LD BC,nn - 3 bytes
        defb #08,#1B,#07                ; &02: LD (BC),A - 1 byte
        defb #18,#11,#FF                ; &03: INC BC - 1 byte
        defb #18,#00,#FF                ; &04: INC B - 1 byte
        defb #19,#00,#FF                ; &05: DEC B - 1 byte
        defb #48,#00,#FC                ; &06: LD B,n - 2 bytes
        defb #1B,#FF,#FF                ; &07: RLCA - 1 byte
        defb #16,#10,#1F                ; &08: EX AF,AF' - 1 byte
        defb #00,#13,#11                ; &09: ADD HL,BC - 1 byte
        defb #08,#07,#1B                ; &0A: LD A,(BC) - 1 byte
        defb #19,#11,#FF                ; &0B: DEC BC - 1 byte
        defb #18,#01,#FF                ; &0C: INC C - 1 byte
        defb #19,#01,#FF                ; &0D: DEC C - 1 byte
        defb #48,#01,#FC                ; &0E: LD C,n - 2 bytes
        defb #1C,#FF,#FF                ; &0F: RRCA - 1 byte
        defb #5D,#FB,#FF                ; &10: DJNZ e - 2 bytes
        defb #88,#12,#FE                ; &11: LD DE,nn - 3 bytes
        defb #08,#1C,#07                ; &12: LD (DE),A - 1 byte
        defb #18,#12,#FF                ; &13: INC DE - 1 byte
        defb #18,#02,#FF                ; &14: INC D - 1 byte
        defb #19,#02,#FF                ; &15: DEC D - 1 byte
        defb #48,#02,#FC                ; &16: LD D,n - 2 bytes
        defb #1E,#FF,#FF                ; &17: RLA - 1 byte
        defb #5F,#FB,#FF                ; &18: JR e - 2 bytes
        defb #00,#13,#12                ; &19: ADD HL,DE - 1 byte
        defb #08,#07,#1C                ; &1A: LD A,(DE) - 1 byte
        defb #19,#12,#FF                ; &1B: DEC DE - 1 byte
        defb #18,#03,#FF                ; &1C: INC E - 1 byte
        defb #19,#03,#FF                ; &1D: DEC E - 1 byte
        defb #48,#03,#FC                ; &1E: LD E,n - 2 bytes
        defb #20,#FF,#FF                ; &1F: RRA - 1 byte
        defb "_#","{"+#80               ; &20: JR NZ,e - 2 bytes
        defb #88,#13,#FE                ; &21: LD HL,nn - 3 bytes
        defb #88,#FD,#13                ; &22: LD (nn),HL - 3 bytes
        defb #18,#13,#FF                ; &23: INC HL - 1 byte
        defb #18,#04,#FF                ; &24: INC H - 1 byte
        defb #19,#04,#FF                ; &25: DEC H - 1 byte
        defb #48,#04,#FC                ; &26: LD H,n - 2 bytes
        defb #21,#FF,#FF                ; &27: DAA - 1 byte
        defb "_'","{"+#80               ; &28: JR Z,e - 2 bytes
        defb #00,#13,#13                ; &29: ADD HL,HL - 1 byte
        defb #88,#13,#FD                ; &2A: LD HL,(nn) - 3 bytes
        defb #19,#13,#FF                ; &2B: DEC HL - 1 byte
        defb #18,#05,#FF                ; &2C: INC L - 1 byte
        defb #19,#05,#FF                ; &2D: DEC L - 1 byte
        defb #48,#05,#FC                ; &2E: LD L,n - 2 bytes
        defb #22,#FF,#FF                ; &2F: CPL - 1 byte
        defb #5F,#22,#FB                ; &30: JR NC,e - 2 bytes
        defb #88,#14,#FE                ; &31: LD SP,nn - 3 bytes
        defb #88,#FD,#07                ; &32: LD (nn),A - 3 bytes
        defb #18,#14,#FF                ; &33: INC SP - 1 byte
        defb #18,#06,#FF                ; &34: INC (HL) - 1 byte
        defb #19,#06,#FF                ; &35: DEC (HL) - 1 byte
        defb #48,#06,#FC                ; &36: LD (HL),n - 2 bytes
        defb #23,#FF,#FF                ; &37: SCF - 1 byte
        defb #5F,#01,#FB                ; &38: JR C,e - 2 bytes
        defb #00,#13,#14                ; &39: ADD HL,SP - 1 byte
        defb #88,#07,#FD                ; &3A: LD A,(nn) - 3 bytes
        defb #19,#14,#FF                ; &3B: DEC SP - 1 byte
        defb #18,#07,#FF                ; &3C: INC A - 1 byte
        defb #19,#07,#FF                ; &3D: DEC A - 1 byte
        defb #48,#07,#FC                ; &3E: LD A,n - 2 bytes
        defb #24,#FF,#FF                ; &3F: CCF - 1 byte
; XMON disassembler: the entries of the opcodes &C0-&FF, 3 bytes each, format as xmon_opcodes_00
; (the entries of the prefixes CB / DD / ED / FD are not used). RST &08 / &10 / &18 have length 3
; (A6 C8 FF): XMON skips the CPC inline word after RST 1-3 like the firmware does; the word shows in
; the byte column only, not as an operand (observed: CF 34 12 -> "CF3412    RST  08"). RST &20-&38
; have length 1 - also RST &28 (FIRM JUMP), whose inline word the firmware skips too: XMON lists it
; as instructions (observed: EF 34 12 -> "RST 28", "INC (HL)", "LD (DE),A"). Read except the unused
; prefix entries CB DD ED FD (D0 D1 D8 D9 E0 E1 in the mini test 2026-10-26).
xmon_opcodes_c0:
        defb #27,#23,#FF                ; &C0: RET NZ - 1 byte
        defb #28,#11,#FF                ; &C1: POP BC - 1 byte
        defb #97,#23,#FE                ; &C2: JP NZ,nn - 3 bytes
        defb #97,#FE,#FF                ; &C3: JP nn - 3 bytes
        defb #A5,#23,#FE                ; &C4: CALL NZ,nn - 3 bytes
        defb #2A,#11,#FF                ; &C5: PUSH BC - 1 byte
        defb #40,#07,#FC                ; &C6: ADD A,n - 2 bytes
        defb #26,#C0,#FF                ; &C7: RST &00 - 1 byte
        defb #27,#27,#FF                ; &C8: RET Z - 1 byte
        defb #27,#FF,#FF                ; &C9: RET - 1 byte
        defb #97,#27,#FE                ; &CA: JP Z,nn - 3 bytes

; ---- never accessed: #F585-#F587 (3 bytes, fill: static) ----
        defb #FF,#FF,#FF                ; &CB: prefix, entry not used (FF FF FF) - unreachable: xll_c0 branches to xll_cb (&F19A) before the table is indexed (proven 2026-10-26: every possible input ran without reading it)
; ---- end of never accessed ----

        defb #A5,#27,#FE                ; &CC: CALL Z,nn - 3 bytes
        defb #A5,#FE,#FF                ; &CD: CALL nn - 3 bytes
        defb #41,#07,#FC                ; &CE: ADC A,n - 2 bytes
        defb #A6,#C8,#FF                ; &CF: RST &08 - 3 bytes (+ CPC inline word: shown in the byte column, not as an operand)
        defb #27,#22,#FF                ; &D0: RET NC - 1 byte
        defb #28,#12,#FF                ; &D1: POP DE - 1 byte
        defb #97,#22,#FE                ; &D2: JP NC,nn - 3 bytes
        defb #69,#F9,#07                ; &D3: OUT (n),A - 2 bytes - operand code &F9: shown as (&F4), bug in xmon_list_operand (bugfix proposal at &F2D2)
        defb #A5,#22,#FE                ; &D4: CALL NC,nn - 3 bytes
        defb #2A,#12,#FF                ; &D5: PUSH DE - 1 byte
        defb #42,#FC,#FF                ; &D6: SUB n - 2 bytes
        defb #A6,#D0,#FF                ; &D7: RST &10 - 3 bytes (+ CPC inline word: shown in the byte column, not as an operand)
        defb #27,#01,#FF                ; &D8: RET C - 1 byte
        defb #2B,#FF,#FF                ; &D9: EXX - 1 byte
        defb #97,#01,#FE                ; &DA: JP C,nn - 3 bytes
        defb #6C,#07,#F9                ; &DB: IN A,(n) - 2 bytes - operand code &F9: shown as (&F4), bug in xmon_list_operand (bugfix proposal at &F2D2)
        defb #A5,#01,#FE                ; &DC: CALL C,nn - 3 bytes

; ---- never accessed: #F5BB-#F5BD (3 bytes, fill: static) ----
