; ---- end of never accessed ----

        defb #43,#07,#FC                ; &DE: SBC A,n - 2 bytes
        defb #A6,#D8,#FF                ; &DF: RST &18 - 3 bytes (+ CPC inline word: shown in the byte column, not as an operand)
        defb #27,#26,#FF                ; &E0: RET PO - 1 byte
        defb #28,#13,#FF                ; &E1: POP HL - 1 byte
        defb #97,#26,#FE                ; &E2: JP PO,nn - 3 bytes
        defb #16,#1E,#13                ; &E3: EX (SP),HL - 1 byte
        defb #A5,#26,#FE                ; &E4: CALL PO,nn - 3 bytes
        defb #2A,#13,#FF                ; &E5: PUSH HL - 1 byte
        defb #44,#FC,#FF                ; &E6: AND n - 2 bytes
        defb #26,#E0,#FF                ; &E7: RST &20 - 1 byte
        defb #27,#25,#FF                ; &E8: RET PE - 1 byte
        defb #17,#06,#FF                ; &E9: JP (HL) - 1 byte
        defb #97,#25,#FE                ; &EA: JP PE,nn - 3 bytes
        defb #16,#12,#13                ; &EB: EX DE,HL - 1 byte
