        defb #2D,#FF,#FF                ; &F3: DI - 1 byte
        defb #A5,#24,#FE                ; &F4: CALL P,nn - 3 bytes
        defb #2A,#10,#FF                ; &F5: PUSH AF - 1 byte
        defb #46,#FC,#FF                ; &F6: OR n - 2 bytes
