        defb #8E                        ; &8E: ADC A,(IX+d)
        defb #96                        ; &96: SUB (IX+d)
        defb #9E                        ; &9E: SBC A,(IX+d)
        defb #A6                        ; &A6: AND (IX+d)
        defb #AE                        ; &AE: XOR (IX+d)
        defb #B6                        ; &B6: OR (IX+d)
        defb #BE                        ; &BE: CP (IX+d)
        defb #E1                        ; &E1: POP IX
        defb #E3                        ; &E3: EX (SP),IX
        defb #E5                        ; &E5: PUSH IX
        defb #F9                        ; &F9: LD SP,IX
; XMON disassembler: the entries of ED &40-&7B, 3 bytes each, format as xmon_opcodes_00
; (xmon_list_line, &F1BF). ED &00-&3F are invalid; ED &7C and up are decoded at &F1C5 (block
; instructions). Read completely (L test 2026-10-26, output/xmon_l/ed_test.bin): every documented
; ED instruction as on the Z80; the undocumented duplicates (NEG / RETN / IM copies, IN (C),
; OUT (C),0, LD (nn),HL / LD HL,(nn) at &63 / &6B, NOP &77) are "-??-" with length 2.
xmon_opcodes_ed40:
        defb #6C,#00,#29                ; ED &40: IN B,(C) - 2 bytes
        defb #69,#29,#00                ; ED &41: OUT (C),B - 2 bytes
        defb #43,#13,#11                ; ED &42: SBC HL,BC - 2 bytes
        defb #C8,#FD,#11                ; ED &43: LD (nn),BC - 4 bytes
        defb #70,#FF,#FF                ; ED &44: NEG - 2 bytes
