        defb #69,#29,#01                ; ED &49: OUT (C),C - 2 bytes
        defb #41,#13,#11                ; ED &4A: ADC HL,BC - 2 bytes
        defb #C8,#11,#FD                ; ED &4B: LD BC,(nn) - 4 bytes
        defb #6F,#FF,#FF                ; ED &4C: -??- - 2 bytes (Z80: NEG, undocumented)
        defb #73,#FF,#FF                ; ED &4D: RETI - 2 bytes
        defb #6F,#FF,#FF                ; ED &4E: -??- - 2 bytes (Z80: IM, undocumented)
        defb #48,#28,#07                ; ED &4F: LD R,A - 2 bytes
        defb #6C,#02,#29                ; ED &50: IN D,(C) - 2 bytes
        defb #69,#29,#02                ; ED &51: OUT (C),D - 2 bytes
        defb #43,#13,#12                ; ED &52: SBC HL,DE - 2 bytes
        defb #C8,#FD,#12                ; ED &53: LD (nn),DE - 4 bytes
        defb #6F,#FF,#FF                ; ED &54: -??- - 2 bytes (Z80: NEG, undocumented)
        defb #6F,#FF,#FF                ; ED &55: -??- - 2 bytes (Z80: RETN, undocumented)
        defb #72,#09,#FF                ; ED &56: IM 1 - 2 bytes
        defb #48,#07,#20                ; ED &57: LD A,I - 2 bytes
        defb #6C,#03,#29                ; ED &58: IN E,(C) - 2 bytes
        defb #69,#29,#03                ; ED &59: OUT (C),E - 2 bytes
        defb #41,#13,#12                ; ED &5A: ADC HL,DE - 2 bytes
        defb #C8,#12,#FD                ; ED &5B: LD DE,(nn) - 4 bytes
        defb #6F,#FF,#FF                ; ED &5C: -??- - 2 bytes (Z80: NEG, undocumented)
        defb #6F,#FF,#FF                ; ED &5D: -??- - 2 bytes (Z80: RETN, undocumented)
        defb #72,#0A,#FF                ; ED &5E: IM 2 - 2 bytes
        defb #48,#07,#28                ; ED &5F: LD A,R - 2 bytes
        defb #6C,#04,#29                ; ED &60: IN H,(C) - 2 bytes
        defb #69,#29,#04                ; ED &61: OUT (C),H - 2 bytes
