        defb #6F,#FF,#FF                ; ED &64: -??- - 2 bytes (Z80: NEG, undocumented)
        defb #6F,#FF,#FF                ; ED &65: -??- - 2 bytes (Z80: RETN, undocumented)
        defb #6F,#FF,#FF                ; ED &66: -??- - 2 bytes (Z80: IM, undocumented)
        defb #74,#FF,#FF                ; ED &67: RRD - 2 bytes
