        defb #6F,#FF,#FF                ; ED &6C: -??- - 2 bytes (Z80: NEG, undocumented)
        defb #6F,#FF,#FF                ; ED &6D: -??- - 2 bytes (Z80: RETN, undocumented)
        defb #6F,#FF,#FF                ; ED &6E: -??- - 2 bytes (Z80: IM, undocumented)
        defb #75,#FF,#FF                ; ED &6F: RLD - 2 bytes
        defb #6F,#FF,#FF                ; ED &70: -??- - 2 bytes (Z80: IN (C), undocumented)
