; Subroutine: xmon_cmd_substitute [#F70B]
; Tasks:        XMON command S (manual): "S addr" - show and change memory byte by byte. Each line:
;               the address, the byte as a character (a space below &20 and from &80), the byte in
;               hex and an input field with the old value as the default (xmon_input_byte). RETURN
;               writes the value (always, through xmon_write_byte - also when unchanged) and goes
;               to the next address; ESC ends S. The line shown differs from the manual (address,
;               old, new): XMON 2.11 adds the character column.
;               Observed 2026-10-26 (41 05 9A 11 at &4000): S4000 -> "4000  A  41  41" RETURN,
;               "4001     05" + 55 RETURN, "4002     9A" + 7 RETURN (-> A7), "4003     11" ESC ->
;               &4000 = 41 55 A7 11, xmon_subst_address = &4003.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, HL; xmon_subst_address
; Calls:        xmon_input_word, xmon_out_lf_cr, xmon_hex_word, xmon_out_two_tabs, xmon_read_byte,
;               xmon_out_char, xmon_hex_byte, xmon_input_byte, xmon_write_byte; ends through ESC in
;               xmon_input_byte (xmon_command_done)
xmon_cmd_substitute:
        ld hl,(xmon_subst_address)      ; default: xmon_subst_address (where the last S ended)
xss_input:
        call xmon_input_word            ; HL = the start address (RETURN / ','; ESC ends the command)
xss_line:
        call xmon_out_lf_cr             ; each address on a new line:
        call xmon_hex_word              ; the address (4 hex digits) ...
        call xmon_out_two_tabs          ; ... two tabs
        ld (xmon_subst_address),hl      ; the current address is kept at once (observed: &4003 after ESC on that line)
        call xmon_read_byte             ; the byte (xmon_read_byte: X / Y / Z apply) ...
        cp #20                          ; ... below &20 (control) ...
        jr c,xss_space                  ; ... -> a space
        bit 7,a                         ; ... &80 and up ...
        jr z,xss_char                   ; ... -> a space too; else the character itself
xss_space:
        ld a,#20                        ; a space instead (observed for &05 and &9A)
xss_char:
        call xmon_out_char              ; the character column
        call xmon_out_two_tabs          ; two tabs
        call xmon_read_byte             ; the byte again ...
        call xmon_hex_byte              ; ... as two hex digits
        call xmon_out_two_tabs          ; two tabs
        call xmon_read_byte             ; the byte a third time: the default ...
        call xmon_input_byte            ; ... for the new value (hex digits shift in from the right, RETURN takes it, ESC ends S - observed: 41 kept, 05 -> 55, 9A + "7" -> A7)
        call xmon_write_byte            ; written back in every case, also when unchanged (xmon_write_byte)
        inc hl                          ; next address
        jr xss_line                     ; next line
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_move [#F745]
; Tasks:        XMON command M (manual): "M addr1,addr2,addr3" - copy addr1..addr2 (inclusive) to
;               addr3, through xmon_read_byte (X / Y / Z apply) and xmon_write_byte. Defaults: addr1 =
;               0000, addr2 = addr1, addr3 = addr2. A target above the end or at / below the start
;               is copied upwards; an overlapping target (start < target <= end) downwards.
;               Observed 2026-10-26 (data 11 22 33 44 55 66 77 at &4000): M4000,4006,5000 -> copy;
;               M4002,4006,4000 -> 33 44 55 66 77 66 77; M4000,4003,4002 -> 11 22 33 11 22 33 44
;               (BUG, should be 11 22 11 22 33 44 77); M + 3 x RETURN -> M0000,0000,0000 (one byte
;               onto itself).
;               Read, not tried: an end below the start gives a length of nearly 64K and overwrites
;               all memory, XMON's stack included.
; *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): the downward copy starts at target + length
; *** instead of target + length - 1. Reorder the 7 one-byte instructions at &F78C-&F792 so that INC
; *** BC comes after the ADD: ld b,h / ld c,l / pop hl / ex de,hl / add hl,bc / ex de,hl / inc bc -
; *** &F78E-&F792 03 E1 EB 09 EB -> E1 EB 09 EB 03 (opcodes, unscrambled: the same bytes at file
; *** offset &378E-&3792). No new space needed.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL
; Calls:        xmon_input_word, xmon_out_comma, xmon_read_byte, xmon_write_byte; ends in
;               xmon_command_done
xmon_cmd_move:
        ld hl,#0000                     ; default start 0000
        call xmon_input_word            ; HL = start (addr1; RETURN / ',' end the input, ESC ends the command)
        push hl                         ; stack: start
        call xmon_out_comma             ; ','
        call xmon_input_word            ; HL = end (addr2; default = start, still in HL)
        push hl                         ; stack: start, end
        call xmon_out_comma             ; ','
        call xmon_input_word            ; HL = target (addr3; default = end)
        ex de,hl                        ; DE = target
        pop hl                          ; HL = end (taken from the stack ...
        push hl                         ; ... and kept there: stack start, end)
        and a                           ; CY = 0 for the SBC
        sbc hl,de                       ; end - target: CY = 1 if the target lies above the end
        jr nc,xcm_check_start           ; target <= end: it may overlap - xcm_check_start decides
; Upward copy (xcm_forward): BC = end - start + 1 bytes, HL runs from the start upwards (source),
; DE from the target upwards. Each byte is read before anything above it is written, so this
; order is safe whenever the target lies above the whole range (no overlap) or at / below the
; start (an overlap downwards only overwrites bytes that were already copied).
xcm_forward:
        pop hl                          ; HL = end (stack: start)
        pop bc                          ; BC = start ...
        push bc                         ; ... kept again (stack: start)
        and a                           ; CY = 0
        sbc hl,bc                       ; HL = end - start (an end below the start wraps to nearly 64K)
        ld b,h                          ; BC = end - start ...
        ld c,l                          ; (C = L)
        inc bc                          ; ... + 1 = the number of bytes
        pop hl                          ; HL = start = the source pointer; DE = the target pointer; stack empty again
xcm_fwd_loop:
        call xmon_read_byte             ; A = the source byte (through xmon_read_byte: X / Y / Z apply) ...
        ex de,hl                        ; ... HL = target for the write ...
        call xmon_write_byte            ; ... written through xmon_write_byte ...
        ex de,hl                        ; ... HL = source, DE = target again
        inc hl                          ; both pointers one byte up
        inc de                          ; (DE + 1)
        dec bc                          ; one byte less ...
        ld a,b                          ; ... BC = 0?
        or c                            ; (B or C)
        jr nz,xcm_fwd_loop              ; no: the next byte (observed: 7 bytes for M4000,4006,5000)
xcm_done:
        jp xmon_command_done            ; "*" prompt
xcm_check_start:
        pop bc                          ; BC = end (stack: start)
        pop hl                          ; HL = start ...
        push hl                         ; ... both back on the stack in the same order (start, end), as xcm_forward / xcm_backward expect
        push bc                         ; (end on top)
        and a                           ; CY = 0
        sbc hl,de                       ; start - target: CY = 1 if the target lies above the start
        jr nc,xcm_forward               ; target <= start: an upward copy cannot overwrite bytes it still has to read (observed: M4002,4006,4000) -> xcm_forward
; Downward copy (xcm_backward), for start < target <= end: an upward copy would overwrite source
; bytes before they are read, so the copy runs from the top down: HL from the end (the last source
; byte) downwards, DE from the last target byte downwards, BC = end - start + 1 bytes.
; BUG: DE starts at target + length instead of target + length - 1, so the whole copy lands one
; byte too high and the byte above the target range is overwritten (fix: INC BC after the ADD -
; see the bugfix proposal at xmon_cmd_move).
xcm_backward:
        pop hl                          ; start < target <= end: copy from the top down. HL = end (stack: start)
        pop bc                          ; BC = start
        push hl                         ; keep the end (stack: end)
        and a                           ; CY = 0
        sbc hl,bc                       ; HL = end - start
        ld b,h                          ; BC = end - start ...
        ld c,l                          ; (C = L)
        inc bc                          ; ... + 1 = the number of bytes (BUG: this INC comes too early, see below)
        pop hl                          ; HL = end = the source pointer (the last byte); stack empty again
        ex de,hl                        ; HL = target ...
        add hl,bc                       ; ... + BC = target + length - BUG: one too high; the last target byte is target + length - 1 (observed: M4000,4003,4002 wrote &4006-&4003 instead of &4005-&4002) ...
        ex de,hl                        ; ... DE = that target pointer, HL = source pointer
xcm_bwd_loop:
        call xmon_read_byte             ; A = the source byte (xmon_read_byte) ...
        ex de,hl                        ; ... HL = target for the write ...
        call xmon_write_byte            ; ... written through xmon_write_byte ...
        ex de,hl                        ; ... HL = source, DE = target again
        dec hl                          ; both pointers one byte down
        dec de                          ; (DE - 1)
        dec bc                          ; one byte less ...
        ld a,b                          ; ... BC = 0?
        or c                            ; (B or C)
        jr nz,xcm_bwd_loop              ; no: the next byte
        jr xcm_done                     ; done: "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_trace [#F7A4]
; Tasks:        XMON command T (manual): "T addr,count" - single-step the user program. Each step
;               lists the instruction at the PC (xmon_list_line), puts RST 6 at the next instruction
;               (and, for JP / JR / DJNZ / CALL, at the target too) and runs it through xmon_run;
;               xmon_breakpoint shows the registers, counts down and (key: pause, ESC: end) goes on
;               at xtr_step. RET is not run but done by XMON itself (xtr_ret); RST 1 / 5 put the
;               breakpoint at the return address on the stack, RST 2 / 3 only there.
;               Observed 2026-10-26 (programs at &4000-&40F2): LD / DJNZ / JR / CALL / JP (HL) /
;               JP (IX) / JP (IY) / RET, RST 08 (LOW JUMP to &000F), RST 28 (FIRM JUMP), RST 18 (FAR
;               CALL), RET NZ, RST 30; key pause and ESC.
;               Bugs and weaknesses (all observed):
;               1. RET cc is always taken (RET NZ with Z = 1 returned).
;               2. After xtr_ret the step count becomes the return address and the next listing
;                  starts at the user SP: T goes on and can lose control in the program.
;               3. RST &00 / &20 / &30 / &38 are done like a RET (pop the stack).
;               4. RST &08 / &28: a POP HL without PUSH takes a word from XMON's stack as the next
;                  address (F7 written there and put back); XMON's SP moves by 2.
;               5. A jump to itself (DJNZ $, JR $) never runs: its target breakpoint is the PC.
;               6. After RST &10 / &18 the program runs on to the caller of the current routine.
; *** BUGFIX PROPOSAL for 2 (todo.md, "Bugfix proposals"): at &F838 jp &F92A instead of jp &F931 -
; *** the operand low byte &F839 &31 -> &2A (raw offset &3839 &39 -> &22): HL = PC and DE = the
; *** count are then loaded again (the RET step itself is then not counted).
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      everything; xmon_user_*, xmon_trace_count, xmon_branch_byte, &BEFF bits 7-5
; Calls:        xmon_input_word, xmon_out_comma_screen, xmon_out_lf_cr, xmon_list_line,
;               xmon_read_byte; continues in xmon_run
xmon_cmd_trace:
        ld hl,(xmon_user_pc)            ; default: xmon_user_pc
        call xmon_input_word            ; the start address (RETURN / ',' - ESC ends the command) ...
        ld (xmon_user_pc),hl            ; ... becomes the user PC
        ld de,#0000                     ; RETURN: DE = 0 = one step (observed) ...
        jr c,xtr_step                   ; RETURN: one step
        call xmon_out_comma_screen      ; ',': the number of steps, default 1 (observed: 000E, 000F, 0002, 0003) ...
        ex de,hl                        ; DE = the start, HL = 0 ...
        inc hl                          ; ... HL = 1 = the default count ...
        call xmon_input_word            ; ... read the count (hex)
        dec hl                          ; ... DE = number - 1
        ex de,hl                        ; DE = count - 1, HL = the start
xtr_step:
        ld a,(xmon_printer_switch)      ; one step: clear the trace flags (bits 7-5 of &BEFF) ...
        and #1F                         ; keep bits 4-0 (bit 0 = printer echo) ...
        ld (xmon_printer_switch),a      ; ... no trace flag set
        push de                         ; ... keep the count; list the instruction at the PC (observed: one line per step) ...
        ld (xmon_list_address),hl       ; the PC to list
        call xmon_out_lf_cr             ; two new lines ...
        call xmon_out_lf_cr             ; ... between the steps
        xor a                           ; no index prefix ...
        ld (xmon_decoded+4),a           ; ... yet
        ld de,xmon_decoded              ; decode into xmon_decoded ...
        call xmon_list_line             ; ... and list the instruction at the PC (it leaves the mnemonic at +1, the target in xmon_branch_target)
        call xmon_out_lf_cr             ; new line
        ld hl,(xmon_list_address)       ; ... HL = the next instruction (xmon_list_address)
        pop de                          ; DE = the count
        ld a,(xmon_decoded+1)           ; by the mnemonic: JP / JR / DJNZ / CALL -> a breakpoint at the target too ...
        cp #17                          ; JP ...
        jr z,xtr_branch                 ; ...
        cp #1F                          ; ... JR ...
        jr z,xtr_branch                 ; ...
        cp #1D                          ; ... DJNZ ...
        jr z,xtr_branch                 ; ...
        cp #25                          ; ... CALL ...
        jr z,xtr_branch                 ; ... -> breakpoints at the target and the next instruction
        cp #27                          ; ... RET (also RET cc!) -> done without running (xtr_ret) ...
        jr z,xtr_ret                    ; RET (any) -> xtr_ret
        cp #26                          ; ... RST -> by its number; anything else: only the next instruction
        jr nz,xtr_next                  ; no RST: only the next instruction
xtr_rst:
        push hl                         ; RST: the opcode at the PC ...
        ld hl,(xmon_user_pc)            ; the opcode itself ...
        ld a,(hl)                       ; ... (the mnemonic does not tell which RST) ...
        pop hl                          ; ... HL = the next instruction again
        cp #CF                          ; ... &CF (LOW JUMP) or &EF (FIRM JUMP): ...
        jr nz,xtr_rst_ef                ; not &CF
xtr_rst_jump:
        ld hl,(xmon_user_sp)            ; ... the routine returns to the word on the user stack: a breakpoint there (observed: &4063 / &40A3) - BUG: it then jumps to xtr_target_hl without the PUSH HL of xtr_branch, so the POP HL at &F86F takes a word from XMON's stack (observed: &0044) as "next" (F7 written there, put back later) and XMON's stack moves by 2
        ld e,(hl)                       ; the word ...
        inc hl                          ; ...
        ld d,(hl)                       ; ... at the user SP ...
        ex de,hl                        ; ... HL = the return address of the routine RST 1 / 5 jumps to
        ld a,(xmon_printer_switch)      ; trace flag bit 7 ...
        set 7,a                         ; ...
        ld (xmon_printer_switch),a      ; ... set: the target breakpoint must be put back
        jr xtr_target_hl                ; target = HL (but there is no PUSH HL on this path: see xtr_target)
xtr_rst_ef:
        cp #EF                          ; &EF (FIRM JUMP)? ...
        jr z,xtr_rst_jump               ; ... yes: as &CF
        cp #D7                          ; &D7 (SIDE CALL) or &DF (FAR CALL): ...
        jr nz,xtr_rst_df                ; not &D7
xtr_rst_call:
        ld hl,(xmon_user_sp)            ; ... only a breakpoint at the word on the user stack (the caller of the current routine), not after the RST: the code after it runs unstepped (observed: DF at &4044 -> stop at &4093, the RET at &4047 ran)
        ld e,(hl)                       ; the word ...
        inc hl                          ; ...
        ld d,(hl)                       ; ... at the user SP ...
        ex de,hl                        ; ... = HL, used as the "next instruction"
        jr xtr_next                     ; one breakpoint there
xtr_rst_df:
        cp #DF                          ; any other RST (&00, &20, &30, &38) falls into xtr_ret - BUG: done like a RET (observed with &F7: it popped &0000)
        jr z,xtr_rst_call               ; &DF: as &D7
xtr_ret:
        ld hl,(xmon_user_sp)            ; RET without running it: PC = the word on the user stack, SP + 2 (observed) - BUG 1: also for RET cc whose condition is false (observed: RET NZ with Z = 1 returned)
        ld e,(hl)                       ; the word at the user SP ...
        inc hl                          ; ...
        ld d,(hl)                       ; ... = DE = the return address ...
        inc hl                          ; ... SP + 2 ...
        ld (xmon_user_sp),hl            ; ... the new user SP ...
        ld (xmon_user_pc),de            ; ... and the new user PC - no instruction runs
        jp xbp_show                     ; BUG 2: into xmon_breakpoint behind the loads of HL / DE (&F92A): DE = the return address becomes the step count and HL = the user SP the next address to list (observed: T went on at &BF80 and lost control in the program) - see the bugfix proposal at &F82A
xtr_branch:
        ld a,(xmon_printer_switch)      ; JP / JR / DJNZ / CALL: trace flag (bit 7 of &BEFF) ...
        set 7,a                         ; ...
        ld (xmon_printer_switch),a      ; ... set
        push hl                         ; keep HL = the next instruction
        ld a,(xmon_decoded+2)           ; ... the target: (HL) -> user HL (JP (HL), observed) ...
        cp #06                          ; operand 1 = (HL)?
        jr nz,xtr_branch_ix             ; no
        ld hl,(xmon_user_hl)            ; JP (HL): the target is the user HL
        jr xtr_target_hl                ; target = HL
xtr_branch_ix:
        cp #19                          ; ... (IX) -> user IX (observed) ...
        jr nz,xtr_branch_iy             ; no
        ld hl,(xmon_user_ix)            ; JP (IX): the user IX
        jr xtr_target_hl                ; target = HL
xtr_branch_iy:
        cp #1A                          ; ... (IY) -> user IY (observed); else the target the disassembler left in xmon_branch_target
        jr nz,xtr_target                ; none of them: the target from xmon_list_line
        ld hl,(xmon_user_iy)            ; JP (IY): the user IY
xtr_target_hl:
        ld (xmon_branch_target),hl      ; the target ...
xtr_target:
        ld hl,(xmon_branch_target)      ; ... its byte (through xmon_read_byte) to xmon_branch_byte, RST 6 there (a jump to itself, e.g. DJNZ $, thus stops at once and never runs - observed)
        call xmon_read_byte             ; the byte at the target ...
        ld (xmon_branch_byte),a         ; ... kept ...
        ld a,#F7                        ; ... and RST 6 ...
        ld (hl),a                       ; ... there (directly: the write goes to RAM)
        pop hl                          ; HL = the next instruction (pushed at &F843; on the RST 1 / 5 path a word of XMON's stack - bug)
xtr_next:
        call xmon_read_byte             ; the next instruction: its byte to xmon_run_byte, RST 6 there; then on in xmon_run
        ld (xmon_run_byte),a            ; ... its byte kept ...
        ld a,#F7                        ; ... RST 6 ...
        ld (hl),a                       ; ... there; falls into xmon_run
; ----------------------------------------------------------------------
; Subroutine: xmon_run [#F879]
; Tasks:        Start the user program (G, and T for each step): keep the trace count (DE) and the
;               start address (HL); for each of the 8 breakpoints keep the byte at its address and
;               put RST 6 (&F7) there, except at the start address; put XMON's breakpoint entry into
;               &0030 (PUSH IY / RST 3 / DEFW xmon_break_far); keep XMON's SP in xmon_run_sp; load
;               the user SP, build "JP user PC" at &BEFA, load BC DE HL AF IY IX and RET into it.
;               Breakpoints are written and read directly (not through xmon_write_byte /
;               xmon_read_byte): an address from &C000 on would read VDOS (not tried).
;               The user program comes back through RST 6 -> &0030 -> xmon_breakpoint.
; Input:        DE = trace count (negative: stop at the first breakpoint), HL = start address
; Called by:    xmon_cmd_go (jp), T (not run yet)
xmon_run:
        ld (xmon_trace_count),de        ; DE: the trace count (G: negative), HL: the start address
        ld (xmon_run_address),hl        ; the start address (for G: the program start; for T: the next instruction)
        ld hl,#BF00                     ; set the 8 breakpoints of xmon_break_area: ...
        ld b,#08                        ; 8 entries
xrun_break:
        ld e,(hl)                       ; ... DE = its address ...
        inc hl                          ; (E = low ...
        ld d,(hl)                       ; ... D = high)
        inc hl                          ; HL = entry + 2
        ld a,(de)                       ; ... keep the byte there again (read directly) ...
        ld (hl),a                       ; ... into entry + 2 ...
        inc hl                          ; HL = the next entry
        push hl                         ; keep it
        ld hl,(xmon_user_pc)            ; ... the start address itself gets no breakpoint (observed: G4005 with B1 = 4005) ...
        or a                            ; CY = 0
        sbc hl,de                       ; PC = this address?
        pop hl                          ; HL back (flags kept)
        jr z,xrun_next                  ; yes: no breakpoint here
        ld a,#F7                        ; ... else RST 6 (&F7) there - an unused entry (0000) puts it at &0000 (observed; put back afterwards)
        ld (de),a                       ; (directly into RAM)
xrun_next:
        djnz xrun_break                 ; next entry
        ld hl,USER_RESTART              ; &0030 (RST 6): PUSH IY / RST 3 (FAR CALL) / DEFW xmon_break_far (&BED0 -> xmon_breakpoint, ROM 5)
        ld (hl),#FD                     ; &0030 = &FD ...
        inc hl                          ; ...
        ld (hl),#E5                     ; ... &E5 (PUSH IY) ...
        inc hl                          ; ...
        ld (hl),#DF                     ; ... &DF (RST 3) ...
        inc hl                          ; ...
        ld (hl),#D0                     ; ... DEFW &BED0 ...
        inc hl                          ; ...
        ld (hl),#BE                     ; ... (the far address xmon_break_far)
        ld (xmon_run_sp),sp             ; keep XMON's SP, switch to the user SP
        ld sp,(xmon_user_sp)            ; SP = the user SP
        ld hl,xmon_user_jump            ; &BEFA = JP user PC; its address on the user stack for the final RET
        ld (hl),#C3                     ; &BEFA = &C3: JP (xmon_user_pc follows) ...
        push hl                         ; ... its address on the user stack for the RET below
        ld bc,(xmon_user_bc)            ; the user registers BC, DE, HL (on the stack), AF, IY, IX ...
        ld de,(xmon_user_de)            ; DE
        ld hl,(xmon_user_hl)            ; HL ...
        push hl                         ; ... on the stack (HL is still needed)
        ld hl,(xmon_user_af)            ; AF ...
        push hl                         ; ...
        pop af                          ; ... through the stack
        ld hl,(xmon_user_iy)            ; IY ...
        push hl                         ; ...
        pop iy                          ; ... through the stack
        ld hl,(xmon_user_ix)            ; IX ...
        push hl                         ; ...
        pop ix                          ; ... through the stack
        pop hl                          ; ... HL
        ret                             ; RET to &BEFA: JP to the user program (observed)
; ----------------------------------------------------------------------
; Subroutine: xmon_breakpoint [#F8D9]
; Tasks:        The RST 6 target (via &0030: PUSH IY / RST 3 FAR CALL through xmon_break_far): keep
;               the user's HL DE BC AF IX, put back the bytes under the 8 breakpoints (last entry
;               first) and the byte at the start address, drop the FAR CALL frame (observed on the
;               stack at entry: B9FC 0000 0586 0035, then the IY from &0030, then the RST return
;               address), keep IY, PC (= return address - 1) and SP, go back to XMON's stack and
;               show the registers. Then count the trace count down: negative (G) -> "*" prompt;
;               else (T) the next step at &F947 (not run yet). With trace flags in &BEFF bits 7-5
;               (T) it also puts back the byte under T's branch-target breakpoint (&F90B, not run).
;               Observed 2026-10-26 with G (three stops, all registers and bytes as expected).
; Input:        entered by RST 6 from the user program
; Changed:      everything; xmon_user_*, the breakpoint bytes, the byte at xmon_run_address
xmon_breakpoint:
        push ix                         ; keep the user's IX (IX is used below)
        ld (xmon_user_hl),hl            ; keep the user's HL, DE, BC, AF, IX (IX was pushed first) ...
        ld (xmon_user_de),de            ; DE
        ld (xmon_user_bc),bc            ; BC
        push af                         ; AF ...
        pop hl                          ; ...
        ld (xmon_user_af),hl            ; ... through HL
        pop hl                          ; IX ...
        ld (xmon_user_ix),hl            ; ... from the stack
        ld b,#08                        ; put back the 8 bytes under the breakpoints, the last entry first (unused entries all share &0000: the first one's byte wins - observed &0000 = 01 again)
        ld hl,#BF17                     ; HL = entry 8 + 2 (the saved byte of B8)
xbp_restore:
        ld a,(hl)                       ; the saved byte ...
        dec hl                          ; ...
        ld d,(hl)                       ; ... the address high ...
        dec hl                          ; ...
        ld e,(hl)                       ; ... and low ...
        dec hl                          ; HL = the previous entry + 2
        ld (de),a                       ; ... the byte back (directly into RAM)
        djnz xbp_restore                ; B8 down to B1
        ld hl,(xmon_run_address)        ; the byte at the start address back (xmon_run_address / xmon_run_byte)
        ld a,(xmon_run_byte)            ; the byte kept by G / xtr_next ...
        ld (hl),a                       ; ... back
        ld a,(xmon_printer_switch)      ; trace flags (bits 7-5 of &BEFF) set? ...
        and #E0                         ; (bits 7-5)
        jr z,xbp_unwind                 ; none: no branch-target breakpoint (G and simple T steps)
        ld hl,(xmon_branch_target)      ; ... T: the byte under its branch-target breakpoint back (not run yet)
        ld a,(xmon_branch_byte)         ; its byte ...
        ld (hl),a                       ; ... back
xbp_unwind:
        pop hl                          ; drop the FAR CALL frame (4 words) ...
        pop hl                          ; (the FAR CALL frame of the firmware:
        pop hl                          ; return into RST 3, ROM state, ...
        pop hl                          ; ... and the return address &0035 behind the RST 3 at &0032)
        pop hl                          ; ... the IY pushed at &0030 ...
        ld (xmon_user_iy),hl            ; = the user IY
        pop hl                          ; ... and the RST return address - 1 = the user PC (observed &4005 / &4006)
        dec hl                          ; (the RST 6 was one byte)
        ld (xmon_user_pc),hl            ; = the address of the breakpoint = the user PC
        ld hl,#0000                     ; the user SP (observed &BF80)
        add hl,sp                       ; HL = SP after the pops ...
        ld (xmon_user_sp),hl            ; ... = the user SP at the breakpoint
        ld hl,(xmon_run_sp)             ; back to XMON's stack
        ld sp,hl                        ; SP = XMON's own stack again
        ld hl,(xmon_user_pc)            ; HL = PC, DE = the trace count
        ld de,(xmon_trace_count)        ; (xtr_ret jumps in below this line - bug)
xbp_show:
        push de                         ; show the stop: HL = PC, DE = the step count
        push hl                         ; keep PC and count over the new line
        call xmon_out_lf_cr             ; new line, the registers (xmon_show_registers), two new lines
        pop hl                          ; HL = PC ...
        pop de                          ; ... DE = count
        call xmon_show_registers        ; the names and the values
        call xmon_out_lf_cr             ; two new lines ...
        call xmon_out_lf_cr             ; ... below the values
        dec de                          ; count down: negative (G) -> "*" prompt (observed) ...
        bit 7,d                         ; negative?
        jp nz,xmon_command_loop         ; yes: back to the "*" prompt (G, the end of T)
        call KM_READ_CHAR               ; ... T: a key pauses, then the next step (not run yet)
        call c,xmon_list_pause          ; key: pause, ESC ends (observed)
        jp xtr_step                     ; T: the next step (HL = PC, DE = count)
xmon_register_names:
        defb "AFBCDEHLIXIYSPXP"         ; R: the 8 column names, 2 characters each: AF BC DE HL IX IY SP XP (XP = the user PC)
; ----------------------------------------------------------------------
; Subroutine: xmon_show_registers [#F960]
; Tasks:        Show the user registers in two lines: the names "-AF-  -BC-  -DE-  -HL-  -IX-  -IY-
;               -SP-  -XP-" (xmon_register_names, four tabs between the columns), then the values of
;               the 7 pairs from xmon_user_af and xmon_user_pc, then CR: the cursor stands at the
;               start of the value line, where R edits the values in place (observed).
; Output:       the cursor at the start of the value line
; Changed:      AF, BC
; Called by:    xmon_cmd_registers (possibly also the breakpoint code &F8D9.., not run yet)
; Calls:        xmon_out_minus, xmon_out_char, xmon_out_four_tabs, xmon_out_lf_cr, xmon_hex_byte
xmon_show_registers:
        push hl                         ; keep HL
        ld hl,xmon_register_names       ; the names ...
        ld b,#08                        ; ... 8 columns: "-AF-" ... "-XP-" (observed)
xsr_name:
        call xmon_out_minus             ; "-" ...
        ld a,(hl)                       ; ... first letter ...
        call xmon_out_char
        inc hl                          ; ...
        ld a,(hl)                       ; ... second letter ...
        call xmon_out_char
        inc hl                          ; next name
        call xmon_out_minus             ; ... "-"
        call xmon_out_four_tabs         ; four tabs to the next column
        djnz xsr_name                   ; 8 names
        call xmon_out_lf_cr             ; next line: the values ...
        ld hl,xmon_user_af              ; ... the 7 pairs from xmon_user_af (&BEEC): AF BC DE HL IX IY SP ...
        ld b,#07                        ; 7 pairs
xsr_value:
        ld c,(hl)                       ; C = low byte ...
        inc hl                          ; ...
        ld a,(hl)                       ; ... A = high byte ...
        inc hl                          ; ... HL = the next pair
        call xmon_hex_byte              ; ... high byte, low byte ...
        ld a,c                          ; the low byte ...
        call xmon_hex_byte              ; ... (the high byte was printed first)
        push bc                         ; (xmon_out_four_tabs changes B)
        call xmon_out_four_tabs         ; ... four tabs
        pop bc                          ; ...
        djnz xsr_value                  ; next pair
        ld a,(xmon_user_pc+1)           ; then the user PC (&BEFB, after the internal byte &BEFA): high ...
        call xmon_hex_byte              ; (high byte of the PC)
        ld a,(xmon_user_pc)             ; ... low
        call xmon_hex_byte              ; (low byte of the PC)
        pop hl                          ; HL back
        ld a,#0D                        ; CR: the cursor back to the start of the value line (for the editing in R)
        jp xmon_out_char                ; CR, through xmon_out_char
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_registers [#F9A7]
; Tasks:        XMON command R (manual): show and change the user registers that G / T load. Shows
;               the names and values (xmon_show_registers), then edits them in place from left to
;               right: the 7 pairs xmon_user_af ... xmon_user_sp (&BEEC-&BEF9), then xmon_user_pc
;               (&BEFB, "XP"; &BEFA is skipped). Each value: xmon_edit_word (default = old value;
;               hex digits shift in, RETURN or ',' take it) and stored at once. ESC ends R at once:
;               the pairs done so far stay changed, the rest is kept. R runs no user code and
;               changes no CPU register of the user program - only the RAM copies.
;               Observed 2026-10-26: 8 x RETURN (nothing changed, new line, "*"); 1234 RETURN /
;               5678 ',' / 'G' (ignored, beep) 9ABC RETURN / ESC -> AF BC DE changed, HL kept,
;               "*" at once; values set back to 0000 afterwards.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; xmon_user_af ... xmon_user_pc
; Calls:        xmon_out_lf_cr, xmon_show_registers, xmon_edit_word; ends in xmon_command_done
xmon_cmd_registers:
        call xmon_out_lf_cr             ; new line
        call xmon_show_registers        ; names and values (the cursor waits at the start of the value line)
        ld hl,xmon_user_af              ; edit the 7 pairs from &BEEC ...
        ld b,#07                        ; 7 pairs
xcr_pair:
        ld e,(hl)                       ; ... HL = the pair's value (DE = its address + 1) ...
        inc hl                          ; (E = low ...
        ld d,(hl)                       ; ... D = high)
        ex de,hl                        ; HL = the value = the default, DE = the pair's address + 1
        push bc                         ; keep the counter
        call xmon_edit_word             ; ... edit it in place (ESC ends R here; the pairs done so far stay changed - observed)
        pop bc                          ; ... and store it at once (observed: 1234 / 5678 / 9ABC)
        ex de,hl                        ; HL = address + 1, DE = the new value
        dec hl                          ; the pair's address ...
        ld (hl),e                       ; ... low byte ...
        inc hl                          ; ...
        ld (hl),d                       ; ... high byte
        inc hl                          ; HL = the next pair
        djnz xcr_pair                   ; next pair
        inc hl                          ; skip &BEFA (internal byte): the user PC at &BEFB ...
        ld e,(hl)                       ; the user PC ...
        inc hl                          ; ...
        ld d,(hl)                       ; ...
        ex de,hl                        ; ... = the default, DE = &BEFC
        call xmon_edit_word             ; ... edit and store it too
        ex de,hl                        ; HL = &BEFC, DE = the new PC
        dec hl                          ; &BEFB ...
        ld (hl),e                       ; ... low ...
        inc hl                          ; ...
        ld (hl),d                       ; ... high
        call xmon_out_lf_cr             ; new line, "*" prompt (observed)
        jp xmon_command_done            ; "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_edit_word [#F9D6]
; Tasks:        Edit one value of R in place: xmon_input_word (default HL), then four cursor-left,
;               the value again (screen only) and four spaces to the next column.
;               BUG (observed 2026-10-26): it calls xmon_hex_byte_quiet twice without putting the
;               printer switch back (&BEFE -> &BEFF, as xmon_input_byte / _word do); the second call
;               even saves the cleared switch in &BEFE. So after the first value of R the printer
;               echo is off for good (P on, R, RETURN: &BEFE / &BEFF 01 01 -> 00 00).
; *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): call xmon_hex_byte (&FA28) instead of
; *** xmon_hex_byte_quiet (&FA1B) at &F9DF and &F9E3 - operand low bytes &F9E0 &1B -> &28 (raw
; *** offset &39E0 &1B -> &28) and &F9E4 &1B -> &28 (raw offset &39E4 &3B -> &08). The switch is
; *** then never touched, and the printer gets the final value of each register.
; Input:        HL = the old value (default)
; Output:       HL = the new value (RETURN or ','); ESC ends the command
; Changed:      AF, B, C; &BEFE, &BEFF (the bug)
; Called by:    xmon_cmd_registers
; Calls:        xmon_input_word, xmon_out_a_4, xmon_hex_byte_quiet
xmon_edit_word:
        call xmon_input_word            ; read the new value (default HL; RETURN or ',' take it - both observed; ESC ends the command) ...
        ld a,#08                        ; ... four cursor-left over it ...
        call xmon_out_a_4               ; (four &08)
        ld a,h                          ; ... show it again (screen only; BUG: the printer switch is not put back - see the header) ...
        call xmon_hex_byte_quiet        ; high byte (screen only - it saves the printer switch to &BEFE and clears bit 0) ...
        ld a,l                          ; ...
        call xmon_hex_byte_quiet        ; ... low byte (the second save copies the already cleared switch)
        ld a,#20                        ; ... and four spaces to the next column (falls into xmon_out_a_4)
; Print character A four times with TXT OUTPUT (observed: four &08 = cursor back over a
; four-digit value in xmon_input_word). Changed: B = 0.
xmon_out_a_4:
        ld b,#04                        ; four times ...
xoa_loop:
        call TXT_OUTPUT                 ; ... A
        djnz xoa_loop                   ; B times (B = 4; B = 0 afterwards)
        ret                             ; done
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_printer [#F9F0]
; Tasks:        XMON command P (manual): printer echo on / off. Toggles bit 0 of xmon_printer_switch
;               (&BEFF); switching on only when MC BUSY PRINTER says the printer is ready. With the
;               echo on, xmon_out_char sends every character also to the printer (&09 as a space).
;               Also the disc monitor's P (xmon_disc_command_table points here directly; it ends in
;               xmon_command_done -> the disc monitor's status line).
;               Observed 2026-10-26: P -> &BEFF 00 -> 01, P -> 01 -> 00; in the disc monitor the same
;               (an empty line, then the status line). Not observed: a busy printer (cpcxray
;               reports it ready).
; Input:        entered from xmon_find_command (xmon_command_table or xmon_disc_command_table)
; Changed:      AF; xmon_printer_switch
; Calls:        xmon_out_lf_cr, MC_BUSY_PRINTER; ends in xmon_command_done
xmon_cmd_printer:
        call xmon_out_lf_cr             ; new line
        ld a,(xmon_printer_switch)      ; the printer switch: on? ...
        bit 0,a                         ; (bit 0 = echo on)
        jr z,xcp_on                     ; ... no: switch it on (xcp_on)
        res 0,a                         ; ... yes: switch it off (observed)
xcp_store:
        ld (xmon_printer_switch),a      ; store the switch (observed: &BEFF 00 -> 01 -> 00)
        jp xmon_command_done            ; new "*" prompt
xcp_on:
        call MC_BUSY_PRINTER            ; switch on only if the printer is ready: MC BUSY PRINTER ...
        jr c,xcp_store                  ; ... busy (CY): stays off (not observed - cpcxray reports the printer ready)
        set 0,a                         ; ... ready: bit 0 on (observed)
        jr xcp_store                    ; store it
xmon_out_four_tabs:
        call xmon_out_two_tabs          ; two tabs, then falls into xmon_out_two_tabs for two more
; ----------------------------------------------------------------------
; Subroutine: xmon_out_two_tabs [#FA0E]
; Tasks:        Print two &09 (cursor right) through xmon_out_char. Part of |XMON (not analysed);
;               used by |ROMCAT (observed: the two spaces between the columns).
; Changed:      AF, C
; Called by:    rsx_romcat, XMON
xmon_out_two_tabs:
        call xmon_out_tab               ; one ...
        jp xmon_out_tab                 ; ... and the second
; ----------------------------------------------------------------------
; Subroutine: xmon_hex_word [#FA14]
; Tasks:        Print HL as four hex digits (observed: the dump line addresses).
; Input:        HL
; Changed:      AF
; Called by:    xmon_dump_lines, more XMON code (not analysed)
; Calls:        xmon_hex_byte
xmon_hex_word:
        ld a,h                          ; high byte ...
        call xmon_hex_byte              ; (two hex digits)
        ld a,l                          ; ... then the low byte
        jr xmon_hex_byte                ; (two hex digits, returns from there)
; ----------------------------------------------------------------------
; Subroutine: xmon_hex_byte_quiet [#FA1B]
; Tasks:        Print A as two hex digits on the screen only: the printer switch (&BEFF) is kept
;               in &BEFE and its bit 0 cleared, then it falls into xmon_hex_byte. The caller puts
;               &BEFE back into &BEFF (observed in xmon_input_byte).
; Input:        A
; Changed:      AF; &BEFE, &BEFF bit 0
; Called by:    xmon_input_byte, more XMON code (not analysed)
xmon_hex_byte_quiet:
        push af                         ; keep A
        ld a,(xmon_printer_switch)      ; keep the printer switch in &BEFE ...
        ld (xmon_printer_saved),a       ; (the caller copies it back)
        res 0,a                         ; ... and switch the printer echo off
        ld (xmon_printer_switch),a      ; (bit 0 = 0)
        pop af                          ; A back; falls into xmon_hex_byte
; ----------------------------------------------------------------------
; Subroutine: xmon_hex_byte [#FA28]
; Tasks:        Print A as two hex digits (xmon_hex_nibble). Part of |XMON; used by |ROMCAT
;               (observed).
; Input:        A
; Changed:      AF
; Called by:    rsx_romcat, XMON
xmon_hex_byte:
        push bc                         ; keep BC, A
        push af                         ; ...
        rrca                            ; high nibble ...
        rrca
        rrca
        rrca                            ; ... to bits 3-0 ...
        call xmon_hex_nibble            ; ... as a digit
        pop af                          ; A again ...
        call xmon_hex_nibble            ; ... low nibble as a digit
        pop bc                          ; BC back (A changed)
        ret                             ; done
xmon_hex_nibble:
        and #0F                         ; low nibble as '0'-'9', 'A'-'F' -> xmon_out_char
        add a,#30                       ; '0' + value ...
        cp #3A                          ; ... above '9'? ...
        jr c,xhn_out                    ; ... no: a digit
        add a,#07                       ; ... yes: 'A'-'F' (&3A + 7 = &41)
xhn_out:
        jp xmon_out_char                ; out (screen and printer)
xmon_input_byte_0:
        xor a                           ; default 00, then on in xmon_input_byte (observed from C)
; ----------------------------------------------------------------------
; Subroutine: xmon_input_byte [#FA45]
; Tasks:        Read a hex byte with a default: show the value (two digits, no printer echo), wait
;               for a key. A hex digit is shifted in from the right (value * 16 + digit), the
;               cursor goes back two places and the new value is shown in place. A key that is no
;               hex digit only beeps (xmon_hex_digit) and is ignored. RETURN takes the value; ESC
;               ends the whole command (jp xmon_command_done, the caller stores nothing).
;               Observed 2026-10-25: Z with default 00, keys '0', '3', RETURN -> 03; Y with "FF"
;               and "07"; a non-hex key (beep, value kept); Y ended with ESC (xmon_rom kept).
; Input:        A = default value
; Output:       A = the value
; Changed:      AF, C
; Called by:    xmon_cmd_z, xmon_cmd_rom_select, more XMON code (not analysed)
; Calls:        xmon_hex_byte_quiet, xmon_get_key, xmon_hex_digit, TXT_OUTPUT
xmon_input_byte:
        push af                         ; the value so far
xib_show:
        call xmon_hex_byte_quiet        ; show it (screen only) ...
        ld a,(xmon_printer_saved)       ; ... printer switch back
        ld (xmon_printer_switch),a      ; (the printer echo was off only for the value)
xib_key:
        call xmon_get_key               ; next key
        cp #0D                          ; RETURN ...
        jr nz,xib_not_return            ; not RETURN
        pop af                          ; ... A = the value, done (observed)
        ret                             ; back with A = the value
xib_not_return:
        cp #FC                          ; ESC? (observed: Y, then ESC)
        jr nz,xib_digit                 ; not ESC: a digit?
        pop af                          ; ESC: drop the value ...
        jp xmon_command_done            ; ... and end the command (nothing stored)
xib_digit:
        push hl                         ; keep HL
        call xmon_hex_digit             ; hex digit? (CY = 1)
        ld c,a                          ; C = the digit
        jr c,xib_valid                  ; hex digit (observed) ...
        pop hl                          ; ... no (observed): the key is ignored (it beeped), next key
        jr xib_key                      ; next key
xib_valid:
        pop hl                          ; HL back
        pop af                          ; value * 16 ...
        add a,a                         ; ...
        add a,a                         ; ...
        add a,a                         ; ...
        add a,a                         ; ... (the old high digit drops out)
        add a,c                         ; ... + digit
        push af                         ; keep the new value
        ld a,#08                        ; cursor back twice ...
        call TXT_OUTPUT                 ; &08 ...
        call TXT_OUTPUT                 ; ... &08 (two digits back)
        pop af                          ; A = the value ...
        push af                         ; ... and kept again for xib_show
        jr xib_show                     ; ... and show the new value in place
; ----------------------------------------------------------------------
; Subroutine: xmon_input_word [#FA7E]
; Tasks:        Read a hex address with a default: show HL (four digits, no printer echo), wait for
;               a key. A hex digit is shifted in from the right (HL * 16 + digit), the cursor goes
;               back four places and the new value is shown in place. RETURN ends with CY = 1,
;               ',' ends with NC / Z, ESC ends the whole command (jp xmon_command_done: new line,
;               "*" prompt). Observed 2026-10-25 in the D command: "0000" ended with ',',
;               "003F" / "0100" ended with RETURN, the default "0100" taken with RETURN, ESC.
;               Read, not observed: a key that is no hex digit (&FAAC).
; Input:        HL = default
; Output:       HL = the value; CY = 1: RETURN, NC: ','
; Changed:      AF, C
; Called by:    xmon_cmd_dump, more XMON commands (not analysed)
; Calls:        xmon_hex_byte_quiet, xmon_get_key, xmon_hex_digit, xmon_out_a_4
xmon_input_word:
        ld a,h                          ; show the value: high byte ...
        call xmon_hex_byte_quiet        ; (screen only)
        ld a,(xmon_printer_saved)       ; printer switch back ...
        ld (xmon_printer_switch),a      ; (the echo is off only while the value is shown)
        ld a,l                          ; ... low byte
        call xmon_hex_byte_quiet        ; (screen only)
        ld a,(xmon_printer_saved)       ; printer switch back ...
        ld (xmon_printer_switch),a      ; ...
xiw_key:
        call xmon_get_key               ; next key
        cp #0D                          ; RETURN: done, CY = 1 (observed)
        scf                             ; CY = 1 ...
        ret z                           ; ... RETURN: done, HL = the value
        and a                           ; NC
        cp #2C                          ; ',': done, NC / Z (observed)
        ret z                           ; ',': done, NC, HL = the value
        cp #FC                          ; ESC (observed: D, then ESC) ...
        jr nz,xiw_digit                 ; not ESC: a digit?
        jp xmon_command_done            ; ... ends the command: new line, "*" prompt
xiw_digit:
        push de                         ; keep DE (used as the value below) ...
        ex de,hl                        ; ... DE = the value
        call xmon_hex_digit             ; hex digit?
        ld c,a                          ; C = the digit
        jr c,xiw_valid                  ; hex digit (observed); no: the key is ignored (beep), next key (read)
        ex de,hl                        ; no hex digit: the key is ignored (it beeped), next key (observed in R: 'G')
        pop de                          ; DE back
        jr xiw_key                      ; next key
xiw_valid:
        ex de,hl                        ; HL = the value
        add hl,hl                       ; HL * 16 ...
        add hl,hl                       ; ...
        add hl,hl                       ; ...
        add hl,hl                       ; ... (the old high digit drops out)
        ld a,l                          ; low byte ...
        and #F0                         ; ... bits 3-0 are 0 after the shift ...
        add a,c                         ; ... + digit
        ld l,a                          ; ... = the new value
        ld a,#08                        ; cursor back four places ...
        call xmon_out_a_4               ; (four &08: back over the 4 digits)
        pop de                          ; DE back
        jr xmon_input_word              ; ... and show the new value in place
xmon_out_lf_cr:
        ld a,#0A                        ; LF, then CR (xmon_out_char) - used by |ROMCAT after each name
        call xmon_out_char              ; LF ...
        ld a,#0D                        ; ... CR
        jr xmon_out_char                ; (screen and printer)
xmon_out_comma_screen:
        ld a,#2C                        ; ',' with TXT OUTPUT only - no printer echo (observed: L's separator)
        jp TXT_OUTPUT                   ; (screen only)
xmon_out_minus:
        ld a,#2D                        ; '-' through xmon_out_char (used by R)
        jr xmon_out_char                ; (screen and printer)
xmon_out_comma:
        ld a,#2C                        ; ',' through xmon_out_char (observed: the D command's separator)
        jr xmon_out_char                ; (screen and printer)
xmon_out_tab:
        ld a,#09                        ; &09: cursor right
xmon_out_char:
        call TXT_OUTPUT                 ; TXT OUTPUT; then, if &BEFF bit 0 is set (XMON's printer switch P, manual), also to the printer with &09 as a space (read; observed clear under |ROMCAT and |XMON)
        ld c,a                          ; C = the character
        ld a,(xmon_printer_switch)      ; the printer switch ...
        rra                             ; ... bit 0 to CY ...
        ret nc                          ; ... off: done (A changed)
        ld a,c                          ; printer echo on (observed): the character ...
        cp #09                          ; ... with &09 (cursor right / tab) sent as a space ...
        jr nz,xoc_printer_wait          ; not a tab: as it is
        ld a,#20                        ; tab -> space
xoc_printer_wait:
        call MC_BUSY_PRINTER            ; ... wait while the printer is busy (no time-out: a printer that stays busy hangs XMON) ...
        jr c,xoc_printer_wait           ; busy: test again
        jp MC_SEND_PRINTER              ; ... and send it (MC SEND PRINTER)
; ----------------------------------------------------------------------
; Subroutine: xmon_get_key [#FAF2]
; Tasks:        Read one XMON key: first empty the key buffer (keys pressed before are thrown
;               away), then wait with a blinking cursor (wait_key_cursor), make it upper case,
;               Z = ESC (key code &FC). Observed up to the wait at the "*" prompt; the
;               to_upper / ESC part is read from the code.
; Output:       A = the key (upper case); Z = ESC
; Changed:      AF
; Called by:    xmon_command_loop, more XMON code (not analysed)
; Calls:        KM_READ_CHAR, wait_key_cursor, to_upper
xmon_get_key:
        call KM_READ_CHAR               ; a key already waiting? ...
        jr c,xmon_get_key               ; ... yes: throw it away, test again
        call wait_key_cursor            ; wait for a new key (observed: waits here at the prompt)
        call to_upper                   ; upper case
        cp #FC                          ; Z = ESC (&FC)
        ret                             ; A = the key (upper case)
; Pause of L (observed 2026-10-26): xmon_cmd_list calls it when KM READ CHAR found a key between
; two lines. xmon_get_key throws that key away and waits for a new one: ESC ends the command
; (xmon_command_done, "*" prompt), any other key returns and the listing goes on.
xmon_list_pause:
        call xmon_get_key               ; the key that stopped the listing was thrown away by xmon_get_key: wait for a new one
        ret nz                          ; not ESC: back, the listing goes on
        jp xmon_command_done            ; ESC: end the command
; ----------------------------------------------------------------------
; Subroutine: wait_key_cursor [#FB07]
; Tasks:        Wait for a key with a blinking cursor: KM READ CHAR in a loop; about every
;               255 x 100 loops TXT PLACE CURSOR toggles the cursor (D = shown). When a key
;               comes, the cursor is removed again if it is shown. Observed: CONIN under CP/M
;               (A> prompt) and the XMON "*" prompt.
; Output:       A = the character, CY = 1 (from KM READ CHAR)
; Changed:      AF
; Called by:    the CONIN routine of bios_char_io (jp from &C6B3), xmon_get_key
wait_key_cursor:
        push bc                         ; keep BC ...
        push de                         ; ... and DE
        ld d,#00                        ; D = 0: cursor not shown
wkc_phase:
        ld b,#FF                        ; 255 polls per blink phase
wkc_poll:
        call KM_READ_CHAR               ; key?
        jr c,wkc_key                    ; yes
        ld c,#64                        ; short delay
wkc_delay:
        dec c                           ; C = &64 ...
        jr nz,wkc_delay                 ; ... down to 0
        djnz wkc_poll                   ; B polls per phase
        call TXT_PLACE_CURSOR           ; toggle the cursor
        ld a,d                          ; D = shown / not shown
        cpl                             ; toggle ...
        ld d,a                          ; ... D
        jr wkc_phase                    ; next phase
wkc_key:
        push af                         ; keep the key
        xor a                           ; A = 0
        cp d                            ; cursor shown?
        call nz,TXT_PLACE_CURSOR        ; yes: remove it
        pop af                          ; A = the key ...
        pop de                          ; ...
        pop bc                          ; ... DE, BC back
        ret                             ; CY = 1 (from KM READ CHAR)
; ----------------------------------------------------------------------
; Subroutine: xmon_write_byte [#FB2B]
; Tasks:        XMON's memory write (A, F, S, M): select the Vortex RAM bank (xmon_bank -> port
;               &FBBD), send the gate array value C' with bit 5 set (and bit 6 for &8000 and up),
;               write A to (HL), send C' back, then select the system bank from (&001F) again
;               (bit 5 = expansion on only if (&001F) <> 0). Interrupts are off meanwhile.
;               Observed 2026-10-26 with A: C' &86 -> &A6 at &4000, &86 -> &E6 at &9000 (bits 7-6 =
;               11: the gate array's RAM configuration register); what bits 5 / 6 do with a Vortex
;               RAM expansion is open (cpcxray emulates none).
;               (&001F) is the system's bank byte (Vortex RAM: bank bits 2-0; 0 without expansion).
;               Observed 2026-10-26 with (&001F) = &01 set by hand (restored to 0 afterwards):
;               F4000,4000,77 -> set 5,a at &FB5B, A = &21 to port &FBBD, &4000 = &77 written. The
;               same rule in both read paths of xmon_read_byte (&FBCC, &FC14; D9000 / D4000).
; Input:        A = the byte, HL = the address
; Changed:      nothing (AF, BC kept; the exchanged registers are used)
; Called by:    xmon_cmd_ascii, xmon_cmd_fill (&EF96), xmon_cmd_substitute / xmon_cmd_move (&F73F,
;               &F76F, &F797)
xmon_write_byte:
        bit 7,h                         ; Z: address below &8000
        push af                         ; keep AF (with the Z of the address test) ...
        push bc                         ; ... and BC
        push af                         ; keep A (the byte)
        di                              ; no interrupts while the memory is switched
        ld bc,#FBBD                     ; the Vortex RAM bank (xmon_bank) to port &FBBD
        ld a,(xmon_bank)                ; (Z, observed 0) ...
        out (c),a                       ; ... out
        pop af                          ; A = the byte, F = Z of bit 7,h
        exx                             ; the gate array value C' (current ROM / mode state) ...
        ld d,c                          ; D' = the old value
        res 6,c                         ; ... bit 6 only for &8000 and up ...
        jr z,xwb_gate                   ; below &8000: bit 6 stays 0
        set 6,c                         ; &8000 and up: bit 6 on
xwb_gate:
        set 5,c                         ; ... bit 5 always: observed &86 -> &A6 at &4000, &86 -> &E6 at &9000 (meaning with a Vortex RAM expansion: open)
        out (c),c                       ; to the gate array (B' = &7F)
        exx                             ; (main registers: HL = the address)
        ld (hl),a                       ; write the byte (observed)
        exx                             ; (C' again)
        res 5,c                         ; the gate array value back (&86)
        out (c),c                       ; to the gate array ...
        ld c,d                          ; ... C' = the old value (D')
        exx                             ; (main registers)
        ld a,(#001F)                    ; the system bank (&001F) back to port &FBBD: bank bits 2-0 ...
        ld b,a                          ; B = (&001F) ...
        and #07                         ; ...
        ld c,a                          ; ... C = its bank bits ...
        ld a,b                          ; ... and bit 5 (expansion on) if (&001F) <> 0 (observed both: 0 normally; &01 set by hand 2026-10-26 -> &21)
        or a                            ; ... (&001F) = 0? ...
        ld a,c                          ; ... A = the bank bits (flags kept)
        jr z,xwb_bank                   ; 0: expansion off (observed)
        set 5,a                         ; (&001F) <> 0: bit 5 = expansion on (observed 2026-10-26 with (&001F) = &01 set by hand: A &01 -> &21 to port &FBBD)
xwb_bank:
        ld bc,#FBBD                     ; port &FBBD
        out (c),a                       ; the system bank back
        exx                             ; ...
        out (c),c                       ; ... and the old gate array value once more
        exx                             ; (main registers)
        pop bc                          ; BC back ...
        pop af                          ; ... AF back
        ei                              ; interrupts on again
        ret                             ; done
; ----------------------------------------------------------------------
; Subroutine: xmon_read_byte [#FB6A]
; Tasks:        Read the byte at HL the way XMON's switches say: Vortex RAM bank (xmon_bank), firmware
;               ROM at &0000-&3FFF (xmon_firmware_rom, X) and, from &8000 on, the upper ROM
;               xmon_rom (Y).
;               Below &8000 (xrb_low; observed 2026-10-25, D0000,003F with X on and D0000,0100
;               with X off): interrupts off, xmon_bank to port &FBBD, gate array: lower ROM on only
;               if the X switch is on, then the value with bit 6 cleared and bit 5 set (&A6
;               observed - its purpose with the Vortex RAM is open; a plain CPC ignores bit 5),
;               read (hl), back to the old gate array value, the bank from (&001F) back to port
;               &FBBD, interrupts on. Result: X on -> the firmware ROM bytes (&0030 = F3 D9 21 2B
;               ...); X off -> RAM (&0030 = FD E5 DF D0 BE, XMON's RST 6).
;               From &8000 on (xrb_high; observed with xmon_rom = &FF, DC000): copy the reader
;               from &FCB0 to RAM &0080 (xmon_ram_reader), bank to &FBBD, then call it with ROM
;               xmon_rom selected and the upper ROM off if xmon_rom >= &FC; put &0080-&0094 back
;               from &AD76, the system bank back, the gate array back. With xmon_rom = &FF the
;               screen RAM was read and cpcxray's access map stayed clean at &C000-&FFFF. With
;               xmon_rom = 5 the reader would read VDOS itself as data - never run that on
;               &C000-&FFFF.
; Input:        HL = address
; Output:       A = the byte; HL unchanged
; Changed:      AF; BC', DE', HL' (C' and the gate array as before)
; Called by:    xmon_dump_lines, more XMON commands (not analysed)
xmon_read_byte:
        bit 7,h                         ; address &8000 or above?
        jr z,xrb_low                    ; below &8000: xrb_low (observed); from &8000: the &0080 reader (read)
xrb_high:
        push bc                         ; from &8000: keep BC, DE, HL (observed with xmon_rom = &FF)
        push de                         ; ...
        push hl                         ; ... HL = the address
        di                              ; no interrupts while the memory is switched
        exx                             ; (C' = the gate array value)
        ld e,c                          ; E' = the gate array value now ...
        res 5,c                         ; ... sent with bit 5 cleared ...
        out (c),c                       ; (to the gate array)
        exx                             ; (main registers again)
        ld bc,#0015                     ; copy the 21-byte reader ...
        ld de,xmon_ram_reader           ; ... to RAM &0080 ...
        ld hl,#FCB0                     ; ... from &FCB0 (observed: &FCB0-&FCC4 read as data, run at &0080)
        ldir                            ; (21 bytes)
        exx                             ; ...
        ld c,e                          ; the gate array value as before
        out (c),c                       ; ... to the gate array
        exx                             ; ...
        pop hl                          ; HL = the address again
        push hl                         ; (kept again)
        ld a,(xmon_bank)                ; XMON's Vortex RAM bank ...
        ld bc,#FBBD                     ; port &FBBD
        out (c),a                       ; ... to port &FBBD (observed 0)
        ld a,(KL_UPPER_ROM)             ; C = the ROM selected now (VDOS), for afterwards
        ld c,a                          ; (the reader selects it again after the read)
        ld a,(xmon_rom)                 ; A = the ROM to read from (Y) ...
        cp #FC                          ; ... &FC-&FF: no ROM, show the RAM (CY = 0) ...
        ld b,#DF                        ; BC = &DF00 + this ROM: the ROM select port
        exx                             ; (the alternate set holds the gate array values for the reader)
        res 5,c                         ; gate array value with bits 5 and 6 cleared ...
        res 6,c                         ; ...
        out (c),c                       ; ... out
        ld d,c                          ; D' = that value
        jr c,xrbh_config                ; a real ROM: upper ROM stays on (observed with ROM 7) ...
        set 3,c                         ; ... &FC-&FF: upper ROM off - the RAM is read (observed with &FF)
xrbh_config:
        ld h,c                          ; H' = ROM configuration for the read
        set 5,c                         ; L' = the same with bits 5 and 6 set (purpose open)
        set 6,c                         ; ...
        ld l,c                          ; ... = L'
        exx                             ; (main registers: HL = the address, BC = &DFxx, A = the ROM)
        call xmon_ram_reader            ; read the byte in RAM (observed)
        ld bc,#0015                     ; put RAM &0080-&0094 back ...
        ld de,xmon_ram_reader           ; (to &0080)
        ld hl,#AD76                     ; ... from the copy xmon_save_low_ram made (observed: &0080 = 0 again)
        ldir                            ; (21 bytes)
        ld d,a                          ; D = the byte
        ld a,(#001F)                    ; the system's bank setting (&001F, observed 0; &01 set by hand for the test of &FBCC) ...
        ld b,a                          ; B = (&001F) ...
        and #07                         ; ...
        ld c,a                          ; ... C = its bank bits ...
        ld a,b                          ; ...
        or a                            ; ... (&001F) = 0? ...
        ld a,c                          ; ... A = the bank bits
        jr z,xrbh_bank                  ; 0: expansion off (observed)
        set 5,a                         ; (&001F) <> 0: bit 5 = expansion on (observed with (&001F) = &01 by hand: D9000 -> A &21 to port &FBBD)
xrbh_bank:
        ld bc,#FBBD                     ; port &FBBD
        out (c),a                       ; ... back to port &FBBD
        ld a,d                          ; A = the byte
        exx                             ; ...
        ld c,e                          ; the old gate array value
        out (c),c                       ; ... to the gate array
        exx                             ; ...
        pop hl                          ; HL ...
        pop de                          ; ... DE ...
        pop bc                          ; ... BC back
        ei                              ; interrupts on
        ret                             ; A = the byte
xrb_low:
        di                              ; no interrupts while the memory is switched
        ld a,(xmon_bank)                ; XMON's Vortex RAM bank (Z) ...
        push bc                         ; keep BC ...
        push hl                         ; ... and HL
        ld bc,#FBBD                     ; port &FBBD
        out (c),a                       ; ... to port &FBBD (observed 0: expansion off)
        exx                             ; (alternate set: C' = the gate array value)
        ld d,c                          ; D' = the gate array value now (C' = &86 observed)
        ld a,(xmon_firmware_rom)        ; X switch ...
        or a                            ; (Z = off)
        set 2,c                         ; ... lower ROM off ...
        jr z,xrbl_gate                  ; ... X off: stays off (observed) ...
        res 2,c                         ; ... X on: lower ROM on (observed)
xrbl_gate:
        out (c),c                       ; to the gate array
        res 6,c                         ; bit 6 off, bit 5 on (&A6 / &A2 observed) ...
        set 5,c                         ; ...
        out (c),c                       ; ... to the gate array too (purpose of bit 5 with the Vortex RAM open)
        exx                             ; (main registers: HL = the address)
        ld l,(hl)                       ; L = the byte
        exx                             ; (alternate set)
        res 5,c                         ; bit 5 off again ...
        out (c),c                       ; to the gate array
        ld a,(#001F)                    ; the system's bank setting, kept in RAM at &001F (observed 0)
        ld c,d                          ; the old gate array value ...
        out (c),c                       ; ... back
        exx                             ; (main registers)
        ld b,a                          ; (&001F): bank in bits 2-0 ...
        and #07                         ; ...
        ld c,a                          ; ... C = the bank bits ...
        ld a,b                          ; ...
        or a                            ; ... 0: expansion off (observed) ...
        ld a,c                          ; ... A = the bank bits (flags kept)
        jr z,xrbl_bank                  ; 0: expansion off (observed)
        set 5,a                         ; (&001F) <> 0: bit 5 = expansion on (observed with (&001F) = &01 by hand: D4000 -> A &21 to port &FBBD)
xrbl_bank:
        ld bc,#FBBD                     ; port &FBBD
        out (c),a                       ; the system's bank back to port &FBBD
        ld a,l                          ; A = the byte
        pop hl                          ; HL as before
        pop bc                          ; BC as before
        ei                              ; interrupts on
        ret                             ; A = the byte
; ----------------------------------------------------------------------
; Subroutine: rsx_romoff / rsx_amsdos [#FC20 / #FC3B]
; Tasks:        Restart the machine with some background ROMs switched off. A mask with one bit per
;               ROM 1-7 (set = off) is built: |ROMOFF without parameters = all (&FF); |ROMOFF,n,..
;               = the given ROMs 0-7; |AMSDOS = VDOS's own ROM (KL CURR SELECTION). A 37-byte
;               start program (romoff_start_code) is copied to &4001, the mask to &4000, and run
;               by MC START PROGRAM (C = 0): firmware reset, then KL INIT BACK only for the ROMs
;               7..1 whose bit is clear, a short delay, then BASIC (JP &C00C). A number >= 8 or
;               with a high byte ends |ROMOFF at once with RET - no message, no reset; BASIC
;               passes the parameters last first, so "3,9" stops at the 9.
;               Observed: |ROMOFF,8 / 256 / "x" / 3,9 -> nothing; |ROMOFF,6 -> restart, VDOS and
;               AMSDOS as before; |ROMOFF,5 and |AMSDOS -> VDOS off (|DIR / |ROMCAT "Unknown
;               command", AMSDOS's CAT, HIMEM &A67B); |ROMOFF -> all off (HIMEM &AB7F, CAT on
;               tape); |ROMOFF,7 -> VDOS without AMSDOS (own workspace &A700, HIMEM &A67B,
;               |DIR works); |ROMOFF,5,7 -> both off. As in the manual (2.0): "|ROMOFF,6,7".
; Input:        A = number of parameters, IX = parameters
; Output:       does not return (restart), except for a bad number
; Called by:    RSX "ROMOFF" / "AMSDOS" (rom_jumpblock)
; Calls:        rom_off_bit, MC_START_PROGRAM; KL_CURR_SELECTION
rsx_romoff:
        ld e,#FF                        ; E = &FF: all ROMs off
        or a                            ; (A = number of parameters)
        jr z,romoff_restart             ; no parameter: |ROMOFF = all (observed)
        inc e                           ; E = 0: only the given ROMs
        ld b,a                          ; B = number of parameters
        push ix                         ; HL = the parameter list (last parameter first)
        pop hl                          ; (HL = IX)
romoff_next_param:
        ld c,(hl)                       ; C = the ROM number ...
        inc hl                          ; ...
        ld a,(hl)                       ; ... A = the high byte ...
        inc hl                          ; ... HL = the next parameter
        or a                            ; ... high byte 0?
        ret nz                          ; no: return, nothing done (observed: 256, "x")
        ld a,c                          ; A = the ROM number
        cp #08                          ; 0-7?
        ret nc                          ; no: return, nothing done (observed: 8, "3,9")
        call rom_off_bit                ; set its bit in the mask
        djnz romoff_next_param          ; next parameter
        jr romoff_restart               ; restart
rsx_amsdos:
        call KL_CURR_SELECTION          ; A = our ROM number (VDOS: 5)
        ld e,#00                        ; mask: only ...
        call rom_off_bit                ; ... our ROM off (observed: VDOS off, AMSDOS on)
romoff_restart:
        ld a,e                          ; A = the mask
        ld hl,#FC69                     ; the start program ...
        ld de,romoff_start              ; ... to &4001 ...
        ld bc,#0025                     ; ... 37 bytes
        ldir                            ; (copy it)
        ld hl,#4000                     ; the mask to &4000
        ld (hl),a                       ; (the start program reads it from there)
        inc hl                          ; HL = &4001: the program's entry
        ld c,#00                        ; C = 0: ROM 0 (BASIC) as the foreground ROM
        jp MC_START_PROGRAM             ; firmware reset, then the start program (does not return)
; ----------------------------------------------------------------------
; Subroutine: rom_off_bit [#FC59]
; Tasks:        Set the bit of ROM A (0-7) in the off mask E, in the order the start program
;               reads it: after the 8 rotations ROM 7 is in bit 7 ... ROM 1 in bit 1 (ROM 0 in
;               bit 0, which the start program does not use). Observed (|ROMOFF, |AMSDOS).
; Input:        A = ROM number, E = mask
; Output:       E
; Changed:      F, E
; Called by:    rsx_romoff, rsx_amsdos
rom_off_bit:
        push bc                         ; keep BC
        ld b,#07                        ; ROM numbers 7 down to 1
rob_loop:
        cp b                            ; this ROM?
        jr nz,rob_next                  ; no
        set 7,e                         ; yes: its bit (rotated into place by the rest of the loop)
rob_next:
        rlc e                           ; next position
        djnz rob_loop                   ; 7 times
        pop bc                          ; BC back
        rlc e                           ; the eighth rotation
        ret                             ; E = the mask with the bit for ROM A

; ---- copied to RAM #4001-#4025 (from #FC69), executed there ----
        DISP #4001
; Start program of |ROMOFF / |AMSDOS (RAM &4001, copied from &FC69, run by MC START PROGRAM
; with ROM 0): initialise the background ROMs 7..1 whose bit in the mask at &4000 is clear,
; wait a little, start BASIC. Observed (|ROMOFF,6 / ,5 / ,7 / all / |AMSDOS).
romoff_start:
        ld c,#07                        ; ROM 7 first (start program, runs in RAM after the firmware reset)
        ld a,(#4000)                    ; the off mask (&4000)
rs_next_rom:
        rlca                            ; next mask bit into CY: ROM C's
        push af
        call nc,KL_INIT_BACK            ; clear: initialise ROM C (KL INIT BACK) - set: it stays off
        pop af
        dec c                           ; ROMs 7 .. 1
        jr nz,rs_next_rom
        ld a,#03                        ; a delay: 3 x 256 x 256 loops ...
rs_delay_3:
        push af                         ; (outer)
        xor a
rs_delay_2:
        push af                         ; (middle)
        xor a
rs_delay_1:
        dec a                           ; (inner)
        jr nz,rs_delay_1
        pop af
        dec a
        jr nz,rs_delay_2
        pop af
        dec a
        jr nz,rs_delay_3
        ld sp,#C000                     ; stack top &C000
        jp #C00C                        ; BASIC's start in ROM 0 (Ready)
        ENT                             ; end of DISP #4001
; ---- end of RAM copy #4001-#4025 (from #FC69) ----

; ----------------------------------------------------------------------
; Subroutine: xmon_save_low_ram [#FC8E]
; Tasks:        Copy RAM &0080-&0094 (21 bytes) to &AD76, with interrupts off. Around the
;               copy it sends C' with bit 5 cleared to the gate array (OUT (C),C with BC'),
;               then C' itself. Bit 5 is no ROM bit (bit 2 = lower ROM, bit 3 = upper ROM), so
;               the lower ROM stays off: observed, &AD76 got the RAM bytes (all 0 after the
;               boot), not the firmware's bytes at &0080 (32 A8 B1 ...). Why XMON keeps this
;               copy and where it is put back is not observed yet (research: a backup of low
;               memory).
; Changed:      AF, BC, DE, HL; D' (= C')
; Called by:    rsx_xmon
xmon_save_low_ram:
        di                              ; no interrupts while the ROM state is changed
        exx                             ; (alternate set: C' = the gate array value)
        ld d,c                          ; D' = the gate array's ROM/mode byte ...
        res 5,c                         ; ... with bit 5 cleared (no ROM bit) ...
        out (c),c                       ; ... to the gate array (the lower ROM stays off, observed)
        ld c,d                          ; C' as before
        exx                             ; (main registers)
        ld hl,xmon_ram_reader           ; RAM &0080-&0094 ...
        ld de,#AD76                     ; ... to &AD76 ...
        ld bc,#0015                     ; ... 21 bytes
        ldir                            ; (copy)
        exx                             ; (alternate set)
        out (c),c                       ; the gate array byte as before (C')
        exx                             ; (main registers)
        ei                              ; interrupts on
        ret                             ; done
; XMON exit to BASIC (ESC at the "*" prompt, observed 2026-10-25): clear &ACA4-&AD6B (BASIC's
; input buffer) with clear_memory, whose RET goes back to the caller of |XMON ("Ready").
xmon_exit_basic:
        ld b,#C8                        ; 200 bytes ...
        ld de,xmon_text_length          ; ... from &ACA4 ...
        jp clear_memory                 ; ... cleared; its RET returns to the RSX caller

; ---- copied to RAM #0080-#0094 (from #FCB0), executed there ----
        DISP #0080
; ----------------------------------------------------------------------
; Subroutine: xmon_ram_reader [#0080 RAM, copied from #FCB0]
; Tasks:        XMON's reader for addresses from &8000 on; it runs in RAM so that the upper ROM can
;               be switched away while it reads. Select ROM xmon_rom, set the gate array to H'
;               (upper ROM off if xmon_rom >= &FC) and L' (H' with bits 6 and 5 set - purpose open),
;               read (hl), upper ROM on again, select the caller's ROM (KL_UPPER_ROM) again.
;               Observed 2026-10-25 with xmon_rom = &FF: DC000 showed the screen RAM, VDOS was not
;               read (access map unchanged at &C000-&FFFF).
; Input:        A = xmon_rom, BC = &DF00 + KL_UPPER_ROM; H' / L' = gate array values, C' = their
;               port (&7F); HL = address
; Output:       A = the byte
; Changed:      C' (= H' with bit 3 cleared)
; Called by:    xmon_read_byte (&FBB1)
xmon_ram_reader:
        out (c),a                       ; select ROM xmon_rom (port &DFxx)
        exx
        ld c,h                          ; ROM configuration H' (observed: upper ROM off) ...
        out (c),c
        ld c,l                          ; ... then L' (bits 6 and 5 set; purpose open)
        out (c),c
        exx
        ld a,(hl)                       ; read the byte (observed: screen RAM at &C000)
        exx
        ld c,h
        res 3,c                         ; upper ROM on again ...
        out (c),c
        exx
        out (c),c                       ; ... and the caller's ROM (VDOS) selected again
        ret
        ENT                             ; end of DISP #0080
; ---- end of RAM copy #0080-#0094 (from #FCB0) ----

; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_ascii [#FCC5]
; Tasks:        XMON command A (manual): "A addr,text" - write a text into memory. The address
;               (default and new value: xmon_fill_address, shared with F) is read with
;               xmon_input_word, then ',' is printed and xmon_input_text reads the text (at most
;               255 characters, keys upper case, DEL deletes, RETURN ends, ESC ends the command);
;               the bytes go to the address through xmon_write_byte. An empty text writes nothing.
;               Observed 2026-10-26: A4000 "xYz" DEL "Q" -> 58 59 51 ("XYQ"); A + RETURN (default
;               4000) + empty text -> nothing; "AB" + ESC -> nothing; 256 characters -> 255 written
;               (&4000-&40FE); A9000 "Z" (the &8000-and-up branch of xmon_write_byte).
;               BUG (observed): xmon_input_line first fills the whole 255-byte buffer &ACA5-&ADA3
;               with spaces, and the text goes there too. XMON's copy of the user's RAM &0080-&0094
;               (xmon_save_low_ram, &AD76-&AD8A) lies in that buffer, so after every A the next
;               memory read from &8000 on (xmon_ram_reader) "restores" spaces or text into
;               &0080-&0094 (observed: A9000 "Z", D8000 -> &0080-&0094 = 21 spaces; with the long
;               text: "123456789ABCDEF012345"). Under CP/M &0080 is the DMA / command line buffer.
; *** BUGFIX PROPOSAL (todo.md, "Bugfix proposals"): ld c,#FF -> ld c,#D1 (209 characters): the
; *** operand at &FCD2 &FF -> &D1 (raw offset &3CD2 &F7 -> &D9); the buffer then ends at &AD75,
; *** just below the save area.
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL; xmon_fill_address, xmon_text_length, the buffer &ACA5-&ADA3
; Calls:        xmon_input_word, xmon_out_comma, xmon_input_text, xmon_write_byte; ends in
;               xmon_command_done
xmon_cmd_ascii:
        ld hl,(xmon_fill_address)       ; default: xmon_fill_address (shared with F)
xca_input:
        call xmon_input_word            ; the address (RETURN / ',') ...
        ld (xmon_fill_address),hl       ; ... kept as the next default (observed: not advanced after the text)
        call xmon_out_comma             ; ','
        ld c,#FF                        ; the text: at most 255 characters (BUG: see the header)
        call xmon_input_text            ; read it (empty: the command ends there); B = the length
        ld de,xmon_decoded              ; B = its length: copy it ...
        ld hl,(xmon_fill_address)       ; HL = the target address
xca_loop:
        ld a,(de)                       ; ... byte by byte to the address (xmon_write_byte) (observed: "XYQ", 255 bytes)
        call xmon_write_byte            ; one byte to memory
        inc hl                          ; next address ...
        inc de                          ; ... next character ...
        djnz xca_loop                   ; ... B times
        jp xmon_command_done            ; "*" prompt
; ----------------------------------------------------------------------
; Subroutine: xmon_cmd_search [#FCE7]
; Tasks:        XMON command C (manual): "C addr,len" - search all memory &0000-&FFFF for the byte
;               sequence of length len (1-255) at addr and list every address where it is found,
;               10 per line. The sequence address defaults to &ACA5 (A's text buffer); the length
;               defaults to 00 (= nothing to do). Every byte is read through xmon_read_byte, so X
;               (lower area), Y (the ROM read from &C000 on) and Z (Vortex bank) apply - with Y = 5
;               C would read all of VDOS as data, so Y must not be 5 for the analysis. A key
;               pauses, ESC (in the pause) ends.
;               Observed 2026-10-26 (Y = 00): C4000,02 with A5 5A at &4000 / &5000 / &6000 and
;               A5 00 at &4010 -> 4000 5000 6000; C4000,00 -> nothing; C8000,01 (A5) -> 30 hits in
;               3 lines incl. the BASIC ROM from &C000 on; C8001,01 (00) with SPACE / SPACE / ESC.
;               Read, not tried: a hit at &FFFF is never reported (xmon_search_byte ends before
;               the compare once HL has wrapped).
; Input:        entered from xmon_find_command (xmon_command_table)
; Changed:      AF, BC, DE, HL, IX
; Calls:        xmon_input_word, xmon_out_comma, xmon_input_byte_0, xmon_out_lf_cr,
;               xmon_search_byte, xmon_hex_word, xmon_out_four_tabs, KM_READ_CHAR, xmon_get_key;
;               ends in xmon_command_done
xmon_cmd_search:
        ld hl,xmon_decoded              ; default: &ACA5 = A's text buffer (a text just written with A can be searched at once)
        call xmon_input_word            ; the address of the byte sequence (RETURN / ',') ...
        push hl                         ; keep it
        call xmon_out_comma             ; ','
        call xmon_input_byte_0          ; its length (default 00) ...
        pop ix                          ; IX = the sequence
        or a                            ; length 0: nothing to do (observed: C4000,00)
        jp z,xmon_command_done          ; (A = the length)
        ld c,a                          ; C = the length
        push bc                         ; keep the length over the new line
        call xmon_out_lf_cr             ; new line before the hits
        pop bc                          ; C = the length
        ld hl,#0000                     ; search from &0000, 10 hits per line
        ld d,#0A                        ; D = hits left in this line
xcs_next:
        push hl                         ; next address: keep it ...
        ld b,c                          ; ... compare C bytes with the sequence at IX ...
        push ix                         ; keep the start of the sequence
xcs_compare:
        call xmon_search_byte           ; compare (HL) with (IX), HL + 1 ...
        jr nc,xcs_end                   ; ... end of memory (HL wrapped to 0): done (observed) ...
        jr nz,xcs_mismatch              ; ... a byte differs: next address (observed: A5 00 at &4010) ...
        inc ix                          ; ... equal: the next sequence byte ...
        djnz xcs_compare                ; ... B times
        pop ix                          ; all equal: a hit
        pop hl                          ; HL = the start address of the hit
        push bc                         ; keep BC (xmon_out_four_tabs changes B)
        call xmon_hex_word              ; print its address (observed: 4000 5000 6000) ...
        inc hl                          ; HL = the next address to test
        dec d                           ; ... 10 per line (observed: 30 hits in 3 lines) ...
        jr nz,xcs_tab                   ; not the 10th: four tabs
        call xmon_out_lf_cr             ; the 10th: new line ...
        ld d,#0A                        ; ... 10 again
        jr xcs_key                      ; ...
xcs_tab:
        call xmon_out_four_tabs         ; ... else four tabs
xcs_key:
        pop bc                          ; BC back
        call KM_READ_CHAR               ; a key? pause: xmon_get_key throws it away and waits; ESC ends, any other key goes on (observed: SPACE / SPACE; ESC while listing only pauses)
        jr nc,xcs_on                    ; no key: on
        call xmon_get_key               ; key: pause - wait for a new one ...
        jr z,xcs_done                   ; ... ESC ends
xcs_on:
        jr xcs_next                     ; next address
xcs_mismatch:
        pop ix                          ; no hit: the address + 1
        pop hl                          ; HL = the address just tested ...
        inc hl                          ; ... + 1
        jr xcs_next                     ; next address
xcs_end:
        pop hl                          ; end of memory: drop IX / HL
        pop hl                          ; (IX and the address)
xcs_done:
        call xmon_out_lf_cr             ; new line, "*" prompt
        jp xmon_command_done            ; "*" prompt
xmon_search_byte:
        call xmon_read_byte             ; the memory byte at HL (xmon_read_byte: X, Y, Z apply; from &C000 on the ROM of Y) ...
        inc hl                          ; HL = the next address
        ld e,a                          ; ... in E; HL wrapped to 0: NC / Z = end (so a hit at &FFFF is never reported - read) ...
        xor a                           ; A = 0 ...
        or h                            ; ... HL = 0? ...
        jr nz,xsb_compare               ; ...
        or l                            ; ...
        ret z                           ; ... yes: Z, NC (from the OR) - the end of memory
xsb_compare:
        push hl                         ; ... the sequence byte at IX ...
        push ix                         ; (HL = IX ...
        pop hl                          ; ... through the stack)
        call xmon_read_byte             ; A = the sequence byte
        pop hl                          ; HL = the next memory address again
        cp e                            ; ... compared: Z = equal; CY = 1: not the end
        scf                             ; CY = 1: not the end
        ret                             ; Z = equal
; ----------------------------------------------------------------------
; Subroutine: rsx_fast [#FD5A]
; Tasks:        |FAST: faster text output in MODE 2 (does nothing in MODE 0 and 1). Installs
;               fast_write_char as the firmware's character writer: builds a FAR CALL stub
;               (fast_write_stub, &B1BA: RST 3 / DEFW &B1BE / RET; far address &FD7D in this
;               ROM) and points the indirection IND TXT WRITE CHAR (&BDD3) to it. |SLOW is TXT
;               RESET, which restores the indirections. Entry fast_install: without the mode
;               test (bios_select_format A = &FE, the CP/M FAST flag). Observed: |FAST in MODE 2;
;               it does not touch eof_test_1a (&BE7C).
; Changed:      AF, DE, HL
; Called by:    RSX "FAST" (rom_jumpblock); bios_select_format (fast_install)
; Calls:        SCR_GET_MODE, KL_CURR_SELECTION
rsx_fast:
        call SCR_GET_MODE               ; Z: MODE 1, C: MODE 0
        ret z                           ; Z: MODE 1 ...
        ret c                           ; ... or MODE 0: nothing to do
fast_install:
        ld hl,fast_write_stub           ; the stub ...
        ld (#BDD4),hl                   ; ... becomes the target of IND TXT WRITE CHAR (&BDD3 JP, address word &BDD4)
        ld de,fast_write_far            ; its far address follows it
        ld (hl),#DF                     ; RST 3 (FAR CALL) ...
        inc hl
        ld (hl),e                       ; ... DEFW fast_write_far
        inc hl
        ld (hl),d
        inc hl
        ld (hl),#C9                     ; RET
        inc hl
        ld (hl),#7D                     ; far address: &FD7D ...
        inc hl
        ld (hl),#FD
        inc hl
        call KL_CURR_SELECTION          ; ... in the ROM selected now (VDOS)
        ld (hl),a
        ret
; ----------------------------------------------------------------------
; Subroutine: fast_write_char [#FD7D]
; Tasks:        Character writer for MODE 2 installed by |FAST (IND TXT WRITE CHAR, reached by a
;               FAR CALL through fast_write_stub): screen address = row * 80 + column +
;               SCR_OFFSET (wrapped in 2K) + SCR_BASE; the 8 matrix bytes - from the lower ROM's
;               font at &3800 or, for a user defined character (TXT_UDG_PRESENT and character >=
;               TXT_UDG_FIRST), from TXT_UDG_TABLE - are copied straight into the 8 pixel lines
;               (+&800 each), complemented when TXT_PAPER is not 0. Much faster than the firmware's
;               general routine, which handles every mode and colour; MODE 2 has only pen and
;               paper 0/1. Observed all three ways (MODE 2 after |FAST): normal text (CAT), PAPER 1
;               / PEN 0 (fwc_inverse), PRINT CHR$(240) (fwc_udg, table at &A678).
; Input:        A = character, H = physical column, L = physical row (as IND TXT WRITE CHAR)
; Changed:      AF, BC, DE, HL
; Called by:    the firmware's text output through IND TXT WRITE CHAR (&BDD3)
fast_write_char:
        di                              ; (C' = gate array ROM/mode state)
        exx
        ld e,c                          ; keep it in E'
        res 2,c                         ; RMR bit 2 = 0: lower ROM on (the font at &3800)
        out (c),c
        exx                             ; the far return restores the ROM state
        ld c,a                          ; C = character
        ld b,h                          ; B = column
        ld e,l                          ; E = row ...
        ld d,#00
        ld h,d
        add hl,hl                       ; ... * 5 ...
        add hl,hl
        add hl,de
        add hl,hl                       ; ... * 16 = row * 80 (bytes per character line in MODE 2)
        add hl,hl
        add hl,hl
        add hl,hl
        ld e,b                          ; + column
        add hl,de
        ld de,(SCR_OFFSET)              ; + hardware scroll offset ...
        add hl,de
        ld a,h                          ; ... wrapped in the 2K of one pixel line ...
        and #07
        ld h,a
        ld a,(SCR_BASE)                 ; ... + screen base (&C0)
        add a,h
        ld h,a
        ex de,hl                        ; DE = screen address of the character's top line
        ld a,(TXT_UDG_PRESENT)          ; user defined characters present?
        rrca                            ; bit 0 ...
        jr c,fwc_check_udg              ; yes: check the character against TXT_UDG_FIRST
fwc_rom_font:
        ld l,c                          ; L = character (ROM font: index = character)
        ld bc,#3800                     ; ROM font &3800 ...
        ld h,c                          ; ... H = 0: HL = character
fwc_matrix:
        add hl,hl                       ; index * 8 (8 bytes per matrix) ...
        add hl,hl                       ; (...)
        add hl,hl                       ; (...)
        add hl,bc                       ; HL = font + character * 8: its matrix
        ex de,hl                        ; HL = screen address, DE = matrix
        ld bc,#0800                     ; BC = &800: from one pixel line to the next
        ld a,(TXT_PAPER)                ; paper (encoded) ...
        or a                            ; ... not 0?
        jr nz,fwc_inverse               ; not 0: inverted (observed: PAPER 1)
        ld a,(de)                       ; pixel line 0: matrix byte 0 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 1: matrix byte 1 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 2: matrix byte 2 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 3: matrix byte 3 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 4: matrix byte 4 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 5: matrix byte 5 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 6: matrix byte 6 ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 7: matrix byte 7 ...
        ld (hl),a                       ; ... onto the screen
        ret                             ; done (the FAR CALL return switches the lower ROM off again)
fwc_inverse:
        ld a,(de)                       ; pixel line 0: matrix byte 0 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 1: matrix byte 1 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 2: matrix byte 2 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 3: matrix byte 3 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 4: matrix byte 4 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 5: matrix byte 5 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 6: matrix byte 6 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        inc de                          ; next matrix byte
        add hl,bc                       ; next pixel line (+&800)
        ld a,(de)                       ; pixel line 7: matrix byte 7 ...
        cpl                             ; ... inverted (paper not 0: PAPER 1, PEN 0) ...
        ld (hl),a                       ; ... onto the screen
        ret                             ; done
fwc_check_udg:
        ld a,(TXT_UDG_FIRST)            ; first user defined character ...
        dec a                           ; ... - 1
        cp c                            ; below the character?
        jr nc,fwc_rom_font              ; no: a ROM character
fwc_udg:
        inc a                           ; user defined (observed: CHR$(240), first = 240): first ...
        ld b,a                          ; ... into B
        ld a,c                          ; character ...
        sub b                           ; ... - first = index in the table
        ld h,#00                        ; HL = index
        ld l,a
        ld bc,(TXT_UDG_TABLE)           ; BC = user defined matrix table (RAM, &A678 observed)
        jr fwc_matrix                   ; matrix = table + index * 8, then copy as usual
; ----------------------------------------------------------------------
; Subroutine: print_dollar_string / print_name_string [#FE16 / #FE20]
; Tasks:        Print the string at HL up to '$' with TXT OUTPUT. print_name_string prints the
;               FIRST character with TXT WR CHAR (control codes as symbols: the hidden RSX
;               names &81-&89 show as one symbol) and the rest through print_dollar_string.
;               Observed (|ROMCAT).
; Input:        HL = string ('$' at the end)
; Changed:      AF, HL
; Called by:    rsx_romcat
print_dollar_string:
        ld a,(hl)                       ; next character
        cp #24                          ; '$': end
        ret z
        call TXT_OUTPUT                 ; print it
        inc hl
        jr print_dollar_string
print_name_string:
        ld a,(hl)                       ; first character
        cp #24
        ret z
        push hl
        call TXT_WR_CHAR                ; as a symbol (TXT WR CHAR: a hidden name byte &01-&09 is shown, not obeyed)
        pop hl
        inc hl
        jr print_dollar_string          ; the rest with TXT OUTPUT
romcat_header_text:
        defb #0A,#0A,#0D                ; LF LF CR "Nr  Ty  Ma  Ve  Mo  Base  Name" CR LF LF '$'
        defb "Nr  Ty  Ma  Ve  Mo  Base  Name"
        defb #0D,#0A,#0A,#24
romcat_no_base_text:
        defb "----  $"                  ; "----  $": no data area (not a background ROM)
romcat_himem_text:
        defb #0A                        ; LF "Himem: $"
        defb "Himem: $"
romcat_rsx_header_text:
        defb #0A                        ; LF "Adr.  RSX-Name" CR LF LF '$'
        defb "Adr.  RSX-Name"
        defb #0D,#0A,#0A,#24
; ----------------------------------------------------------------------
; Subroutine: rsx_romcat [#FE74]
; Tasks:        |ROMCAT: table of ROMs 0-7 - "Himem: hhhh" (BASIC's HIMEM &AE7B), then per ROM
;               number, type, mark, version, modification (the first 4 header bytes), the data
;               area (Base, from KL_ROM_IY_TABLE, only for a background ROM, type 1) and the
;               name (its first command name). |ROMCAT,n: list ROM n's command names with their
;               jump addresses ("Adr.  RSX-Name"); ESC held: pause, then ESC ends, another key
;               goes on. Both copy a small helper to &BF00 (over the HELLO loader's RAM copy,
;               which is only needed at the start) that pages in ROM n and reads it:
;               romcat_rom_info (from &FF4A, 47 bytes) and romcat_rsx_entry (from &FF79, 71).
;               Not in the manual (2.0), which has |ROMS (a table of ROMs 0-7: No, Name,
;               Version) instead.
;               Observed: |ROMCAT -> Himem A677; 00-04, 06: "80 01 00 00 ---- BASIC" (empty slots
;               show the on-board BASIC), 05 "01 01 21 03 A6FC V ROM", 07 "01 00 05 00 A700 CPM
;               ROM"; |ROMCAT,7 (AMSDOS commands, hidden ones shown as one symbol), ,5 ("C1E9
;               V ROM", "CF7E GET", ...), ,0 / ,3 ("C000 BASIC"); ESC pause + ESC end; pause +
;               space goes on; ,8, ,-1 and two parameters: nothing (silent RET); ,256: ROM 0 (only
;               the low byte is read).
; Input:        A = number of parameters (0 or 1), IX = parameters
; Output:       -
; Changed:      AF, BC, DE, HL
; Called by:    RSX "ROMCAT" (rom_jumpblock)
; Calls:        print_dollar_string, print_name_string, romcat_rom_info, romcat_rsx_entry, print_hex_byte, print_two_spaces, print_lf_cr, KM_TEST_KEY, KM_READ_CHAR, KM_WAIT_CHAR, TXT_PLACE_CURSOR, print_message
rsx_romcat:
        cp #01                          ; no parameter: the ROM table
        jr c,romcat_table
        ret nz                          ; more than one: nothing (observed)
        ld a,(ix+#00)                   ; ROM number (low byte only: 256 -> 0, observed) ...
        cp #08                          ; ... 0-7?
        ret nc                          ; no: nothing (observed: 8, -1)
        ld hl,romcat_rsx_header_text    ; "Adr.  RSX-Name"
        call print_dollar_string
        ld bc,#0047                     ; copy romcat_rsx_entry (71 bytes) ...
        ld de,#BF00                     ; ... to &BF00
        ld hl,#FF79
        ldir
romcat_next_rsx:
        ld c,(ix+#00)                   ; C = the ROM
        call #BF00                      ; next command name of that ROM -> &BF47, its address -> &BF45; CY = no more
        jp c,print_crlf_message         ; end of the table: CR LF, done
        ld hl,rre_address               ; the jump address ...
        ld b,(hl)
        inc hl
        ld a,(hl)
        inc hl
        call xmon_hex_byte              ; ... high byte ...
        ld a,b
        call xmon_hex_byte              ; ... low byte (observed: "CF7E  GET")
        call xmon_out_two_tabs          ; two spaces
        call print_name_string          ; the name (from &BF47)
        call xmon_out_lf_cr             ; LF CR
        ld a,#42                        ; ESC key (key number 66) held?
        call KM_TEST_KEY
        or a
        jr z,romcat_next_rsx            ; no: next name
        call KM_READ_CHAR               ; yes: take the key ...
        call TXT_PLACE_CURSOR           ; cursor shown ...
        call KM_WAIT_CHAR               ; ... wait for a key (pause, observed)
        push af
        call TXT_PLACE_CURSOR           ; cursor off again
        pop af
        cp #FC                          ; ESC again?
        jr nz,romcat_next_rsx           ; no: go on (observed: space)
        jp xmon_out_lf_cr               ; yes: LF CR, done (observed)
romcat_table:
        ld hl,romcat_himem_text         ; "Himem: " ...
        call print_dollar_string
        ld hl,(#AE7B)                   ; ... BASIC's HIMEM (&AE7B on the 464) ...
        ld a,h
        call xmon_hex_byte
        ld a,l
        call xmon_hex_byte
; Second entry of romcat_table: the ROM list without the "Himem" line - copy the header reader
; romcat_rom_info to &BF00, print the column header and one line per ROM 0-7 (number, type, mark,
; version, modification, data area, name). Called by XMON's Y (xmon_cmd_rom_select, observed
; 2026-10-25); |ROMCAT falls into it after the Himem line. Note: the copy to &BF00 overwrites
; XMON's breakpoint area (xmon_break_area).
romcat_rom_list:
        ld bc,#002F                     ; copy romcat_rom_info (47 bytes) ... (XMON's Y enters here, without the Himem line)
        ld de,#BF00                     ; ... to &BF00
        ld hl,#FF4A
        ldir
        ld hl,romcat_header_text        ; the column header
        call print_dollar_string
        ld c,#00                        ; ROM 0 first
romcat_next_rom:
        push bc                         ; keep the ROM number
        call #BF00                      ; header bytes -> &BF2F, name -> &BF33 ('$' at the end)
        pop bc
        push bc
        ld a,c                          ; the ROM number
        call xmon_hex_byte
        call xmon_out_two_tabs
        ld hl,#BF2F                     ; the 4 header bytes: type, mark, version, modification
        ld b,#04
        ld d,(hl)                       ; D = the type
romcat_header_byte:
        ld a,(hl)                       ; next header byte, in hex
        inc hl
        call xmon_hex_byte
        call xmon_out_two_tabs
        djnz romcat_header_byte         ; 4 of them
        pop bc
        push bc
        push hl                         ; HL = the name
        ld a,#80                        ; type &80 (foreground: BASIC)?
        cp d
        jr z,romcat_no_base             ; yes: no data area
        ld a,#01                        ; type 1 (background)?
        cp d
        jr z,romcat_base                ; yes: its data area
romcat_no_base:
        ld hl,romcat_no_base_text       ; "----" (observed: BASIC)
        call print_dollar_string
        jr romcat_name
romcat_base:
        ld hl,KL_ROM_IY_TABLE+2         ; the ROM's entry in the IY table ...
        ld b,#00
        dec c                           ; (ROM c: entry c)
        add hl,bc
        add hl,bc
        ld b,(hl)                       ; ... the data area (observed: V ROM A6FC, CPM ROM A700)
        inc hl
        ld a,(hl)
        call xmon_hex_byte
        ld a,b
        call xmon_hex_byte
        call xmon_out_two_tabs
romcat_name:
        pop hl                          ; the name
        call print_dollar_string
        call print_crlf_message         ; CR LF
        pop bc
        inc c                           ; next ROM ...
        ld a,c
        cp #08                          ; ... up to 7
        jr nz,romcat_next_rom
print_crlf_message:
        xor a                           ; message 0: CR LF
        jp print_message

; ---- copied to RAM #BF00-#BF2E (from #FF4A), executed there ----
        DISP #BF00
; ----------------------------------------------------------------------
; Subroutine: romcat_rom_info [#BF00] (RAM, copied from &FF4A by rsx_romcat)
; Tasks:        For the |ROMCAT table: page in ROM C, copy its first 4 header bytes (type, mark,
;               version, modification) to &BF2F and, for a foreground (&80) or background (1)
;               ROM, its first command name (the ROM name, bit 7 ends it) to &BF33 with '$'.
;               Runs in RAM because it pages the ROM in at &C000. Observed (|ROMCAT).
; Input:        C = ROM number
; Output:       &BF2F-&BF32 header bytes, &BF33.. name + '$'
; Changed:      AF, BC, DE, HL
; Called by:    rsx_romcat (romcat_next_rom)
; Calls:        KL_ROM_SELECT, KL_ROM_DESELECT
romcat_rom_info:
        call KL_ROM_SELECT              ; page in ROM C (B = the previous selection)
        push bc                         ; keep the previous ROM selection
        ld de,#BF2F                     ; the 4 header bytes go to &BF2F ...
        push de                         ; (kept: HL = &BF2F later)
        ld hl,rom_type                  ; ... from &C000: type, mark, version, modification
        ld bc,#0004
        ldir                            ; copy them
        pop hl                          ; HL = the copied type byte
        ld a,#80                        ; &80: foreground ROM (BASIC) ...
        cp (hl)
        jr z,rri_name                   ; ... has a name
        ld a,#01                        ; 1: background ROM ...
        cp (hl)
rri_type_check:
        jr nz,rri_done                  ; other types (0 = foreground program?): no name (observed: none)
rri_name:
        ld hl,(rom_name_pointer)        ; HL = the name table (header +4) ...
rri_copy_name:
        ld a,(hl)                       ; ... its first name: next character
        bit 7,a                         ; bit 7 = the last one?
        res 7,a                         ; without bit 7 ...
        ld (de),a                       ; ... into &BF33..
        inc de
        inc hl
        jr z,rri_copy_name              ; not the last: on (observed: "V ROM", "CPM ROM", "BASIC")
rri_done:
        ld a,#24                        ; '$' ends the name for print_dollar_string
        ld (de),a
        pop bc                          ; the previous ROM ...
        jp KL_ROM_DESELECT              ; ... paged in again, return
        ENT                             ; end of DISP #BF00
; ---- end of RAM copy #BF00-#BF2E (from #FF4A) ----


; ---- copied to RAM #BF00-#BF46 (from #FF79), executed there ----
        DISP #BF00
; ----------------------------------------------------------------------
; Subroutine: romcat_rsx_entry [#BF00] (RAM, copied from &FF79 by rsx_romcat)
; Tasks:        For |ROMCAT,n: page in ROM C and fetch its next command: the entry counter is
;               the operand of the LD A,n at &BF0A (self-modifying, starts at 0). Skip that many
;               names, copy the next one to &BF47 ('$' at the end) and its jump address (from
;               the jumpblock at &C007 + 3 x index) to &BF45. End of the name table (byte 0):
;               CY = 1. Runs in RAM because it pages the ROM in at &C000. Observed (|ROMCAT,0,
;               3, 5, 7).
; Input:        C = ROM number; &BF0B = entry counter
; Output:       CY = 0: &BF45 = jump address, &BF47.. name; CY = 1: no more names
; Changed:      AF, BC, DE, HL; &BF0B + 1
; Called by:    rsx_romcat (romcat_next_rsx)
; Calls:        KL_ROM_SELECT, KL_ROM_DESELECT
romcat_rsx_entry:
        ld de,#BF47                     ; name buffer &BF47
        call KL_ROM_SELECT              ; page in ROM C (B = the previous selection)
        push bc                         ; keep it
        ld hl,(rom_name_pointer)        ; HL = the ROM's name table (header +4)
        ld a,#00                        ; A = entry counter: the operand at &BF0B (self-modifying; 0 after the copy)
        inc a                           ; next entry ...
        ld (#BF0B),a                    ; ... stored back into the operand
rre_skip_name:
        dec a                           ; skip counter - 1 names ...
        jr z,rre_check_end              ; done: HL = the wanted name
rre_skip_char:
        bit 7,(hl)                      ; ... to the character with bit 7
        inc hl
        jr z,rre_skip_char
        jr rre_skip_name                ; next name
rre_check_end:
        cp (hl)                         ; A = 0: a 0 byte ends the name table
        scf                             ; CY = 1: no more names ...
        jr z,rre_done                   ; ... (observed: the end of every list)
rre_copy_name:
        ld a,(hl)                       ; copy the name: next character
        bit 7,a                         ; bit 7 = the last one?
        res 7,a                         ; without bit 7 ...
        ld (de),a                       ; ... into &BF47..
        inc de
        inc hl
        jr z,rre_copy_name              ; not the last: on
rre_name_done:
        ld a,#24                        ; '$' ends the name
        ld (de),a
        ld a,(#BF0B)                    ; the entry counter ...
        dec a                           ; ... - 1 = its index (0 = the ROM name with the init entry)
rre_jump_address:
        ld c,a                          ; BC = index ...
        ld b,#00
        ld hl,#C007                     ; ... the jumpblock from &C006: the address word of JP n at &C007 + 3 x index
        add hl,bc
        add hl,bc
        add hl,bc
rre_store_address:
        ld e,(hl)                       ; DE = the JP's target ...
        inc hl
        ld d,(hl)
        ld (rre_address),de             ; ... to &BF45 (observed: C1E9 V ROM, CF7E GET, ...)
        scf                             ; CY = 0: an entry was found ...
        ccf                             ; (CCF after SCF)
rre_done:
        pop bc                          ; the previous ROM ...
        jp KL_ROM_DESELECT              ; ... paged in again, return
rre_address:
        defb #00,#00                    ; the jump address of the entry (filled at run time)
        ENT                             ; end of DISP #BF00
; ---- end of RAM copy #BF00-#BF46 (from #FF79) ----

; ----------------------------------------------------------------------
; Data: rom_tail_copy [#FFC0-#FFFF] (64 bytes) - not code, unreachable, copied by nothing
; A fully scrambled duplicate of &FF40-&FF7F, 128 bytes higher: the end of rsx_romcat's ROM loop
; (&FF40-&FF49), romcat_rom_info (&FF4A-&FF78, all 47 bytes) and the start of romcat_rsx_entry
; (&FF79-&FF7F). The bytes below are the decoded (data) values; the comments show them as Z80 code.
; 61 of the 64 raw bytes equal &FF40-&FF7F; the 3 others (&FFC4, &FFC6, &FFC7) are the opcodes
; JR NZ / XOR A / JP, which are stored in the clear at &FF44 / &FF46 / &FF47 (executed there) but
; scrambled like data here - so every byte of this block is scrambled. Read as ROM code (opcode raw,
; operands decoded) or raw it is nonsense; no jump, call or LDIR reaches it (the two LDIR copies of
; rsx_romcat end at &FF78 and &FFBF). Probably a leftover of the EPROM image build: a 128-byte record
; written once more behind the program, scrambled entirely because the tool knew no opcodes there
; (a guess). Read once as data on purpose 2026-10-26 (LDIR &FFC0 -> &4100, 64 bytes, from RAM &4000):
; &4100-&413F = the values below.
rom_tail_copy:
        defb #0C                        ; inc c                  (= &FF40, end of rsx_romcat's ROM loop)
        defb #79                        ; ld a,c                 (= &FF41)
        defb #FE,#08                    ; cp #08                 (= &FF42)
        defb #20,#AB                    ; jr nz,romcat_next_rom  (= &FF44; raw &00 here, &20 in the clear at &FF44)
        defb #AF                        ; xor a                  (= &FF46; raw &8F here, &AF in the clear at &FF46)
        defb #C3,#D4,#CC                ; jp #CCD4               (= &FF47; raw &E3 here, &C3 in the clear at &FF47)
        defb #CD,#0F,#B9                ; call KL_ROM_SELECT     (= romcat_rom_info &FF4A, RAM &BF00)
        defb #C5                        ; push bc
        defb #11,#2F,#BF                ; ld de,#BF2F
        defb #D5                        ; push de
        defb #21,#00,#C0                ; ld hl,#C000
        defb #01,#04,#00                ; ld bc,#0004
        defb #ED,#B0                    ; ldir
        defb #E1                        ; pop hl
        defb #3E,#80                    ; ld a,#80
        defb #BE                        ; cp (hl)
        defb #28,#05                    ; jr z,rri_name
        defb #3E,#01                    ; ld a,#01
        defb #BE                        ; cp (hl)
        defb #20,#0D                    ; jr nz,rri_done
        defb #2A,#04,#C0                ; ld hl,(#C004)
        defb #7E                        ; ld a,(hl)
        defb #CB,#7F                    ; bit 7,a
        defb #CB,#BF                    ; res 7,a
        defb #12                        ; ld (de),a
        defb #13                        ; inc de
        defb #23                        ; inc hl
        defb #28,#F6                    ; jr z,rri_copy_name
        defb #3E,#24                    ; ld a,#24
        defb #12                        ; ld (de),a
        defb #C1                        ; pop bc
        defb #C3,#18,#B9                ; jp KL_ROM_DESELECT     (end of romcat_rom_info, &FF76)
        defb #11,#47,#BF                ; ld de,#BF47            (= romcat_rsx_entry &FF79, RAM &BF00)
        defb #CD,#0F,#B9                ; call KL_ROM_SELECT
        defb #C5                        ; push bc                (the copy ends with the ROM)
